using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace BlogApi;

[ApiController]
[Route("api/blogs")]
public class BlogsController(BlogContext db) : ControllerBase
{
    [HttpPost]
    public async Task<ActionResult<BlogResponse>> Create(BlogRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Name)) return BadRequest();

        var blog = new Blog { Id = Guid.NewGuid(), Name = request.Name };
        db.Blogs.Add(blog);
        await db.SaveChangesAsync();

        return CreatedAtAction(nameof(Get), new { id = blog.Id }, new BlogResponse(blog.Id, blog.Name));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<BlogResponse>> Get(Guid id)
    {
        var blog = await db.Blogs.FindAsync(id);
        if (blog is null) return NotFound();

        return new BlogResponse(blog.Id, blog.Name);
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<BlogResponse>> Update(Guid id, BlogRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Name)) return BadRequest();

        var blog = await db.Blogs.FindAsync(id);
        if (blog is null) return NotFound();

        blog.Name = request.Name;
        await db.SaveChangesAsync();

        return new BlogResponse(blog.Id, blog.Name);
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var blog = await db.Blogs.FindAsync(id);
        if (blog is null) return NotFound();

        db.Blogs.Remove(blog);
        await db.SaveChangesAsync();

        return NoContent();
    }
}

[ApiController]
[Route("api")]
public class PostsController(BlogContext db) : ControllerBase
{
    [HttpPost("blogs/{blogId:guid}/posts")]
    public async Task<ActionResult<PostResponse>> Create(Guid blogId, PostRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Title)) return BadRequest();
        if (!await db.Blogs.AnyAsync(b => b.Id == blogId)) return NotFound();

        var post = new Post { Id = Guid.NewGuid(), BlogId = blogId, Title = request.Title };
        db.Posts.Add(post);
        await db.SaveChangesAsync();

        return CreatedAtAction(nameof(Get), new { id = post.Id }, ToResponse(post));
    }

    [HttpGet("posts/{id:guid}")]
    public async Task<ActionResult<PostResponse>> Get(Guid id)
    {
        var post = await db.Posts.FindAsync(id);
        if (post is null) return NotFound();

        post.Views++;
        await db.SaveChangesAsync();

        return ToResponse(post);
    }

    [HttpPut("posts/{id:guid}")]
    public async Task<ActionResult<PostResponse>> Update(Guid id, PostRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Title)) return BadRequest();

        var post = await db.Posts.FindAsync(id);
        if (post is null) return NotFound();

        post.Title = request.Title;
        await db.SaveChangesAsync();

        return ToResponse(post);
    }

    [HttpDelete("posts/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var post = await db.Posts.FindAsync(id);
        if (post is null) return NotFound();

        db.Posts.Remove(post);
        await db.SaveChangesAsync();

        return NoContent();
    }

    private static PostResponse ToResponse(Post post) =>
        new(post.Id, post.BlogId, post.Title, post.Views);
}
