using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace BlogApi;

public class Blog
{
    public Guid Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public List<Post> Posts { get; set; } = new();
}

public class Post
{
    public Guid Id { get; set; }
    public Guid BlogId { get; set; }
    public Blog? Blog { get; set; }
    public string Title { get; set; } = string.Empty;
    public int Views { get; set; }
}

public class BlogDbContext(DbContextOptions<BlogDbContext> options) : DbContext(options)
{
    public DbSet<Blog> Blogs => Set<Blog>();
    public DbSet<Post> Posts => Set<Post>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(e =>
        {
            e.HasKey(b => b.Id);
            e.Property(b => b.Name).IsRequired();
        });

        modelBuilder.Entity<Post>(e =>
        {
            e.HasKey(p => p.Id);
            e.Property(p => p.Title).IsRequired();
            e.Property(p => p.Views).HasDefaultValue(0);
            e.HasOne(p => p.Blog)
                .WithMany(b => b.Posts)
                .HasForeignKey(p => p.BlogId)
                .OnDelete(DeleteBehavior.Cascade);
        });
    }
}

public class BlogRequest
{
    [Required]
    public string Name { get; set; } = string.Empty;
}

public class PostRequest
{
    [Required]
    public string Title { get; set; } = string.Empty;
}

public record BlogResponse(Guid Id, string Name)
{
    public static BlogResponse From(Blog b) => new(b.Id, b.Name);
}

public record PostResponse(Guid Id, Guid BlogId, string Title, int Views)
{
    public static PostResponse From(Post p) => new(p.Id, p.BlogId, p.Title, p.Views);
}

