// Models.cs, Data.cs, AppSetup.cs
using Microsoft.EntityFrameworkCore;

public class Blog
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public string Name { get; set; } = "";
    public Guid ConcurrencyStamp { get; set; } = Guid.NewGuid();
    public List<Post> Posts { get; set; } = new();
}

public class Post
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public Guid BlogId { get; set; }
    public Blog? Blog { get; set; }
    public string Title { get; set; } = "";
    public int Views { get; set; }
    public Guid ConcurrencyStamp { get; set; } = Guid.NewGuid();
}

public record BlogDto(Guid Id, string Name);
public record PostDto(Guid Id, Guid BlogId, string Title);
public record BlogRequest(string? Name);
public record PostCreateRequest(string? Title);
public record PostUpdateRequest(Guid BlogId, string? Title);

public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Blog> Blogs => Set<Blog>();
    public DbSet<Post> Posts => Set<Post>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(e =>
        {
            e.HasKey(x => x.Id);
            e.Property(x => x.Name).IsRequired();
            e.Property(x => x.ConcurrencyStamp).IsConcurrencyToken();
        });

        modelBuilder.Entity<Post>(e =>
        {
            e.HasKey(x => x.Id);
            e.Property(x => x.Title).IsRequired();
            e.Property(x => x.Views).HasDefaultValue(0);
            e.Property(x => x.ConcurrencyStamp).IsConcurrencyToken();
            e.HasOne(x => x.Blog).WithMany(x => x.Posts)
                .HasForeignKey(x => x.BlogId)
                .OnDelete(DeleteBehavior.Cascade);
            e.HasIndex(x => x.BlogId);
        });
    }
}

