using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

public abstract class EntityController(BlogContext db) : ControllerBase
{
    protected BlogContext Db { get; } = db;

    protected static string ETag(int version) => $"\"{version}\"";

    // Optimistic concurrency: If-Match is optional, but when sent it must match the current version.
    protected bool PreconditionFailed(int version)
    {
        var ifMatch = Request.Headers["If-Match"].ToString();
        return ifMatch.Length > 0 && ifMatch != ETag(version);
    }

    // Returns false when another request changed the row after it was loaded.
    protected async Task<bool> TrySaveAsync()
    {
        try { await Db.SaveChangesAsync(); return true; }
        catch (DbUpdateConcurrencyException) { return false; }
    }
}
