    {
        if (string.IsNullOrWhiteSpace(request.Name)) return BadRequest();
        var blog = await Db.Blogs.FindAsync(id);
        if (blog is null) return NotFound();
        if (PreconditionFailed(blog.Version)) return StatusCode(StatusCodes.Status412PreconditionFailed);

        blog.Name = request.Name;
        blog.Version++;
        if (!await TrySaveAsync()) return Conflict();
        Response.Headers["ETag"] = ETag(blog.Version);
        return Ok(ToResponse(blog));
    }

