        if (blog is null) return NoContent(); // idempotent for retries
        if (PreconditionFailed(blog.Version)) return StatusCode(StatusCodes.Status412PreconditionFailed);

        Db.Blogs.Remove(blog); // posts are removed by the ON DELETE CASCADE foreign key
