using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api")]
public class PostsController(BlogContext db) : EntityController(db)
{
    [HttpPost("blogs/{blogId:guid}/posts")]
    public async Task<IActionResult> Create(Guid blogId, PostRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Title)) return BadRequest();
        if (!await Db.Blogs.AnyAsync(b => b.Id == blogId)) return NotFound();

        var id = request.Id ?? Guid.NewGuid();
        var existing = await Db.Posts.FindAsync(id);
        if (existing is not null) return existing.BlogId == blogId ? Ok(ToResponse(existing)) : Conflict();

        var post = new Post { Id = id, BlogId = blogId, Title = request.Title };
        Db.Posts.Add(post);
        await Db.SaveChangesAsync();
        Response.Headers["ETag"] = ETag(post.Version);
        return CreatedAtAction(nameof(Get), new { id }, ToResponse(post));
    }

    [HttpGet("posts/{id:guid}")]
    public async Task<IActionResult> Get(Guid id)
    {
        // Atomic server-side increment, so concurrent reads don't lose counts.
        var updated = await Db.Posts.Where(p => p.Id == id)
            .ExecuteUpdateAsync(s => s.SetProperty(p => p.Views, p => p.Views + 1));
        if (updated == 0) return NotFound();

        var post = await Db.Posts.AsNoTracking().FirstAsync(p => p.Id == id);
        Response.Headers["ETag"] = ETag(post.Version);
        return Ok(ToResponse(post));
    }

    [HttpPut("posts/{id:guid}")]
    public async Task<IActionResult> Update(Guid id, PostRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Title)) return BadRequest();
        var post = await Db.Posts.FindAsync(id);
        if (post is null) return NotFound();
        if (PreconditionFailed(post.Version)) return StatusCode(StatusCodes.Status412PreconditionFailed);

        if (request.BlogId is Guid blogId && blogId != post.BlogId)
        {
            if (!await Db.Blogs.AnyAsync(b => b.Id == blogId)) return BadRequest();
            post.BlogId = blogId;
        }
        post.Title = request.Title;
        post.Version++;
        if (!await TrySaveAsync()) return Conflict();

        await Db.Entry(post).ReloadAsync(); // pick up the current Views counter
        Response.Headers["ETag"] = ETag(post.Version);
        return Ok(ToResponse(post));
    }

    [HttpDelete("posts/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var post = await Db.Posts.FindAsync(id);
        if (post is null) return NoContent();
        if (PreconditionFailed(post.Version)) return StatusCode(StatusCodes.Status412PreconditionFailed);

        Db.Posts.Remove(post);
        if (!await TrySaveAsync()) return Conflict();
        return NoContent();
    }

    private static PostResponse ToResponse(Post p) => new(p.Id, p.BlogId, p.Title, p.Views);
