using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ModelBinding;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

public abstract class ApiControllerBase : ControllerBase
{
    protected IActionResult Fail(int status, string? etag = null)
    {
        if (etag is not null) Response.Headers.ETag = etag;
        return Problem(statusCode: status);
    }

    protected static bool Matches(string? header, string etag) =>
        header is not null && (header.Trim() == "*" || header.Split(',').Any(t => t.Trim() == etag));

    protected async Task<IActionResult> Stale(DbUpdateConcurrencyException ex, CancellationToken ct, bool deleting = false)
    {
        var values = await ex.Entries.Single().GetDatabaseValuesAsync(ct);
        if (values is null) return deleting ? NoContent() : Fail(404);
        if (values["DeletedAt"] is not null) return deleting ? NoContent() : Fail(410);
        return Fail(412, (string)values["ETag"]!);
    }
}

[ApiController]
[Route("api/blogs")]
public sealed class BlogsController(BlogDbContext db) : ApiControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] BlogRequest body, CancellationToken ct)
    {
        if (body is null || body.Id == Guid.Empty || string.IsNullOrWhiteSpace(body.Name)) return Fail(400);
        var name = Canon.Norm(body.Name);
        var etag = Canon.Blog(body.Id, name);
        db.Blogs.Add(new Blog { PublicId = body.Id, Name = name, ETag = etag, CreateHash = etag });
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (ex.InnerException is SqliteException { SqliteErrorCode: 19 })
        {
            db.ChangeTracker.Clear();
            var existing = await db.Blogs.IgnoreQueryFilters().AsNoTracking().FirstAsync(b => b.PublicId == body.Id, ct);
            if (existing.DeletedAt is not null) return Fail(410);
            if (existing.CreateHash != etag) return Fail(409);
            Response.Headers.ETag = existing.ETag;
            return Ok(new BlogResponse(existing.PublicId, existing.Name));
        }
        Response.Headers.ETag = etag;
        return Created($"/api/blogs/{body.Id:D}", new BlogResponse(body.Id, name));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var blog = await db.Blogs.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null) return Fail(404);
        if (blog.DeletedAt is not null) return Fail(410);
        Response.Headers.ETag = blog.ETag;
        if (Matches(Request.Headers.IfNoneMatch.ToString(), blog.ETag)) return StatusCode(StatusCodes.Status304NotModified);
        return Ok(new BlogResponse(blog.PublicId, blog.Name));
