public class Blog
{
    public int Id { get; set; }
    public Guid PublicId { get; set; }
    public string Name { get; set; } = string.Empty;
    public string ETag { get; set; } = string.Empty;
    public string CreateHash { get; set; } = string.Empty;
    public DateTimeOffset? DeletedAt { get; set; }
    public List<Post> Posts { get; set; } = [];
}

public class Post
{
    public int Id { get; set; }
    public Guid PublicId { get; set; }
    public int BlogId { get; set; }
    public Blog Blog { get; set; } = null!;
    public string Title { get; set; } = string.Empty;
    public string ETag { get; set; } = string.Empty;
    public string CreateHash { get; set; } = string.Empty;
    public int Views { get; set; }
    public DateTimeOffset? DeletedAt { get; set; }
}

public sealed record BlogRequest(Guid? Id, string? Name);
public sealed record BlogResponse(Guid Id, string Name);
public sealed record PostRequest(Guid? Id, Guid? BlogId, string? Title);
public sealed record PostResponse(Guid Id, Guid BlogId, string Title);

public static class Canonical
{
    public static string Nfc(string s) => s.Normalize(NormalizationForm.FormC);

    public static string Blog(Guid id, string name) => $"{{\"id\":\"{id:D}\",\"name\":{Str(name)}}}";

    public static string Post(Guid id, Guid blogId, string title) =>
        $"{{\"id\":\"{id:D}\",\"blogId\":\"{blogId:D}\",\"title\":{Str(title)}}}";

    public static string Tag(string json) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(json)))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in Nfc(s))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }
}

public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Blog> Blogs => Set<Blog>();
    public DbSet<Post> Posts => Set<Post>();

    protected override void OnModelCreating(ModelBuilder mb)
    {
        mb.Entity<Blog>(b =>
        {
            b.HasKey(x => x.Id);
            b.HasIndex(x => x.PublicId).IsUnique();
            b.Property(x => x.Name).IsRequired();
            b.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
            b.Property(x => x.CreateHash).IsRequired().Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            b.HasQueryFilter(x => x.DeletedAt == null);
        });

        mb.Entity<Post>(p =>
        {
            p.HasKey(x => x.Id);
            p.HasIndex(x => x.PublicId).IsUnique();
            p.Property(x => x.Title).IsRequired();
            p.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
            p.Property(x => x.CreateHash).IsRequired().Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            p.Property(x => x.Views).HasDefaultValue(0);
            p.HasOne(x => x.Blog).WithMany(x => x.Posts).HasForeignKey(x => x.BlogId).OnDelete(DeleteBehavior.Restrict);
            p.HasQueryFilter(x => x.DeletedAt == null);
        });
    }
}
