using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

public abstract class ApiControllerBase(AppDbContext db) : ControllerBase
{
    protected AppDbContext Db { get; } = db;

    protected ObjectResult Error(int status, string title) =>
        new(new ProblemDetails { Status = status, Title = title })
        {
            StatusCode = status,
            ContentTypes = { "application/problem+json" }
        };

    protected static bool Matches(string? header, string etag) =>
        (header ?? string.Empty).Split(',').Select(s => s.Trim()).Any(s => s == "*" || s == etag);

    protected static bool IsUniqueViolation(DbUpdateException ex) =>
        ex.InnerException is SqliteException { SqliteExtendedErrorCode: 2067 or 1555 };
}

[Route("api/blogs")]
public class BlogsController(AppDbContext db) : ApiControllerBase(db)
{
    [HttpPost]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, Required] BlogRequest? body, CancellationToken ct)
    {
        if (body is null || body.Id is not { } id || id == Guid.Empty || string.IsNullOrWhiteSpace(body.Name))
            return Error(400, "Invalid blog.");

        var name = Canonical.Nfc(body.Name);
        var tag = Canonical.Tag(Canonical.Blog(id, name));
        var blog = new Blog { PublicId = id, Name = name, ETag = tag, CreateHash = tag };
        Db.Blogs.Add(blog);
        try
        {
            await Db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (IsUniqueViolation(ex))
        {
            Db.Entry(blog).State = EntityState.Detached;
            var existing = await Db.Blogs.IgnoreQueryFilters().AsNoTracking().FirstAsync(b => b.PublicId == id, ct);
            if (existing.DeletedAt is not null) return Error(410, "Blog was deleted.");
            if (existing.CreateHash != tag) return Error(409, "Blog id is already used with different content.");
            Response.Headers.ETag = existing.ETag;
            return Ok(new BlogResponse(id, existing.Name));
        }

        Response.Headers.ETag = tag;
        return Created($"/api/blogs/{id:D}", new BlogResponse(id, name));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var blog = await Find(id, ct);
        if (blog is null) return Error(404, "Blog not found.");
        if (blog.DeletedAt is not null) return Error(410, "Blog was deleted.");
        Response.Headers.ETag = blog.ETag;
        if (Matches(Request.Headers.IfNoneMatch, blog.ETag)) return StatusCode(StatusCodes.Status304NotModified);
        return Ok(new BlogResponse(blog.PublicId, blog.Name));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromBody, Required] BlogRequest? body,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (body is null || body.Id != id || string.IsNullOrWhiteSpace(body.Name)) return Error(400, "Invalid blog.");
        if (string.IsNullOrEmpty(ifMatch)) return Error(428, "If-Match header is required.");

        var blog = await Find(id, ct);
        if (blog is null) return Error(404, "Blog not found.");
        if (blog.DeletedAt is not null) return Error(410, "Blog was deleted.");

        var name = Canonical.Nfc(body.Name);
        var tag = Canonical.Tag(Canonical.Blog(id, name));
        if (blog.ETag == tag)
        {
            Response.Headers.ETag = tag;
            return NoContent();
        }
        if (!Matches(ifMatch, blog.ETag))
        {
            Response.Headers.ETag = blog.ETag;
            return Error(412, "ETag does not match.");
        }

        blog.Name = name;
        blog.ETag = tag;
        try
        {
            await Db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await Stale(id, ct, deleteIsIdempotent: false);
        }

        Response.Headers.ETag = tag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch)) return Error(428, "If-Match header is required.");

        var blog = await Find(id, ct);
        if (blog is null || blog.DeletedAt is not null) return NoContent();
        if (!Matches(ifMatch, blog.ETag))
        {
            Response.Headers.ETag = blog.ETag;
            return Error(412, "ETag does not match.");
        }

        await using var tx = await Db.Database.BeginTransactionAsync(ct);
        var now = DateTimeOffset.UtcNow;
        blog.DeletedAt = now;
        foreach (var post in await Db.Posts.Where(p => p.BlogId == blog.Id).ToListAsync(ct))
            post.DeletedAt = now;
        try
        {
            await Db.SaveChangesAsync(ct);
            await tx.CommitAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await Stale(id, ct, deleteIsIdempotent: true);
        }

        return NoContent();
    }

    private Task<Blog?> Find(Guid id, CancellationToken ct) =>
        Db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == id, ct);

    private async Task<IActionResult> Stale(Guid id, CancellationToken ct, bool deleteIsIdempotent)
    {
        var current = await Db.Blogs.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (current is null) return Error(404, "Blog not found.");
        if (current.DeletedAt is not null) return deleteIsIdempotent ? NoContent() : Error(410, "Blog was deleted.");
        Response.Headers.ETag = current.ETag;
        return Error(412, "ETag does not match.");
    }
}

