    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromBody, Required] PostRequest? body,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (body is null || body.Id != id || body.BlogId is not { } blogId || string.IsNullOrWhiteSpace(body.Title))
            return Error(400, "Invalid post.");
        if (string.IsNullOrEmpty(ifMatch)) return Error(428, "If-Match header is required.");

        var post = await Find(id, ct);
        if (post is null) return Error(404, "Post not found.");
        if (post.DeletedAt is not null) return Error(410, "Post was deleted.");
        if (post.Blog.PublicId != blogId) return Error(409, "Moving a post to another blog is not allowed.");

        var title = Canonical.Nfc(body.Title);
        var tag = Canonical.Tag(Canonical.Post(id, blogId, title));
        if (post.ETag == tag)
        {
            Response.Headers.ETag = tag;
            return NoContent();
        }
        if (!Matches(ifMatch, post.ETag))
        {
            Response.Headers.ETag = post.ETag;
            return Error(412, "ETag does not match.");
        }

        post.Title = title;
        post.ETag = tag;
        try
        {
            await Db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await Stale(id, ct, deleteIsIdempotent: false);
        }

        Response.Headers.ETag = tag;
        return NoContent();
    }

    [HttpDelete("api/posts/{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch)) return Error(428, "If-Match header is required.");

        var post = await Find(id, ct);
        if (post is null || post.DeletedAt is not null) return NoContent();
        if (!Matches(ifMatch, post.ETag))
        {
            Response.Headers.ETag = post.ETag;
            return Error(412, "ETag does not match.");
        }

        post.DeletedAt = DateTimeOffset.UtcNow;
        try
        {
            await Db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await Stale(id, ct, deleteIsIdempotent: true);
        }

        return NoContent();
    }

    private static PostResponse Rep(Post p) => new(p.PublicId, p.Blog.PublicId, p.Title);

    private Task<Post?> Find(Guid id, CancellationToken ct) =>
        Db.Posts.IgnoreQueryFilters().Include(p => p.Blog).FirstOrDefaultAsync(p => p.PublicId == id, ct);

    private async Task<IActionResult> Stale(Guid id, CancellationToken ct, bool deleteIsIdempotent)
    {
        var current = await Db.Posts.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(p => p.PublicId == id, ct);
        if (current is null) return Error(404, "Post not found.");
        if (current.DeletedAt is not null) return deleteIsIdempotent ? NoContent() : Error(410, "Post was deleted.");
        Response.Headers.ETag = current.ETag;
        return Error(412, "ETag does not match.");
    }
}
