using System.ComponentModel.DataAnnotations;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

public sealed class BlogRequest
{
    public Guid? Id { get; set; }
    public string? Name { get; set; }
}

public sealed class PostRequest
{
    public Guid? Id { get; set; }
    public Guid? BlogId { get; set; }
    public string? Title { get; set; }
}

public sealed record BlogResponse(Guid Id, string Name);

public sealed record PostResponse(Guid Id, Guid BlogId, string Title);

public static class Canon
{
    public static string Nfc(string s) => s.Normalize(NormalizationForm.FormC);

    public static string Blog(Guid id, string name) =>
        $"{{\"id\":\"{id:D}\",\"name\":\"{Esc(name)}\"}}";

    public static string Post(Guid id, Guid blogId, string title) =>
        $"{{\"id\":\"{id:D}\",\"blogId\":\"{blogId:D}\",\"title\":\"{Esc(title)}\"}}";

    static string Esc(string s)
    {
        var sb = new StringBuilder();
        foreach (var c in Nfc(s))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (char.IsControl(c)) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.ToString();
    }
}

public static class Etags
{
    public static string Of(string canonical) => Quote(Base64Url(SHA256.HashData(Encoding.UTF8.GetBytes(canonical))));

    public static string Tombstone() => Quote(Base64Url(SHA256.HashData(Guid.NewGuid().ToByteArray())));

    public static bool Matches(string? header, string etag) =>
        header is not null && header.Split(',').Any(t => t.Trim() is var v && (v == "*" || v == etag));

    static string Quote(string s) => $"\"{s}\"";

    static string Base64Url(byte[] bytes) =>
        Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
}

public static class Db
{
    public static bool IsUniqueViolation(this DbUpdateException ex) =>
        ex.InnerException is SqliteException { SqliteExtendedErrorCode: 2067 or 1555 };
}

public abstract class ApiControllerBase : ControllerBase
{
    public const string ProblemJson = "application/problem+json";

    protected IActionResult Fail(int status) => Problem(statusCode: status);

    protected void Tag(string etag) => Response.Headers.ETag = etag;
}
