using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[Route("api/blogs")]
public class BlogsController(AppDbContext db) : ApiControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, ProblemJson)]
    public async Task<IActionResult> Create([FromBody, Required] BlogRequest? body, CancellationToken ct)
    {
        if (body is null || body.Id is not Guid id || body.Name is not string raw) return Fail(400);
        var name = Canon.Nfc(raw);
        var etag = Etags.Of(Canon.Blog(id, name));
        db.Blogs.Add(new Blog { PublicId = id, Name = name, ETag = etag, CreateHash = etag });
        try
        {
            await db.SaveChangesAsync(ct);
            Tag(etag);
            return Created($"/api/blogs/{id:D}", new BlogResponse(id, name));
        }
        catch (DbUpdateException ex) when (ex.IsUniqueViolation())
        {
            db.ChangeTracker.Clear();
            var existing = await db.Blogs.IgnoreQueryFilters().AsNoTracking().SingleOrDefaultAsync(b => b.PublicId == id, ct);
            if (existing?.DeletedAt is not null) return Fail(410);
            if (existing is null || existing.CreateHash != etag) return Fail(409);
            Tag(existing.ETag);
            return Ok(new BlogResponse(existing.PublicId, existing.Name));
        }
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, ProblemJson)]
    public async Task<IActionResult> Get(Guid id, [FromHeader(Name = "If-None-Match")] string? ifNoneMatch, CancellationToken ct)
    {
        var blog = await db.Blogs.IgnoreQueryFilters().AsNoTracking().SingleOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null) return Fail(404);
        if (blog.DeletedAt is not null) return Fail(410);
        Tag(blog.ETag);
        if (Etags.Matches(ifNoneMatch, blog.ETag)) return StatusCode(StatusCodes.Status304NotModified);
        return Ok(new BlogResponse(blog.PublicId, blog.Name));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, ProblemJson)]
    public async Task<IActionResult> Update(Guid id, [FromBody, Required] BlogRequest? body, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (body is null || body.Id != id || body.Name is not string raw) return Fail(400);
        if (ifMatch is null) return Fail(428);
        var name = Canon.Nfc(raw);
        var target = Etags.Of(Canon.Blog(id, name));
        var blog = await db.Blogs.IgnoreQueryFilters().SingleOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null) return Fail(404);
        if (blog.DeletedAt is not null) return Fail(410);
        if (blog.ETag == target) { Tag(target); return NoContent(); }
        if (!Etags.Matches(ifMatch, blog.ETag)) { Tag(blog.ETag); return Fail(412); }
        blog.Name = name;
        blog.ETag = target;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await Stale(id, target, ct);
        }
        Tag(target);
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, ProblemJson)]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (ifMatch is null) return Fail(428);
        var blog = await db.Blogs.Include(b => b.Posts).SingleOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null) return NoContent();
        if (!Etags.Matches(ifMatch, blog.ETag)) { Tag(blog.ETag); return Fail(412); }
        var now = DateTimeOffset.UtcNow;
        blog.DeletedAt = now;
        blog.ETag = Etags.Tombstone();
        foreach (var post in blog.Posts)
        {
            post.DeletedAt = now;
            post.ETag = Etags.Tombstone();
        }
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await StaleDelete(id, ct);
        }
        return NoContent();
    }

    async Task<IActionResult> Stale(Guid id, string target, CancellationToken ct)
    {
        var cur = await db.Blogs.IgnoreQueryFilters().AsNoTracking().SingleOrDefaultAsync(b => b.PublicId == id, ct);
        if (cur is null) return Fail(404);
        if (cur.DeletedAt is not null) return Fail(410);
        if (cur.ETag == target) { Tag(target); return NoContent(); }
        Tag(cur.ETag);
        return Fail(412);
    }

    async Task<IActionResult> StaleDelete(Guid id, CancellationToken ct)
    {
        var cur = await db.Blogs.IgnoreQueryFilters().AsNoTracking().SingleOrDefaultAsync(b => b.PublicId == id, ct);
        if (cur is null || cur.DeletedAt is not null) return NoContent();
        Tag(cur.ETag);
        return Fail(412);
    }
}
