using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

public static class Canon
{
    public static string Blog(Guid id, string name) =>
        Etag($"{{\"id\":\"{id:D}\",\"name\":{Str(name)}}}");

    public static string Post(Guid id, Guid blogId, string title) =>
        Etag($"{{\"id\":\"{id:D}\",\"blogId\":\"{blogId:D}\",\"title\":{Str(title)}}}");

    static string Etag(string json) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(json)))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s.Normalize(NormalizationForm.FormC))
            sb.Append(c switch
            {
                '"' => "\\\"",
                '\\' => "\\\\",
                '\b' => "\\b",
                '\f' => "\\f",
                '\n' => "\\n",
                '\r' => "\\r",
                '\t' => "\\t",
                < ' ' => $"\\u{(int)c:x4}",
                _ => c.ToString()
            });
        return sb.Append('"').ToString();
    }
}

public abstract class ApiControllerBase : ControllerBase
{
    protected static bool Matches(string? header, string etag) =>
        !string.IsNullOrEmpty(header) &&
        (header == "*" || header.Split(',', StringSplitOptions.TrimEntries).Contains(etag));

    protected static bool IsUnique(DbUpdateException ex) =>
        ex.InnerException is SqliteException { SqliteExtendedErrorCode: 2067 or 1555 };

    protected ContentResult Error(int status, string? detail = null) => new()
    {
        StatusCode = status,
        ContentType = "application/problem+json",
        Content = JsonSerializer.Serialize(new ProblemDetails
        {
            Status = status,
            Title = status switch
            {
                400 => "Bad Request",
                404 => "Not Found",
                409 => "Conflict",
                410 => "Gone",
                412 => "Precondition Failed",
                428 => "Precondition Required",
                _ => "Error"
            },
            Detail = detail
        })
    };
}
