using Microsoft.EntityFrameworkCore;

public record BlogBody(Guid? Id, string? Name);
public record BlogResponse(Guid Id, string Name);

[Route("api/blogs")]
public class BlogsController(BlogDbContext db) : ApiControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, Required] BlogBody body, CancellationToken ct)
    {
        if (body is null || body.Id is not { } id || id == Guid.Empty || string.IsNullOrWhiteSpace(body.Name))
            return Error(400);

        var name = body.Name.Normalize(NormalizationForm.FormC);
        var etag = Canon.Blog(id, name);
        db.Blogs.Add(new Blog { PublicId = id, Name = name, ETag = etag, RequestHash = etag });
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (IsUnique(ex))
        {
            db.ChangeTracker.Clear();
            var old = await db.Blogs.IgnoreQueryFilters().AsNoTracking()
                .Where(b => b.PublicId == id)
                .Select(b => new { b.Name, b.ETag, b.RequestHash, b.DeletedAt })
                .SingleAsync(ct);
            if (old.DeletedAt is not null) return Error(410);
            if (old.RequestHash != etag) return Error(409);
            Response.Headers.ETag = old.ETag;
            return Ok(new BlogResponse(id, old.Name));
        }

        Response.Headers.ETag = etag;
        return Created($"/api/blogs/{id:D}", new BlogResponse(id, name));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var b = await db.Blogs.IgnoreQueryFilters().AsNoTracking()
            .Where(x => x.PublicId == id)
            .Select(x => new { x.Name, x.ETag, x.DeletedAt })
            .FirstOrDefaultAsync(ct);
        if (b is null) return Error(404);
        if (b.DeletedAt is not null) return Error(410);

        Response.Headers.ETag = b.ETag;
        if (Matches(Request.Headers.IfNoneMatch, b.ETag)) return StatusCode(304);
        return Ok(new BlogResponse(id, b.Name));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(
        Guid id,
        [FromBody, Required] BlogBody body,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        CancellationToken ct)
    {
        if (body is null || body.Id != id || string.IsNullOrWhiteSpace(body.Name)) return Error(400);
        if (string.IsNullOrEmpty(ifMatch)) return Error(428);

        var name = body.Name.Normalize(NormalizationForm.FormC);
        var etag = Canon.Blog(id, name);
        var b = await db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (b is null) return Error(404);
        if (b.DeletedAt is not null) return Error(410);
        if (b.ETag == etag)
        {
            Response.Headers.ETag = etag;
            return NoContent();
        }
        if (!Matches(ifMatch, b.ETag))
        {
            Response.Headers.ETag = b.ETag;
            return Error(412);
        }

        b.Name = name;
        b.ETag = etag;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await Stale(id, ct);
        }

        Response.Headers.ETag = etag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch)) return Error(428);

        var b = await db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (b is null || b.DeletedAt is not null) return NoContent();
        if (!Matches(ifMatch, b.ETag))
        {
            Response.Headers.ETag = b.ETag;
            return Error(412);
        }

        DateTimeOffset? now = DateTimeOffset.UtcNow;
        await using var tx = await db.Database.BeginTransactionAsync(ct);
        b.DeletedAt = now;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await Stale(id, ct);
        }

        await db.Posts.Where(p => p.BlogId == b.Id && p.DeletedAt == null)
            .ExecuteUpdateAsync(s => s.SetProperty(p => p.DeletedAt, now), ct);
        await tx.CommitAsync(ct);
        return NoContent();
    }

    private async Task<IActionResult> Stale(Guid id, CancellationToken ct)
    {
        db.ChangeTracker.Clear();
        var c = await db.Blogs.IgnoreQueryFilters().AsNoTracking()
            .Where(x => x.PublicId == id)
            .Select(x => new { x.ETag, x.DeletedAt })
            .FirstOrDefaultAsync(ct);
        if (c is null) return Error(404);
        if (c.DeletedAt is not null) return Error(410);
        Response.Headers.ETag = c.ETag;
        return Error(412);
    }
}

