```csharp
using System.Buffers.Text;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

public static class ETags
{
    public static string Blog(Guid id, string name) => $"{{\"id\":\"{id:D}\",\"name\":{Str(name)}}}";
    public static string Post(Guid id, Guid blogId, string title) => $"{{\"id\":\"{id:D}\",\"blogId\":\"{blogId:D}\",\"title\":{Str(title)}}}";

    public static string Of(string canonicalJson) =>
        "\"" + Base64Url.EncodeToString(SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson))) + "\"";

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s.Normalize(NormalizationForm.FormC))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }
}

public static class HttpHelpers
{
    public static ObjectResult Problem(int status, string title) =>
        new(new ProblemDetails { Status = status, Title = title })
        {
            StatusCode = status,
            ContentTypes = { "application/problem+json" }
        };

    public static bool Matches(string header, string etag) =>
        header.Split(',').Select(t => t.Trim()).Any(t => t == "*" || t == etag);

    public static bool IsUniqueViolation(DbUpdateException ex) =>
        ex.InnerException is SqliteException { SqliteExtendedErrorCode: 2067 };
}
