using System.ComponentModel.DataAnnotations;
using System.Text;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[Route("api/blogs")]
public sealed class BlogsController(BlogDbContext db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] BlogWrite body, CancellationToken ct)
    {
        if (body is null || body.Id == Guid.Empty || string.IsNullOrWhiteSpace(body.Name))
            return HttpHelpers.Problem(400, "Invalid blog.");

        var name = body.Name.Normalize(NormalizationForm.FormC);
        var etag = ETags.Of(ETags.Blog(body.Id, name));
        var blog = new Blog { PublicId = body.Id, Name = name, ETag = etag, CreateHash = etag };
        db.Blogs.Add(blog);

        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (HttpHelpers.IsUniqueViolation(ex))
        {
            db.ChangeTracker.Clear();
            var existing = await db.Blogs.IgnoreQueryFilters().AsNoTracking().SingleAsync(b => b.PublicId == body.Id, ct);
            if (existing.DeletedAt is not null) return HttpHelpers.Problem(410, "Blog was deleted.");
            if (existing.CreateHash != etag) return HttpHelpers.Problem(409, "A different blog with this id already exists.");
            Response.Headers.ETag = existing.ETag;
            return Ok(new BlogResponse(existing.PublicId, existing.Name));
        }

        Response.Headers.ETag = etag;
        return Created($"/api/blogs/{blog.PublicId:D}", new BlogResponse(blog.PublicId, blog.Name));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get([FromRoute] Guid id, CancellationToken ct)
    {
        var blog = await db.Blogs.IgnoreQueryFilters().AsNoTracking().SingleOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null) return HttpHelpers.Problem(404, "Blog not found.");
        if (blog.DeletedAt is not null) return HttpHelpers.Problem(410, "Blog was deleted.");

        Response.Headers.ETag = blog.ETag;
        if (HttpHelpers.Matches(Request.Headers.IfNoneMatch.ToString(), blog.ETag)) return StatusCode(StatusCodes.Status304NotModified);
        return Ok(new BlogResponse(blog.PublicId, blog.Name));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Replace(
        [FromRoute] Guid id,
        [FromBody] BlogWrite body,
        [FromHeader(Name = "If-Match"), Required] string ifMatch,
        CancellationToken ct)
    {
        if (body is null || body.Id == Guid.Empty || body.Id != id || string.IsNullOrWhiteSpace(body.Name))
            return HttpHelpers.Problem(400, "Invalid blog.");
        if (string.IsNullOrEmpty(ifMatch)) return HttpHelpers.Problem(428, "If-Match header is required.");

        var name = body.Name.Normalize(NormalizationForm.FormC);
        var etag = ETags.Of(ETags.Blog(id, name));
        var blog = await db.Blogs.IgnoreQueryFilters().SingleOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null) return HttpHelpers.Problem(404, "Blog not found.");
        if (blog.DeletedAt is not null) return HttpHelpers.Problem(410, "Blog was deleted.");

        if (blog.ETag == etag)
        {
            Response.Headers.ETag = etag;
            return NoContent();
        }
        if (!HttpHelpers.Matches(ifMatch, blog.ETag))
        {
            Response.Headers.ETag = blog.ETag;
            return HttpHelpers.Problem(412, "The blog was modified; use the current ETag.");
        }

        blog.Name = name;
        blog.ETag = etag;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var current = await db.Blogs.IgnoreQueryFilters().AsNoTracking().SingleAsync(b => b.PublicId == id, ct);
            if (current.DeletedAt is not null) return HttpHelpers.Problem(410, "Blog was deleted.");
            Response.Headers.ETag = current.ETag;
            return HttpHelpers.Problem(412, "The blog was modified; use the current ETag.");
        }

        Response.Headers.ETag = etag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(
        [FromRoute] Guid id,
        [FromHeader(Name = "If-Match"), Required] string ifMatch,
        CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch)) return HttpHelpers.Problem(428, "If-Match header is required.");

        var blog = await db.Blogs.IgnoreQueryFilters().Include(b => b.Posts).SingleOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null || blog.DeletedAt is not null) return NoContent();
        if (!HttpHelpers.Matches(ifMatch, blog.ETag))
        {
            Response.Headers.ETag = blog.ETag;
            return HttpHelpers.Problem(412, "The blog was modified; use the current ETag.");
        }

        var now = DateTime.UtcNow;
        blog.DeletedAt = now;
        foreach (var post in blog.Posts.Where(p => p.DeletedAt is null)) post.DeletedAt = now;

        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var current = await db.Blogs.IgnoreQueryFilters().AsNoTracking().SingleAsync(b => b.PublicId == id, ct);
            if (current.DeletedAt is not null) return NoContent();
            Response.Headers.ETag = current.ETag;
            return HttpHelpers.Problem(412, "The blog was modified; use the current ETag.");
        }

        return NoContent();
    }
}

