    [HttpPost("~/api/blogs/{blogId:guid}/posts")]
    [ProducesResponseType(typeof(PostResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(PostResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromRoute] Guid blogId, [FromBody] PostWrite body, CancellationToken ct)
    {
        if (body is null || body.Id == Guid.Empty || body.BlogId != blogId || string.IsNullOrWhiteSpace(body.Title))
            return HttpHelpers.Problem(400, "Invalid post.");

        var blog = await db.Blogs.IgnoreQueryFilters().AsNoTracking().SingleOrDefaultAsync(b => b.PublicId == blogId, ct);
        if (blog is null) return HttpHelpers.Problem(404, "Blog not found.");
        if (blog.DeletedAt is not null) return HttpHelpers.Problem(410, "Blog was deleted.");

        var title = body.Title.Normalize(NormalizationForm.FormC);
        var etag = ETags.Of(ETags.Post(body.Id, blogId, title));
        var post = new Post { PublicId = body.Id, BlogId = blog.Id, Title = title, ETag = etag, CreateHash = etag };
        db.Posts.Add(post);

        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (HttpHelpers.IsUniqueViolation(ex))
        {
            db.ChangeTracker.Clear();
            var existing = await db.Posts.IgnoreQueryFilters().AsNoTracking().SingleAsync(p => p.PublicId == body.Id, ct);
            if (existing.DeletedAt is not null) return HttpHelpers.Problem(410, "Post was deleted.");
            if (existing.CreateHash != etag) return HttpHelpers.Problem(409, "A different post with this id already exists.");
            Response.Headers.ETag = existing.ETag;
            return Ok(new PostResponse(existing.PublicId, blogId, existing.Title));
        }

        Response.Headers.ETag = etag;
        return Created($"/api/posts/{post.PublicId:D}", new PostResponse(post.PublicId, blogId, post.Title));
    }

    [HttpGet("api/posts/{id:guid}")]
    [ProducesResponseType(typeof(PostResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get([FromRoute] Guid id, CancellationToken ct)
    {
        var post = await db.Posts.IgnoreQueryFilters().Include(p => p.Blog).AsNoTracking()
            .SingleOrDefaultAsync(p => p.PublicId == id, ct);
        if (post is null) return HttpHelpers.Problem(404, "Post not found.");
        if (post.DeletedAt is not null) return HttpHelpers.Problem(410, "Post was deleted.");

        Response.Headers.ETag = post.ETag;
        if (HttpHelpers.Matches(Request.Headers.IfNoneMatch.ToString(), post.ETag)) return StatusCode(StatusCodes.Status304NotModified);

        await db.Posts.Where(p => p.Id == post.Id)
            .ExecuteUpdateAsync(s => s.SetProperty(p => p.Views, p => p.Views + 1), ct);
        return Ok(new PostResponse(post.PublicId, post.Blog.PublicId, post.Title));
    }

    [HttpPut("api/posts/{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Replace(
        [FromRoute] Guid id,
        [FromBody] PostWrite body,
        [FromHeader(Name = "If-Match"), Required] string ifMatch,
        CancellationToken ct)
    {
        if (body is null || body.Id == Guid.Empty || body.Id != id || string.IsNullOrWhiteSpace(body.Title))
            return HttpHelpers.Problem(400, "Invalid post.");
        if (string.IsNullOrEmpty(ifMatch)) return HttpHelpers.Problem(428, "If-Match header is required.");

        var title = body.Title.Normalize(NormalizationForm.FormC);
        var etag = ETags.Of(ETags.Post(id, body.BlogId, title));
        var post = await db.Posts.IgnoreQueryFilters().Include(p => p.Blog).SingleOrDefaultAsync(p => p.PublicId == id, ct);
        if (post is null) return HttpHelpers.Problem(404, "Post not found.");
        if (post.DeletedAt is not null) return HttpHelpers.Problem(410, "Post was deleted.");

        if (post.ETag == etag)
        {
            Response.Headers.ETag = etag;
            return NoContent();
        }
        if (body.BlogId != post.Blog.PublicId) return HttpHelpers.Problem(409, "A post cannot be moved to another blog.");
        if (!HttpHelpers.Matches(ifMatch, post.ETag))
        {
            Response.Headers.ETag = post.ETag;
            return HttpHelpers.Problem(412, "The post was modified; use the current ETag.");
        }

        post.Title = title;
        post.ETag = etag;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var current = await db.Posts.IgnoreQueryFilters().AsNoTracking().SingleAsync(p => p.PublicId == id, ct);
            if (current.DeletedAt is not null) return HttpHelpers.Problem(410, "Post was deleted.");
            Response.Headers.ETag = current.ETag;
            return HttpHelpers.Problem(412, "The post was modified; use the current ETag.");
        }

        Response.Headers.ETag = etag;
        return NoContent();
    }

    [HttpDelete("api/posts/{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(
        [FromRoute] Guid id,
        [FromHeader(Name = "If-Match"), Required] string ifMatch,
        CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch)) return HttpHelpers.Problem(428, "If-Match header is required.");

        var post = await db.Posts.IgnoreQueryFilters().SingleOrDefaultAsync(p => p.PublicId == id, ct);
        if (post is null || post.DeletedAt is not null) return NoContent();
        if (!HttpHelpers.Matches(ifMatch, post.ETag))
        {
            Response.Headers.ETag = post.ETag;
            return HttpHelpers.Problem(412, "The post was modified; use the current ETag.");
        }

        post.DeletedAt = DateTime.UtcNow;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var current = await db.Posts.IgnoreQueryFilters().AsNoTracking().SingleAsync(p => p.PublicId == id, ct);
            if (current.DeletedAt is not null) return NoContent();
            Response.Headers.ETag = current.ETag;
            return HttpHelpers.Problem(412, "The post was modified; use the current ETag.");
        }

        return NoContent();
    }
}
