using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;

public class Blog
{
    public int Id { get; set; }
    public Guid PublicId { get; set; }
    public string Name { get; set; } = "";
    public string ETag { get; set; } = "";
    public string CreateHash { get; set; } = "";
    public DateTimeOffset? DeletedAt { get; set; }
    public List<Post> Posts { get; set; } = [];
}

public class Post
{
    public int Id { get; set; }
    public Guid PublicId { get; set; }
    public int BlogId { get; set; }
    public Guid BlogPublicId { get; set; }
    public Blog Blog { get; set; } = null!;
    public string Title { get; set; } = "";
    public int Views { get; set; }
    public string ETag { get; set; } = "";
    public string CreateHash { get; set; } = "";
    public DateTimeOffset? DeletedAt { get; set; }
}

public record BlogRequest(Guid? Id, string? Name);
public record BlogDto(Guid Id, string Name);
public record PostRequest(Guid? Id, Guid? BlogId, string? Title);
public record PostDto(Guid Id, Guid BlogId, string Title);

public static class Etags
{
    public static string Blog(Guid id, string name) =>
        Hash($"{{\"id\":\"{id:D}\",\"name\":{Str(name)}}}");

    public static string Post(Guid id, Guid blogId, string title) =>
        Hash($"{{\"id\":\"{id:D}\",\"blogId\":\"{blogId:D}\",\"title\":{Str(title)}}}");

    public static bool Matches(string header, string etag) =>
        header.Split(',').Select(t => t.Trim()).Any(t => t == "*" || t == etag);

    static string Hash(string json) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(json)))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s.Normalize(NormalizationForm.FormC))
            sb.Append(c switch
            {
                '"' => "\\\"",
                '\\' => "\\\\",
                '\b' => "\\b",
                '\f' => "\\f",
                '\n' => "\\n",
                '\r' => "\\r",
                '\t' => "\\t",
                < ' ' => $"\\u{(int)c:x4}",
                _ => c.ToString()
            });
        return sb.Append('"').ToString();
    }
}

public abstract class ApiControllerBase : ControllerBase
{
    protected string IfMatch => Request.Headers["If-Match"].ToString();

    protected IActionResult Fail(int status, string title) => Problem(title: title, statusCode: status);

    protected IActionResult Stale(string etag)
    {
        Response.Headers["ETag"] = etag;
        return Fail(412, "Precondition failed");
    }
}

public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Blog> Blogs => Set<Blog>();
    public DbSet<Post> Posts => Set<Post>();

    protected override void OnModelCreating(ModelBuilder model)
    {
        model.Entity<Blog>(b =>
        {
            b.HasKey(x => x.Id);
            b.HasIndex(x => x.PublicId).IsUnique();
            b.Property(x => x.Name).IsRequired();
            b.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
            b.Property(x => x.CreateHash).IsRequired().ValueGeneratedNever()
                .Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            b.HasQueryFilter(x => x.DeletedAt == null);
        });

        model.Entity<Post>(p =>
        {
            p.HasKey(x => x.Id);
            p.HasIndex(x => x.PublicId).IsUnique();
            p.Property(x => x.Title).IsRequired();
            p.Property(x => x.Views).IsRequired();
            p.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
            p.Property(x => x.CreateHash).IsRequired().ValueGeneratedNever()
                .Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            p.HasOne(x => x.Blog).WithMany(b => b.Posts).HasForeignKey(x => x.BlogId).OnDelete(DeleteBehavior.Restrict);
            p.HasQueryFilter(x => x.DeletedAt == null);
        });
    }
}
