using System.ComponentModel.DataAnnotations;
using System.Text;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/blogs")]
public class BlogsController(AppDbContext db) : ApiControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(BlogDto), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogDto), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, Required] BlogRequest body, CancellationToken ct)
    {
        if (body.Id is not Guid id || string.IsNullOrWhiteSpace(body.Name)) return Fail(400, "Invalid body");
        var name = body.Name.Normalize(NormalizationForm.FormC);
        var etag = Etags.Blog(id, name);

        var blog = await Find(id, ct);
        if (blog is null)
        {
            try
            {
                db.Blogs.Add(new Blog { PublicId = id, Name = name, ETag = etag, CreateHash = etag });
                await db.SaveChangesAsync(ct);
                Response.Headers["ETag"] = etag;
                return Created($"/api/blogs/{id:D}", new BlogDto(id, name));
            }
            catch (DbUpdateException)
            {
                db.ChangeTracker.Clear();
                blog = await Find(id, ct);
                if (blog is null) throw;
            }
        }

        if (blog.DeletedAt is not null) return Fail(410, "Gone");
        if (blog.CreateHash != etag) return Fail(409, "Conflict");
        Response.Headers["ETag"] = blog.ETag;
        return Ok(new BlogDto(id, blog.Name));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(BlogDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var blog = await Find(id, ct);
        if (blog is null) return Fail(404, "Not found");
        if (blog.DeletedAt is not null) return Fail(410, "Gone");
        Response.Headers["ETag"] = blog.ETag;
        if (Etags.Matches(Request.Headers["If-None-Match"], blog.ETag)) return StatusCode(StatusCodes.Status304NotModified);
        return Ok(new BlogDto(id, blog.Name));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody, Required] BlogRequest body, CancellationToken ct)
    {
        if (body.Id != id || string.IsNullOrWhiteSpace(body.Name)) return Fail(400, "Invalid body");
        if (IfMatch == "") return Fail(428, "If-Match header is required");

        var name = body.Name.Normalize(NormalizationForm.FormC);
        var etag = Etags.Blog(id, name);
        var blog = await Find(id, ct);
        if (blog is null) return Fail(404, "Not found");
        if (blog.DeletedAt is not null) return Fail(410, "Gone");
        if (blog.ETag == etag)
        {
            Response.Headers["ETag"] = blog.ETag;
            return NoContent();
        }
        if (!Etags.Matches(IfMatch, blog.ETag)) return Stale(blog.ETag);

        blog.Name = name;
        blog.ETag = etag;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var current = await Find(id, ct);
            if (current is null) return Fail(404, "Not found");
            return current.DeletedAt is not null ? Fail(410, "Gone") : Stale(current.ETag);
        }
        Response.Headers["ETag"] = etag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        if (IfMatch == "") return Fail(428, "If-Match header is required");
        var blog = await Find(id, ct);
        if (blog is null || blog.DeletedAt is not null) return NoContent();
        if (!Etags.Matches(IfMatch, blog.ETag)) return Stale(blog.ETag);

        var now = DateTimeOffset.UtcNow;
        blog.DeletedAt = now;
        blog.ETag = Guid.NewGuid().ToString("N");
        foreach (var post in await db.Posts.Where(p => p.BlogId == blog.Id).ToListAsync(ct))
        {
            post.DeletedAt = now;
            post.ETag = Guid.NewGuid().ToString("N");
        }
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var current = await Find(id, ct);
            return current is null || current.DeletedAt is not null ? NoContent() : Stale(current.ETag);
        }
        return NoContent();
    }

    Task<Blog?> Find(Guid id, CancellationToken ct) =>
        db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == id, ct);
}
