[Route("api/support-tickets")]
public class SupportTicketsController(TicketsDbContext db) : ControllerBase
{
    [HttpPost]
    public async Task<ActionResult<TicketResponse>> Create([FromBody] TicketRequest request, CancellationToken ct)
    {
        if (Validate(request) is { } error) return BadRequest(error);

        var key = Request.Headers["Idempotency-Key"].FirstOrDefault();
        if (key is not null)
        {
            var existing = await db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.IdempotencyKey == key, ct);
            if (existing is not null) return Ok(ToResponse(existing));
        }

        var ticket = new Ticket
        {
            Id = Guid.NewGuid(),
            Subject = request.Subject!,
            Priority = request.Priority,
            Escalated = request.Escalated,
            Category = request.Category!,
            Version = 1,
            IdempotencyKey = key
        };
        db.Tickets.Add(ticket);

        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException) when (key is not null)
        {
            db.ChangeTracker.Clear();
            var existing = await db.Tickets.AsNoTracking().FirstAsync(t => t.IdempotencyKey == key, ct);
            return Ok(ToResponse(existing));
        }

        return CreatedAtAction(nameof(Get), new { id = ticket.Id }, ToResponse(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> Get(Guid id, CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        var updated = await db.Tickets.Where(t => t.Id == id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, now), ct);
        if (updated == 0) return NotFound();

        var ticket = await db.Tickets.AsNoTracking().FirstAsync(t => t.Id == id, ct);
        Response.Headers.ETag = $"\"{ticket.Version}\"";
        return ToResponse(ticket);
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> Update(Guid id, [FromBody] TicketRequest request, CancellationToken ct)
    {
        if (Validate(request) is { } error) return BadRequest(error);

        var ticket = await db.Tickets.FirstOrDefaultAsync(t => t.Id == id, ct);
        if (ticket is null) return NotFound();

        var ifMatch = Request.Headers["If-Match"].FirstOrDefault();
        if (ifMatch is not null && int.TryParse(ifMatch.Trim('"'), out var expected) && expected != ticket.Version)
            return Conflict();

        ticket.Subject = request.Subject!;
        ticket.Priority = request.Priority;
        ticket.Escalated = request.Escalated;
        ticket.Category = request.Category!;
        ticket.Version++;

        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }

        Response.Headers.ETag = $"\"{ticket.Version}\"";
        return ToResponse(ticket);
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var deleted = await db.Tickets.Where(t => t.Id == id).ExecuteDeleteAsync(ct);
        return deleted == 0 ? NotFound() : NoContent();
    }

    private static string? Validate(TicketRequest request) =>
        string.IsNullOrWhiteSpace(request.Subject) || string.IsNullOrWhiteSpace(request.Category)
            ? "Subject and category are required."
            : null;

    private static TicketResponse ToResponse(Ticket t) =>
        new(t.Id, t.Subject, t.Priority, t.Escalated, t.Category, t.ViewCount, t.LastViewedAt);
}

