using System.ComponentModel.DataAnnotations;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

public static class Canonical
{
    public static string Blog(Guid id, string name) =>
        Hash($"{{\"id\":\"{id:D}\",\"name\":{Str(name)}}}");

    public static string Post(Guid id, Guid blogId, string title) =>
        Hash($"{{\"id\":\"{id:D}\",\"blogId\":\"{blogId:D}\",\"title\":{Str(title)}}}");

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s.Normalize(NormalizationForm.FormC))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append($"\\u{(int)c:x4}");
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }

    static string Hash(string json) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(json)))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
}

public abstract class EtagControllerBase : ControllerBase
{
    protected bool HasIfMatch => Request.Headers.IfMatch.Count > 0;

    protected bool IfMatchOk(string etag) => Request.Headers.IfMatch.Any(h => Tags(h).Any(t => t == "*" || t == etag));

    protected bool IfNoneMatchOk(string etag) => Request.Headers.IfNoneMatch.Any(h => Tags(h).Any(t => t == "*" || t == etag));

    protected IActionResult Fail(int status, string title) => Problem(title: title, statusCode: status);

    protected IActionResult Precondition(string etag)
    {
        Response.Headers.ETag = etag;
        return Fail(412, "Precondition Failed");
    }

    protected static bool IsUnique(DbUpdateException ex) =>
        ex.InnerException is SqliteException { SqliteExtendedErrorCode: 2067 or 1555 };

    static IEnumerable<string> Tags(string? header) => (header ?? "").Split(',').Select(s => s.Trim());
}

[ApiController]
[Route("api/blogs")]
public class BlogsController(AppDbContext db) : EtagControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(BlogDto), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogDto), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, Required] BlogRequest? body, CancellationToken ct)
    {
        if (body is null || body.Id == Guid.Empty || string.IsNullOrWhiteSpace(body.Name)) return Fail(400, "Invalid Request");
        var name = body.Name.Normalize(NormalizationForm.FormC);
        var etag = Canonical.Blog(body.Id, name);

        db.Blogs.Add(new Blog { PublicId = body.Id, Name = name, ETag = etag, CreateHash = etag });
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (IsUnique(ex))
        {
            db.ChangeTracker.Clear();
            var existing = await db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == body.Id, ct);
            if (existing is null) return Fail(409, "Conflict");
            if (existing.DeletedAt is not null) return Fail(410, "Gone");
            if (existing.CreateHash != etag) return Fail(409, "Conflict");
            Response.Headers.ETag = existing.ETag;
            return Ok(new BlogDto(existing.PublicId, existing.Name));
        }

        Response.Headers.ETag = etag;
        return Created($"/api/blogs/{body.Id:D}", new BlogDto(body.Id, name));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(BlogDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var blog = await db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null) return Fail(404, "Not Found");
        if (blog.DeletedAt is not null) return Fail(410, "Gone");
        Response.Headers.ETag = blog.ETag;
        if (IfNoneMatchOk(blog.ETag)) return StatusCode(StatusCodes.Status304NotModified);
        return Ok(new BlogDto(blog.PublicId, blog.Name));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromBody, Required] BlogRequest? body, CancellationToken ct)
    {
        if (body is null || body.Id != id || string.IsNullOrWhiteSpace(body.Name)) return Fail(400, "Invalid Request");
        if (!HasIfMatch) return Fail(428, "Precondition Required");
        var name = body.Name.Normalize(NormalizationForm.FormC);
        var etag = Canonical.Blog(id, name);

        var blog = await db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null) return Fail(404, "Not Found");
        if (blog.DeletedAt is not null) return Fail(410, "Gone");
        if (blog.ETag == etag)
        {
            Response.Headers.ETag = etag;
            return NoContent();
        }
        if (!IfMatchOk(blog.ETag)) return Precondition(blog.ETag);

        blog.Name = name;
        blog.ETag = etag;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var current = await db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == id, ct);
            if (current is null) return Fail(404, "Not Found");
            if (current.DeletedAt is not null) return Fail(410, "Gone");
            if (current.ETag == etag)
            {
                Response.Headers.ETag = etag;
                return NoContent();
            }
            return Precondition(current.ETag);
        }

        Response.Headers.ETag = etag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        if (!HasIfMatch) return Fail(428, "Precondition Required");
        var blog = await db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null || blog.DeletedAt is not null) return NoContent();
        if (!IfMatchOk(blog.ETag)) return Precondition(blog.ETag);

        var now = DateTime.UtcNow;
        await using var tx = await db.Database.BeginTransactionAsync(ct);
        blog.DeletedAt = now;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var current = await db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == id, ct);
            return current is null || current.DeletedAt is not null ? NoContent() : Precondition(current.ETag);
        }

        await db.Posts.IgnoreQueryFilters()
            .Where(p => p.BlogId == blog.Id && p.DeletedAt == null)
            .ExecuteUpdateAsync(s => s.SetProperty(p => p.DeletedAt, (DateTime?)now), ct);
        await tx.CommitAsync(ct);
        return NoContent();
    }
}

[ApiController]
[Route("api")]
public class PostsController(AppDbContext db) : EtagControllerBase
{
    [HttpPost("blogs/{blogId:guid}/posts")]
    [ProducesResponseType(typeof(PostDto), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(PostDto), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create(Guid blogId, [FromBody, Required] PostRequest? body, CancellationToken ct)
    {
        if (body is null || body.Id == Guid.Empty || body.BlogId != blogId || string.IsNullOrWhiteSpace(body.Title))
            return Fail(400, "Invalid Request");

        var blog = await db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == blogId, ct);
        if (blog is null) return Fail(404, "Not Found");
        if (blog.DeletedAt is not null) return Fail(410, "Gone");

        var title = body.Title.Normalize(NormalizationForm.FormC);
        var etag = Canonical.Post(body.Id, blogId, title);
        db.Posts.Add(new Post
        {
            PublicId = body.Id, BlogId = blog.Id, BlogPublicId = blogId,
            Title = title, ETag = etag, CreateHash = etag
        });
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (IsUnique(ex))
        {
            db.ChangeTracker.Clear();
            var existing = await db.Posts.IgnoreQueryFilters().FirstOrDefaultAsync(p => p.PublicId == body.Id, ct);
            if (existing is null) return Fail(409, "Conflict");
            if (existing.DeletedAt is not null) return Fail(410, "Gone");
            if (existing.BlogPublicId != blogId || existing.CreateHash != etag) return Fail(409, "Conflict");
            Response.Headers.ETag = existing.ETag;
            return Ok(new PostDto(existing.PublicId, existing.BlogPublicId, existing.Title));
        }

        Response.Headers.ETag = etag;
        return Created($"/api/posts/{body.Id:D}", new PostDto(body.Id, blogId, title));
    }

    [HttpGet("posts/{id:guid}")]
    [ProducesResponseType(typeof(PostDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var post = await db.Posts.IgnoreQueryFilters().FirstOrDefaultAsync(p => p.PublicId == id, ct);
        if (post is null) return Fail(404, "Not Found");
        if (post.DeletedAt is not null) return Fail(410, "Gone");
        Response.Headers.ETag = post.ETag;
        if (IfNoneMatchOk(post.ETag)) return StatusCode(StatusCodes.Status304NotModified);

        await db.Posts.Where(p => p.Id == post.Id)
            .ExecuteUpdateAsync(s => s.SetProperty(p => p.Views, p => p.Views + 1), ct);
        return Ok(new PostDto(post.PublicId, post.BlogPublicId, post.Title));
    }

    [HttpPut("posts/{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromBody, Required] PostRequest? body, CancellationToken ct)
    {
        if (body is null || body.Id != id || body.BlogId == Guid.Empty || string.IsNullOrWhiteSpace(body.Title))
            return Fail(400, "Invalid Request");
        if (!HasIfMatch) return Fail(428, "Precondition Required");
        var title = body.Title.Normalize(NormalizationForm.FormC);
        var etag = Canonical.Post(id, body.BlogId, title);

        var post = await db.Posts.IgnoreQueryFilters().FirstOrDefaultAsync(p => p.PublicId == id, ct);
        if (post is null) return Fail(404, "Not Found");
        if (post.DeletedAt is not null) return Fail(410, "Gone");
        if (post.ETag == etag)
        {
            Response.Headers.ETag = etag;
            return NoContent();
        }
        if (post.BlogPublicId != body.BlogId) return Fail(409, "Moving a post to another blog is not allowed");
        if (!IfMatchOk(post.ETag)) return Precondition(post.ETag);

        post.Title = title;
        post.ETag = etag;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var current = await db.Posts.IgnoreQueryFilters().FirstOrDefaultAsync(p => p.PublicId == id, ct);
            if (current is null) return Fail(404, "Not Found");
            if (current.DeletedAt is not null) return Fail(410, "Gone");
            if (current.ETag == etag)
            {
                Response.Headers.ETag = etag;
                return NoContent();
            }
            return Precondition(current.ETag);
        }

        Response.Headers.ETag = etag;
        return NoContent();
    }

    [HttpDelete("posts/{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        if (!HasIfMatch) return Fail(428, "Precondition Required");
        var post = await db.Posts.IgnoreQueryFilters().FirstOrDefaultAsync(p => p.PublicId == id, ct);
        if (post is null || post.DeletedAt is not null) return NoContent();
        if (!IfMatchOk(post.ETag)) return Precondition(post.ETag);

        post.DeletedAt = DateTime.UtcNow;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var current = await db.Posts.IgnoreQueryFilters().FirstOrDefaultAsync(p => p.PublicId == id, ct);
            return current is null || current.DeletedAt is not null ? NoContent() : Precondition(current.ETag);
        }
        return NoContent();
    }
}
