[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController(TicketDbContext db) : ControllerBase
{
    private const int MaxUpdateAttempts = 3;

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] TicketInput input)
    {
        var key = Request.Headers["Idempotency-Key"].FirstOrDefault();
        if (await ReplayAsync(key) is { } replay) return replay;

        var ticket = new Ticket
        {
            Id = Guid.NewGuid(),
            Subject = input.Subject,
            Priority = input.Priority,
            Escalated = input.Escalated,
            Category = input.Category
        };
        db.Tickets.Add(ticket);
        if (key is not null) db.IdempotencyRecords.Add(new IdempotencyRecord { Key = key, TicketId = ticket.Id });

        try
        {
            await db.SaveChangesAsync();
        }
        catch (DbUpdateException) when (key is not null)
        {
            db.ChangeTracker.Clear();
            if (await ReplayAsync(key) is { } raced) return raced;
            throw;
        }

        return Created(Location(ticket.Id), ToDto(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id)
    {
        var updated = await db.Tickets
            .Where(t => t.Id == id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, DateTime.UtcNow));
        if (updated == 0) return NotFound();

        var ticket = await Find(id);
        return ticket is null ? NotFound() : Ok(ToDto(ticket));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] TicketInput input)
    {
        for (var attempt = 1; ; attempt++)
        {
            var ticket = await db.Tickets.FirstOrDefaultAsync(t => t.Id == id);
            if (ticket is null) return NotFound();

            ticket.Subject = input.Subject;
            ticket.Priority = input.Priority;
            ticket.Escalated = input.Escalated;
            ticket.Category = input.Category;
            ticket.Version++;

            try
            {
                await db.SaveChangesAsync();
                return Ok(ToDto(ticket));
            }
            catch (DbUpdateConcurrencyException) when (attempt < MaxUpdateAttempts)
            {
                db.ChangeTracker.Clear();
            }
            catch (DbUpdateConcurrencyException)
            {
                return Conflict();
            }
        }
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        await db.Tickets.Where(t => t.Id == id).ExecuteDeleteAsync();
        return NoContent();
    }

    private async Task<Ticket?> Find(Guid id) =>
        await db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id);

    private async Task<IActionResult?> ReplayAsync(string? key)
    {
        if (key is null) return null;
        var record = await db.IdempotencyRecords.AsNoTracking().FirstOrDefaultAsync(r => r.Key == key);
        if (record is null) return null;
        var ticket = await Find(record.TicketId);
        return ticket is null ? Conflict() : Created(Location(ticket.Id), ToDto(ticket));
    }

    private static string Location(Guid id) => $"/api/support-tickets/{id}";

    private static TicketDto ToDto(Ticket t) => new(t.Id, t.Subject, t.Priority, t.Escalated, t.Category);
}
