        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException) when (request.Id is not null)
        {
            return Conflict();
        }

        return Created($"/api/support-tickets/{ticket.Id}", Present(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        var viewed = await db.Tickets.Where(t => t.Id == id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, now), ct);
        if (viewed == 0) return NotFound();

        var ticket = await db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id, ct);
        return ticket is null ? NotFound() : Ok(Present(ticket));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, TicketRequest request, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(request.Subject)) return BadRequest("Subject is required.");

        var ticket = await db.Tickets.FirstOrDefaultAsync(t => t.Id == id, ct);
        if (ticket is null) return NotFound();

        var ifMatch = Request.Headers["If-Match"].ToString();
        if (ifMatch.Length > 0 && ifMatch != ETagOf(ticket)) return StatusCode(StatusCodes.Status412PreconditionFailed);

        ticket.Subject = request.Subject;
        ticket.Priority = request.Priority;
        ticket.Escalated = request.Escalated;
        ticket.Category = request.Category ?? string.Empty;
        ticket.ConcurrencyStamp = Guid.NewGuid();

        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }

        return Ok(Present(ticket));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        await db.Tickets.Where(t => t.Id == id).ExecuteDeleteAsync(ct);
        return NoContent();
    }

    private TicketResponse Present(Ticket ticket)
    {
        Response.Headers["ETag"] = ETagOf(ticket);
        return TicketResponse.From(ticket);
    }

    private static string ETagOf(Ticket ticket) => $"\"{ticket.ConcurrencyStamp:N}\"";
}
