using System.Buffers.Text;
using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;
using Microsoft.Data.Sqlite;

public sealed class Ticket
{
    public int Id { get; set; }
    public Guid PublicId { get; set; }
    public string Subject { get; set; } = "";
    public int Priority { get; set; }
    public bool Escalated { get; set; }
    public string Category { get; set; } = "";
    public string ETag { get; set; } = "";
    public string CreateHash { get; set; } = "";
    public int ViewCount { get; set; }
    public DateTime? LastViewedAt { get; set; }
    public DateTime? DeletedAt { get; set; }
}

public sealed class TicketDbContext(DbContextOptions<TicketDbContext> options) : DbContext(options)
{
    public DbSet<Ticket> Tickets => Set<Ticket>();

    protected override void OnModelCreating(ModelBuilder mb)
    {
        mb.Entity<Ticket>(e =>
        {
            e.HasKey(t => t.Id);
            e.HasIndex(t => t.PublicId).IsUnique();
            e.Property(t => t.Subject).IsRequired().HasMaxLength(200);
            e.Property(t => t.Category).IsRequired().HasMaxLength(100);
            e.Property(t => t.ETag).IsRequired().IsConcurrencyToken();
            e.Property(t => t.CreateHash).IsRequired().Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            e.HasQueryFilter(t => t.DeletedAt == null);
        });
    }
}

public sealed record SupportTicketDto(Guid Id, string Subject, int Priority, bool Escalated, string Category);

public sealed record SupportTicketRequest(Guid? Id, string? Subject, int? Priority, bool? Escalated, string? Category);

public static class Canon
{
    public static string Nfc(string s) => s.Normalize(NormalizationForm.FormC);

    public static string Etag(Guid id, string subject, int priority, bool escalated, string category)
    {
        var esc = escalated ? "true" : "false";
        var json = $"{{\"id\":\"{id:D}\",\"subject\":{Str(subject)},\"priority\":{priority.ToString(CultureInfo.InvariantCulture)},\"escalated\":{esc},\"category\":{Str(category)}}}";
        return "\"" + Base64Url.EncodeToString(SHA256.HashData(Encoding.UTF8.GetBytes(json))) + "\"";
    }

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in Nfc(s))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }
}

public static class AppSetup
{
    public static void ConfigureServices(IServiceCollection services, string sqliteConnectionString)
    {
        services.AddDbContext<TicketDbContext>(o => o.UseSqlite(sqliteConnectionString));
        services.Configure<ApiBehaviorOptions>(o => o.SuppressModelStateInvalidFilter = true);
    }
}
