using System.ComponentModel.DataAnnotations;
using System.Diagnostics.CodeAnalysis;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/support-tickets")]
public sealed class SupportTicketsController(TicketDbContext db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(SupportTicketDto), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(SupportTicketDto), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, Required] SupportTicketRequest? body, CancellationToken ct)
    {
        if (!IsValid(body)) return Error(StatusCodes.Status400BadRequest, "Invalid support ticket.");

        var id = body.Id!.Value;
        var subject = Canon.Nfc(body.Subject!);
        var category = Canon.Nfc(body.Category!);
        var priority = body.Priority!.Value;
        var escalated = body.Escalated!.Value;
        var etag = Canon.Etag(id, subject, priority, escalated, category);

        var ticket = new Ticket
        {
            PublicId = id, Subject = subject, Priority = priority, Escalated = escalated,
            Category = category, ETag = etag, CreateHash = etag
        };
        db.Tickets.Add(ticket);
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (IsUniqueViolation(ex))
        {
            var existing = await db.Tickets.IgnoreQueryFilters().AsNoTracking()
                .FirstAsync(t => t.PublicId == id, ct);
            if (existing.DeletedAt is not null) return Error(StatusCodes.Status410Gone, "Support ticket was deleted.");
            if (existing.CreateHash != etag) return Error(StatusCodes.Status409Conflict, "Support ticket id already exists with different content.");
            Response.Headers.ETag = existing.ETag;
            return Ok(ToDto(existing));
        }

        Response.Headers.ETag = etag;
        Response.Headers.Location = $"/api/support-tickets/{id:D}";
        return StatusCode(StatusCodes.Status201Created, ToDto(ticket));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(SupportTicketDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, [FromHeader(Name = "If-None-Match")] string? ifNoneMatch, CancellationToken ct)
    {
        var ticket = await db.Tickets.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(t => t.PublicId == id, ct);
        if (ticket is null) return Error(StatusCodes.Status404NotFound, "Support ticket not found.");
        if (ticket.DeletedAt is not null) return Error(StatusCodes.Status410Gone, "Support ticket was deleted.");

        await db.Tickets.Where(t => t.PublicId == id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, DateTime.UtcNow), ct);

        Response.Headers.ETag = ticket.ETag;
        if (ifNoneMatch is not null && Matches(ifNoneMatch, ticket.ETag)) return StatusCode(StatusCodes.Status304NotModified);
        return Ok(ToDto(ticket));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
