    public async Task<IActionResult> Put(Guid id, [FromBody, Required] SupportTicketRequest? body,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (!IsValid(body) || body.Id != id) return Error(StatusCodes.Status400BadRequest, "Invalid support ticket.");
        if (ifMatch is null) return Error(StatusCodes.Status428PreconditionRequired, "If-Match header is required.");

        var ticket = await db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(t => t.PublicId == id, ct);
        if (ticket is null) return Error(StatusCodes.Status404NotFound, "Support ticket not found.");
        if (ticket.DeletedAt is not null) return Error(StatusCodes.Status410Gone, "Support ticket was deleted.");

        var subject = Canon.Nfc(body.Subject!);
