        if (t.ETag == c.ETag)
        {
            Response.Headers["ETag"] = c.ETag;
            return NoContent();
        }
        if (!Matches(ifMatch, t.ETag)) return Precondition(t.ETag);

        t.Subject = c.Subject;
        t.Priority = c.Priority;
        t.Escalated = c.Escalated;
        t.Category = c.Category;
        t.ETag = c.ETag;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await Current(id, ct);
            return current is null ? Problem(statusCode: 404)
                : current.DeletedAt is not null ? Problem(statusCode: 410)
                : Precondition(current.ETag);
        }
        Response.Headers["ETag"] = c.ETag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [Required, FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken ct)
    {
        if (ifMatch is null) return Problem(statusCode: 428);
        var t = await FindLive(id, ct);
        if (t is null) return NoContent();
        if (!Matches(ifMatch, t.ETag)) return Precondition(t.ETag);

        t.DeletedAt = DateTime.UtcNow;
        t.ETag = $"\"deleted-{Guid.NewGuid():N}\"";
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await Current(id, ct);
            return current is { DeletedAt: null } ? Precondition(current.ETag) : NoContent();
        }
        return NoContent();
    }

    Task<Ticket?> FindLive(Guid id, CancellationToken ct) =>
        db.Tickets.FirstOrDefaultAsync(x => x.PublicId == id, ct);

    Task<Ticket?> Current(Guid id, CancellationToken ct) =>
        db.Tickets.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);

    Task<bool> IsDeleted(Guid id, CancellationToken ct) =>
        db.Tickets.IgnoreQueryFilters().AnyAsync(x => x.PublicId == id && x.DeletedAt != null, ct);

    IActionResult Precondition(string etag)
    {
        Response.Headers["ETag"] = etag;
        return Problem(statusCode: 412);
    }

    static bool Matches(string? header, string etag) =>
        header is not null && header.Split(',').Any(v => { var s = v.Trim(); return s == "*" || s == etag; });

    static Ticket? ToCandidate(TicketRequest? b)
    {
        if (b is null || b.Id is null || b.Priority is null || b.Escalated is null
            || string.IsNullOrWhiteSpace(b.Subject) || string.IsNullOrWhiteSpace(b.Category)) return null;
        var t = new Ticket
        {
            PublicId = b.Id.Value,
            Subject = Ticket.Nfc(b.Subject),
            Priority = b.Priority.Value,
            Escalated = b.Escalated.Value,
            Category = Ticket.Nfc(b.Category),
        };
        t.ETag = Ticket.ComputeETag(t.PublicId, t.Subject, t.Priority, t.Escalated, t.Category);
        return t;
    }

    static TicketDto ToDto(Ticket t) => new(t.PublicId, t.Subject, t.Priority, t.Escalated, t.Category);
}
