// Models.cs
using System.ComponentModel.DataAnnotations;
using System.Security.Cryptography;
using System.Text;

public class Ticket
{
    public int Id { get; set; }
    public Guid PublicId { get; set; }
    public string Subject { get; set; } = "";
    public int Priority { get; set; }
    public bool Escalated { get; set; }
    public string Category { get; set; } = "";
    public string ETag { get; set; } = "";
    public string CreateRequestHash { get; set; } = "";
    public int ViewCount { get; set; }
    public DateTime? LastViewedAt { get; set; }
    public DateTime? DeletedAt { get; set; }

    public static string Nfc(string s) => s.Normalize(NormalizationForm.FormC);

    public static string Canonical(Guid id, string subject, int priority, bool escalated, string category)
    {
        var esc = escalated ? "true" : "false";
        return "{\"id\":" + Json(id.ToString()) +
               ",\"subject\":" + Json(subject) +
               ",\"priority\":" + priority.ToString(System.Globalization.CultureInfo.InvariantCulture) +
               ",\"escalated\":" + esc +
               ",\"category\":" + Json(category) + "}";
    }

    public static string ComputeEtag(string canonical)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return "\"" + Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    private static string Json(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in Nfc(s))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append($"\\u{(int)c:x4}");
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }
}

public class TicketRequest
{
    [Required] public Guid? Id { get; set; }
    [Required(AllowEmptyStrings = false)] public string? Subject { get; set; }
    [Required] public int? Priority { get; set; }
    [Required] public bool? Escalated { get; set; }
    [Required(AllowEmptyStrings = false)] public string? Category { get; set; }
}

public record TicketResponse(Guid Id, string Subject, int Priority, bool Escalated, string Category);
