// Marks If-Match as required in OpenAPI while still letting the action return 428 itself.
internal sealed class IfMatchRequiredProvider : IApiDescriptionProvider
{
    public int Order => 0;
    public void OnProvidersExecuting(ApiDescriptionProviderContext context) { }
    public void OnProvidersExecuted(ApiDescriptionProviderContext context)
    {
        foreach (var d in context.Results)
            if (d.HttpMethod is "PUT" or "DELETE")
                foreach (var p in d.ParameterDescriptions)
                    if (p.Source == Microsoft.AspNetCore.Mvc.ModelBinding.BindingSource.Header)
                        p.IsRequired = true;
    }
}

