using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController(TicketDb db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] TicketRequest body, CancellationToken ct)
    {
        var ticket = new Ticket { PublicId = body.Id!.Value };
        Apply(ticket, body);
        ticket.CreateRequestHash = ticket.ETag;
        db.Tickets.Add(ticket);
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (ex.InnerException is SqliteException { SqliteExtendedErrorCode: 2067 })
        {
            db.ChangeTracker.Clear();
            var existing = await db.Tickets.IgnoreQueryFilters().AsNoTracking()
                .SingleAsync(x => x.PublicId == ticket.PublicId, ct);
            if (existing.DeletedAt is not null) return Fail(410, "Gone");
            if (existing.CreateRequestHash != ticket.CreateRequestHash) return Fail(409, "Conflict");
            Response.Headers.ETag = existing.ETag;
            return Ok(ToResponse(existing));
        }
        Response.Headers.ETag = ticket.ETag;
        return Created($"/api/support-tickets/{ticket.PublicId}", ToResponse(ticket));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var t = await db.Tickets.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null) return Fail(404, "Not Found");
        if (t.DeletedAt is not null) return Fail(410, "Gone");

        await db.Tickets.Where(x => x.PublicId == id && x.DeletedAt == null)
            .ExecuteUpdateAsync(s => s
                .SetProperty(x => x.ViewCount, x => x.ViewCount + 1)
                .SetProperty(x => x.LastViewedAt, (DateTime?)DateTime.UtcNow), ct);

        Response.Headers.ETag = t.ETag;
        if (Matches(Request.Headers.IfNoneMatch.ToString(), t.ETag)) return StatusCode(StatusCodes.Status304NotModified);
        return Ok(ToResponse(t));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody] TicketRequest body, [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken ct)
    {
        if (body.Id != id) return Fail(400, "Route id and body id differ");
        if (string.IsNullOrEmpty(ifMatch)) return Fail(428, "Precondition Required");

        var t = await db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null) return Fail(404, "Not Found");
        if (t.DeletedAt is not null) return Fail(410, "Gone");

        var newEtag = Etag(body);
        Response.Headers.ETag = t.ETag;
        if (t.ETag == newEtag) return NoContent();
        if (!Matches(ifMatch, t.ETag)) return Fail(412, "Precondition Failed");

        Apply(t, body);
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            return await Stale(id, ct);
        }
        Response.Headers.ETag = t.ETag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch)) return Fail(428, "Precondition Required");

        var t = await db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null || t.DeletedAt is not null) return NoContent();
        if (!Matches(ifMatch, t.ETag))
        {
            Response.Headers.ETag = t.ETag;
            return Fail(412, "Precondition Failed");
        }

        t.DeletedAt = DateTime.UtcNow;
        t.ETag = Ticket.ComputeEtag(Guid.NewGuid().ToString());
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var alreadyDeleted = await db.Tickets.IgnoreQueryFilters()
                .AnyAsync(x => x.PublicId == id && x.DeletedAt != null, ct);
            return alreadyDeleted ? NoContent() : await Stale(id, ct);
        }
        return NoContent();
    }

    private async Task<IActionResult> Stale(Guid id, CancellationToken ct)
    {
        var cur = await db.Tickets.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (cur is null) return Fail(404, "Not Found");
        if (cur.DeletedAt is not null) return Fail(410, "Gone");
        Response.Headers.ETag = cur.ETag;
        return Fail(412, "Precondition Failed");
    }

    private ObjectResult Fail(int status, string title) =>
        new(new ProblemDetails { Status = status, Title = title }) { StatusCode = status, ContentType = "application/problem+json" };

    private static bool Matches(string? header, string etag) =>
        header is not null && header.Split(',').Select(v => v.Trim()).Any(v => v == "*" || v == etag);

    private static string Etag(TicketRequest b) =>
        Ticket.ComputeEtag(Ticket.Canonical(b.Id!.Value, b.Subject!, b.Priority!.Value, b.Escalated!.Value, b.Category!));

    private static void Apply(Ticket t, TicketRequest b)
    {
        t.Subject = Ticket.Nfc(b.Subject!);
        t.Priority = b.Priority!.Value;
        t.Escalated = b.Escalated!.Value;
        t.Category = Ticket.Nfc(b.Category!);
        t.ETag = Etag(b);
    }

    private static TicketResponse ToResponse(Ticket t) => new(t.PublicId, t.Subject, t.Priority, t.Escalated, t.Category);
}
