    {
        if (!IsValid(request)) return BadRequest();
        var shipment = await db.Consignments.FirstOrDefaultAsync(c => c.Id == id, ct);
        if (shipment is null) return NotFound();
        var warehouseId = request.WarehouseId ?? shipment.WarehouseId;
        if (!await db.Depots.AnyAsync(d => d.Id == warehouseId, ct)) return BadRequest();
        shipment.WarehouseId = warehouseId;
        shipment.Reference = request.Reference;
        shipment.WeightKg = request.WeightKg;
        shipment.Fragile = request.Fragile;
        await db.SaveChangesAsync(ct);
        await TouchWarehouse(warehouseId, ct);
        return ToResponse(shipment);
