        var shipment = await db.Consignments.FirstOrDefaultAsync(c => c.Id == id, ct);
        if (shipment is null) return NotFound();
        db.Consignments.Remove(shipment);
        await db.SaveChangesAsync(ct);
        await TouchWarehouse(shipment.WarehouseId, ct);
