```csharp
using System.ComponentModel.DataAnnotations;
using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

namespace SupportTickets;

public record TicketRequest(Guid? Id, string? Subject, int? Priority, bool? Escalated, string? Category);

public record TicketResponse(Guid Id, string Subject, int Priority, bool Escalated, string Category);

public sealed record TicketValues(Guid Id, string Subject, int Priority, bool Escalated, string Category)
{
    public string ETag => TicketCanon.ETagOf(this);
}

public static class TicketCanon
{
    public static string Canonical(TicketValues v) =>
        "{\"id\":\"" + v.Id.ToString("D") + "\",\"subject\":" + Str(v.Subject) +
        ",\"priority\":" + v.Priority.ToString(CultureInfo.InvariantCulture) +
        ",\"escalated\":" + (v.Escalated ? "true" : "false") +
        ",\"category\":" + Str(v.Category) + "}";

    public static string ETagOf(TicketValues v) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(Canonical(v))))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var ch in s.Normalize(NormalizationForm.FormC))
            sb.Append(ch switch
            {
                '"' => "\\\"",
                '\\' => "\\\\",
                '\b' => "\\b",
                '\f' => "\\f",
                '\n' => "\\n",
                '\r' => "\\r",
                '\t' => "\\t",
                _ when ch < 0x20 => $"\\u{(int)ch:x4}",
                _ => ch.ToString()
            });
        return sb.Append('"').ToString();
    }
}

[Route("api/support-tickets")]
public class SupportTicketsController(TicketsDbContext db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, Required] TicketRequest? body, CancellationToken ct)
    {
        var v = Validate(body);
        if (v is null) return Fail(400, "Invalid support ticket.");

        var ticket = new Ticket
        {
            PublicId = v.Id, Subject = v.Subject, Priority = v.Priority, Escalated = v.Escalated,
            Category = v.Category, ETag = v.ETag, RequestHash = v.ETag
        };
        db.Tickets.Add(ticket);
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (ex.InnerException is SqliteException { SqliteExtendedErrorCode: 2067 })
        {
            db.ChangeTracker.Clear();
            var existing = await Find(v.Id, ct);
            if (existing is null) return Fail(409, "Support ticket id is already in use.");
            if (existing.DeletedAt is not null) return Fail(410, "Support ticket was deleted.");
            if (existing.RequestHash != v.ETag) return Fail(409, "Support ticket id is already in use with different content.");
            Response.Headers.ETag = existing.ETag;
            return Ok(ToResponse(existing));
        }

        Response.Headers.ETag = ticket.ETag;
        return Created($"/api/support-tickets/{ticket.PublicId:D}", ToResponse(ticket));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var t = await Find(id, ct);
        if (t is null) return Fail(404, "Support ticket not found.");
        if (t.DeletedAt is not null) return Fail(410, "Support ticket was deleted.");

        Response.Headers.ETag = t.ETag;
        if (Matches(Request.Headers["If-None-Match"], t.ETag)) return StatusCode(StatusCodes.Status304NotModified);

        var now = DateTime.UtcNow;
        await db.Tickets.Where(x => x.PublicId == id).ExecuteUpdateAsync(s => s
            .SetProperty(x => x.ViewCount, x => x.ViewCount + 1)
            .SetProperty(x => x.LastViewedAt, (DateTime?)now), ct);
        return Ok(ToResponse(t));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromBody, Required] TicketRequest? body,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        var v = Validate(body);
        if (v is null || v.Id != id) return Fail(400, "Invalid support ticket.");
        if (ifMatch is null) return Fail(428, "If-Match header is required.");

        var t = await db.Tickets.IgnoreQueryFilters().SingleOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null) return Fail(404, "Support ticket not found.");
        if (t.DeletedAt is not null) return Fail(410, "Support ticket was deleted.");

        Response.Headers.ETag = t.ETag;
        if (t.ETag == v.ETag) return NoContent();
        if (!Matches(ifMatch, t.ETag)) return Fail(412, "ETag does not match the current version.");

        t.Subject = v.Subject;
        t.Priority = v.Priority;
        t.Escalated = v.Escalated;
        t.Category = v.Category;
        t.ETag = v.ETag;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await Stale(id, ct);
        }

        Response.Headers.ETag = v.ETag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (ifMatch is null) return Fail(428, "If-Match header is required.");

        var t = await db.Tickets.IgnoreQueryFilters().SingleOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null || t.DeletedAt is not null) return NoContent();
        if (!Matches(ifMatch, t.ETag))
        {
            Response.Headers.ETag = t.ETag;
            return Fail(412, "ETag does not match the current version.");
        }

        t.DeletedAt = DateTime.UtcNow;
        t.ETag = Guid.NewGuid().ToString("N");
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await Find(id, ct);
            if (cur is null || cur.DeletedAt is not null) return NoContent();
            Response.Headers.ETag = cur.ETag;
            return Fail(412, "ETag does not match the current version.");
        }
        return NoContent();
    }

    async Task<IActionResult> Stale(Guid id, CancellationToken ct)
    {
        var cur = await Find(id, ct);
        if (cur is null) return Fail(404, "Support ticket not found.");
        if (cur.DeletedAt is not null) return Fail(410, "Support ticket was deleted.");
        Response.Headers.ETag = cur.ETag;
        return Fail(412, "ETag does not match the current version.");
    }

    Task<Ticket?> Find(Guid id, CancellationToken ct) =>
        db.Tickets.IgnoreQueryFilters().AsNoTracking().SingleOrDefaultAsync(x => x.PublicId == id, ct);

    static bool Matches(string? header, string etag) =>
        !string.IsNullOrEmpty(header) && header.Split(',').Select(s => s.Trim()).Any(s => s == "*" || s == etag);

    static TicketValues? Validate(TicketRequest? r)
    {
        if (r is null || r.Id is not { } id || r.Priority is not { } priority || r.Escalated is not { } escalated) return null;
        var subject = r.Subject?.Normalize(NormalizationForm.FormC);
        var category = r.Category?.Normalize(NormalizationForm.FormC);
        if (string.IsNullOrWhiteSpace(subject) || string.IsNullOrWhiteSpace(category)) return null;
        return new TicketValues(id, subject, priority, escalated, category);
    }

    static TicketResponse ToResponse(Ticket t) => new(t.PublicId, t.Subject, t.Priority, t.Escalated, t.Category);

    static ObjectResult Fail(int status, string title) =>
        new(new ProblemDetails { Status = status, Title = title }) { StatusCode = status, ContentType = "application/problem+json" };
}

public static class AppSetup
{
    public static void ConfigureServices(IServiceCollection services, string sqliteConnectionString) =>
        services.AddDbContext<TicketsDbContext>(o => o.UseSqlite(sqliteConnectionString));
}
