    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var t = await db.Tickets.IgnoreQueryFilters().AsNoTracking()
            .SingleOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null) return Error(404, "Ticket not found.");
        if (t.DeletedAt is not null) return Error(410, "Ticket was deleted.");
        await db.Tickets.Where(x => x.PublicId == id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(x => x.ViewCount, x => x.ViewCount + 1)
                .SetProperty(x => x.LastViewedAt, DateTime.UtcNow), ct);
        Response.Headers["ETag"] = t.ETag;
        string? ifNoneMatch = Request.Headers["If-None-Match"];
        return ifNoneMatch == t.ETag ? StatusCode(StatusCodes.Status304NotModified) : Ok(ToResponse(t));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody, Required] TicketRequest? body,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (body is null || !Valid(body) || body.Id != id) return Error(400, "Invalid ticket or id mismatch.");
        if (string.IsNullOrEmpty(ifMatch)) return Error(428, "If-Match header is required.");
        var etag = TicketETag.Compute(id, body.Subject, body.Priority, body.Escalated, body.Category);
        var t = await db.Tickets.IgnoreQueryFilters().SingleOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null) return Error(404, "Ticket not found.");
        if (t.DeletedAt is not null) return Error(410, "Ticket was deleted.");
        if (t.ETag == etag)
        {
            Response.Headers["ETag"] = etag;
            return NoContent();
        }
        if (ifMatch != "*" && ifMatch != t.ETag)
        {
            Response.Headers["ETag"] = t.ETag;
            return Error(412, "ETag does not match the current ticket.");
        }
        t.Subject = body.Subject;
        t.Priority = body.Priority;
        t.Escalated = body.Escalated;
        t.Category = body.Category;
        t.ETag = etag;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await db.Tickets.IgnoreQueryFilters().AsNoTracking()
                .Where(x => x.PublicId == id)
                .Select(x => new { x.ETag, x.DeletedAt })
                .SingleOrDefaultAsync(ct);
            if (cur is null) return Error(404, "Ticket not found.");
            if (cur.DeletedAt is not null) return Error(410, "Ticket was deleted.");
            Response.Headers["ETag"] = cur.ETag;
            return cur.ETag == etag ? NoContent() : Error(412, "ETag does not match the current ticket.");
        }
        Response.Headers["ETag"] = etag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch)) return Error(428, "If-Match header is required.");
        var t = await db.Tickets.IgnoreQueryFilters().SingleOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null || t.DeletedAt is not null) return NoContent();
        if (ifMatch != "*" && ifMatch != t.ETag)
        {
            Response.Headers["ETag"] = t.ETag;
            return Error(412, "ETag does not match the current ticket.");
        }
        t.DeletedAt = DateTime.UtcNow;
        t.ETag = "\"" + Guid.NewGuid().ToString("N") + "\"";
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await db.Tickets.IgnoreQueryFilters().AsNoTracking()
                .Where(x => x.PublicId == id)
                .Select(x => new { x.ETag, x.DeletedAt })
                .SingleOrDefaultAsync(ct);
            if (cur is null || cur.DeletedAt is not null) return NoContent();
            Response.Headers["ETag"] = cur.ETag;
            return Error(412, "ETag does not match the current ticket.");
        }
        return NoContent();
    }

    private static bool Valid(TicketRequest b) =>
        b.Id != Guid.Empty && !string.IsNullOrWhiteSpace(b.Subject) && !string.IsNullOrWhiteSpace(b.Category);

    private static bool IsUniqueViolation(DbUpdateException ex) =>
        ex.InnerException is SqliteException { SqliteErrorCode: 19, SqliteExtendedErrorCode: 2067 };

    private static TicketResponse ToResponse(Ticket t) =>
        new(t.PublicId, t.Subject, t.Priority, t.Escalated, t.Category);

    private ObjectResult Error(int status, string title)
    {
        var result = new ObjectResult(new ProblemDetails { Status = status, Title = title }) { StatusCode = status };
        result.ContentTypes.Add("application/problem+json");
        return result;
    }
}
