public class Ticket
{
    public int Id { get; set; }
    public Guid PublicId { get; set; }
    public string Subject { get; set; } = "";
    public int Priority { get; set; }
    public bool Escalated { get; set; }
    public string Category { get; set; } = "";
    public string ETag { get; set; } = "";
    public string RequestHash { get; set; } = "";
    public int ViewCount { get; set; }
    public DateTime? LastViewedAt { get; set; }
    public DateTime? DeletedAt { get; set; }
}

public sealed class SupportTicketDbContext(DbContextOptions<SupportTicketDbContext> options) : DbContext(options)
{
    public DbSet<Ticket> Tickets => Set<Ticket>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Ticket>(e =>
        {
            e.HasKey(t => t.Id);
            e.HasIndex(t => t.PublicId).IsUnique();
            e.Property(t => t.Subject).IsRequired();
            e.Property(t => t.Category).IsRequired();
            e.Property(t => t.ETag).IsRequired().IsConcurrencyToken();
            e.Property(t => t.RequestHash).IsRequired().Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            e.Property(t => t.ViewCount);
            e.Property(t => t.LastViewedAt);
            e.Property(t => t.DeletedAt);
            e.HasQueryFilter(t => t.DeletedAt == null);
        });
    }
}

public sealed record TicketRequest(Guid? Id, string? Subject, int? Priority, bool? Escalated, string? Category);

public sealed record TicketResponse(Guid Id, string Subject, int Priority, bool Escalated, string Category);

public sealed record TicketValues(Guid Id, string Subject, int Priority, bool Escalated, string Category)
{
    public static TicketValues? From(TicketRequest? r) =>
        r is { Id: not null, Subject: not null, Priority: not null, Escalated: not null, Category: not null }
        && !string.IsNullOrWhiteSpace(r.Subject) && !string.IsNullOrWhiteSpace(r.Category)
            ? new TicketValues(r.Id.Value, Nfc(r.Subject), r.Priority.Value, r.Escalated.Value, Nfc(r.Category))
            : null;

    public string ETag
    {
        get
        {
            var id = Id.ToString("D");
            var esc = Escalated ? "true" : "false";
            var json = "{\"id\":\"" + id + "\",\"subject\":" + Str(Subject) + ",\"priority\":" + Priority
                     + ",\"escalated\":" + esc + ",\"category\":" + Str(Category) + "}";
            var hash = SHA256.HashData(Encoding.UTF8.GetBytes(json));
            return "\"" + Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
        }
    }

    public TicketResponse ToResponse() => new(Id, Subject, Priority, Escalated, Category);

    static string Nfc(string s) => s.Normalize(NormalizationForm.FormC);

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s)
            sb.Append(c switch
            {
                '"' => "\\\"",
                '\\' => "\\\\",
                '\b' => "\\b",
                '\f' => "\\f",
                '\n' => "\\n",
                '\r' => "\\r",
                '\t' => "\\t",
                _ when c < 0x20 => $"\\u{(int)c:x4}",
                _ => c.ToString()
            });
        return sb.Append('"').ToString();
    }
}

[ApiController]
[Route("api/support-tickets")]
public sealed class SupportTicketsController(SupportTicketDbContext db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, Required] TicketRequest? body, CancellationToken ct)
    {
        var v = TicketValues.From(body);
        if (v is null) return Fail(400, "Invalid support ticket.");

        var existing = await Find(v.Id, ct);
        if (existing is null)
        {
            db.Tickets.Add(new Ticket
            {
                PublicId = v.Id, Subject = v.Subject, Priority = v.Priority, Escalated = v.Escalated,
                Category = v.Category, ETag = v.ETag, RequestHash = v.ETag
            });
            try
            {
                await db.SaveChangesAsync(ct);
                Response.Headers["ETag"] = v.ETag;
                return Created($"/api/support-tickets/{v.Id:D}", v.ToResponse());
            }
            catch (DbUpdateException ex) when (ex.InnerException is SqliteException { SqliteErrorCode: 19 })
            {
                db.ChangeTracker.Clear();
                existing = await Find(v.Id, ct);
            }
        }

        if (existing is null) return Fail(409, "Conflict.");
        if (existing.DeletedAt is not null) return Fail(410, "Deleted.");
        if (existing.RequestHash != v.ETag) return Fail(409, "Id already used with different content.");
        Response.Headers["ETag"] = existing.ETag;
        return Ok(ToResponse(existing));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var t = await Find(id, ct);
        if (t is null) return Fail(404, "Not found.");
        if (t.DeletedAt is not null) return Fail(410, "Deleted.");
        Response.Headers["ETag"] = t.ETag;
        if (Matches(Request.Headers["If-None-Match"].ToString(), t.ETag)) return StatusCode(304);

        await db.Tickets.Where(x => x.Id == t.Id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(x => x.ViewCount, x => x.ViewCount + 1)
                .SetProperty(x => x.LastViewedAt, DateTime.UtcNow), ct);
        return Ok(ToResponse(t));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        [FromBody, Required] TicketRequest? body, CancellationToken ct)
    {
        var v = TicketValues.From(body);
        if (v is null || v.Id != id) return Fail(400, "Invalid support ticket.");
        if (ifMatch is null) return Fail(428, "If-Match header is required.");

        var t = await Find(id, ct);
        if (t is null) return Fail(404, "Not found.");
        if (t.DeletedAt is not null) return Fail(410, "Deleted.");
        if (t.ETag == v.ETag)
        {
            Response.Headers["ETag"] = t.ETag;
            return NoContent();
        }
        if (!Matches(ifMatch, t.ETag)) return Precondition(t.ETag);

        t.Subject = v.Subject;
        t.Priority = v.Priority;
        t.Escalated = v.Escalated;
        t.Category = v.Category;
        t.ETag = v.ETag;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var cur = await Find(id, ct);
            if (cur is null) return Fail(404, "Not found.");
            if (cur.DeletedAt is not null) return Fail(410, "Deleted.");
            return Precondition(cur.ETag);
        }
        Response.Headers["ETag"] = v.ETag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        CancellationToken ct)
    {
        if (ifMatch is null) return Fail(428, "If-Match header is required.");

        var t = await Find(id, ct);
        if (t is null || t.DeletedAt is not null) return NoContent();
        if (!Matches(ifMatch, t.ETag)) return Precondition(t.ETag);

        t.DeletedAt = DateTime.UtcNow;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var cur = await Find(id, ct);
            if (cur is null || cur.DeletedAt is not null) return NoContent();
            return Precondition(cur.ETag);
        }
        return NoContent();
    }

    // Tracked lookup that sees soft-deleted rows, so 410 can be told apart from 404.
    Task<Ticket?> Find(Guid id, CancellationToken ct) =>
        db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(t => t.PublicId == id, ct);

    IActionResult Precondition(string currentEtag)
    {
        Response.Headers["ETag"] = currentEtag;
        return Fail(412, "The ETag does not match the current version.");
    }

    static TicketResponse ToResponse(Ticket t) => new(t.PublicId, t.Subject, t.Priority, t.Escalated, t.Category);

    static bool Matches(string? header, string etag) =>
        header is not null && header.Split(',').Select(s => s.Trim()).Any(s => s == "*" || s == etag);

    static ContentResult Fail(int status, string title) => new()
    {
        StatusCode = status,
        ContentType = "application/problem+json",
        Content = JsonSerializer.Serialize(new { type = "about:blank", title, status })
    };
}
