        var consignment = await db.Consignments.FirstOrDefaultAsync(c => c.Id == id, ct);
        if (consignment is null) return NotFound();

        consignment.DownloadCount++;
        await db.SaveChangesAsync(ct);
        return Ok(ToResponse(consignment));
