[ApiController]
[Route("api/warehouses")]
public class WarehousesController(AppDbContext db) : ControllerBase
{
    [HttpPost]
    public async Task<IActionResult> Create(WarehouseRequest request, CancellationToken ct)
    {
        if (!IsValid(request)) return BadRequest();

        // A client-supplied id makes retries idempotent: an identical replay returns the existing item.
        var id = request.Id is { } given && given != Guid.Empty ? given : Guid.NewGuid();
        var existing = await db.Depots.AsNoTracking().FirstOrDefaultAsync(d => d.Id == id, ct);
        if (existing is not null)
            return existing.Code == request.Code && existing.CapacityCubicMeters == request.CapacityCubicMeters
                ? Ok(ToResponse(existing))
                : Conflict();

        var depot = new Depot
        {
            Id = id,
            Code = request.Code!,
            CapacityCubicMeters = request.CapacityCubicMeters!.Value,
            LastAuditAt = DateTime.UtcNow,
            Version = Guid.NewGuid()
        };
        db.Depots.Add(depot);
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateException) { return Conflict(); }

        return CreatedAtAction(nameof(Get), new { id = depot.Id }, ToResponse(depot));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var depot = await db.Depots.AsNoTracking().FirstOrDefaultAsync(d => d.Id == id, ct);
        return depot is null ? NotFound() : Ok(ToResponse(depot));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, WarehouseRequest request, CancellationToken ct)
    {
        if (!IsValid(request) || (request.Id is { } bodyId && bodyId != id)) return BadRequest();

        var depot = await db.Depots.FirstOrDefaultAsync(d => d.Id == id, ct);
        if (depot is null) return NotFound();

        depot.Code = request.Code!;
        depot.CapacityCubicMeters = request.CapacityCubicMeters!.Value;
        depot.LastAuditAt = DateTime.UtcNow;
        depot.Version = Guid.NewGuid();

        // Concurrency token is compared against the value loaded above; a conflicting write yields 409.
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateException) { return Conflict(); }

        return Ok(ToResponse(depot));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        // Idempotent: deleting a missing warehouse still returns 204. Shipments cascade.
        await db.Depots.Where(d => d.Id == id).ExecuteDeleteAsync(ct);
        return NoContent();
    }

    private static bool IsValid(WarehouseRequest r) =>
        !string.IsNullOrWhiteSpace(r.Code) && r.CapacityCubicMeters is >= 0;

    private static WarehouseResponse ToResponse(Depot d) => new(d.Id, d.Code, d.CapacityCubicMeters);
