[ApiController]
[Route("api")]
public class ShipmentsController(AppDbContext db) : ControllerBase
{
    [HttpPost("warehouses/{warehouseId:guid}/shipments")]
    public async Task<IActionResult> Create(Guid warehouseId, ShipmentRequest request, CancellationToken ct)
    {
        if (!IsValid(request) || (request.WarehouseId is { } bodyWarehouse && bodyWarehouse != warehouseId))
            return BadRequest();
        if (!await db.Depots.AnyAsync(d => d.Id == warehouseId, ct)) return NotFound();

        var id = request.Id is { } given && given != Guid.Empty ? given : Guid.NewGuid();
        var existing = await db.Consignments.AsNoTracking().FirstOrDefaultAsync(c => c.Id == id, ct);
        if (existing is not null)
            return Same(existing, warehouseId, request) ? Ok(ToResponse(existing)) : Conflict();

        var consignment = new Consignment
        {
            Id = id,
            WarehouseId = warehouseId,
            Reference = request.Reference!,
            WeightKg = request.WeightKg!.Value,
            Fragile = request.Fragile,
            Version = Guid.NewGuid()
        };
        db.Consignments.Add(consignment);
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateException) { return Conflict(); }

        await Touch(warehouseId, ct);
        return CreatedAtAction(nameof(Get), new { id }, ToResponse(consignment));
    }

    [HttpGet("shipments/{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var consignment = await db.Consignments.FirstOrDefaultAsync(c => c.Id == id, ct);
        if (consignment is null) return NotFound();

        // Atomic counter update in SQL, so concurrent reads don't lose increments.
        await db.Consignments.Where(c => c.Id == id)
            .ExecuteUpdateAsync(s => s.SetProperty(c => c.DownloadCount, c => c.DownloadCount + 1), ct);
        return Ok(ToResponse(consignment));
    }

    [HttpPut("shipments/{id:guid}")]
    public async Task<IActionResult> Update(Guid id, ShipmentRequest request, CancellationToken ct)
    {
        if (!IsValid(request) || (request.Id is { } bodyId && bodyId != id)) return BadRequest();

        var consignment = await db.Consignments.FirstOrDefaultAsync(c => c.Id == id, ct);
        if (consignment is null) return NotFound();

        var newWarehouseId = request.WarehouseId ?? consignment.WarehouseId;
        if (newWarehouseId != consignment.WarehouseId &&
            !await db.Depots.AnyAsync(d => d.Id == newWarehouseId, ct))
            return NotFound();

        var oldWarehouseId = consignment.WarehouseId;
        consignment.WarehouseId = newWarehouseId;
        consignment.Reference = request.Reference!;
        consignment.WeightKg = request.WeightKg!.Value;
        consignment.Fragile = request.Fragile;
        consignment.Version = Guid.NewGuid();

        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateException) { return Conflict(); }

        await Touch(newWarehouseId, ct);
        if (oldWarehouseId != newWarehouseId) await Touch(oldWarehouseId, ct);
        return Ok(ToResponse(consignment));
    }

    [HttpDelete("shipments/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        // Idempotent: deleting a missing shipment still returns 204.
        var warehouseId = await db.Consignments.Where(c => c.Id == id)
            .Select(c => (Guid?)c.WarehouseId).FirstOrDefaultAsync(ct);
        if (warehouseId is null) return NoContent();

        await db.Consignments.Where(c => c.Id == id).ExecuteDeleteAsync(ct);
        await Touch(warehouseId.Value, ct);
        return NoContent();
    }

    private Task Touch(Guid warehouseId, CancellationToken ct) =>
        db.Depots.Where(d => d.Id == warehouseId)
            .ExecuteUpdateAsync(s => s.SetProperty(d => d.LastAuditAt, DateTime.UtcNow), ct);

    private static bool IsValid(ShipmentRequest r) =>
        !string.IsNullOrWhiteSpace(r.Reference) && r.WeightKg is >= 0;

    private static bool Same(Consignment c, Guid warehouseId, ShipmentRequest r) =>
        c.WarehouseId == warehouseId && c.Reference == r.Reference && c.WeightKg == r.WeightKg && c.Fragile == r.Fragile;

    private static ShipmentResponse ToResponse(Consignment c) =>
        new(c.Id, c.WarehouseId, c.Reference, c.WeightKg, c.Fragile);
