using Microsoft.EntityFrameworkCore;

public class Depot
{
    public Guid Id { get; set; }
    public string Code { get; set; } = "";
    public int CapacityCubicMeters { get; set; }
    public DateTime? LastAuditAt { get; set; }
    public Guid Version { get; set; }
    public List<Consignment> Consignments { get; set; } = new();
}

public class Consignment
{
    public Guid Id { get; set; }
    public Guid DepotId { get; set; }
    public Depot Depot { get; set; } = null!;
    public string Reference { get; set; } = "";
    public decimal WeightKg { get; set; }
    public bool Fragile { get; set; }
    public int DownloadCount { get; set; }
    public Guid Version { get; set; }
}

public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Depot> Depots => Set<Depot>();
    public DbSet<Consignment> Consignments => Set<Consignment>();

    protected override void OnModelCreating(ModelBuilder b)
    {
        b.Entity<Depot>(e =>
        {
            e.HasKey(x => x.Id);
            e.Property(x => x.Code).IsRequired();
            e.Property(x => x.Version).IsConcurrencyToken().ValueGeneratedNever();
            e.HasMany(x => x.Consignments).WithOne(x => x.Depot).HasForeignKey(x => x.DepotId).OnDelete(DeleteBehavior.Cascade);
        });

        b.Entity<Consignment>(e =>
        {
            e.HasKey(x => x.Id);
            e.Property(x => x.Reference).IsRequired();
            e.Property(x => x.Version).IsConcurrencyToken().ValueGeneratedNever();
        });
    }

    public override int SaveChanges() { Stamp(); return base.SaveChanges(); }

    public override Task<int> SaveChangesAsync(CancellationToken cancellationToken = default)
    {
        Stamp();
        return base.SaveChangesAsync(cancellationToken);
    }

    private void Stamp()
    {
        foreach (var e in ChangeTracker.Entries().Where(e => e.State is EntityState.Added or EntityState.Modified))
        {
            if (e.Entity is Depot d) d.LastAuditAt = DateTime.UtcNow;
            if (e.Entity is Depot or Consignment) e.Property("Version").CurrentValue = Guid.NewGuid();
        }
    }
}

