// Helpers.cs
using Microsoft.EntityFrameworkCore;

public static class Concurrency
{
    public static string NewToken() => Guid.NewGuid().ToString("N");

    public static string ETag(string token) => $"\"{token}\"";

    // Optional If-Match: when supplied, the stored version must match or the request gets 412.
    public static bool Matches(HttpRequest request, string token) =>
        !request.Headers.TryGetValue("If-Match", out var v) || v == "*" || v == ETag(token);

    // Concurrent-update and unique/FK violations surface as 409 Conflict.
    public static async Task<IActionResult?> SaveAsync(DbContext db, CancellationToken ct)
    {
        try
        {
            await db.SaveChangesAsync(ct);
            return null;
        }
        catch (DbUpdateException)
        {
            return new ConflictResult();
        }
    }
}
