// Canon.cs
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public static class Canon
{
    public static string Depot(Guid id, string code, int capacityCubicMeters) =>
        Hash($"{{\"id\":\"{id:D}\",\"code\":{Str(code)},\"capacityCubicMeters\":{capacityCubicMeters.ToString(CultureInfo.InvariantCulture)}}}");

    public static string Shipment(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile) =>
        Hash($"{{\"id\":\"{id:D}\",\"warehouseId\":\"{warehouseId:D}\",\"reference\":{Str(reference)},\"weightKg\":{weightKg.Normalize().ToString(CultureInfo.InvariantCulture)},\"fragile\":{(fragile ? "true" : "false")}}}");

    public static string Tombstone() => "\"" + Guid.NewGuid().ToString("N") + "\"";

    private static string Hash(string json) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(json))).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";

    private static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s.Normalize(NormalizationForm.FormC))
        {
            sb.Append(c switch
            {
                '"' => "\\\"",
                '\\' => "\\\\",
                '\b' => "\\b",
                '\f' => "\\f",
                '\n' => "\\n",
                '\r' => "\\r",
                '\t' => "\\t",
                < ' ' => $"\\u{(int)c:x4}",
                _ => c.ToString()
            });
        }
        return sb.Append('"').ToString();
    }
}
