// ApiHelpers.cs
using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.AspNetCore.Mvc;

public static class ApiHelpers
{
    static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

    public static IActionResult Problem(int status, string title) => new ContentResult
    {
        StatusCode = status,
        ContentType = "application/problem+json",
        Content = JsonSerializer.Serialize(new ProblemDetails { Status = status, Title = title }, JsonOptions)
    };

    public static bool Matches(string? header, string etag) =>
        !string.IsNullOrEmpty(header) && (header.Trim() == "*" || header.Split(',').Any(t => t.Trim() == etag));

    public static string ETagOf(string canonicalJson) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson))).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";

    public static string Warehouse(Guid id, string code, int capacity) =>
        $"{{\"id\":\"{id:D}\",\"code\":{Str(code)},\"capacityCubicMeters\":{capacity}}}";

    public static string Shipment(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile)
    {
        var f = fragile ? "true" : "false";
        return $"{{\"id\":\"{id:D}\",\"warehouseId\":\"{warehouseId:D}\",\"reference\":{Str(reference)},\"weightKg\":{Num(weightKg)},\"fragile\":{f}}}";
    }

    static string Num(decimal d) => d.ToString("0.############################", CultureInfo.InvariantCulture);

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s.Normalize(NormalizationForm.FormC))
            sb.Append(c switch
            {
                '"' => "\\\"",
                '\\' => "\\\\",
                '\b' => "\\b",
                '\f' => "\\f",
                '\n' => "\\n",
                '\r' => "\\r",
                '\t' => "\\t",
                _ when c < 0x20 => $"\\u{(int)c:x4}",
                _ => c.ToString()
            });
        return sb.Append('"').ToString();
    }
}
