[Route("api/warehouses")]
public sealed class WarehousesController(AppDbContext db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, Required] WarehouseRequest body, CancellationToken ct)
    {
        if (!ModelState.IsValid || body.Id == Guid.Empty) return ApiHelpers.Problem(400, "Invalid warehouse.");

        var etag = ApiHelpers.ETagOf(ApiHelpers.Warehouse(body.Id, body.Code, body.CapacityCubicMeters));
        var depot = new Depot { Id = body.Id, Code = body.Code, CapacityCubicMeters = body.CapacityCubicMeters, ETag = etag, CreateHash = etag, LastAuditAt = DateTime.UtcNow };
        db.Depots.Add(depot);
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateException ex) when (ex.InnerException is SqliteException { SqliteErrorCode: 19 })
        {
            db.Entry(depot).State = EntityState.Detached;
            var existing = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstAsync(d => d.Id == body.Id, ct);
            if (existing.DeletedAt is not null) return ApiHelpers.Problem(410, "Warehouse was deleted.");
            if (existing.CreateHash != etag) return ApiHelpers.Problem(409, "Warehouse id is already used with different content.");
            Response.Headers.ETag = existing.ETag;
            return Ok(ToResponse(existing));
        }

        Response.Headers.ETag = etag;
        return Created($"/api/warehouses/{depot.Id:D}", ToResponse(depot));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var d = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, ct);
        if (d is null) return ApiHelpers.Problem(404, "Warehouse not found.");
        if (d.DeletedAt is not null) return ApiHelpers.Problem(410, "Warehouse was deleted.");

        Response.Headers.ETag = d.ETag;
        if (ApiHelpers.Matches(Request.Headers["If-None-Match"].ToString(), d.ETag)) return StatusCode(StatusCodes.Status304NotModified);
        return Ok(ToResponse(d));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, [FromBody, Required] WarehouseRequest body, CancellationToken ct)
    {
        ModelState.Remove(nameof(ifMatch));
        if (!ModelState.IsValid || body.Id != id) return ApiHelpers.Problem(400, "Invalid warehouse.");
        if (ifMatch is null) return ApiHelpers.Problem(428, "If-Match header is required.");

        var d = await db.Depots.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.Id == id, ct);
        if (d is null) return ApiHelpers.Problem(404, "Warehouse not found.");
        if (d.DeletedAt is not null) return ApiHelpers.Problem(410, "Warehouse was deleted.");

        var etag = ApiHelpers.ETagOf(ApiHelpers.Warehouse(id, body.Code, body.CapacityCubicMeters));
        if (d.ETag == etag) { Response.Headers.ETag = etag; return NoContent(); }
        if (!ApiHelpers.Matches(ifMatch, d.ETag)) { Response.Headers.ETag = d.ETag; return ApiHelpers.Problem(412, "ETag does not match."); }

        d.Code = body.Code;
        d.CapacityCubicMeters = body.CapacityCubicMeters;
        d.ETag = etag;
        d.LastAuditAt = DateTime.UtcNow;
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { return await StaleAsync(id, ct); }

        Response.Headers.ETag = etag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (ifMatch is null) return ApiHelpers.Problem(428, "If-Match header is required.");

        var d = await db.Depots.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.Id == id, ct);
        if (d is null || d.DeletedAt is not null) return NoContent();
        if (!ApiHelpers.Matches(ifMatch, d.ETag)) { Response.Headers.ETag = d.ETag; return ApiHelpers.Problem(412, "ETag does not match."); }

        var now = DateTime.UtcNow;
        d.DeletedAt = now;
        d.LastAuditAt = now;
        foreach (var c in await db.Consignments.Where(x => x.DepotPk == d.Pk).ToListAsync(ct)) c.DeletedAt = now;
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { return await StaleAsync(id, ct); }

        return NoContent();
    }

    private async Task<IActionResult> StaleAsync(Guid id, CancellationToken ct)
    {
        Response.Headers.ETag = await db.Depots.IgnoreQueryFilters().Where(x => x.Id == id).Select(x => x.ETag).FirstAsync(ct);
