// ShipmentsController.cs
using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

public sealed class ShipmentsController(AppDbContext db) : ControllerBase
{
    [HttpPost("api/warehouses/{warehouseId:guid}/shipments")]
    [ProducesResponseType(typeof(ShipmentResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(ShipmentResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create(Guid warehouseId, [FromBody, Required] ShipmentRequest body, CancellationToken ct)
    {
        if (!ModelState.IsValid || body.Id == Guid.Empty || body.WarehouseId != warehouseId) return ApiHelpers.Problem(400, "Invalid shipment.");

        var depot = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.Id == warehouseId, ct);
        if (depot is null) return ApiHelpers.Problem(404, "Warehouse not found.");
        if (depot.DeletedAt is not null) return ApiHelpers.Problem(410, "Warehouse was deleted.");

        var etag = ApiHelpers.ETagOf(ApiHelpers.Shipment(body.Id, warehouseId, body.Reference, body.WeightKg, body.Fragile));
        var c = new Consignment { Id = body.Id, DepotPk = depot.Pk, Reference = body.Reference, WeightKg = body.WeightKg, Fragile = body.Fragile, ETag = etag, CreateHash = etag };
        db.Consignments.Add(c);
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateException ex) when (ex.InnerException is SqliteException { SqliteErrorCode: 19 })
        {
            db.Entry(c).State = EntityState.Detached;
            var existing = await db.Consignments.IgnoreQueryFilters().AsNoTracking().Include(x => x.Depot).FirstAsync(x => x.Id == body.Id, ct);
            if (existing.DeletedAt is not null) return ApiHelpers.Problem(410, "Shipment was deleted.");
            if (existing.Depot.Id != warehouseId || existing.CreateHash != etag) return ApiHelpers.Problem(409, "Shipment id is already used with different content.");
            Response.Headers.ETag = existing.ETag;
            return Ok(ToResponse(existing, existing.Depot.Id));
        }

        Response.Headers.ETag = etag;
        return Created($"/api/shipments/{c.Id:D}", ToResponse(c, warehouseId));
    }

    [HttpGet("api/shipments/{id:guid}")]
    [ProducesResponseType(typeof(ShipmentResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var c = await db.Consignments.IgnoreQueryFilters().AsNoTracking().Include(x => x.Depot).FirstOrDefaultAsync(x => x.Id == id, ct);
        if (c is null) return ApiHelpers.Problem(404, "Shipment not found.");
        if (c.DeletedAt is not null) return ApiHelpers.Problem(410, "Shipment was deleted.");

        Response.Headers.ETag = c.ETag;
        if (ApiHelpers.Matches(Request.Headers["If-None-Match"].ToString(), c.ETag)) return StatusCode(StatusCodes.Status304NotModified);

        await db.Consignments.Where(x => x.Pk == c.Pk).ExecuteUpdateAsync(s => s.SetProperty(x => x.DownloadCount, x => x.DownloadCount + 1), ct);
        return Ok(ToResponse(c, c.Depot.Id));
    }

    [HttpPut("api/shipments/{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, [FromBody, Required] ShipmentRequest body, CancellationToken ct)
    {
        ModelState.Remove(nameof(ifMatch));
        if (!ModelState.IsValid || body.Id != id) return ApiHelpers.Problem(400, "Invalid shipment.");
        if (ifMatch is null) return ApiHelpers.Problem(428, "If-Match header is required.");

        var c = await db.Consignments.IgnoreQueryFilters().Include(x => x.Depot).FirstOrDefaultAsync(x => x.Id == id, ct);
        if (c is null) return ApiHelpers.Problem(404, "Shipment not found.");
        if (c.DeletedAt is not null) return ApiHelpers.Problem(410, "Shipment was deleted.");
        if (body.WarehouseId != c.Depot.Id) return ApiHelpers.Problem(409, "Moving a shipment to another warehouse is not allowed.");

        var etag = ApiHelpers.ETagOf(ApiHelpers.Shipment(id, c.Depot.Id, body.Reference, body.WeightKg, body.Fragile));
        if (c.ETag == etag) { Response.Headers.ETag = etag; return NoContent(); }
        if (!ApiHelpers.Matches(ifMatch, c.ETag)) { Response.Headers.ETag = c.ETag; return ApiHelpers.Problem(412, "ETag does not match."); }

        c.Reference = body.Reference;
        c.WeightKg = body.WeightKg;
        c.Fragile = body.Fragile;
        c.ETag = etag;
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { return await StaleAsync(id, ct); }

        Response.Headers.ETag = etag;
        return NoContent();
    }

    [HttpDelete("api/shipments/{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (ifMatch is null) return ApiHelpers.Problem(428, "If-Match header is required.");

        var c = await db.Consignments.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.Id == id, ct);
        if (c is null || c.DeletedAt is not null) return NoContent();
        if (!ApiHelpers.Matches(ifMatch, c.ETag)) { Response.Headers.ETag = c.ETag; return ApiHelpers.Problem(412, "ETag does not match."); }

        c.DeletedAt = DateTime.UtcNow;
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { return await StaleAsync(id, ct); }

        return NoContent();
    }

    private async Task<IActionResult> StaleAsync(Guid id, CancellationToken ct)
    {
        Response.Headers.ETag = await db.Consignments.IgnoreQueryFilters().Where(x => x.Id == id).Select(x => x.ETag).FirstAsync(ct);
        return ApiHelpers.Problem(412, "Shipment was modified concurrently.");
    }

    private static ShipmentResponse ToResponse(Consignment c, Guid warehouseId) => new(c.Id, warehouseId, c.Reference, c.WeightKg, c.Fragile);
}
