}

public sealed record WarehouseDto(Guid Id, string Code, int CapacityCubicMeters);
public sealed record ShipmentDto(Guid Id, Guid WarehouseId, string Reference, decimal WeightKg, bool Fragile);

public sealed class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Depot> Depots => Set<Depot>();
    public DbSet<Consignment> Consignments => Set<Consignment>();

    protected override void OnModelCreating(ModelBuilder b)
    {
        b.Entity<Depot>(e =>
        {
            e.HasKey(x => x.Id);
            e.HasIndex(x => x.PublicId).IsUnique();
            e.Property(x => x.Code).IsRequired();
            e.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
            e.Property(x => x.CreateRequestHash).IsRequired().ValueGeneratedNever()
                .Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            e.HasQueryFilter(x => x.DeletedAt == null);
        });

        b.Entity<Consignment>(e =>
        {
            e.HasKey(x => x.Id);
            e.HasIndex(x => x.PublicId).IsUnique();
            e.Property(x => x.Reference).IsRequired();
            e.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
            e.Property(x => x.CreateRequestHash).IsRequired().ValueGeneratedNever()
                .Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            e.HasOne(x => x.Depot).WithMany().HasForeignKey(x => x.DepotId).OnDelete(DeleteBehavior.Restrict);
            e.HasQueryFilter(x => x.DeletedAt == null);
        });
    }
