public static class Canon
{
    public static string Warehouse(WarehouseDto d) =>
        "{\"id\":\"" + d.Id.ToString("D") + "\",\"code\":" + Str(d.Code) +
        ",\"capacityCubicMeters\":" + d.CapacityCubicMeters.ToString(CultureInfo.InvariantCulture) + "}";

    public static string Shipment(ShipmentDto d) =>
        "{\"id\":\"" + d.Id.ToString("D") + "\",\"warehouseId\":\"" + d.WarehouseId.ToString("D") +
        "\",\"reference\":" + Str(d.Reference) +
        ",\"weightKg\":" + d.WeightKg.ToString("0.############################", CultureInfo.InvariantCulture) +
        ",\"fragile\":" + (d.Fragile ? "true" : "false") + "}";

    public static string Hash(string json) =>
        Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(json))).TrimEnd('=').Replace('+', '-').Replace('/', '_');

    public static string Quote(string etag) => "\"" + etag + "\"";

    public static bool Matches(string? header, string etag) =>
        header is not null && header.Split(',').Select(t => t.Trim().Trim('"')).Any(t => t == "*" || t == etag);

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var ch in s.Normalize(NormalizationForm.FormC))
            sb.Append(ch switch
            {
                '"' => "\\\"",
                '\\' => "\\\\",
                '\b' => "\\b",
                '\f' => "\\f",
                '\n' => "\\n",
                '\r' => "\\r",
                '\t' => "\\t",
                < ' ' => $"\\u{(int)ch:x4}",
                _ => ch.ToString()
            });
        return sb.Append('"').ToString();
    }
}

public static class Rules
{
    public static bool Valid(WarehouseDto d) =>
        d.Id != Guid.Empty && !string.IsNullOrWhiteSpace(d.Code) && d.CapacityCubicMeters >= 0;

    public static bool Valid(ShipmentDto d) =>
        d.Id != Guid.Empty && d.WarehouseId != Guid.Empty && !string.IsNullOrWhiteSpace(d.Reference) && d.WeightKg >= 0;
}

public abstract class ApiBase : ControllerBase
{
    protected IActionResult Fail(int status, string? etag = null)
    {
        if (etag is not null) Response.Headers.ETag = Canon.Quote(etag);
        return Problem(statusCode: status);
    }
}
