public sealed class WarehousesController(AppDbContext db) : ApiBase
{
    [HttpPost("api/warehouses")]
    [ProducesResponseType(typeof(WarehouseDto), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(WarehouseDto), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, Required] WarehouseDto? dto, CancellationToken ct)
    {
        if (dto is null || !Rules.Valid(dto)) return Fail(400);
        var hash = Canon.Hash(Canon.Warehouse(dto));
        db.Depots.Add(new Depot
        {
            PublicId = dto.Id, Code = dto.Code, CapacityCubicMeters = dto.CapacityCubicMeters,
            ETag = hash, CreateRequestHash = hash, LastAuditAt = DateTime.UtcNow
        });
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            db.ChangeTracker.Clear();
            var existing = await db.Depots.IgnoreQueryFilters().AsNoTracking()
                .SingleOrDefaultAsync(x => x.PublicId == dto.Id, ct);
            if (existing is null) throw;
            if (existing.DeletedAt is not null) return Fail(410);
            if (existing.CreateRequestHash != hash) return Fail(409);
            Response.Headers.ETag = Canon.Quote(existing.ETag);
            return Ok(new WarehouseDto(existing.PublicId, existing.Code, existing.CapacityCubicMeters));
        }
        Response.Headers.ETag = Canon.Quote(hash);
        return Created($"/api/warehouses/{dto.Id:D}", dto);
    }

    [HttpGet("api/warehouses/{id:guid}")]
    [ProducesResponseType(typeof(WarehouseDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var d = await db.Depots.AsNoTracking().SingleOrDefaultAsync(x => x.PublicId == id, ct);
        if (d is null)
            return Fail(await db.Depots.IgnoreQueryFilters().AnyAsync(x => x.PublicId == id && x.DeletedAt != null, ct) ? 410 : 404);
        Response.Headers.ETag = Canon.Quote(d.ETag);
        if (Canon.Matches(Request.Headers.IfNoneMatch.ToString(), d.ETag)) return StatusCode(304);
        return Ok(new WarehouseDto(d.PublicId, d.Code, d.CapacityCubicMeters));
    }

    [HttpPut("api/warehouses/{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody, Required] WarehouseDto? dto,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (dto is null || !Rules.Valid(dto) || dto.Id != id) return Fail(400);
        if (string.IsNullOrEmpty(ifMatch)) return Fail(428);
        var d = await db.Depots.SingleOrDefaultAsync(x => x.PublicId == id, ct);
        if (d is null)
            return Fail(await db.Depots.IgnoreQueryFilters().AnyAsync(x => x.PublicId == id && x.DeletedAt != null, ct) ? 410 : 404);
        var newTag = Canon.Hash(Canon.Warehouse(dto));
        if (d.ETag == newTag)
        {
            Response.Headers.ETag = Canon.Quote(d.ETag);
            return NoContent();
        }
        if (!Canon.Matches(ifMatch, d.ETag)) return Fail(412, d.ETag);
        d.Code = dto.Code;
        d.CapacityCubicMeters = dto.CapacityCubicMeters;
        d.ETag = newTag;
        d.LastAuditAt = DateTime.UtcNow;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await db.Depots.IgnoreQueryFilters().AsNoTracking().SingleOrDefaultAsync(x => x.PublicId == id, ct);
            return cur is { DeletedAt: null } ? Fail(412, cur.ETag) : Fail(410);
        }
        Response.Headers.ETag = Canon.Quote(newTag);
        return NoContent();
    }

    [HttpDelete("api/warehouses/{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch)) return Fail(428);
        var d = await db.Depots.SingleOrDefaultAsync(x => x.PublicId == id, ct);
        if (d is null) return NoContent();
        if (!Canon.Matches(ifMatch, d.ETag)) return Fail(412, d.ETag);
        var now = DateTime.UtcNow;
        await using var tx = await db.Database.BeginTransactionAsync(ct);
        d.DeletedAt = now;
        d.LastAuditAt = now;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await db.Depots.IgnoreQueryFilters().AsNoTracking().SingleOrDefaultAsync(x => x.PublicId == id, ct);
            return cur is { DeletedAt: null } ? Fail(412, cur.ETag) : NoContent();
        }
        await db.Consignments.Where(c => c.DepotId == d.Id)
            .ExecuteUpdateAsync(s => s.SetProperty(c => c.DeletedAt, (DateTime?)now), ct);
        await tx.CommitAsync(ct);
        return NoContent();
    }
}

