        if (string.IsNullOrEmpty(ifMatch)) return Fail(428);
        var c = await db.Consignments.Include(x => x.Depot).SingleOrDefaultAsync(x => x.PublicId == id, ct);
        if (c is null)
            return Fail(await db.Consignments.IgnoreQueryFilters().AnyAsync(x => x.PublicId == id && x.DeletedAt != null, ct) ? 410 : 404);
        var newTag = Canon.Hash(Canon.Shipment(dto));
        if (c.ETag == newTag)
        {
            Response.Headers.ETag = Canon.Quote(c.ETag);
            return NoContent();
        }
        if (!Canon.Matches(ifMatch, c.ETag)) return Fail(412, c.ETag);
        if (dto.WarehouseId != c.Depot.PublicId) return Fail(409);
        c.Reference = dto.Reference;
        c.WeightKg = dto.WeightKg;
        c.Fragile = dto.Fragile;
        c.ETag = newTag;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await db.Consignments.IgnoreQueryFilters().AsNoTracking().SingleOrDefaultAsync(x => x.PublicId == id, ct);
            return cur is { DeletedAt: null } ? Fail(412, cur.ETag) : Fail(410);
        }
        Response.Headers.ETag = Canon.Quote(newTag);
        return NoContent();
    }

    [HttpDelete("api/shipments/{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch)) return Fail(428);
        var c = await db.Consignments.SingleOrDefaultAsync(x => x.PublicId == id, ct);
        if (c is null) return NoContent();
        if (!Canon.Matches(ifMatch, c.ETag)) return Fail(412, c.ETag);
        c.DeletedAt = DateTime.UtcNow;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await db.Consignments.IgnoreQueryFilters().AsNoTracking().SingleOrDefaultAsync(x => x.PublicId == id, ct);
            return cur is { DeletedAt: null } ? Fail(412, cur.ETag) : NoContent();
        }
        return NoContent();
    }
}
