public static class Canon
{
    public static string N(string s) => s.Normalize(NormalizationForm.FormC);

    public static string Warehouse(WarehouseDto w) =>
        $"{{\"id\":\"{w.Id:D}\",\"code\":{Str(w.Code)},\"capacityCubicMeters\":{w.CapacityCubicMeters}}}";

    public static string Shipment(ShipmentDto s) =>
        $"{{\"id\":\"{s.Id:D}\",\"warehouseId\":\"{s.WarehouseId:D}\",\"reference\":{Str(s.Reference)},\"weightKg\":{Num(s.WeightKg)},\"fragile\":{s.Fragile.ToString().ToLowerInvariant()}}}";

    public static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s.Normalize(NormalizationForm.FormC))
            sb.Append(c switch
            {
                '"' => "\\\"",
                '\\' => "\\\\",
                '\b' => "\\b",
                '\f' => "\\f",
                '\n' => "\\n",
                '\r' => "\\r",
                '\t' => "\\t",
                _ when c < 0x20 => $"\\u{(int)c:x4}",
                _ => c.ToString()
            });
        return sb.Append('"').ToString();
    }

    public static string Num(decimal d) => d.ToString("0.############################", CultureInfo.InvariantCulture);

    public static string Etag(string canonical)
    {
        var h = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return "\"" + Convert.ToBase64String(h).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    public static bool Unique(Exception ex) =>
        ex is DbUpdateException { InnerException: SqliteException { SqliteExtendedErrorCode: 2067 } };
}

