using System.Linq.Expressions;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

public abstract class ApiBase : ControllerBase
{
    protected string IfMatch => Request.Headers.IfMatch.ToString();

    protected IActionResult Err(int status, string title) =>
        new ObjectResult(new ProblemDetails { Status = status, Title = title })
        {
            StatusCode = status,
            ContentType = "application/problem+json"
        };

    protected IActionResult Precondition(string etag)
    {
        Response.Headers.ETag = etag;
        return Err(412, "Precondition failed");
    }

    protected async Task<IActionResult> Fail<T>(DbSet<T> set, Expression<Func<T, bool>> match, CancellationToken ct) where T : class, IEntity
    {
        var e = await set.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(match, ct);
        return e == null ? Err(404, "Not found") : e.DeletedAt != null ? Err(410, "Gone") : Precondition(e.ETag);
    }

    protected bool NotModified(string etag) =>
        Request.Headers.IfNoneMatch.Any(v => (v ?? "").Split(',').Select(s => s.Trim()).Contains(etag));
}

[ApiController]
[Route("api/warehouses")]
public class WarehousesController(AppDbContext db) : ApiBase
{
    [HttpPost]
    [ProducesResponseType(typeof(WarehouseDto), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(WarehouseDto), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] WarehouseDto body, CancellationToken ct)
    {
        if (body.Id == Guid.Empty || string.IsNullOrWhiteSpace(body.Code) || body.CapacityCubicMeters < 0)
            return Err(400, "Invalid body");
        var etag = Canon.Etag(Canon.Warehouse(body));
        var depot = new Depot
        {
            Id = body.Id,
            Code = Canon.N(body.Code),
            CapacityCubicMeters = body.CapacityCubicMeters,
            ETag = etag,
            RequestHash = etag,
            LastAuditAt = DateTime.UtcNow
        };
        db.Depots.Add(depot);
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateException ex) when (Canon.Unique(ex))
        {
            db.ChangeTracker.Clear();
            var existing = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstAsync(d => d.Id == body.Id, ct);
            if (existing.DeletedAt != null) return Err(410, "Gone");
            if (existing.RequestHash != etag) return Err(409, "Id already used with different content");
            Response.Headers.ETag = existing.ETag;
            return Ok(ToDto(existing));
        }
        Response.Headers.ETag = etag;
        return Created($"/api/warehouses/{depot.Id}", ToDto(depot));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(WarehouseDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var d = await db.Depots.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, ct);
        if (d == null) return await Fail(db.Depots, x => x.Id == id, ct);
        Response.Headers.ETag = d.ETag;
        if (NotModified(d.ETag)) return StatusCode(StatusCodes.Status304NotModified);
        return Ok(ToDto(d));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody] WarehouseDto body, CancellationToken ct)
    {
        if (body.Id != id || string.IsNullOrWhiteSpace(body.Code) || body.CapacityCubicMeters < 0)
            return Err(400, "Invalid body");
        if (string.IsNullOrEmpty(IfMatch)) return Err(428, "If-Match required");
        var d = await db.Depots.FirstOrDefaultAsync(x => x.Id == id, ct);
        if (d == null) return await Fail(db.Depots, x => x.Id == id, ct);
        var etag = Canon.Etag(Canon.Warehouse(body));
        if (d.ETag == etag) { Response.Headers.ETag = etag; return NoContent(); }
        if (IfMatch != "*")
        {
            if (IfMatch != d.ETag) return Precondition(d.ETag);
            db.Entry(d).Property(x => x.ETag).OriginalValue = IfMatch;
        }
        d.Code = Canon.N(body.Code);
        d.CapacityCubicMeters = body.CapacityCubicMeters;
        d.ETag = etag;
        d.LastAuditAt = DateTime.UtcNow;
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { return await Fail(db.Depots, x => x.Id == id, ct); }
        Response.Headers.ETag = etag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        if (string.IsNullOrEmpty(IfMatch)) return Err(428, "If-Match required");
        var d = await db.Depots.Include(x => x.Consignments).FirstOrDefaultAsync(x => x.Id == id, ct);
        if (d == null) return NoContent();
        if (IfMatch != "*")
        {
            if (IfMatch != d.ETag) return Precondition(d.ETag);
            db.Entry(d).Property(x => x.ETag).OriginalValue = IfMatch;
        }
        var now = DateTime.UtcNow;
        d.DeletedAt = now;
        d.LastAuditAt = now;
        foreach (var c in d.Consignments) c.DeletedAt = now;
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { return await Fail(db.Depots, x => x.Id == id, ct); }
        return NoContent();
    }

    static WarehouseDto ToDto(Depot d) => new(d.Id, d.Code, d.CapacityCubicMeters);
}

