public static class Canon
{
    public static string Nfc(string s) => s.Normalize(NormalizationForm.FormC);

    public static string Id(Guid g) => g.ToString("D");

    public static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in Nfc(s))
            sb.Append(c switch
            {
                '"' => "\\\"",
                '\\' => "\\\\",
                '\b' => "\\b",
                '\f' => "\\f",
                '\n' => "\\n",
                '\r' => "\\r",
                '\t' => "\\t",
                < ' ' => $"\\u{(int)c:x4}",
                _ => c.ToString()
            });
        return sb.Append('"').ToString();
    }

    public static string Num(decimal d) => d.ToString("0.############################", CultureInfo.InvariantCulture);

    public static string Warehouse(Guid id, string code, int cap) =>
        $"{{\"id\":\"{Id(id)}\",\"code\":{Str(code)},\"capacityCubicMeters\":{cap}}}";

    public static string Shipment(Guid id, Guid warehouseId, string reference, decimal weight, bool fragile)
    {
        var f = fragile ? "true" : "false";
        return $"{{\"id\":\"{Id(id)}\",\"warehouseId\":\"{Id(warehouseId)}\",\"reference\":{Str(reference)},\"weightKg\":{Num(weight)},\"fragile\":{f}}}";
    }

    public static string ETag(string canonical) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(canonical)))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
}
