        var reference = Canon.Nfc(body.Reference);
        var etag = Canon.ETag(Canon.Shipment(id, warehouseId, reference, weight, fragile));
        if (c.ETag == etag) { Response.Headers.ETag = etag; return NoContent(); }
        if (!Api.Matches(ifMatch, c.ETag)) return await Stale(id, ct);

        c.Reference = reference;
        c.WeightKg = weight;
        c.Fragile = fragile;
        c.ETag = etag;

        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { return await Stale(id, ct); }

        Response.Headers.ETag = etag;
        return NoContent();
    }

    [HttpDelete("shipments/{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch)) return Api.Err(428, "If-Match header is required.");

        var c = await db.Consignments.FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (c is null) return NoContent();
        if (!Api.Matches(ifMatch, c.ETag)) { Response.Headers.ETag = c.ETag; return Api.Err(412, "ETag does not match."); }

        c.DeletedAt = DateTime.UtcNow;
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { return await Stale(id, ct); }

        return NoContent();
    }

    private static ShipmentResponse Shape(Consignment c) =>
        new(c.PublicId, c.Depot.PublicId, c.Reference, c.WeightKg, c.Fragile);

    private async Task<IActionResult> Missing(Guid id, CancellationToken ct) =>
        await db.Consignments.IgnoreQueryFilters().AnyAsync(x => x.PublicId == id && x.DeletedAt != null, ct)
            ? Api.Err(410, "Shipment was deleted.")
            : Api.Err(404, "Shipment not found.");

    private async Task<IActionResult> MissingWarehouse(Guid id, CancellationToken ct) =>
        await db.Depots.IgnoreQueryFilters().AnyAsync(x => x.PublicId == id && x.DeletedAt != null, ct)
            ? Api.Err(410, "Warehouse was deleted.")
            : Api.Err(404, "Warehouse not found.");

    private async Task<IActionResult> Stale(Guid id, CancellationToken ct)
    {
        db.ChangeTracker.Clear();
        var etag = await db.Consignments.IgnoreQueryFilters().Where(x => x.PublicId == id).Select(x => x.ETag).FirstOrDefaultAsync(ct);
        if (etag is null) return Api.Err(404, "Shipment not found.");
        Response.Headers.ETag = etag;
        return Api.Err(412, "ETag does not match.");
    }
}
