public static class Canon
{
    public static string N(string s) => s.Normalize(NormalizationForm.FormC);

    public static string Etag(string json) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(json))).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";

    public static string Tombstone() => "\"deleted-" + Guid.NewGuid().ToString("N") + "\"";

    public static string Warehouse(Guid id, string code, int capacity) =>
        $"{{\"id\":\"{id:D}\",\"code\":{Str(code)},\"capacityCubicMeters\":{capacity.ToString(CultureInfo.InvariantCulture)}}}";

    public static string Shipment(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile) =>
        $"{{\"id\":\"{id:D}\",\"warehouseId\":\"{warehouseId:D}\",\"reference\":{Str(reference)},\"weightKg\":{Num(weightKg)},\"fragile\":{(fragile ? "true" : "false")}}}";

    static string Num(decimal d) => d.ToString("0.############################", CultureInfo.InvariantCulture);

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in N(s))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4")); else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }
}

public abstract class ApiBase : ControllerBase
{
    protected IActionResult Fail(int status, string title, string? etag = null)
    {
        if (etag is not null) Response.Headers["ETag"] = etag;
        return new ObjectResult(new ProblemDetails { Status = status, Title = title })
        {
            StatusCode = status,
            ContentTypes = { "application/problem+json" }
        };
    }

    protected string IfNoneMatch => Request.Headers["If-None-Match"].ToString();

    protected static bool Matches(string ifMatch, string current) => ifMatch == "*" || ifMatch == current;

    protected static bool IsUniqueViolation(DbUpdateException ex) => ex.InnerException is SqliteException { SqliteErrorCode: 19 };
}
