using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[Route("api/warehouses")]
public sealed class WarehousesController(AppDbContext db) : ApiBase
{
    [HttpPost]
    [ProducesResponseType(typeof(WarehouseDto), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(WarehouseDto), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, Required] WarehouseDto body, CancellationToken ct)
    {
        if (body is null || body.Id == Guid.Empty || string.IsNullOrWhiteSpace(body.Code) || body.CapacityCubicMeters < 0)
            return Fail(400, "Invalid warehouse");

        var code = Canon.N(body.Code);
        var etag = Canon.Etag(Canon.Warehouse(body.Id, code, body.CapacityCubicMeters));
        db.Depots.Add(new Depot
        {
            Id = body.Id, Code = code, CapacityCubicMeters = body.CapacityCubicMeters,
            ETag = etag, CreateRequestHash = etag, LastAuditAt = DateTime.UtcNow
        });

        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (IsUniqueViolation(ex))
        {
            db.ChangeTracker.Clear();
            var existing = await db.Depots.IgnoreQueryFilters().AsNoTracking().SingleOrDefaultAsync(d => d.Id == body.Id, ct);
            if (existing?.DeletedAt is not null) return Fail(410, "Warehouse was deleted");
            if (existing is null || existing.CreateRequestHash != etag) return Fail(409, "Warehouse id already in use");
            Response.Headers["Location"] = $"/api/warehouses/{existing.Id:D}";
            Response.Headers["ETag"] = existing.ETag;
            return Ok(new WarehouseDto(existing.Id, existing.Code, existing.CapacityCubicMeters));
        }

        Response.Headers["Location"] = $"/api/warehouses/{body.Id:D}";
        Response.Headers["ETag"] = etag;
        return StatusCode(StatusCodes.Status201Created, new WarehouseDto(body.Id, code, body.CapacityCubicMeters));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(WarehouseDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var d = await db.Depots.IgnoreQueryFilters().AsNoTracking().SingleOrDefaultAsync(x => x.Id == id, ct);
        if (d is null) return Fail(404, "Warehouse not found");
        if (d.DeletedAt is not null) return Fail(410, "Warehouse was deleted");
        Response.Headers["ETag"] = d.ETag;
        if (IfNoneMatch == d.ETag) return StatusCode(StatusCodes.Status304NotModified);
        return Ok(new WarehouseDto(d.Id, d.Code, d.CapacityCubicMeters));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Replace(Guid id, [FromBody, Required] WarehouseDto body,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (body is null || body.Id != id || string.IsNullOrWhiteSpace(body.Code) || body.CapacityCubicMeters < 0)
            return Fail(400, "Invalid warehouse");
        if (ifMatch is null) return Fail(428, "If-Match header is required");

        var d = await db.Depots.IgnoreQueryFilters().SingleOrDefaultAsync(x => x.Id == id, ct);
        if (d is null) return Fail(404, "Warehouse not found");
        if (d.DeletedAt is not null) return Fail(410, "Warehouse was deleted");

        var code = Canon.N(body.Code);
        var etag = Canon.Etag(Canon.Warehouse(id, code, body.CapacityCubicMeters));
        if (d.ETag == etag)
        {
            Response.Headers["ETag"] = etag;
            return NoContent();
        }
        if (!Matches(ifMatch, d.ETag)) return Fail(412, "ETag mismatch", d.ETag);

        d.Code = code;
        d.CapacityCubicMeters = body.CapacityCubicMeters;
        d.ETag = etag;
        d.LastAuditAt = DateTime.UtcNow;

        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await db.Depots.IgnoreQueryFilters().AsNoTracking().Where(x => x.Id == id).Select(x => x.ETag).SingleOrDefaultAsync(ct);
            return Fail(412, "ETag mismatch", cur);
        }

        Response.Headers["ETag"] = etag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (ifMatch is null) return Fail(428, "If-Match header is required");

        var d = await db.Depots.IgnoreQueryFilters().SingleOrDefaultAsync(x => x.Id == id, ct);
        if (d is null || d.DeletedAt is not null) return NoContent();
        if (!Matches(ifMatch, d.ETag)) return Fail(412, "ETag mismatch", d.ETag);

        var now = DateTime.UtcNow;
        d.DeletedAt = now;
        d.ETag = Canon.Tombstone();
        d.LastAuditAt = now;

        var shipments = await db.Consignments.IgnoreQueryFilters()
            .Where(c => c.WarehouseId == id && c.DeletedAt == null).ToListAsync(ct);
        foreach (var c in shipments)
        {
            c.DeletedAt = now;
            c.ETag = Canon.Tombstone();
        }

        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await db.Depots.IgnoreQueryFilters().AsNoTracking().Where(x => x.Id == id).Select(x => x.ETag).SingleOrDefaultAsync(ct);
            return Fail(412, "ETag mismatch", cur);
        }

        return NoContent();
    }
}
