        Response.Headers["Location"] = $"/api/shipments/{body.Id:D}";
        Response.Headers["ETag"] = etag;
        return StatusCode(StatusCodes.Status201Created, new ShipmentDto(body.Id, warehouseId, reference, body.WeightKg, body.Fragile));
