    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Replace(Guid id, [FromBody, Required] ShipmentDto body,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (body is null || body.Id != id || body.WarehouseId == Guid.Empty
            || string.IsNullOrWhiteSpace(body.Reference) || body.WeightKg < 0)
            return Fail(400, "Invalid shipment");
        if (ifMatch is null) return Fail(428, "If-Match header is required");

        var c = await db.Consignments.IgnoreQueryFilters().SingleOrDefaultAsync(x => x.Id == id, ct);
        if (c is null) return Fail(404, "Shipment not found");
        if (c.DeletedAt is not null) return Fail(410, "Shipment was deleted");
        if (body.WarehouseId != c.WarehouseId) return Fail(409, "Shipments cannot be moved to another warehouse");

