        c.Reference = reference;
        c.WeightKg = body.WeightKg;
        c.Fragile = body.Fragile;
        c.ETag = etag;

        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await db.Consignments.IgnoreQueryFilters().AsNoTracking().Where(x => x.Id == id).Select(x => x.ETag).SingleOrDefaultAsync(ct);
            return Fail(412, "ETag mismatch", cur);
        }

        Response.Headers["ETag"] = etag;
        return NoContent();
    }

