```csharp
using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using Microsoft.EntityFrameworkCore;

public static class Canon
{
    public static string Nfc(string s) => s.Normalize(NormalizationForm.FormC);

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in Nfc(s))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append($"\\u{(int)c:x4}");
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }

    static string Num(decimal d) => d.ToString("0.############################", CultureInfo.InvariantCulture);

    public static string Depot(DepotDto d) =>
        Tag($"{{\"id\":\"{d.Id:D}\",\"code\":{Str(d.Code!)},\"capacityCubicMeters\":{d.CapacityCubicMeters}}}");

    public static string Shipment(ShipmentDto s) =>
        Tag($"{{\"id\":\"{s.Id:D}\",\"warehouseId\":\"{s.WarehouseId:D}\",\"reference\":{Str(s.Reference!)},\"weightKg\":{Num(s.WeightKg!.Value)},\"fragile\":{(s.Fragile!.Value ? "true" : "false")}}}");

    public static string Tombstone() => "\"deleted-" + Guid.NewGuid().ToString("N") + "\"";

    static string Tag(string json) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(json))).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
}

public static class AppSetup
{
    public static void ConfigureServices(IServiceCollection services, string sqliteConnectionString) =>
        services.AddDbContext<AppDbContext>(o => o.UseSqlite(sqliteConnectionString));
}
