{
    protected static ObjectResult Fail(int status, string title) =>
        new(new ProblemDetails { Status = status, Title = title }) { StatusCode = status, ContentTypes = { "application/problem+json" } };

    protected IActionResult Precondition(string etag)
    {
        Response.Headers.ETag = etag;
        return Fail(412, "Precondition failed");
    }

    protected void SetEtag(string etag) => Response.Headers.ETag = etag;

    protected static bool Matches(string header, string etag) =>
        header.Split(',').Select(s => s.Trim()).Any(s => s == "*" || s == etag);

    protected static bool IsUnique(DbUpdateException ex) =>
        ex.InnerException is SqliteException { SqliteExtendedErrorCode: 2067 };
}

