public static class Canon
{
    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }

    static bool Norm(string? s, out string r)
    {
        r = "";
        if (s == null) return false;
        try { r = s.Normalize(NormalizationForm.C); return true; }
        catch (ArgumentException) { return false; }
    }

    public static string Blog(Guid id, string name) => "{\"id\":\"" + id.ToString("D") + "\",\"name\":" + Str(name) + "}";

    public static string Post(Guid id, Guid blogId, string title) =>
        "{\"id\":\"" + id.ToString("D") + "\",\"blogId\":\"" + blogId.ToString("D") + "\",\"title\":" + Str(title) + "}";

    public static string ETag(string canonical) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(canonical))).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";

    public static bool TryBlog(BlogRequest? b, out Guid id, out string name)
    {
        id = default; name = "";
        if (b?.Id == null || !Norm(b.Name, out name)) return false;
        id = b.Id.Value;
        return true;
    }

    public static bool TryPost(PostRequest? p, out Guid id, out Guid blogId, out string title)
    {
        id = default; blogId = default; title = "";
        if (p?.Id == null || p.BlogId == null || !Norm(p.Title, out title)) return false;
        id = p.Id.Value; blogId = p.BlogId.Value;
        return true;
    }
}

public abstract class ApiBase : ControllerBase
{
    protected IActionResult Err(int code, string title) =>
        new ObjectResult(new ProblemDetails { Status = code, Title = title })
        {
            StatusCode = code,
            ContentTypes = { "application/problem+json" }
        };

    protected void SetETag(string etag) => Response.Headers.ETag = etag;

    protected static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var part in header.Split(','))
        {
            var t = part.Trim();
            if (t == "*") return true;
            if (t.StartsWith("W/")) t = t.Substring(2);
            if (t == etag) return true;
        }
        return false;
    }

    protected static bool Unique(DbUpdateException ex) =>
        ex.InnerException is SqliteException { SqliteErrorCode: 19 } se && se.SqliteExtendedErrorCode is 2067 or 1555;
}

