public static class Canon
{
    public static string? Norm(string? s)
    {
        if (s is null) return null;
        try { return s.Normalize(NormalizationForm.FormC); } catch (ArgumentException) { return null; }
    }

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }

    static string Hash(string json)
    {
        var b = Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(json)))
            .Replace('+', '-').Replace('/', '_').TrimEnd('=');
        return "\"" + b + "\"";
    }

    public static string BlogTag(Guid id, string name) =>
        Hash("{\"id\":\"" + id.ToString("D") + "\",\"name\":" + Str(name) + "}");

    public static string PostTag(Guid id, Guid blogId, string title) =>
        Hash("{\"id\":\"" + id.ToString("D") + "\",\"blogId\":\"" + blogId.ToString("D") + "\",\"title\":" + Str(title) + "}");

    public static bool Matches(string? header, string etag, bool weak)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var t in header.Split(','))
        {
            var v = t.Trim();
            if (v == "*") return true;
            if (weak && v.StartsWith("W/")) v = v[2..];
            if (v == etag) return true;
        }
        return false;
    }
}

