    protected IActionResult Err(int status, string title) =>
        new ObjectResult(new ProblemDetails { Status = status, Title = title })
        { StatusCode = status, ContentTypes = { Pj } };

    protected IActionResult ErrTag(int status, string title, string etag)
    {
        Response.Headers.ETag = etag;
        return Err(status, title);
    }

    protected IActionResult NoContentTag(string etag)
    {
        Response.Headers.ETag = etag;
        return NoContent();
    }

    protected static bool IsUnique(DbUpdateException ex) =>
        ex.InnerException is SqliteException { SqliteErrorCode: 19 };
}

