public static class Canon
{
    public static string Nfc(string s) => s.Normalize(NormalizationForm.FormC);

    static string Q(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }

    public static string BlogJson(Guid id, string name) =>
        "{\"id\":\"" + id.ToString("D") + "\",\"name\":" + Q(name) + "}";

    public static string PostJson(Guid id, Guid blogId, string title) =>
        "{\"id\":\"" + id.ToString("D") + "\",\"blogId\":\"" + blogId.ToString("D") + "\",\"title\":" + Q(title) + "}";

    public static string ETag(string json) =>
        "\"" + Base64Url.EncodeToString(SHA256.HashData(Encoding.UTF8.GetBytes(json))) + "\"";

    public static bool IsUnique(DbUpdateException e) =>
        e.InnerException is SqliteException { SqliteErrorCode: 19, SqliteExtendedErrorCode: 2067 or 1555 };

    public static bool IsBusy(Exception e) =>
        e.InnerException is SqliteException { SqliteErrorCode: 5 or 6 } || e is SqliteException { SqliteErrorCode: 5 or 6 };
}

public abstract class ApiBase : ControllerBase
{
    protected const string Pj = "application/problem+json";

    protected ObjectResult Err(int status, string title)
    {
        var r = new ObjectResult(new ProblemDetails { Status = status, Title = title }) { StatusCode = status };
        r.ContentTypes.Add(Pj);
        return r;
    }

    protected void SetETag(string etag) => Response.Headers.ETag = etag;

    protected static bool Matches(string? header, string etag) =>
        header != null && header.Split(',').Select(t => t.Trim()).Any(t => t == "*" || t == etag);

    protected static bool NoneMatch(string? header, string etag) =>
        !string.IsNullOrWhiteSpace(header) && header.Split(',').Select(t => t.Trim())
            .Any(t => t == "*" || (t.StartsWith("W/") ? t[2..] : t) == etag);

    protected static bool TryNfc(string s, out string result)
    {
        try { result = Canon.Nfc(s); return true; }
        catch (ArgumentException) { result = ""; return false; }
    }
}

