public static class Canon
{
    public static string? Nfc(string? s)
    {
        if (s == null) return null;
        try { return s.Normalize(NormalizationForm.FormC); } catch (ArgumentException) { return null; }
    }

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }

    static string Hash(string json)
    {
        var h = SHA256.HashData(Encoding.UTF8.GetBytes(json));
        var b64 = Convert.ToBase64String(h).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + b64 + "\"";
    }

    public static string BlogTag(Guid id, string name) =>
        Hash("{\"id\":\"" + id.ToString("D") + "\",\"name\":" + Str(name) + "}");

    public static string PostTag(Guid id, Guid blogId, string title) =>
        Hash("{\"id\":\"" + id.ToString("D") + "\",\"blogId\":\"" + blogId.ToString("D") + "\",\"title\":" + Str(title) + "}");

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var raw in header.Split(','))
        {
            var t = raw.Trim();
            if (t == "*") return true;
            if (t.StartsWith("W/")) t = t.Substring(2);
            if (t == etag) return true;
        }
        return false;
    }
}

public abstract class ApiBase : ControllerBase
{
    protected const string Pj = "application/problem+json";

    protected IActionResult Err(int status, string title, string? etag = null)
    {
        if (etag != null) Response.Headers.ETag = etag;
        var r = new ObjectResult(new ProblemDetails { Status = status, Title = title }) { StatusCode = status };
        r.ContentTypes.Add(Pj);
        return r;
    }

    protected IActionResult Json(int status, object body, string etag)
    {
        Response.Headers.ETag = etag;
        return new ObjectResult(body) { StatusCode = status };
    }

    protected IActionResult NoContentTagged(string etag)
    {
        Response.Headers.ETag = etag;
        return NoContent();
    }

    protected static bool IsUnique(DbUpdateException e) =>
        e.InnerException is SqliteException { SqliteErrorCode: 19 };
}

