public class BlogsController : ApiBase
{
    private readonly AppDbContext db;
    public BlogsController(AppDbContext db) { this.db = db; }

    static bool Valid(BlogRequest? b, out Guid id, out string name)
    {
        id = default; name = "";
        if (b?.Id == null) return false;
        var n = Canon.Nfc(b.Name);
        if (n == null) return false;
        id = b.Id.Value; name = n;
        return true;
    }

    [HttpPost("blogs")]
    [ProducesResponseType(typeof(BlogResponse), 201)]
    [ProducesResponseType(typeof(BlogResponse), 200)]
    [ProducesResponseType(typeof(ProblemDetails), 400, Pj)]
    [ProducesResponseType(typeof(ProblemDetails), 409, Pj)]
    [ProducesResponseType(typeof(ProblemDetails), 410, Pj)]
    public async Task<IActionResult> Create([FromBody, Required] BlogRequest? body, CancellationToken ct)
    {
        if (!Valid(body, out var id, out var name)) return Err(400, "Invalid body");
        var etag = Canon.BlogTag(id, name);
        db.Blogs.Add(new Blog { PublicId = id, Name = name, ETag = etag, CreateHash = etag });
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException e) when (IsUnique(e))
        {
            db.ChangeTracker.Clear();
            var ex = await db.Blogs.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(b => b.PublicId == id, ct);
            if (ex == null) return Err(409, "Conflict");
            if (ex.DeletedAt != null) return Err(410, "Gone");
            if (ex.CreateHash != etag) return Err(409, "Id already used with different content");
            return Json(200, new BlogResponse(ex.PublicId, ex.Name), ex.ETag);
        }
        Response.Headers.ETag = etag;
        return Created($"/api/blogs/{id:D}", new BlogResponse(id, name));
    }

    [HttpGet("blogs/{id:guid}")]
    [ProducesResponseType(typeof(BlogResponse), 200)]
    [ProducesResponseType(304)]
    [ProducesResponseType(typeof(ProblemDetails), 404, Pj)]
    [ProducesResponseType(typeof(ProblemDetails), 410, Pj)]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var b = await db.Blogs.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (b == null) return Err(404, "Not found");
        if (b.DeletedAt != null) return Err(410, "Gone");
        if (Canon.Matches(Request.Headers.IfNoneMatch.ToString(), b.ETag))
        {
            Response.Headers.ETag = b.ETag;
            return StatusCode(304);
        }
        return Json(200, new BlogResponse(b.PublicId, b.Name), b.ETag);
    }

    [HttpPut("blogs/{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 400, Pj)]
    [ProducesResponseType(typeof(ProblemDetails), 404, Pj)]
    [ProducesResponseType(typeof(ProblemDetails), 410, Pj)]
    [ProducesResponseType(typeof(ProblemDetails), 412, Pj)]
    [ProducesResponseType(typeof(ProblemDetails), 428, Pj)]
    public async Task<IActionResult> Put(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        [FromBody, Required] BlogRequest? body, CancellationToken ct)
    {
        if (!Valid(body, out var bid, out var name) || bid != id) return Err(400, "Invalid body");
        if (string.IsNullOrWhiteSpace(ifMatch)) return Err(428, "If-Match required");
        var etag = Canon.BlogTag(id, name);
        string? current = null;
        for (var i = 0; i < 5; i++)
        {
            var b = await db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (b == null) return Err(404, "Not found");
            if (b.DeletedAt != null) return Err(410, "Gone");
            current = b.ETag;
            if (b.ETag == etag) return NoContentTagged(etag);
            if (!Canon.Matches(ifMatch, b.ETag)) return Err(412, "Precondition failed", b.ETag);
            b.Name = name; b.ETag = etag;
            try
            {
                await db.SaveChangesAsync(ct);
                return NoContentTagged(etag);
            }
            catch (DbUpdateConcurrencyException) { db.ChangeTracker.Clear(); }
        }
        return Err(412, "Precondition failed", current);
    }

    [HttpDelete("blogs/{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 412, Pj)]
    [ProducesResponseType(typeof(ProblemDetails), 428, Pj)]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch)) return Err(428, "If-Match required");
        string? current = null;
        for (var i = 0; i < 5; i++)
        {
            var b = await db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (b == null || b.DeletedAt != null) return NoContent();
            current = b.ETag;
            if (!Canon.Matches(ifMatch, b.ETag)) return Err(412, "Precondition failed", b.ETag);
            var now = DateTime.UtcNow;
            b.DeletedAt = now; b.ETag = "deleted";
            var posts = await db.Posts.Where(p => p.BlogId == b.Id).ToListAsync(ct);
            foreach (var p in posts) { p.DeletedAt = now; p.ETag = "deleted"; }
            try
            {
                await db.SaveChangesAsync(ct);
                return NoContent();
            }
            catch (DbUpdateConcurrencyException) { db.ChangeTracker.Clear(); }
        }
        return Err(412, "Precondition failed", current);
    }
}

