public static class Canon
{
    public static bool TryNormalize(string? s, out string result)
    {
        result = "";
        if (s is null) return false;
        try { result = s.Normalize(NormalizationForm.FormC); return true; }
        catch (ArgumentException) { return false; }
    }

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }

    public static string Hash(string canonical)
    {
        var h = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return "\"" + Convert.ToBase64String(h).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    public static string BlogETag(Guid id, string name) =>
        Hash("{\"id\":\"" + id.ToString("D") + "\",\"name\":" + Str(name) + "}");

    public static string PostETag(Guid id, Guid blogId, string title) =>
        Hash("{\"id\":\"" + id.ToString("D") + "\",\"blogId\":\"" + blogId.ToString("D") + "\",\"title\":" + Str(title) + "}");

    public static bool TryBlog(BlogRequest? b, out Guid id, out string name)
    {
        id = default; name = "";
        if (b is null || b.Id is null || b.Id == Guid.Empty) return false;
        id = b.Id.Value;
        return TryNormalize(b.Name, out name);
    }

    public static bool TryPost(PostRequest? p, out Guid id, out Guid blogId, out string title)
    {
        id = default; blogId = default; title = "";
        if (p is null || p.Id is null || p.Id == Guid.Empty || p.BlogId is null || p.BlogId == Guid.Empty) return false;
        id = p.Id.Value; blogId = p.BlogId.Value;
        return TryNormalize(p.Title, out title);
    }

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var raw in header.Split(','))
        {
            var t = raw.Trim();
            if (t.StartsWith("W/")) t = t.Substring(2);
            if (t == "*" || t == etag) return true;
        }
        return false;
    }

    public static bool IsUnique(DbUpdateException ex) =>
        ex.InnerException is SqliteException { SqliteErrorCode: 19, SqliteExtendedErrorCode: 2067 or 1555 };

    public static string Tombstone() => Hash("deleted:" + Guid.NewGuid().ToString("D"));
}

public abstract class ApiBase : ControllerBase
{
    protected IActionResult Fail(int status, string detail) =>
        new ObjectResult(new ProblemDetails { Status = status, Title = detail, Detail = detail })
        {
            StatusCode = status,
            ContentTypes = { "application/problem+json" }
        };

    protected IActionResult Stale(string etag)
    {
        Response.Headers.ETag = etag;
        return Fail(412, "The If-Match precondition failed.");
    }

    protected IActionResult NoContentWith(string etag)
    {
        Response.Headers.ETag = etag;
        return NoContent();
    }

    protected IActionResult Gone() => Fail(410, "The resource has been deleted.");
    protected IActionResult NotFoundProblem() => Fail(404, "The resource was not found.");
    protected IActionResult Bad(string detail = "Invalid request.") => Fail(400, detail);
    protected IActionResult Missing() => Fail(428, "The If-Match header is required.");
}

