public static class Canon
{
    public static string? Nfc(string? s)
    {
        if (s is null) return null;
        try { return s.Normalize(NormalizationForm.FormC); }
        catch (ArgumentException) { return null; }
    }

    static void Str(StringBuilder sb, string s)
    {
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }

    static string Hash(StringBuilder sb)
    {
        var h = SHA256.HashData(Encoding.UTF8.GetBytes(sb.ToString()));
        var b64 = Convert.ToBase64String(h).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + b64 + "\"";
    }

    public static string Blog(Guid id, string name)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("D")).Append("\",\"name\":");
        Str(sb, name);
        sb.Append('}');
        return Hash(sb);
    }

    public static string Post(Guid id, Guid blogId, string title)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("D")).Append("\",\"blogId\":\"").Append(blogId.ToString("D")).Append("\",\"title\":");
        Str(sb, title);
        sb.Append('}');
        return Hash(sb);
    }
}

public abstract class ApiBase : ControllerBase
{
    protected IActionResult Err(int status, string title)
    {
        var r = new ObjectResult(new ProblemDetails { Status = status, Title = title }) { StatusCode = status };
        r.ContentTypes.Add("application/problem+json");
        return r;
    }

    protected IActionResult ErrTag(int status, string title, string etag)
    {
        Response.Headers.ETag = etag;
        return Err(status, title);
    }

    protected IActionResult NoContentTag(string etag)
    {
        Response.Headers.ETag = etag;
        return NoContent();
    }

    protected string IfMatch => Request.Headers.IfMatch.ToString();

    protected static bool TagMatches(string header, string etag) =>
        header.Split(',').Select(t => t.Trim()).Any(t => t == "*" || (t.StartsWith("W/") ? t[2..] : t) == etag);

    protected static bool IsUnique(DbUpdateException e) =>
        e.InnerException is SqliteException s && s.SqliteExtendedErrorCode is 2067 or 1555;

    protected bool NotModified(string etag)
    {
        var inm = Request.Headers.IfNoneMatch.ToString();
        return !string.IsNullOrWhiteSpace(inm) && TagMatches(inm, etag);
    }
}

