[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly AppDbContext _db;
    public SupportTicketsController(AppDbContext db) => _db = db;

    private IActionResult WithEtag(Ticket t, TicketDto dto, int status = 200)
    {
        Response.Headers.ETag = $"\"{t.Version}\"";
        return status == 201
            ? Created($"/api/support-tickets/{t.Id}", dto)
            : Ok(dto);
    }

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] TicketRequest req, CancellationToken ct)
    {
        string? key = Request.Headers["Idempotency-Key"].FirstOrDefault();
        if (string.IsNullOrWhiteSpace(key)) key = null;

        if (key != null)
        {
            var prior = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.IdempotencyKey == key, ct);
            if (prior != null) return WithEtag(prior, TicketDto.From(prior), 201);
        }
        if (req.Id is Guid rid && rid != Guid.Empty)
        {
            var prior = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == rid, ct);
            if (prior != null) return WithEtag(prior, TicketDto.From(prior), 201);
        }

        var ticket = new Ticket
        {
            Id = req.Id is Guid g && g != Guid.Empty ? g : Guid.NewGuid(),
            Subject = req.Subject!,
            Priority = req.Priority,
            Escalated = req.Escalated,
            Category = req.Category ?? "",
            IdempotencyKey = key,
            Version = 1
        };
        _db.Tickets.Add(ticket);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();
            var existing = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(
                t => t.Id == ticket.Id || (key != null && t.IdempotencyKey == key), ct);
            if (existing == null) throw;
            return WithEtag(existing, TicketDto.From(existing), 201);
        }
        return WithEtag(ticket, TicketDto.From(ticket), 201);
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        int rows = await _db.Tickets.Where(t => t.Id == id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, now), ct);
        if (rows == 0) return NotFound();
        var ticket = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id, ct);
        if (ticket == null) return NotFound();
        return WithEtag(ticket, TicketDto.From(ticket));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] TicketRequest req, CancellationToken ct)
    {
        if (req.Id is Guid bid && bid != Guid.Empty && bid != id)
            return BadRequest("Id in body does not match route.");

        long? expected = null;
        string? ifMatch = Request.Headers.IfMatch.FirstOrDefault();
        if (!string.IsNullOrWhiteSpace(ifMatch) && ifMatch.Trim() != "*")
        {
            var raw = ifMatch.Trim();
            if (raw.StartsWith("W/")) raw = raw[2..];
            if (!long.TryParse(raw.Trim('"'), out var v)) return StatusCode(StatusCodes.Status412PreconditionFailed);
            expected = v;
        }

        string subject = req.Subject!;
        string category = req.Category ?? "";
        int priority = req.Priority;
        bool escalated = req.Escalated;

        int rows = await _db.Tickets
            .Where(t => t.Id == id && (expected == null || t.Version == expected))
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.Subject, subject)
                .SetProperty(t => t.Priority, priority)
                .SetProperty(t => t.Escalated, escalated)
                .SetProperty(t => t.Category, category)
                .SetProperty(t => t.Version, t => t.Version + 1), ct);

        if (rows == 0)
        {
            bool exists = await _db.Tickets.AnyAsync(t => t.Id == id, ct);
            return exists ? StatusCode(StatusCodes.Status412PreconditionFailed) : NotFound();
        }
        var ticket = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id, ct);
        if (ticket == null) return NotFound();
        return WithEtag(ticket, TicketDto.From(ticket));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        long? expected = null;
        string? ifMatch = Request.Headers.IfMatch.FirstOrDefault();
        if (!string.IsNullOrWhiteSpace(ifMatch) && ifMatch.Trim() != "*")
        {
            var raw = ifMatch.Trim();
            if (raw.StartsWith("W/")) raw = raw[2..];
            if (!long.TryParse(raw.Trim('"'), out var v)) return StatusCode(StatusCodes.Status412PreconditionFailed);
            expected = v;
        }
        int rows = await _db.Tickets
            .Where(t => t.Id == id && (expected == null || t.Version == expected))
            .ExecuteDeleteAsync(ct);
        if (rows == 0)
        {
            bool exists = await _db.Tickets.AnyAsync(t => t.Id == id, ct);
            return exists ? StatusCode(StatusCodes.Status412PreconditionFailed) : NotFound();
        }
        return NoContent();
    }
}
