public class SupportTicketsController : ControllerBase
{
    private readonly SupportDbContext _db;
    public SupportTicketsController(SupportDbContext db) => _db = db;

    private static TicketResponse ToDto(Ticket t) => new()
    {
        Id = t.Id, Subject = t.Subject, Priority = t.Priority, Escalated = t.Escalated, Category = t.Category
    };

    private void SetEtag(Ticket t) => Response.Headers.ETag = $"\"{t.Version}\"";

    private static bool Valid(TicketRequest? r) => r != null && !string.IsNullOrWhiteSpace(r.Subject);

    private static bool SameContent(Ticket t, TicketRequest r) =>
        t.Subject == r.Subject && t.Priority == (r.Priority ?? 0) &&
        t.Escalated == (r.Escalated ?? false) && t.Category == (r.Category ?? "");

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] TicketRequest? req, CancellationToken ct)
    {
        if (!Valid(req)) return BadRequest();
        req!.Subject = req.Subject!;

        string? key = Request.Headers["Idempotency-Key"].FirstOrDefault();
        if (string.IsNullOrWhiteSpace(key)) key = null;

        if (key != null)
        {
            var rec = await _db.IdempotencyRecords.AsNoTracking().FirstOrDefaultAsync(r => r.Key == key, ct);
            if (rec != null)
            {
                var prev = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == rec.TicketId, ct);
                if (prev != null) { SetEtag(prev); return Ok(ToDto(prev)); }
            }
        }

        var id = req.Id is { } g && g != Guid.Empty ? g : Guid.NewGuid();

        var existing = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id, ct);
        if (existing != null)
        {
            if (!SameContent(existing, req)) return Conflict();
            SetEtag(existing);
            return Ok(ToDto(existing));
        }

        var ticket = new Ticket
        {
            Id = id,
            Subject = req.Subject!,
            Priority = req.Priority ?? 0,
            Escalated = req.Escalated ?? false,
            Category = req.Category ?? ""
        };
        _db.Tickets.Add(ticket);
        if (key != null) _db.IdempotencyRecords.Add(new IdempotencyRecord { Key = key, TicketId = id });

        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();
            Ticket? winner = null;
            if (key != null)
            {
                var rec = await _db.IdempotencyRecords.AsNoTracking().FirstOrDefaultAsync(r => r.Key == key, ct);
                if (rec != null)
                    winner = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == rec.TicketId, ct);
            }
            winner ??= await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id, ct);
            if (winner == null) throw;
            if (key == null && !SameContent(winner, req)) return Conflict();
            SetEtag(winner);
            return Ok(ToDto(winner));
        }

        SetEtag(ticket);
        return Created($"/api/support-tickets/{ticket.Id}", ToDto(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        var rows = await _db.Tickets.Where(t => t.Id == id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, now), ct);
        if (rows == 0) return NotFound();

        var ticket = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id, ct);
        if (ticket == null) return NotFound();
        SetEtag(ticket);
        return Ok(ToDto(ticket));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] TicketRequest? req, CancellationToken ct)
    {
        if (!Valid(req)) return BadRequest();
        if (req!.Id is { } bodyId && bodyId != Guid.Empty && bodyId != id) return BadRequest();

        long? expected = null;
        var ifMatch = Request.Headers.IfMatch.FirstOrDefault();
        if (!string.IsNullOrWhiteSpace(ifMatch) && ifMatch.Trim() != "*")
        {
            var v = ifMatch.Trim();
            if (v.StartsWith("W/")) v = v[2..];
            v = v.Trim('"');
            if (!long.TryParse(v, out var parsed)) return StatusCode(StatusCodes.Status412PreconditionFailed);
            expected = parsed;
        }

        var subject = req.Subject!;
        var priority = req.Priority ?? 0;
        var escalated = req.Escalated ?? false;
        var category = req.Category ?? "";

        var q = _db.Tickets.Where(t => t.Id == id);
        if (expected != null) { var e = expected.Value; q = q.Where(t => t.Version == e); }

        var rows = await q.ExecuteUpdateAsync(s => s
            .SetProperty(t => t.Subject, subject)
            .SetProperty(t => t.Priority, priority)
            .SetProperty(t => t.Escalated, escalated)
            .SetProperty(t => t.Category, category)
            .SetProperty(t => t.Version, t => t.Version + 1), ct);

        var ticket = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id, ct);
        if (ticket == null) return NotFound();
        if (rows == 0) return StatusCode(StatusCodes.Status412PreconditionFailed);
        SetEtag(ticket);
        return Ok(ToDto(ticket));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var rows = await _db.Tickets.Where(t => t.Id == id).ExecuteDeleteAsync(ct);
        return rows == 0 ? NotFound() : NoContent();
    }
}
