        var s = header.Trim();
        if (s == "*") return true;
        if (s.StartsWith("W/")) s = s[2..];
        s = s.Trim('"');
        if (!Guid.TryParse(s, out var g)) return false;
        version = g;
        return true;
    }

    private async Task<IActionResult> ExistingResult(Guid id, bool created)
    {
        var t = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id);
        if (t == null) return Conflict();
        Response.Headers.ETag = ETagOf(t.Version);
        var body = TicketResponse.From(t);
        return created
            ? Created($"/api/support-tickets/{t.Id}", body)
            : Ok(body);
    }

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] TicketDto dto,
        [FromHeader(Name = "Idempotency-Key")] string? idempotencyKey)
    {
        if (string.IsNullOrWhiteSpace(dto.Subject) || dto.Category == null)
            return BadRequest();
        if (dto.Id == Guid.Empty) return BadRequest();

        if (!string.IsNullOrEmpty(idempotencyKey))
        {
            var rec = await _db.IdempotencyRecords.AsNoTracking()
                .FirstOrDefaultAsync(r => r.Key == idempotencyKey);
            if (rec != null) return await ExistingResult(rec.TicketId, true);
        }

        var id = dto.Id ?? Guid.NewGuid();
        if (dto.Id != null && await _db.Tickets.AnyAsync(t => t.Id == id))
            return await ExistingResult(id, false);

        var ticket = new Ticket
        {
            Id = id,
            Subject = dto.Subject,
            Priority = dto.Priority,
            Escalated = dto.Escalated,
            Category = dto.Category,
            ViewCount = 0,
            LastViewedAt = null,
            Version = Guid.NewGuid()
        };
        _db.Tickets.Add(ticket);
        if (!string.IsNullOrEmpty(idempotencyKey))
            _db.IdempotencyRecords.Add(new IdempotencyRecord { Key = idempotencyKey, TicketId = id });

        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();
            if (!string.IsNullOrEmpty(idempotencyKey))
            {
                var rec = await _db.IdempotencyRecords.AsNoTracking()
                    .FirstOrDefaultAsync(r => r.Key == idempotencyKey);
                if (rec != null) return await ExistingResult(rec.TicketId, true);
            }
            if (dto.Id != null && await _db.Tickets.AnyAsync(t => t.Id == id))
                return await ExistingResult(id, false);
            throw;
        }

        Response.Headers.ETag = ETagOf(ticket.Version);
        return Created($"/api/support-tickets/{ticket.Id}", TicketResponse.From(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id)
    {
        var now = DateTime.UtcNow;
        var n = await _db.Tickets.Where(t => t.Id == id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, (DateTime?)now));
        if (n == 0) return NotFound();
        var ticket = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id);
        if (ticket == null) return NotFound();
        Response.Headers.ETag = ETagOf(ticket.Version);
        return Ok(TicketResponse.From(ticket));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] TicketDto dto,
        [FromHeader(Name = "If-Match")] string? ifMatch)
    {
        if (string.IsNullOrWhiteSpace(dto.Subject) || dto.Category == null)
            return BadRequest();
        if (dto.Id != null && dto.Id != id) return BadRequest();
        if (!TryParseIfMatch(ifMatch, out var expected)) return StatusCode(412);

        var newVersion = Guid.NewGuid();
        var n = await _db.Tickets
            .Where(t => t.Id == id && (expected == null || t.Version == expected))
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.Subject, dto.Subject)
                .SetProperty(t => t.Priority, dto.Priority)
                .SetProperty(t => t.Escalated, dto.Escalated)
                .SetProperty(t => t.Category, dto.Category)
                .SetProperty(t => t.Version, newVersion));

        if (n == 0)
        {
            return await _db.Tickets.AnyAsync(t => t.Id == id)
                ? StatusCode(412)
                : NotFound();
        }

        var ticket = await _db.Tickets.AsNoTracking().FirstAsync(t => t.Id == id);
        Response.Headers.ETag = ETagOf(ticket.Version);
        return Ok(TicketResponse.From(ticket));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var n = await _db.Tickets.Where(t => t.Id == id).ExecuteDeleteAsync();
        return n == 0 ? NotFound() : NoContent();
    }
}
```

Design notes on retries and concurrent edits:

- **Retried POST:** The server honors an optional `Idempotency-Key` header. A repeated key returns the originally created ticket instead of creating a duplicate. A client-supplied `id` is also treated idempotently, so a repeat returns the existing ticket. A race between two identical requests is resolved by the primary-key conflict, after which the existing ticket is returned.
- **Concurrent PUT:** Each ticket has a `Version` that changes on every update, and it is exposed as the `ETag` header. With `If-Match`, a stale version gets `412`. Without it, the update is a single atomic statement, so the last write wins and nothing fails.
- **Concurrent GET:** `ViewCount` and `LastViewedAt` are incremented atomically in SQL, so concurrent views aren't lost. Because the PUT never touches those columns and the view update never changes `Version`, they don't conflict with each other. Clients can't set them.
- **DELETE:** A single atomic delete returns `404` if the ticket is already gone.

