    [HttpPost]
    public async Task<IActionResult> Create([FromBody] TicketRequest? req, CancellationToken ct)
    {
        if (req == null || string.IsNullOrWhiteSpace(req.Subject))
            return BadRequest(new { error = "subject is required" });

        string? key = Request.Headers["Idempotency-Key"].FirstOrDefault();
        if (string.IsNullOrWhiteSpace(key)) key = null;

        if (key != null)
        {
            var prev = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.IdempotencyKey == key, ct);
            if (prev != null) { SetETag(prev); return Ok(ToDto(prev)); }
        }
        if (req.Id is Guid rid && rid != Guid.Empty)
        {
            var prev = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == rid, ct);
            if (prev != null) { SetETag(prev); return Ok(ToDto(prev)); }
        }

        var ticket = new Ticket
        {
            Id = req.Id is Guid g && g != Guid.Empty ? g : Guid.NewGuid(),
            Subject = req.Subject,
            Priority = req.Priority,
            Escalated = req.Escalated,
            Category = req.Category ?? "",
            IdempotencyKey = key,
            Version = Guid.NewGuid()
        };
        _db.Tickets.Add(ticket);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();
            var existing = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(
                t => t.Id == ticket.Id || (key != null && t.IdempotencyKey == key), ct);
            if (existing == null) throw;
            SetETag(existing);
            return Ok(ToDto(existing));
        }
        SetETag(ticket);
        return Created($"/api/support-tickets/{ticket.Id}", ToDto(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        var rows = await _db.Tickets.Where(t => t.Id == id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, now), ct);
        if (rows == 0) return NotFound();
        var ticket = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id, ct);
        if (ticket == null) return NotFound();
        SetETag(ticket);
        return Ok(ToDto(ticket));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] TicketRequest? req, CancellationToken ct)
    {
        if (req == null || string.IsNullOrWhiteSpace(req.Subject))
            return BadRequest(new { error = "subject is required" });
        if (req.Id is Guid bid && bid != Guid.Empty && bid != id)
            return BadRequest(new { error = "id mismatch" });

        string? ifMatch = Request.Headers.IfMatch.FirstOrDefault()?.Trim();
        bool conditional = !string.IsNullOrEmpty(ifMatch) && ifMatch != "*";
        string? expected = conditional ? ifMatch!.Trim('"') : null;

        for (int attempt = 0; attempt < 20; attempt++)
        {
            var ticket = await _db.Tickets.FirstOrDefaultAsync(t => t.Id == id, ct);
            if (ticket == null) return NotFound();
            if (conditional && !string.Equals(ticket.Version.ToString(), expected, StringComparison.OrdinalIgnoreCase))
                return StatusCode(StatusCodes.Status412PreconditionFailed);

            ticket.Subject = req.Subject;
            ticket.Priority = req.Priority;
            ticket.Escalated = req.Escalated;
            ticket.Category = req.Category ?? "";
            ticket.Version = Guid.NewGuid();
            try
            {
                await _db.SaveChangesAsync(ct);
                SetETag(ticket);
                return Ok(ToDto(ticket));
            }
            catch (DbUpdateConcurrencyException)
            {
                _db.ChangeTracker.Clear();
                if (conditional) return StatusCode(StatusCodes.Status412PreconditionFailed);
            }
        }
        return StatusCode(StatusCodes.Status409Conflict);
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var rows = await _db.Tickets.Where(t => t.Id == id).ExecuteDeleteAsync(ct);
        return rows == 0 ? NotFound() : NoContent();
    }
}
