        string? key = Request.Headers["Idempotency-Key"].FirstOrDefault();
        if (string.IsNullOrWhiteSpace(key)) key = null;

        if (key != null)
        {
            var rec = await _db.IdempotencyRecords.AsNoTracking().FirstOrDefaultAsync(r => r.Key == key, ct);
            if (rec != null) return await Replay(rec.TicketId, ct);
        }

        var id = req!.Id is { } g && g != Guid.Empty ? g : Guid.NewGuid();
        var existing = await Load(id, ct);
        if (existing != null) return SameContent(existing, req) ? Ok(TicketResponse.From(existing)) : Conflict();

        var ticket = new Ticket
        {
            Id = id, Subject = req.Subject!, Priority = req.Priority,
            Escalated = req.Escalated, Category = req.Category!
        };
        _db.Tickets.Add(ticket);
        if (key != null) _db.IdempotencyRecords.Add(new IdempotencyRecord { Key = key, TicketId = id });

        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();
            if (key != null)
            {
                var rec = await _db.IdempotencyRecords.AsNoTracking().FirstOrDefaultAsync(r => r.Key == key, ct);
                if (rec != null) return await Replay(rec.TicketId, ct);
            }
            var again = await Load(id, ct);
            if (again != null && SameContent(again, req)) return Ok(TicketResponse.From(again));
            return Conflict();
        }

        SetEtag(ticket.Version);
        return Created($"/api/support-tickets/{id}", TicketResponse.From(ticket));
    }

