        r != null && r.Id.HasValue && r.Id.Value != Guid.Empty && r.Subject != null
        && r.Priority.HasValue && r.Escalated.HasValue && r.Category != null;

    static bool IsBusy(Exception e) =>
        e is SqliteException s && (s.SqliteErrorCode == 5 || s.SqliteErrorCode == 6);

    async Task SaveAsync(CancellationToken ct)
    {
        for (var attempt = 0; ; attempt++)
        {
            try { await _db.SaveChangesAsync(ct); return; }
            catch (DbUpdateException e) when (e is not DbUpdateConcurrencyException && IsBusy(e.InnerException!) && attempt < 8)
            {
                await Task.Delay(25 * (attempt + 1), ct);
            }
