            var existing = await _db.Tickets.IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(t => t.PublicId == id, ct);
            if (existing == null) throw;
            if (existing.DeletedAt != null) return Problem(410, "Ticket was deleted.");
            if (existing.CreateHash != etag) return Problem(409, "A ticket with this id exists with different content.", existing.ETag);
            Response.Headers.ETag = existing.ETag;
