        if (string.IsNullOrWhiteSpace(ifMatch)) return Problem(428, "If-Match header is required.");

        var newEtag = TicketCanonical.Hash(id, request.Subject!, request.Priority!.Value, request.Escalated!.Value, request.Category!);
        for (var attempt = 0; attempt < 5; attempt++)
