public class FlexibleIntConverter : JsonConverter<int?>
{
    public override int? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        if (reader.TokenType == JsonTokenType.Null) return null;
        if (reader.TokenType != JsonTokenType.Number) throw new JsonException("priority must be a number");
        if (reader.TryGetInt32(out var i)) return i;
        if (reader.TryGetDecimal(out var d) && d == decimal.Truncate(d) && d >= int.MinValue && d <= int.MaxValue)
            return (int)d;
        throw new JsonException("priority must be an integer");
    }

    public override void Write(Utf8JsonWriter writer, int? value, JsonSerializerOptions options)
    {
        if (value is null) writer.WriteNullValue(); else writer.WriteNumberValue(value.Value);
    }
}

