        if (v is null) return Err(400, "Invalid request");
        var etag = TicketCanonical.ETag(v);
        var entity = new Ticket
        {
            PublicId = v.Id,
            Subject = v.Subject,
            Priority = v.Priority,
            Escalated = v.Escalated,
            Category = v.Category,
            ETag = etag,
            CreateHash = etag
        };
        _db.Tickets.Add(entity);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.Entry(entity).State = EntityState.Detached;
            var existing = await _db.Tickets.IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(t => t.PublicId == v.Id, ct);
            if (existing is null) throw;
            if (existing.DeletedAt != null) return Err(410, "Gone");
            if (existing.CreateHash != etag) return Err(409, "Conflict");
            Response.Headers.ETag = existing.ETag;
            return Ok(ToResponse(existing));
        }
        Response.Headers.ETag = etag;
        return Created($"{Request.PathBase}/api/support-tickets/{v.Id:D}", ToResponse(entity));
    }

