[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private const string Pj = "application/problem+json";
    private readonly AppDbContext _db;

    public SupportTicketsController(AppDbContext db) => _db = db;

    private static string Normalize(string s) => s.Normalize(NormalizationForm.FormC);

    private static bool IsValid(TicketRequest? b) =>
        b is { Id: { } id } && id != Guid.Empty && b.Subject != null && b.Priority != null
        && b.Escalated != null && b.Category != null;

    private static void Escape(StringBuilder sb, string s)
    {
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }

    private static string ComputeETag(Guid id, string subject, int priority, bool escalated, string category)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("D").ToLowerInvariant()).Append("\",\"subject\":");
        Escape(sb, Normalize(subject));
        sb.Append(",\"priority\":").Append(priority.ToString(CultureInfo.InvariantCulture));
        sb.Append(",\"escalated\":").Append(escalated ? "true" : "false");
        sb.Append(",\"category\":");
        Escape(sb, Normalize(category));
        sb.Append('}');
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(sb.ToString()));
        return "\"" + Base64Url.EncodeToString(hash) + "\"";
    }

    private static bool HeaderMatches(string header, string current)
    {
        foreach (var part in header.Split(','))
        {
            var p = part.Trim();
            if (p == "*") return true;
