public static class Canonical
{
    static string Norm(string s) => s.Normalize(NormalizationForm.FormC);

    static void WriteString(StringBuilder sb, string s)
    {
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }

    public static string Json(Guid id, string subject, int priority, bool escalated, string category)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":");
        WriteString(sb, id.ToString("D").ToLowerInvariant());
        sb.Append(",\"subject\":");
        WriteString(sb, Norm(subject));
        sb.Append(",\"priority\":").Append(priority.ToString(CultureInfo.InvariantCulture));
        sb.Append(",\"escalated\":").Append(escalated ? "true" : "false");
        sb.Append(",\"category\":");
        WriteString(sb, Norm(category));
        sb.Append('}');
        return sb.ToString();
    }

    public static string ETag(Guid id, string subject, int priority, bool escalated, string category)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(Json(id, subject, priority, escalated, category)));
        var b64 = Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + b64 + "\"";
    }

    public static string Normalize(string s) => Norm(s);

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var raw in header.Split(','))
        {
            var t = raw.Trim();
            if (t == "*") return true;
            if (t.StartsWith("W/", StringComparison.Ordinal)) t = t[2..];
            if (t == etag) return true;
        }
        return false;
    }
}

public class RequiredIfMatchProvider : IApiDescriptionProvider
{
    public int Order => 0;

    public void OnProvidersExecuting(ApiDescriptionProviderContext context) { }

    public void OnProvidersExecuted(ApiDescriptionProviderContext context)
    {
        foreach (var d in context.Results)
            foreach (var p in d.ParameterDescriptions)
                if (p.Source == BindingSource.Header && string.Equals(p.Name, "If-Match", StringComparison.OrdinalIgnoreCase))
                    p.IsRequired = true;
    }
}

