    {
        var deleted = await _db.Tickets.IgnoreQueryFilters().AsNoTracking()
            .AnyAsync(t => t.PublicId == id && t.DeletedAt != null, ct);
        return deleted ? Err(410, "Gone") : Err(404, "Not Found");
    }

    static bool IsUnique(DbUpdateException ex) =>
        ex.InnerException is SqliteException { SqliteErrorCode: 19 };

    [HttpPost]
    [ProducesResponseType<TicketResponse>(StatusCodes.Status201Created)]
    [ProducesResponseType<TicketResponse>(StatusCodes.Status200OK)]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status400BadRequest, Pj)]
