        {
            PublicId = id,
            Subject = subject,
            Priority = request.Priority.Value,
            Escalated = request.Escalated.Value,
            Category = category,
            ETag = etag,
            CreateHash = etag
        };
        _db.Tickets.Add(entity);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (IsUnique(ex))
        {
            _db.ChangeTracker.Clear();
            var existing = await _db.Tickets.IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(t => t.PublicId == id, ct);
            if (existing is null) throw;
            if (existing.DeletedAt != null) return Err(410, "Gone");
            if (existing.CreateHash != etag) return Err(409, "Conflict");
            SetETag(existing.ETag);
            return Ok(ToResponse(existing));
        }

        SetETag(entity.ETag);
        return CreatedAtAction(nameof(Get), new { id }, ToResponse(entity));
    }

