    [ProducesResponseType<TicketResponse>(StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status404NotFound, Pj)]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status410Gone, Pj)]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var t = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null) return await NotFoundOrGone(id, ct);

        try
        {
            var now = DateTime.UtcNow;
            await _db.Tickets.Where(x => x.PublicId == id)
                .ExecuteUpdateAsync(s => s
                    .SetProperty(x => x.ViewCount, x => x.ViewCount + 1)
