    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status400BadRequest, Pj)]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status404NotFound, Pj)]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status410Gone, Pj)]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status412PreconditionFailed, Pj)]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status428PreconditionRequired, Pj)]
    public async Task<IActionResult> Update(Guid id, [FromBody] TicketRequest request,
        [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken ct)
    {
        if (request.Id is null || request.Id != id) return Err(400, "Body id must equal route id");
        if (string.IsNullOrWhiteSpace(ifMatch)) return Err(428, "If-Match required");

        var subject = Canonical.Normalize(request.Subject!);
        var category = Canonical.Normalize(request.Category!);
        var priority = request.Priority!.Value;
        var escalated = request.Escalated!.Value;
        var newEtag = Canonical.ETag(id, subject, priority, escalated, category);

        var t = await _db.Tickets.FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null) return await NotFoundOrGone(id, ct);

        if (t.ETag == newEtag)
        {
            SetETag(t.ETag);
            return NoContent();
        }
        if (!Canonical.Matches(ifMatch, t.ETag))
        {
            SetETag(t.ETag);
            return Err(412, "Precondition Failed");
