        t.Subject = subject;
        t.Priority = priority;
        t.Escalated = escalated;
        t.Category = category;
        t.ETag = newEtag;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();
            var cur = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (cur is null) return await NotFoundOrGone(id, ct);
            SetETag(cur.ETag);
            if (cur.ETag == newEtag) return NoContent();
            return Err(412, "Precondition Failed");
        }

        SetETag(newEtag);
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status412PreconditionFailed, Pj)]
