using System.Text.Json;
using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace WarehouseApi;

public class Depot
{
    public Guid Id { get; set; }
    public string Code { get; set; } = "";
    public int CapacityCubicMeters { get; set; }
    public DateTime? LastAuditAt { get; set; }
    public Guid Version { get; set; }
    public List<Consignment> Consignments { get; set; } = new();
}

public class Consignment
{
    public Guid Id { get; set; }
    public Guid DepotId { get; set; }
    public Depot? Depot { get; set; }
    public string Reference { get; set; } = "";
    public decimal WeightKg { get; set; }
    public bool Fragile { get; set; }
    public int DownloadCount { get; set; }
    public Guid Version { get; set; }
}

public class IdempotencyRecord
{
    public string Key { get; set; } = "";
    public string Body { get; set; } = "";
    public string Location { get; set; } = "";
}

public class AppDbContext : DbContext
{
    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }
    public DbSet<Depot> Depots => Set<Depot>();
    public DbSet<Consignment> Consignments => Set<Consignment>();
    public DbSet<IdempotencyRecord> IdempotencyRecords => Set<IdempotencyRecord>();

    protected override void OnModelCreating(ModelBuilder b)
    {
        b.Entity<Depot>(e =>
        {
            e.HasKey(x => x.Id);
            e.Property(x => x.Version).IsConcurrencyToken();
            e.HasMany(x => x.Consignments).WithOne(x => x.Depot).HasForeignKey(x => x.DepotId).OnDelete(DeleteBehavior.Cascade);
        });
        b.Entity<Consignment>(e =>
        {
            e.HasKey(x => x.Id);
            e.Property(x => x.Version).IsConcurrencyToken();
        });
        b.Entity<IdempotencyRecord>().HasKey(x => x.Key);
    }
}

public static class AppSetup
{
    public static void ConfigureServices(IServiceCollection services, string sqliteConnectionString)
    {
        services.AddDbContext<AppDbContext>(o => o.UseSqlite(sqliteConnectionString));
    }
}

public class WarehouseRequest
{
    [Required] public string? Code { get; set; }
    [Required, Range(0, int.MaxValue)] public int? CapacityCubicMeters { get; set; }
}

public class ShipmentRequest
{
    [Required] public string? Reference { get; set; }
    [Required, Range(typeof(decimal), "0", "79228162514264337593543950335")] public decimal? WeightKg { get; set; }
    public bool Fragile { get; set; }
}

public record WarehouseDto(Guid Id, string Code, int CapacityCubicMeters);
public record ShipmentDto(Guid Id, Guid WarehouseId, string Reference, decimal WeightKg, bool Fragile);

static class Helpers
{
    public static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web);

    public static bool BlankCode(string? s) => string.IsNullOrWhiteSpace(s);

    // null header => no precondition; returns false if header present but unparsable
    public static bool TryIfMatch(HttpRequest r, out Guid? expected)
    {
        expected = null;
        if (!r.Headers.TryGetValue("If-Match", out var v) || string.IsNullOrWhiteSpace(v.ToString())) return true;
        var s = v.ToString().Trim();
        if (s == "*") return true;
        s = s.Trim('"');
        if (Guid.TryParse(s, out var g)) { expected = g; return true; }
        return false;
    }

    public static string? IdemKey(HttpRequest r, string scope) =>
        r.Headers.TryGetValue("Idempotency-Key", out var v) && !string.IsNullOrWhiteSpace(v.ToString())
            ? scope + "|" + v.ToString() : null;

    public static ContentResult Replay(HttpResponse resp, IdempotencyRecord rec)
    {
        resp.Headers["Location"] = rec.Location;
        return new ContentResult { StatusCode = 201, Content = rec.Body, ContentType = "application/json" };
    }
}

[ApiController]
public class WarehousesController : ControllerBase
{
    private readonly AppDbContext _db;
    public WarehousesController(AppDbContext db) => _db = db;

    private static WarehouseDto ToDto(Depot d) => new(d.Id, d.Code, d.CapacityCubicMeters);

    [HttpPost("api/warehouses")]
    public async Task<IActionResult> Create([FromBody] WarehouseRequest req, CancellationToken ct)
    {
        if (Helpers.BlankCode(req.Code)) return BadRequest();
        var key = Helpers.IdemKey(Request, "POST/warehouses");
        if (key != null)
        {
            var existing = await _db.IdempotencyRecords.AsNoTracking().FirstOrDefaultAsync(x => x.Key == key, ct);
            if (existing != null) return Helpers.Replay(Response, existing);
        }
        var d = new Depot
        {
            Id = Guid.NewGuid(), Code = req.Code!, CapacityCubicMeters = req.CapacityCubicMeters!.Value,
            LastAuditAt = DateTime.UtcNow, Version = Guid.NewGuid()
        };
        var dto = ToDto(d);
        var loc = $"/api/warehouses/{d.Id}";
        _db.Depots.Add(d);
        if (key != null)
            _db.IdempotencyRecords.Add(new IdempotencyRecord { Key = key, Body = JsonSerializer.Serialize(dto, Helpers.Json), Location = loc });
        try { await _db.SaveChangesAsync(ct); }
        catch (DbUpdateException) when (key != null)
        {
            _db.ChangeTracker.Clear();
            var existing = await _db.IdempotencyRecords.AsNoTracking().FirstOrDefaultAsync(x => x.Key == key, ct);
            if (existing != null) return Helpers.Replay(Response, existing);
            throw;
        }
        Response.Headers.ETag = $"\"{d.Version}\"";
        return Created(loc, dto);
    }

    [HttpGet("api/warehouses/{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var d = await _db.Depots.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, ct);
        if (d == null) return NotFound();
        Response.Headers.ETag = $"\"{d.Version}\"";
        return Ok(ToDto(d));
    }

    [HttpPut("api/warehouses/{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] WarehouseRequest req, CancellationToken ct)
    {
        if (Helpers.BlankCode(req.Code)) return BadRequest();
        if (!Helpers.TryIfMatch(Request, out var expected)) return StatusCode(412);
        var code = req.Code!;
        var cap = req.CapacityCubicMeters!.Value;
        var newVersion = Guid.NewGuid();
        var now = DateTime.UtcNow;
        var q = _db.Depots.Where(x => x.Id == id);
        if (expected != null) q = q.Where(x => x.Version == expected);
        var rows = await q.ExecuteUpdateAsync(s => s
            .SetProperty(x => x.Code, code)
            .SetProperty(x => x.CapacityCubicMeters, cap)
            .SetProperty(x => x.LastAuditAt, now)
            .SetProperty(x => x.Version, newVersion), ct);
        if (rows == 0)
            return await _db.Depots.AnyAsync(x => x.Id == id, ct) ? StatusCode(412) : NotFound();
        Response.Headers.ETag = $"\"{newVersion}\"";
        return Ok(new WarehouseDto(id, code, cap));
    }

    [HttpDelete("api/warehouses/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        await _db.Consignments.Where(x => x.DepotId == id).ExecuteDeleteAsync(ct);
        var rows = await _db.Depots.Where(x => x.Id == id).ExecuteDeleteAsync(ct);
        return rows == 0 ? NotFound() : NoContent();
    }
}

