        try { await _db.SaveChangesAsync(ct); }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();
            if (key != null)
            {
                var existing = await _db.IdempotencyRecords.AsNoTracking().FirstOrDefaultAsync(x => x.Key == key, ct);
                if (existing != null) return Helpers.Replay(Response, existing);
            }
            if (!await _db.Depots.AnyAsync(x => x.Id == warehouseId, ct)) return NotFound();
            throw;
        }
        Response.Headers.ETag = $"\"{c.Version}\"";
        return Created(loc, dto);
    }

