    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        await _db.Consignments.Where(x => x.Id == id)
            .ExecuteUpdateAsync(s => s.SetProperty(x => x.DownloadCount, x => x.DownloadCount + 1), ct);
        var c = await _db.Consignments.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, ct);
        if (c == null) return NotFound();
        Response.Headers.ETag = $"\"{c.Version}\"";
        return Ok(ToDto(c));
    }

    [HttpPut("api/shipments/{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] ShipmentRequest req, CancellationToken ct)
    {
        if (Helpers.BlankCode(req.Reference)) return BadRequest();
        if (!Helpers.TryIfMatch(Request, out var expected)) return StatusCode(412);
        var reference = req.Reference!;
        var weight = req.WeightKg!.Value;
        var fragile = req.Fragile;
        var newVersion = Guid.NewGuid();
        var q = _db.Consignments.Where(x => x.Id == id);
        if (expected != null) q = q.Where(x => x.Version == expected);
        var rows = await q.ExecuteUpdateAsync(s => s
            .SetProperty(x => x.Reference, reference)
            .SetProperty(x => x.WeightKg, weight)
            .SetProperty(x => x.Fragile, fragile)
            .SetProperty(x => x.Version, newVersion), ct);
        if (rows == 0)
            return await _db.Consignments.AnyAsync(x => x.Id == id, ct) ? StatusCode(412) : NotFound();
        var c = await _db.Consignments.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, ct);
        if (c == null) return NotFound();
        Response.Headers.ETag = $"\"{newVersion}\"";
        return Ok(ToDto(c));
