public abstract class ApiBase : ControllerBase
{
    protected readonly AppDbContext Db;
    protected static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web);
    protected ApiBase(AppDbContext db) => Db = db;

    protected static bool NotBlank(string? s) => !string.IsNullOrWhiteSpace(s);

    protected static Guid? ParseTag(string? tag)
    {
        if (tag == null) return null;
        tag = tag.Trim();
        if (tag.StartsWith("W/")) tag = tag[2..];
        return Guid.TryParse(tag.Trim('"'), out var g) ? g : Guid.Empty;
    }

    // null = no precondition; Guid.Empty = unmatchable
    protected Guid? IfMatch()
    {
        var h = Request.Headers.IfMatch.FirstOrDefault();
        if (string.IsNullOrWhiteSpace(h) || h.Trim() == "*") return null;
        return ParseTag(h.Split(',')[0]);
    }

    protected void SetEtag(Guid v) => Response.Headers.ETag = $"\"{v}\"";

    protected string? IdemScope()
    {
        var key = Request.Headers["Idempotency-Key"].FirstOrDefault();
        return string.IsNullOrWhiteSpace(key) ? null : $"{Request.Path}|{key}";
    }

    protected IActionResult Replay(IdempotencyRecord r)
    {
        Response.Headers.Location = r.Location;
        return new ContentResult { StatusCode = 201, Content = r.Body, ContentType = "application/json" };
    }

    protected async Task<IdempotencyRecord?> FindRecord(string? scope) =>
        scope == null ? null : await Db.IdempotencyRecords.AsNoTracking().FirstOrDefaultAsync(r => r.Scope == scope);

    protected async Task<IActionResult> Created(string? scope, object dto, string location, Func<Task<bool>>? parentMissing = null)
    {
        var body = JsonSerializer.Serialize(dto, Json);
        if (scope != null) Db.IdempotencyRecords.Add(new IdempotencyRecord { Scope = scope, Location = location, Body = body });
        try
        {
            await Db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            Db.ChangeTracker.Clear();
            var rec = await FindRecord(scope);
            if (rec != null) return Replay(rec);
            if (parentMissing != null && await parentMissing()) return NotFound();
            throw;
        }
        Response.Headers.Location = location;
        return new ContentResult { StatusCode = 201, Content = body, ContentType = "application/json" };
    }
}

