[Route("api/warehouses")]
public class WarehousesController : ApiBase
{
    public WarehousesController(AppDbContext db) : base(db) { }

    static WarehouseDto ToDto(Depot d) => new(d.Id, d.Code, d.CapacityCubicMeters);

    [HttpPost]
    public async Task<IActionResult> Create(WarehouseRequest req)
    {
        if (!NotBlank(req.Code)) { ModelState.AddModelError(nameof(req.Code), "Code is required."); return ValidationProblem(ModelState); }
        var scope = IdemScope();
        var existing = await FindRecord(scope);
        if (existing != null) return Replay(existing);

        var d = new Depot
        {
            Id = Guid.NewGuid(), Code = req.Code!, CapacityCubicMeters = req.CapacityCubicMeters!.Value,
            LastAuditAt = DateTime.UtcNow, Version = Guid.NewGuid()
        };
        Db.Depots.Add(d);
        return await Created(scope, ToDto(d), $"/api/warehouses/{d.Id}");
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id)
    {
        var d = await Db.Depots.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id);
        if (d == null) return NotFound();
        SetEtag(d.Version);
        return Ok(ToDto(d));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, WarehouseRequest req)
    {
        if (!NotBlank(req.Code)) { ModelState.AddModelError(nameof(req.Code), "Code is required."); return ValidationProblem(ModelState); }
        var match = IfMatch();
        for (var attempt = 0; attempt < 10; attempt++)
        {
            Db.ChangeTracker.Clear();
            var d = await Db.Depots.FirstOrDefaultAsync(x => x.Id == id);
            if (d == null) return NotFound();
            if (match != null && d.Version != match) return StatusCode(412);
            d.Code = req.Code!;
