            d.LastAuditAt = DateTime.UtcNow;
            d.Version = Guid.NewGuid();
            try
            {
                await Db.SaveChangesAsync();
                SetEtag(d.Version);
                return Ok(ToDto(d));
            }
            catch (DbUpdateConcurrencyException)
            {
                if (match != null) return StatusCode(412);
            }
        }
        return Conflict();
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var match = IfMatch();
        var q = Db.Depots.Where(x => x.Id == id);
        if (match != null) q = q.Where(x => x.Version == match);
        if (await q.ExecuteDeleteAsync() > 0) return NoContent();
        if (match != null && await Db.Depots.AnyAsync(x => x.Id == id)) return StatusCode(412);
        return NotFound();
    }
