public abstract class ApiBase : ControllerBase
{
    protected readonly AppDbContext Db;
    protected ApiBase(AppDbContext db) => Db = db;

    protected void SetETag(long version) => Response.Headers.ETag = $"\"{version}\"";

    // Returns null when no If-Match header (last write wins); -1 for "*" (any version).
    protected long? ExpectedVersion(out bool malformed)
    {
        malformed = false;
        var h = Request.Headers.IfMatch.ToString().Trim();
        if (h.Length == 0) return null;
        if (h == "*") return -1;
        if (h.StartsWith("W/")) h = h[2..];
        h = h.Trim('"');
        if (long.TryParse(h, out var v)) return v;
        malformed = true;
        return null;
    }

    protected string? IdempotencyScope()
    {
        var key = Request.Headers["Idempotency-Key"].ToString();
        return key.Length == 0 ? null : $"{Request.Path.Value}|{key}";
    }
}

