[Route("api/warehouses")]
public class WarehousesController : ApiBase
{
    public WarehousesController(AppDbContext db) : base(db) { }

    static WarehouseDto ToDto(Depot d) => new(d.Id, d.Code, d.CapacityCubicMeters);

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] WarehouseRequest req, CancellationToken ct)
    {
        if (!req.IsValid()) return BadRequest();
        var scope = IdempotencyScope();

        if (scope != null)
        {
            var replay = await Replay(scope, ct);
            if (replay != null) return replay;
        }

        var d = new Depot { Id = Guid.NewGuid(), Code = req.Code!.Trim(), CapacityCubicMeters = req.CapacityCubicMeters!.Value };
        Db.Depots.Add(d);
        if (scope != null) Db.IdempotencyRecords.Add(new IdempotencyRecord { Scope = scope, ResourceId = d.Id });
        try
        {
            await Db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException) when (scope != null)
        {
            Db.ChangeTracker.Clear();
            var replay = await Replay(scope, ct);
            if (replay != null) return replay;
            throw;
        }
        SetETag(d.Version);
        return Created($"/api/warehouses/{d.Id}", ToDto(d));
    }

    async Task<IActionResult?> Replay(string scope, CancellationToken ct)
    {
        var rec = await Db.IdempotencyRecords.AsNoTracking().FirstOrDefaultAsync(r => r.Scope == scope, ct);
        if (rec == null) return null;
        var d = await Db.Depots.AsNoTracking().FirstOrDefaultAsync(x => x.Id == rec.ResourceId, ct);
        if (d == null)
        {
            await Db.IdempotencyRecords.Where(r => r.Scope == scope).ExecuteDeleteAsync(ct);
            return null;
        }
        SetETag(d.Version);
        return Created($"/api/warehouses/{d.Id}", ToDto(d));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var d = await Db.Depots.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, ct);
        if (d == null) return NotFound();
        SetETag(d.Version);
        return Ok(ToDto(d));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] WarehouseRequest req, CancellationToken ct)
    {
        if (!req.IsValid()) return BadRequest();
        var expected = ExpectedVersion(out var malformed);
        if (malformed) return BadRequest();

        var code = req.Code!.Trim();
        var cap = req.CapacityCubicMeters!.Value;
        var now = DateTime.UtcNow;
        var q = Db.Depots.Where(x => x.Id == id);
        if (expected is >= 0) q = q.Where(x => x.Version == expected.Value);

        var rows = await q.ExecuteUpdateAsync(s => s
            .SetProperty(x => x.Code, code)
            .SetProperty(x => x.CapacityCubicMeters, cap)
            .SetProperty(x => x.LastAuditAt, now)
            .SetProperty(x => x.Version, x => x.Version + 1), ct);

        if (rows == 0)
        {
            return await Db.Depots.AnyAsync(x => x.Id == id, ct)
                ? StatusCode(StatusCodes.Status412PreconditionFailed)
                : NotFound();
        }

        var d = await Db.Depots.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, ct);
        if (d == null) return NotFound();
        SetETag(d.Version);
        return Ok(ToDto(d));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var expected = ExpectedVersion(out var malformed);
        if (malformed) return BadRequest();
        var q = Db.Depots.Where(x => x.Id == id);
        if (expected is >= 0) q = q.Where(x => x.Version == expected.Value);

        await using var tx = await Db.Database.BeginTransactionAsync(ct);
        var ids = await q.Select(x => x.Id).ToListAsync(ct);
        if (ids.Count == 0)
        {
            return await Db.Depots.AnyAsync(x => x.Id == id, ct)
                ? StatusCode(StatusCodes.Status412PreconditionFailed)
                : NotFound();
        }
        await Db.Consignments.Where(c => c.DepotId == id).ExecuteDeleteAsync(ct);
        var rows = await q.ExecuteDeleteAsync(ct);
        await tx.CommitAsync(ct);
        return rows == 0 ? NotFound() : NoContent();
    }
}

