internal static class Helpers
{
    public static string ETag(Guid v) => "\"" + v.ToString("N") + "\"";

    public static bool MatchesIfMatch(string? header, Guid version)
    {
        if (string.IsNullOrWhiteSpace(header)) return true;
        var h = header.Trim();
        if (h == "*") return true;
        return h.Split(',').Select(s => s.Trim()).Any(s => s == ETag(version) || s == "W/" + ETag(version));
    }
}

