    public async Task<IActionResult> Create(Guid warehouseId, [FromBody] ShipmentRequest? req, [FromHeader(Name = "Idempotency-Key")] string? key)
    {
        if (!Valid(req)) return BadRequest();
        if (!await _db.Depots.AnyAsync(d => d.Id == warehouseId)) return NotFound();
        var scope = $"POST /api/warehouses/{warehouseId}/shipments";
        if (!string.IsNullOrEmpty(key))
        {
            var existing = await FindExisting(scope, key);
            if (existing != null) return existing;
        }
        var c = new Consignment
        {
            Id = Guid.NewGuid(),
            DepotId = warehouseId,
            Reference = req!.Reference!,
            WeightKg = req.WeightKg!.Value,
            Fragile = req.Fragile ?? false,
            Version = Guid.NewGuid()
        };
        _db.Consignments.Add(c);
        if (!string.IsNullOrEmpty(key))
