public static class Canon
{
    static void Str(StringBuilder sb, string s)
    {
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }

    static string Dec(decimal d) => (d / 1.0000000000000000000000000000m).ToString(CultureInfo.InvariantCulture);

    static string Hash(string json) =>
        "\"" + System.Buffers.Text.Base64Url.EncodeToString(SHA256.HashData(Encoding.UTF8.GetBytes(json))) + "\"";

    public static string DepotTag(Guid id, string code, int cap)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("D")).Append("\",\"code\":");
        Str(sb, code);
        sb.Append(",\"capacityCubicMeters\":").Append(cap.ToString(CultureInfo.InvariantCulture)).Append('}');
        return Hash(sb.ToString());
    }

    public static string ConsignmentTag(Guid id, Guid wid, string reference, decimal weight, bool fragile)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("D")).Append("\",\"warehouseId\":\"").Append(wid.ToString("D")).Append("\",\"reference\":");
        Str(sb, reference);
        sb.Append(",\"weightKg\":").Append(Dec(weight)).Append(",\"fragile\":").Append(fragile ? "true" : "false").Append('}');
        return Hash(sb.ToString());
    }

    static bool Text(string? s, out string n)
    {
        n = "";
        if (string.IsNullOrWhiteSpace(s)) return false;
        try { n = s.Normalize(NormalizationForm.FormC); return true; }
        catch (ArgumentException) { return false; }
    }

    public static bool Check(DepotRequest? b, out Guid id, out string code, out int cap)
    {
        id = default; code = ""; cap = 0;
        if (b is null || b.Id is null || b.Id == Guid.Empty || b.CapacityCubicMeters is null || b.CapacityCubicMeters < 0) return false;
        if (!Text(b.Code, out code)) return false;
        id = b.Id.Value; cap = b.CapacityCubicMeters.Value;
        return true;
    }

    public static bool Check(ConsignmentRequest? b, out Guid id, out Guid wid, out string reference, out decimal weight, out bool fragile)
    {
        id = default; wid = default; reference = ""; weight = 0; fragile = false;
        if (b is null || b.Id is null || b.Id == Guid.Empty || b.WarehouseId is null || b.WeightKg is null || b.WeightKg < 0 || b.Fragile is null) return false;
        if (!Text(b.Reference, out reference)) return false;
        id = b.Id.Value; wid = b.WarehouseId.Value; weight = b.WeightKg.Value; fragile = b.Fragile.Value;
        return true;
    }
}

[ApiController]
public abstract class ApiBase : ControllerBase
{
    protected const string Pj = "application/problem+json";

    protected IActionResult Fail(int code, string title)
    {
        var r = new ObjectResult(new ProblemDetails { Status = code, Title = title }) { StatusCode = code };
        r.ContentTypes.Add(Pj);
        return r;
    }

    protected void SetETag(string etag) => Response.Headers.ETag = etag;

    protected bool BodyInvalid() =>
        ModelState.Any(kv => kv.Value is { Errors.Count: > 0 } &&
                             !kv.Key.Replace("-", "").Equals("ifmatch", StringComparison.OrdinalIgnoreCase));

    protected static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var raw in header.Split(','))
        {
            var t = raw.Trim();
            if (t == "*") return true;
            if (t.StartsWith("W/")) t = t[2..];
            if (t == etag) return true;
        }
        return false;
    }

    protected static bool IsUnique(DbUpdateException ex) =>
        ex is not DbUpdateConcurrencyException && ex.InnerException is SqliteException { SqliteErrorCode: 19 };

    protected static string Tombstone() => Guid.NewGuid().ToString("N");
}

[Route("api/warehouses")]
public class WarehousesController : ApiBase
{
    readonly AppDb db;
    public WarehousesController(AppDb db) => this.db = db;

    static DepotResponse Map(Depot d) => new(d.PublicId, d.Code, d.CapacityCubicMeters);

    [HttpPost]
    [ProducesResponseType<DepotResponse>(201)]
    [ProducesResponseType<DepotResponse>(200)]
    [ProducesResponseType<ProblemDetails>(400, Pj)]
    [ProducesResponseType<ProblemDetails>(409, Pj)]
    [ProducesResponseType<ProblemDetails>(410, Pj)]
    public async Task<IActionResult> Create([FromBody, Required] DepotRequest body, CancellationToken ct)
    {
        if (BodyInvalid() || !Canon.Check(body, out var id, out var code, out var cap)) return Fail(400, "Invalid body");
        var etag = Canon.DepotTag(id, code, cap);
        var entity = new Depot
        {
            PublicId = id, Code = code, CapacityCubicMeters = cap,
            ETag = etag, CreateHash = etag, LastAuditAt = DateTime.UtcNow
        };
        db.Depots.Add(entity);
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (IsUnique(ex))
        {
            db.ChangeTracker.Clear();
            var ex2 = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(d => d.PublicId == id, ct);
            if (ex2 is null) return Fail(409, "Conflict");
            if (ex2.DeletedAt != null) return Fail(410, "Gone");
            if (ex2.CreateHash != etag) return Fail(409, "Id already used with different content");
            SetETag(ex2.ETag);
            return Ok(Map(ex2));
        }
        SetETag(etag);
        return Created($"/api/warehouses/{id}", Map(entity));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType<DepotResponse>(200)]
    [ProducesResponseType(304)]
    [ProducesResponseType<ProblemDetails>(404, Pj)]
    [ProducesResponseType<ProblemDetails>(410, Pj)]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var d = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (d is null) return Fail(404, "Not found");
        if (d.DeletedAt != null) return Fail(410, "Gone");
        SetETag(d.ETag);
        if (Request.Headers.IfNoneMatch.Count > 0 && Matches(Request.Headers.IfNoneMatch.ToString(), d.ETag)) return StatusCode(304);
        return Ok(Map(d));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType<ProblemDetails>(400, Pj)]
    [ProducesResponseType<ProblemDetails>(404, Pj)]
    [ProducesResponseType<ProblemDetails>(410, Pj)]
    [ProducesResponseType<ProblemDetails>(412, Pj)]
    [ProducesResponseType<ProblemDetails>(428, Pj)]
    public async Task<IActionResult> Update(Guid id, [FromBody, Required] DepotRequest body,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (BodyInvalid() || !Canon.Check(body, out var bid, out var code, out var cap) || bid != id) return Fail(400, "Invalid body");
        if (string.IsNullOrWhiteSpace(ifMatch)) return Fail(428, "If-Match required");
        var d = await db.Depots.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (d is null) return Fail(404, "Not found");
        if (d.DeletedAt != null) return Fail(410, "Gone");
        var etag = Canon.DepotTag(id, code, cap);
        if (d.ETag == etag) { SetETag(etag); return NoContent(); }
        if (!Matches(ifMatch, d.ETag)) { SetETag(d.ETag); return Fail(412, "Precondition failed"); }
        d.Code = code; d.CapacityCubicMeters = cap; d.ETag = etag; d.LastAuditAt = DateTime.UtcNow;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var cur = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (cur is null) return Fail(404, "Not found");
            if (cur.DeletedAt != null) return Fail(410, "Gone");
            SetETag(cur.ETag);
            return cur.ETag == etag ? NoContent() : Fail(412, "Precondition failed");
        }
        SetETag(etag);
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType<ProblemDetails>(412, Pj)]
    [ProducesResponseType<ProblemDetails>(428, Pj)]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch)) return Fail(428, "If-Match required");
        for (var attempt = 0; attempt < 5; attempt++)
        {
            db.ChangeTracker.Clear();
            var d = await db.Depots.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (d is null || d.DeletedAt != null) return NoContent();
            if (!Matches(ifMatch, d.ETag)) { SetETag(d.ETag); return Fail(412, "Precondition failed"); }
            var now = DateTime.UtcNow;
            d.DeletedAt = now; d.ETag = Tombstone();
            foreach (var c in await db.Consignments.Where(c => c.DepotId == d.Id).ToListAsync(ct))
            {
                c.DeletedAt = now; c.ETag = Tombstone();
            }
            try
            {
                await db.SaveChangesAsync(ct);
                return NoContent();
            }
            catch (DbUpdateConcurrencyException) { }
        }
        return Fail(412, "Precondition failed");
    }
}

