public abstract class ApiBase : ControllerBase
{
    protected ObjectResult Fail(int status, string title)
    {
        var r = new ObjectResult(new ProblemDetails { Status = status, Title = title })
        {
            StatusCode = status
        };
        r.ContentTypes.Add("application/problem+json");
        return r;
    }

    protected void SetETag(string etag) => Response.Headers.ETag = etag;

    protected static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var part in header.Split(','))
        {
            var p = part.Trim();
            if (p == "*") return true;
            if (p.StartsWith("W/", StringComparison.Ordinal)) p = p[2..];
            if (p == etag) return true;
        }
        return false;
    }
}

