public static class Canon
{
    public static string Str(string s)
    {
        var n = s.Normalize(NormalizationForm.FormC);
        var sb = new StringBuilder("\"");
        foreach (var ch in n)
        {
            switch (ch)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (ch < 0x20) sb.Append("\\u").Append(((int)ch).ToString("x4"));
                    else sb.Append(ch);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }

    public static string Num(decimal d)
    {
        if (d == 0) return "0";
        return (d / 1.0000000000000000000000000000m).ToString(CultureInfo.InvariantCulture);
    }

    public static string Depot(Guid id, string code, int cap) =>
        "{\"id\":\"" + id.ToString("D") + "\",\"code\":" + Str(code) +
        ",\"capacityCubicMeters\":" + cap.ToString(CultureInfo.InvariantCulture) + "}";

    public static string Consignment(Guid id, Guid wid, string reference, decimal weight, bool fragile) =>
        "{\"id\":\"" + id.ToString("D") + "\",\"warehouseId\":\"" + wid.ToString("D") + "\",\"reference\":" + Str(reference) +
        ",\"weightKg\":" + Num(weight) + ",\"fragile\":" + (fragile ? "true" : "false") + "}";

    public static string ETag(string json)
    {
        var h = SHA256.HashData(Encoding.UTF8.GetBytes(json));
        var b64 = Convert.ToBase64String(h).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + b64 + "\"";
    }

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var part in header.Split(','))
        {
            var t = part.Trim();
            if (t == "*" || t == etag) return true;
        }
        return false;
    }
}

