                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }

    public static string Num(decimal d)
    {
        if (d == 0) return "0";
        var s = d.ToString(CultureInfo.InvariantCulture);
        return s.Contains('.') ? s.TrimEnd('0').TrimEnd('.') : s;
    }

    public static string Guid(Guid g) => "\"" + g.ToString("D").ToLowerInvariant() + "\"";

    public static string Hash(string json) =>
        Base64Url.EncodeToString(SHA256.HashData(Encoding.UTF8.GetBytes(json)));
}

public class DepotRequest
{
    public Guid? Id { get; set; }
    public string? Code { get; set; }
    public int? CapacityCubicMeters { get; set; }

    public bool Validate()
    {
        try
        {
            if (Id is null || Id == Guid.Empty || string.IsNullOrWhiteSpace(Code)) return false;
            if (CapacityCubicMeters is null or < 0) return false;
            Code = Code.Normalize(NormalizationForm.FormC);
            return true;
        }
        catch (ArgumentException) { return false; }
    }

    public string Hash() => Canon.Hash(
        "{\"id\":" + Canon.Guid(Id!.Value) + ",\"code\":" + Canon.Str(Code!) +
        ",\"capacityCubicMeters\":" + CapacityCubicMeters!.Value.ToString(CultureInfo.InvariantCulture) + "}");
}

public class ConsignmentRequest
{
    public Guid? Id { get; set; }
    public Guid? WarehouseId { get; set; }
    public string? Reference { get; set; }
    public decimal? WeightKg { get; set; }
    public bool? Fragile { get; set; }

    public bool Validate()
    {
        try
        {
            if (Id is null || Id == Guid.Empty || WarehouseId is null || WarehouseId == Guid.Empty) return false;
            if (string.IsNullOrWhiteSpace(Reference) || WeightKg is null or < 0 || Fragile is null) return false;
            Reference = Reference.Normalize(NormalizationForm.FormC);
            WeightKg = decimal.Parse(Canon.Num(WeightKg.Value), CultureInfo.InvariantCulture);
            return true;
        }
        catch (ArgumentException) { return false; }
    }

    public string Hash() => Canon.Hash(
        "{\"id\":" + Canon.Guid(Id!.Value) + ",\"warehouseId\":" + Canon.Guid(WarehouseId!.Value) +
        ",\"reference\":" + Canon.Str(Reference!) + ",\"weightKg\":" + Canon.Num(WeightKg!.Value) +
        ",\"fragile\":" + (Fragile!.Value ? "true" : "false") + "}");
}

public record DepotResponse(Guid Id, string Code, int CapacityCubicMeters);
public record ConsignmentResponse(Guid Id, Guid WarehouseId, string Reference, decimal WeightKg, bool Fragile);

public abstract class ApiBase : ControllerBase
{
    protected const string Pj = "application/problem+json";

    protected IActionResult Fail(int status, string title) =>
        new ObjectResult(new ProblemDetails { Status = status, Title = title })
        {
            StatusCode = status,
            ContentTypes = { Pj }
        };

    protected void SetETag(string etag) => Response.Headers.ETag = "\"" + etag + "\"";

    protected static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var raw in header.Split(','))
        {
            var t = raw.Trim();
            if (t == "*") return true;
            if (t.StartsWith("W/")) t = t[2..];
            if (t == "\"" + etag + "\"") return true;
        }
        return false;
    }

    protected bool BodyInvalid() =>
        ModelState.Any(kv => kv.Key != "If-Match" && kv.Key != "ifMatch" && kv.Value!.Errors.Count > 0);

    protected static bool IsUnique(DbUpdateException e) =>
        e.InnerException is SqliteException { SqliteErrorCode: 19 };
}

[Route("api/warehouses")]
public class WarehousesController(AppDbContext db) : ApiBase
{
    static DepotResponse Map(Depot d) => new(d.PublicId, d.Code, d.CapacityCubicMeters);

    [HttpPost]
    [ProducesResponseType(typeof(DepotResponse), 201)]
    [ProducesResponseType(typeof(DepotResponse), 200)]
    [ProducesResponseType(typeof(ProblemDetails), 400, Pj)]
    [ProducesResponseType(typeof(ProblemDetails), 409, Pj)]
    [ProducesResponseType(typeof(ProblemDetails), 410, Pj)]
    public async Task<IActionResult> Create(
        [FromBody(EmptyBodyBehavior = EmptyBodyBehavior.Disallow), Required] DepotRequest body, CancellationToken ct)
    {
        if (BodyInvalid() || body is null || !body.Validate()) return Fail(400, "Invalid body");
        var id = body.Id!.Value;
        var hash = body.Hash();
        var e = new Depot
        {
            PublicId = id,
            Code = body.Code!,
            CapacityCubicMeters = body.CapacityCubicMeters!.Value,
            ETag = hash,
            CreateHash = hash,
            LastAuditAt = DateTime.UtcNow
        };
        db.Depots.Add(e);
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (IsUnique(ex))
        {
            db.ChangeTracker.Clear();
            var cur = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(d => d.PublicId == id, ct);
            if (cur is null) throw;
            if (cur.DeletedAt != null) return Fail(410, "Gone");
            if (cur.CreateHash == hash || cur.ETag == hash)
            {
                SetETag(cur.ETag);
                return Ok(Map(cur));
            }
            return Fail(409, "Conflict");
        }
        SetETag(hash);
        return Created($"/api/warehouses/{id}", Map(e));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(DepotResponse), 200)]
    [ProducesResponseType(304)]
    [ProducesResponseType(typeof(ProblemDetails), 404, Pj)]
    [ProducesResponseType(typeof(ProblemDetails), 410, Pj)]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var e = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(d => d.PublicId == id, ct);
        if (e is null) return Fail(404, "Not found");
        if (e.DeletedAt != null) return Fail(410, "Gone");
        SetETag(e.ETag);
        if (Matches(Request.Headers.IfNoneMatch.ToString(), e.ETag)) return StatusCode(304);
        return Ok(Map(e));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 400, Pj)]
    [ProducesResponseType(typeof(ProblemDetails), 404, Pj)]
    [ProducesResponseType(typeof(ProblemDetails), 410, Pj)]
    [ProducesResponseType(typeof(ProblemDetails), 412, Pj)]
    [ProducesResponseType(typeof(ProblemDetails), 428, Pj)]
    public async Task<IActionResult> Update(Guid id,
        [FromBody(EmptyBodyBehavior = EmptyBodyBehavior.Disallow), Required] DepotRequest body,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (BodyInvalid() || body is null || !body.Validate() || body.Id != id) return Fail(400, "Invalid body");
        if (string.IsNullOrWhiteSpace(ifMatch)) return Fail(428, "If-Match required");
        var hash = body.Hash();
        for (var attempt = 0; attempt < 5; attempt++)
        {
            var e = await db.Depots.IgnoreQueryFilters().FirstOrDefaultAsync(d => d.PublicId == id, ct);
            if (e is null) return Fail(404, "Not found");
            if (e.DeletedAt != null) return Fail(410, "Gone");
            if (e.ETag == hash)
            {
                SetETag(e.ETag);
                return NoContent();
            }
            if (!Matches(ifMatch, e.ETag))
            {
                SetETag(e.ETag);
                return Fail(412, "Precondition failed");
            }
            e.Code = body.Code!;
            e.CapacityCubicMeters = body.CapacityCubicMeters!.Value;
            e.ETag = hash;
            e.LastAuditAt = DateTime.UtcNow;
            try
            {
                await db.SaveChangesAsync(ct);
                SetETag(hash);
                return NoContent();
            }
            catch (DbUpdateConcurrencyException)
            {
                db.ChangeTracker.Clear();
            }
        }
        return Fail(412, "Precondition failed");
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 412, Pj)]
    [ProducesResponseType(typeof(ProblemDetails), 428, Pj)]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch)) return Fail(428, "If-Match required");
        for (var attempt = 0; attempt < 5; attempt++)
        {
            var e = await db.Depots.IgnoreQueryFilters().FirstOrDefaultAsync(d => d.PublicId == id, ct);
            if (e is null || e.DeletedAt != null) return NoContent();
            if (!Matches(ifMatch, e.ETag))
            {
                SetETag(e.ETag);
                return Fail(412, "Precondition failed");
            }
            var now = DateTime.UtcNow;
            e.DeletedAt = now;
            e.LastAuditAt = now;
            var children = await db.Consignments.Where(c => c.DepotId == e.Id).ToListAsync(ct);
            foreach (var c in children) c.DeletedAt = now;
            try
            {
                await db.SaveChangesAsync(ct);
                return NoContent();
            }
            catch (DbUpdateConcurrencyException)
            {
                db.ChangeTracker.Clear();
            }
        }
        return Fail(412, "Precondition failed");
    }
}

