public static class Canon
{
    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s.Normalize(NormalizationForm.FormC))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }

    static string Dec(decimal d) => (d / 1.0000000000000000000000000000m).ToString(CultureInfo.InvariantCulture);
    static string G(Guid g) => "\"" + g.ToString("D").ToLowerInvariant() + "\"";

    public static string Depot(Guid id, string code, int cap) =>
        $"{{\"id\":{G(id)},\"code\":{Str(code)},\"capacityCubicMeters\":{cap.ToString(CultureInfo.InvariantCulture)}}}";

    public static string Consignment(Guid id, Guid wid, string reference, decimal w, bool fragile) =>
        $"{{\"id\":{G(id)},\"warehouseId\":{G(wid)},\"reference\":{Str(reference)},\"weightKg\":{Dec(w)},\"fragile\":{(fragile ? "true" : "false")}}}";

    public static string ETag(string json) =>
        "\"" + Base64Url.EncodeToString(SHA256.HashData(Encoding.UTF8.GetBytes(json))) + "\"";

    public static string Norm(string s) => s.Normalize(NormalizationForm.FormC);

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var part in header.Split(','))
        {
            var p = part.Trim();
            if (p == "*" || p == etag) return true;
        }
        return false;
    }
}

public abstract class ApiBase : ControllerBase
{
    protected ObjectResult Problem2(int status, string title) =>
        new(new ProblemDetails { Status = status, Title = title })
        {
            StatusCode = status,
            ContentTypes = { "application/problem+json" }
        };

    protected ObjectResult BadReq(string t = "Invalid request") => Problem2(400, t);
    protected ObjectResult NotFound2() => Problem2(404, "Not found");
    protected ObjectResult Conflict2(string t = "Conflict") => Problem2(409, t);
    protected ObjectResult Gone() => Problem2(410, "Gone");
    protected ObjectResult PreconditionRequired() => Problem2(428, "If-Match header is required");

    protected ObjectResult Stale(string currentETag)
    {
        Response.Headers.ETag = currentETag;
        return Problem2(412, "Precondition failed");
    }

    protected string? IfMatchHeader()
    {
        var v = Request.Headers["If-Match"].ToString();
        return string.IsNullOrWhiteSpace(v) ? null : v;
    }
