    [ProducesResponseType(typeof(ProblemDetails), 400, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 409, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, Required] DepotRequest? body, CancellationToken ct)
    {
        if (!Valid(body)) return BadReq();
        var id = body!.Id!.Value;
        var code = Canon.Norm(body.Code!);
        var etag = Canon.ETag(Canon.Depot(id, code, body.CapacityCubicMeters!.Value));
        var e = new Depot
        {
            PublicId = id, Code = code, CapacityCubicMeters = body.CapacityCubicMeters.Value,
            ETag = etag, CreateHash = etag
        };
