        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            db.ChangeTracker.Clear();
            var ex = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(d => d.PublicId == id, ct);
            if (ex == null) throw;
            if (ex.DeletedAt != null) return Gone();
            if (ex.CreateHash != etag) return Conflict2("Id already exists with different content");
            Response.Headers.ETag = ex.ETag;
            return Ok(ToDto(ex));
        }
        Response.Headers.ETag = etag;
        return Created($"/api/warehouses/{id:D}", ToDto(e));
    }

    [HttpGet("api/warehouses/{id:guid}")]
    [ProducesResponseType(typeof(DepotResponse), 200)]
    [ProducesResponseType(304)]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
