            db.ChangeTracker.Clear();
            var d = await db.Depots.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (d == null || d.DeletedAt != null) return NoContent();
            if (!Canon.Matches(ifMatch, d.ETag)) return Stale(d.ETag);
            var now = DateTime.UtcNow;
            d.DeletedAt = now;
            var children = await db.Consignments.Where(c => c.DepotId == d.Id).ToListAsync(ct);
