public abstract class ApiBase : ControllerBase
{
    protected IActionResult Err(int status, string title) =>
        new ObjectResult(new ProblemDetails { Status = status, Title = title })
        {
            StatusCode = status,
            ContentTypes = { "application/problem+json" }
        };

    protected void SetETag(string etag) => Response.Headers.ETag = etag;

    protected IActionResult ErrWithETag(int status, string title, string etag)
    {
        SetETag(etag);
        return Err(status, title);
    }

    protected IActionResult NoContentWithETag(string etag)
    {
        SetETag(etag);
        return NoContent();
    }

    protected static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var part in header.Split(','))
        {
            var t = part.Trim();
            if (t == "*") return true;
            if (t.StartsWith("W/", StringComparison.Ordinal)) t = t[2..];
            if (t == etag) return true;
        }
        return false;
    }

    protected static bool IsUnique(DbUpdateException e) =>
        e.InnerException is SqliteException { SqliteErrorCode: 19 };

    protected static string? Norm(string? s)
    {
        if (s == null) return null;
        try { return s.Normalize(System.Text.NormalizationForm.FormC); }
        catch (ArgumentException) { return null; }
    }

    static string Esc(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }

    static string Num(decimal d) =>
        d == 0 ? "0" : d.ToString("0.############################", CultureInfo.InvariantCulture);

    static string Hash(string json) =>
        "\"" + System.Buffers.Text.Base64Url.EncodeToString(SHA256.HashData(Encoding.UTF8.GetBytes(json))) + "\"";

    protected static string DepotETag(Guid id, string code, int cap) =>
        Hash($"{{\"id\":\"{id.ToString("D")}\",\"code\":{Esc(code)},\"capacityCubicMeters\":{cap.ToString(CultureInfo.InvariantCulture)}}}");

    protected static string ConsignmentETag(Guid id, Guid wid, string reference, decimal weight, bool fragile) =>
        Hash($"{{\"id\":\"{id.ToString("D")}\",\"warehouseId\":\"{wid.ToString("D")}\",\"reference\":{Esc(reference)},\"weightKg\":{Num(weight)},\"fragile\":{(fragile ? "true" : "false")}}}");
}

[ApiController]
[Route("api/warehouses")]
public class WarehousesController : ApiBase
{
    readonly AppDbContext _db;
    public WarehousesController(AppDbContext db) => _db = db;

    static DepotResponse Map(Depot d) => new()
    {
        Id = d.PublicId,
        Code = d.Code,
        CapacityCubicMeters = d.CapacityCubicMeters
    };

    bool Validate(DepotRequest? b, out string code, out int cap)
    {
        code = ""; cap = 0;
        if (!ModelState.IsValid || b == null || b.Id == null || b.Id == Guid.Empty
            || b.CapacityCubicMeters == null || b.CapacityCubicMeters < 0) return false;
        var c = Norm(b.Code);
        if (string.IsNullOrWhiteSpace(c)) return false;
        code = c; cap = b.CapacityCubicMeters.Value;
        return true;
    }

    [HttpPost]
    [ProducesResponseType(typeof(DepotResponse), 201)]
    [ProducesResponseType(typeof(DepotResponse), 200)]
    [ProducesResponseType(typeof(ProblemDetails), 400, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 409, "application/problem+json")]
