[ApiController]
[Route("api/posts")]
public sealed class PostsController(AppDbContext db) : ControllerBase
{
    [HttpGet("{id:guid}")]
    public async Task<ActionResult<PostResponse>> Get(
        Guid id,
        CancellationToken cancellationToken)
    {
        var post = await db.Posts.FindAsync(new object[] { id }, cancellationToken);
        if (post is null)
            return NotFound();

        // Increment in the database so parallel reads do not overwrite one another.
        await db.Posts
            .Where(item => item.Id == id)
            .ExecuteUpdateAsync(
                setters => setters.SetProperty(item => item.Views, item => item.Views + 1),
                cancellationToken);

        post.Views++;
        return Ok(ToResponse(post));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<PostResponse>> Update(
        Guid id,
        [FromBody] PostRequest request,
        CancellationToken cancellationToken)
    {
        if (id != request.Id || request.BlogId == Guid.Empty ||
            string.IsNullOrWhiteSpace(request.Title))
            return BadRequest();

        var post = await db.Posts.FindAsync(new object[] { id }, cancellationToken);
        if (post is null)
            return NotFound();

        if (!await db.Blogs.AnyAsync(
                blog => blog.Id == request.BlogId, cancellationToken))
            return NotFound();

        post.BlogId = request.BlogId;
        post.Title = request.Title;
        await db.SaveChangesAsync(cancellationToken);
        return Ok(ToResponse(post));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken cancellationToken)
    {
        var post = await db.Posts.FindAsync(new object[] { id }, cancellationToken);
        if (post is null)
            return NotFound();

        db.Posts.Remove(post);
        await db.SaveChangesAsync(cancellationToken);
        return NoContent();
    }

    private static PostResponse ToResponse(Post post) =>
        new(post.Id, post.BlogId, post.Title, post.Views);
}
