POST requests use client-supplied GUIDs as idempotency keys: repeating a matching create returns the existing resource; reusing an ID with different data returns `409 Conflict`. Post reads increment `Views` with a database-side update, avoiding lost increments from simultaneous reads. Concurrent PUTs use last-write-wins semantics; preventing silent overwrites would require clients to supply a version/ETag token, which is not part of the specified request shape.

```csharp
using Microsoft.EntityFrameworkCore;

public sealed class Blog
{
    public Guid Id { get; set; }
    public string Name { get; set; } = string.Empty;

    // EF uses this token to reject updates based on stale data.
    public int Version { get; set; }

    public List<Post> Posts { get; set; } = new();
}

public sealed class Post
{
    public Guid Id { get; set; }
    public Guid BlogId { get; set; }
    public string Title { get; set; } = string.Empty;

    // Maintained by the server; clients cannot set it through the API.
    public int Views { get; set; }

    public int Version { get; set; }
    public Blog? Blog { get; set; }
}

public sealed class AppDbContext(DbContextOptions<AppDbContext> options)
    : DbContext(options)
{
    public DbSet<Blog> Blogs => Set<Blog>();
    public DbSet<Post> Posts => Set<Post>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>()
            .Property(blog => blog.Version)
            .IsConcurrencyToken();

        modelBuilder.Entity<Post>()
            .Property(post => post.Version)
            .IsConcurrencyToken();

        modelBuilder.Entity<Blog>()
            .HasMany(blog => blog.Posts)
            .WithOne(post => post.Blog)
            .HasForeignKey(post => post.BlogId)
            .OnDelete(DeleteBehavior.Cascade);
    }
}

