    [HttpPost]
    public async Task<ActionResult<BlogResponse>> Create(
        BlogRequest request,
        CancellationToken cancellationToken)
    {
        if (request.Id == Guid.Empty || string.IsNullOrWhiteSpace(request.Name))
            return BadRequest();

        var existing = await db.Blogs.FindAsync(
            new object[] { request.Id }, cancellationToken);

        // A client-provided ID makes a retried create safe and repeatable.
        if (existing is not null)
        {
            if (existing.Name != request.Name)
                return Conflict();

            return Ok(new BlogResponse(existing.Id, existing.Name));
        }

        var blog = new Blog { Id = request.Id, Name = request.Name };
        db.Blogs.Add(blog);

        try
        {
            await db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            // Another request may have created this ID concurrently.
            db.Entry(blog).State = EntityState.Detached;
            existing = await db.Blogs.FindAsync(
                new object[] { request.Id }, cancellationToken);

            if (existing is null || existing.Name != request.Name)
                return Conflict();

            return Ok(new BlogResponse(existing.Id, existing.Name));
        }

        return CreatedAtAction(
            nameof(Get), new { id = blog.Id },
            new BlogResponse(blog.Id, blog.Name));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<BlogResponse>> Get(
        Guid id,
        CancellationToken cancellationToken)
    {
        var blog = await db.Blogs.AsNoTracking()
            .FirstOrDefaultAsync(item => item.Id == id, cancellationToken);

        return blog is null
            ? NotFound()
            : Ok(new BlogResponse(blog.Id, blog.Name));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(
        Guid id,
        BlogRequest request,
        CancellationToken cancellationToken)
    {
        if (request.Id != id || string.IsNullOrWhiteSpace(request.Name))
            return BadRequest();

        var blog = await db.Blogs.FindAsync(new object[] { id }, cancellationToken);
        if (blog is null)
            return NotFound();

        var originalVersion = blog.Version;
        blog.Name = request.Name;
        blog.Version++;

        db.Entry(blog).Property(item => item.Version).OriginalValue = originalVersion;

        try
        {
            await db.SaveChangesAsync(cancellationToken);
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(
        Guid id,
        CancellationToken cancellationToken)
    {
        var blog = await db.Blogs.FindAsync(new object[] { id }, cancellationToken);
        if (blog is null)
            return NoContent();

        db.Blogs.Remove(blog);

        try
        {
            await db.SaveChangesAsync(cancellationToken);
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            return NoContent();
