public static class Canon
{
    public const string Pj = "application/problem+json";

    public static string Norm(string s) => s.Normalize(NormalizationForm.FormC);

    static void Str(StringBuilder sb, string s)
    {
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }

    static string Dec(decimal d) =>
        d == 0 ? "0" : d.ToString("0.############################", CultureInfo.InvariantCulture);

    static string Hash(string json) =>
        System.Buffers.Text.Base64Url.EncodeToString(SHA256.HashData(Encoding.UTF8.GetBytes(json)));

    public static string DepotTag(Guid id, string code, int capacity)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("D")).Append("\",\"code\":");
        Str(sb, Norm(code));
        sb.Append(",\"capacityCubicMeters\":").Append(capacity.ToString(CultureInfo.InvariantCulture)).Append('}');
        return Hash(sb.ToString());
    }

    public static string ConsignmentTag(Guid id, Guid warehouseId, string reference, decimal weight, bool fragile)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("D")).Append("\",\"warehouseId\":\"").Append(warehouseId.ToString("D"))
          .Append("\",\"reference\":");
        Str(sb, Norm(reference));
        sb.Append(",\"weightKg\":").Append(Dec(weight)).Append(",\"fragile\":").Append(fragile ? "true" : "false").Append('}');
        return Hash(sb.ToString());
    }

    public static string Quote(string etag) => "\"" + etag + "\"";

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var part in header.Split(','))
        {
            var t = part.Trim();
            if (t == "*") return true;
            if (t.StartsWith("W/")) t = t[2..];
            if (t.Trim('"') == etag) return true;
        }
        return false;
    }

    public static bool IsUnique(DbUpdateException e) =>
        e.InnerException is SqliteException { SqliteErrorCode: 19 };

    public static bool IsBusy(DbUpdateException e) =>
        e.InnerException is SqliteException { SqliteErrorCode: 5 or 6 };
}

public abstract class ApiControllerBase : ControllerBase
{
    protected IActionResult Err(int code, string title) =>
        Problem(detail: title, statusCode: code, title: title);

    protected void SetETag(string etag) => Response.Headers.ETag = Canon.Quote(etag);

    protected bool HasIfMatch(out string value)
    {
        value = Request.Headers.TryGetValue("If-Match", out var h) ? h.ToString() : "";
        return !string.IsNullOrWhiteSpace(value);
    }

    protected bool BodyInvalid()
    {
        ModelState.Remove("ifMatch");
        ModelState.Remove("If-Match");
        return !ModelState.IsValid;
    }
}

