using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

public sealed record BlogRequest(Guid Id, string Name);
public sealed record BlogResponse(Guid Id, string Name);

public sealed record PostRequest(Guid Id, string Title);
public sealed record PostResponse(Guid Id, Guid BlogId, string Title);

[ApiController]
[Route("api/blogs")]
public sealed class BlogsController : ControllerBase
{
    private readonly AppDbContext _db;

    public BlogsController(AppDbContext db) => _db = db;

    [HttpPost]
    public async Task<ActionResult<BlogResponse>> Create(
        BlogRequest request,
        CancellationToken cancellationToken)
    {
        if (request.Id == Guid.Empty || string.IsNullOrWhiteSpace(request.Name))
            return BadRequest();

        var existing = await _db.Blogs.AsNoTracking()
            .SingleOrDefaultAsync(blog => blog.Id == request.Id, cancellationToken);

        if (existing is not null)
        {
            if (existing.Name != request.Name)
                return Conflict();

            return Ok(ToResponse(existing));
        }

        var blog = new Blog { Id = request.Id, Name = request.Name };
        _db.Blogs.Add(blog);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            // A concurrent retry may have inserted this same client-provided ID.
            _db.Entry(blog).State = EntityState.Detached;
            existing = await _db.Blogs.AsNoTracking()
                .SingleOrDefaultAsync(item => item.Id == request.Id, cancellationToken);

            if (existing is null || existing.Name != request.Name)
                return Conflict();

            return Ok(ToResponse(existing));
        }

        SetVersion(blog.Version);
        return CreatedAtAction(nameof(Get), new { id = blog.Id }, ToResponse(blog));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<BlogResponse>> Get(Guid id, CancellationToken cancellationToken)
    {
        var blog = await _db.Blogs.AsNoTracking()
            .SingleOrDefaultAsync(item => item.Id == id, cancellationToken);

        if (blog is null)
            return NotFound();

        SetVersion(blog.Version);
        return Ok(ToResponse(blog));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(
        Guid id,
        BlogRequest request,
        CancellationToken cancellationToken)
    {
        if (request.Id != id || string.IsNullOrWhiteSpace(request.Name))
            return BadRequest();

        var blog = await _db.Blogs.SingleOrDefaultAsync(item => item.Id == id, cancellationToken);
        if (blog is null)
            return NotFound();

        if (!TryGetExpectedVersion(out var expectedVersion))
            return StatusCode(StatusCodes.Status428PreconditionRequired);

        if (blog.Version != expectedVersion)
            return StatusCode(StatusCodes.Status412PreconditionFailed);

        _db.Entry(blog).Property(item => item.Version).OriginalValue = expectedVersion;
        blog.Name = request.Name;
        blog.Version = Guid.NewGuid();

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return StatusCode(StatusCodes.Status412PreconditionFailed);
        }

        SetVersion(blog.Version);
        return Ok(ToResponse(blog));
    }

