POST requests use a client-provided `id` as the retry key; repeating the same request returns the existing resource, while reusing that ID with different content returns `409 Conflict`. PUT and DELETE require the `ETag` returned by GET or create in an `If-Match` header, so concurrent stale edits receive `412 Precondition Failed`. `Views` is stored on `Post` but never included in client request or response models.

```csharp
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

public sealed class Blog
{
    public Guid Id { get; set; }
    public string Name { get; set; } = string.Empty;

    // Used for optimistic concurrency checks on updates.
    public int Revision { get; set; }

    public List<Post> Posts { get; set; } = new();
}

public sealed class Post
{
    public Guid Id { get; set; }
    public Guid BlogId { get; set; }
    public string Title { get; set; } = string.Empty;

    // Maintained by the server; client updates never overwrite it.
    public int Views { get; set; }

    // Used for optimistic concurrency checks on updates.
    public int Revision { get; set; }

    public Blog Blog { get; set; } = null!;
}

public sealed class BlogsDbContext(DbContextOptions<BlogsDbContext> options)
    : DbContext(options)
{
    public DbSet<Blog> Blogs => Set<Blog>();
    public DbSet<Post> Posts => Set<Post>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            entity.HasKey(blog => blog.Id);
            entity.Property(blog => blog.Name).IsRequired();
            entity.Property(blog => blog.Revision).IsConcurrencyToken();
            entity.HasMany(blog => blog.Posts)
                .WithOne(post => post.Blog)
                .HasForeignKey(post => post.BlogId)
                .OnDelete(DeleteBehavior.Cascade);
        });

        modelBuilder.Entity<Post>(entity =>
        {
            entity.HasKey(post => post.Id);
            entity.Property(post => post.Title).IsRequired();
            entity.Property(post => post.Revision).IsConcurrencyToken();
        });
    }
}

