Create requests may include an optional `id`. Supplying a stable ID lets clients safely retry a timed-out POST without creating a duplicate; when omitted, the server generates the ID, so the client cannot identify a retry. Updates preserve `Post.Views`, and concurrent updates that conflict return `409 Conflict`.

```csharp
using System.ComponentModel.DataAnnotations;
using System.Text.Json.Serialization;
using Microsoft.EntityFrameworkCore;

public sealed class Blog
{
    public Guid Id { get; set; }
    public string Name { get; set; } = string.Empty;

    // Internal concurrency token; it is not part of the JSON representation.
    public int Version { get; set; }

    public ICollection<Post> Posts { get; set; } = new List<Post>();
}

public sealed class Post
{
    public Guid Id { get; set; }
    public Guid BlogId { get; set; }
    public string Title { get; set; } = string.Empty;

    // Maintained by the server; clients cannot set it through the API.
    public int Views { get; set; }

    // Internal concurrency token; it is not part of the JSON representation.
    public int Version { get; set; }

    public Blog Blog { get; set; } = null!;
}

public sealed class BlogPostContext(DbContextOptions<BlogPostContext> options)
    : DbContext(options)
{
    public DbSet<Blog> Blogs => Set<Blog>();
    public DbSet<Post> Posts => Set<Post>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>()
            .Property(blog => blog.Version)
            .IsConcurrencyToken();

        modelBuilder.Entity<Post>()
            .Property(post => post.Version)
            .IsConcurrencyToken();

        modelBuilder.Entity<Post>()
            .HasOne(post => post.Blog)
            .WithMany(blog => blog.Posts)
            .HasForeignKey(post => post.BlogId)
            .OnDelete(DeleteBehavior.Cascade);
    }

    public override int SaveChanges()
    {
        IncrementVersions();
        return base.SaveChanges();
    }

    public override Task<int> SaveChangesAsync(CancellationToken cancellationToken = default)
    {
        IncrementVersions();
        return base.SaveChangesAsync(cancellationToken);
    }

    private void IncrementVersions()
    {
        foreach (var entry in ChangeTracker.Entries<Blog>()
                     .Where(entry => entry.State == EntityState.Modified))
        {
            entry.Entity.Version++;
        }

        foreach (var entry in ChangeTracker.Entries<Post>()
                     .Where(entry => entry.State == EntityState.Modified))
        {
            entry.Entity.Version++;
        }
    }
}

