    {
        var id = request.Id.GetValueOrDefault();
        if (id == Guid.Empty)
            id = Guid.NewGuid();

        var existing = await db.Blogs.FindAsync([id], cancellationToken);
        if (existing is not null)
        {
            // Repeating a create with the same ID and content is safe.
            if (existing.Name == request.Name)
                return Ok(new BlogResponse(existing.Id, existing.Name));

            return Conflict();
        }

        var blog = new Blog { Id = id, Name = request.Name };
        db.Blogs.Add(blog);

        try
        {
            await db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            // Another request may have created this ID concurrently.
            db.Entry(blog).State = EntityState.Detached;
            existing = await db.Blogs.FindAsync([id], cancellationToken);
            if (existing is not null && existing.Name == request.Name)
                return Ok(new BlogResponse(existing.Id, existing.Name));

            return Conflict();
        }

        return CreatedAtAction(
            nameof(Get),
            new { id = blog.Id },
            new BlogResponse(blog.Id, blog.Name));
    }

