    {
        var blog = await db.Blogs.AsNoTracking()
            .FirstOrDefaultAsync(item => item.Id == id, cancellationToken);

        return blog is null
            ? NotFound()
            : Ok(new BlogResponse(blog.Id, blog.Name));
    }

