internal static class ApiSupport
{
    public static string BlogETag(Guid id, string name) =>
        Hash($"{{\"id\":\"{id.ToString("D").ToLowerInvariant()}\",\"name\":{Quote(name.Normalize(NormalizationForm.FormC))}}}");

    public static string PostETag(Guid id, Guid blogId, string title) =>
        Hash($"{{\"id\":\"{id.ToString("D").ToLowerInvariant()}\",\"blogId\":\"{blogId.ToString("D").ToLowerInvariant()}\",\"title\":{Quote(title.Normalize(NormalizationForm.FormC))}}}");

    private static string Hash(string canonical)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return "\"" + Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    private static string Quote(string value)
    {
        var result = new StringBuilder("\"");
        foreach (var c in value)
        {
            switch (c)
            {
                case '"': result.Append("\\\""); break;
                case '\\': result.Append("\\\\"); break;
                case '\b': result.Append("\\b"); break;
                case '\f': result.Append("\\f"); break;
                case '\n': result.Append("\\n"); break;
                case '\r': result.Append("\\r"); break;
                case '\t': result.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        result.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else
                        result.Append(c);
                    break;
            }
        }

        return result.Append('"').ToString();
    }

    public static string ContentHash<T>(T value) =>
        Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(value)));

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        return header.Split(',').Select(x => x.Trim()).Any(x => x == "*" || x == etag);
    }

    public static bool IsPrecondition(string? header, string etag) => Matches(header, etag);

    public static ObjectResult Problem(int status, string title, string detail)
    {
        var problem = new ProblemDetails { Status = status, Title = title, Detail = detail };
        var result = new ObjectResult(problem) { StatusCode = status };
        result.ContentTypes.Add("application/problem+json");
        return result;
    }

    public static void SetETag(HttpResponse response, string etag) => response.Headers.ETag = etag;

    public static async Task<bool> IsDeletedBlog(BlogsDbContext db, Guid id, CancellationToken ct) =>
        await db.Blogs.IgnoreQueryFilters().AnyAsync(x => x.Id == id && x.DeletedAt != null, ct);

    public static async Task<bool> IsDeletedPost(BlogsDbContext db, Guid id, CancellationToken ct) =>
        await db.Posts.IgnoreQueryFilters().AnyAsync(x => x.Id == id && x.DeletedAt != null, ct);
}

[ApiController]
[Route("api/blogs")]
public sealed class BlogsController(BlogsDbContext db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(BlogResponse), 201)]
    [ProducesResponseType(typeof(BlogResponse), 200)]
    [ProducesResponseType(typeof(ProblemDetails), 400, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 409, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, BindRequired] BlogRequest request, CancellationToken ct)
    {
        if (request.Id == Guid.Empty || string.IsNullOrWhiteSpace(request.Name))
            return ApiSupport.Problem(400, "Bad Request", "A non-empty id and name are required.");

        var name = request.Name.Normalize(NormalizationForm.FormC);
        var etag = ApiSupport.BlogETag(request.Id, name);
        var contentHash = ApiSupport.ContentHash(new { request.Id, Name = name });
        var blog = new Blog { Id = request.Id, Name = name, ETag = etag, CreateHash = contentHash };

        try
        {
            db.Blogs.Add(blog);
            await db.SaveChangesAsync(ct);
            ApiSupport.SetETag(Response, etag);
            Response.Headers.Location = $"/api/blogs/{request.Id:D}";
            return StatusCode(201, new BlogResponse(blog.Id, blog.Name));
        }
        catch (DbUpdateException)
        {
            db.ChangeTracker.Clear();
            var existing = await db.Blogs.IgnoreQueryFilters().SingleOrDefaultAsync(x => x.Id == request.Id, ct);
            if (existing is null) throw;
            if (existing.DeletedAt is not null)
                return ApiSupport.Problem(410, "Gone", "This blog id has been deleted.");
            if (existing.CreateHash != contentHash)
                return ApiSupport.Problem(409, "Conflict", "The id is already used by different content.");

            ApiSupport.SetETag(Response, existing.ETag);
            return Ok(new BlogResponse(existing.Id, existing.Name));
        }
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(BlogResponse), 200)]
    [ProducesResponseType(304)]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var blog = await db.Blogs.SingleOrDefaultAsync(x => x.Id == id, ct);
        if (blog is null)
        {
            if (await ApiSupport.IsDeletedBlog(db, id, ct))
                return ApiSupport.Problem(410, "Gone", "This blog has been deleted.");
            return ApiSupport.Problem(404, "Not Found", "Blog was not found.");
        }

        ApiSupport.SetETag(Response, blog.ETag);
        if (ApiSupport.Matches(Request.Headers.IfNoneMatch.ToString(), blog.ETag))
            return StatusCode(304);
        return Ok(new BlogResponse(blog.Id, blog.Name));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 400, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 412, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 428, "application/problem+json")]
    public async Task<IActionResult> Update(
        Guid id,
        [FromBody, BindRequired] BlogRequest request,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        CancellationToken ct)
    {
        if (request.Id == Guid.Empty || request.Id != id || string.IsNullOrWhiteSpace(request.Name))
            return ApiSupport.Problem(400, "Bad Request", "The body must contain the route id and a name.");

        var name = request.Name.Normalize(NormalizationForm.FormC);
        var newTag = ApiSupport.BlogETag(id, name);
        var blog = await db.Blogs.SingleOrDefaultAsync(x => x.Id == id, ct);
        if (blog is null)
        {
            if (await ApiSupport.IsDeletedBlog(db, id, ct))
                return ApiSupport.Problem(410, "Gone", "This blog has been deleted.");
            return ApiSupport.Problem(404, "Not Found", "Blog was not found.");
        }

        if (blog.ETag == newTag) return NoContent();
        if (string.IsNullOrWhiteSpace(ifMatch))
            return ApiSupport.Problem(428, "Precondition Required", "If-Match is required.");
        if (!ApiSupport.IsPrecondition(ifMatch, blog.ETag))
        {
            ApiSupport.SetETag(Response, blog.ETag);
            return ApiSupport.Problem(412, "Precondition Failed", "The item has changed.");
        }

        var oldTag = blog.ETag;
        blog.Name = name;
        blog.ETag = newTag;
        try
        {
            await db.SaveChangesAsync(ct);
            ApiSupport.SetETag(Response, newTag);
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            Response.Headers.ETag = oldTag;
            return ApiSupport.Problem(412, "Precondition Failed", "The item has changed.");
        }
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 412, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 428, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return ApiSupport.Problem(428, "Precondition Required", "If-Match is required.");

        var blog = await db.Blogs.SingleOrDefaultAsync(x => x.Id == id, ct);
        if (blog is null) return NoContent();
        if (!ApiSupport.IsPrecondition(ifMatch, blog.ETag))
        {
            ApiSupport.SetETag(Response, blog.ETag);
            return ApiSupport.Problem(412, "Precondition Failed", "The item has changed.");
        }

        var now = DateTimeOffset.UtcNow;
        var posts = await db.Posts.Where(x => x.BlogId == id).ToListAsync(ct);
        foreach (var post in posts) post.DeletedAt = now;
        blog.DeletedAt = now;
        try
        {
            await db.SaveChangesAsync(ct);
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            return ApiSupport.Problem(412, "Precondition Failed", "The item has changed.");
        }
    }
}

