        entity.HasIndex("Id").IsUnique();
        entity.Property<Guid>("Id").IsRequired();
        entity.Property<string>("ETag").IsRequired().IsConcurrencyToken();
        entity.Property<string>("CreateHash").IsRequired()
            .Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
