public sealed record BlogResponse(Guid Id, string Name);
public sealed record PostResponse(Guid Id, Guid BlogId, string Title);
public sealed record BlogRequest(Guid Id, string? Name);
public sealed record PostRequest(Guid Id, Guid BlogId, string? Title);

internal static class ApiHelpers
{
    public static string BlogTag(Guid id, string? name) =>
        Tag(JsonSerializer.Serialize(new object?[] { id.ToString("D").ToLowerInvariant(), Normalize(name) }));

    public static string PostTag(Guid id, Guid blogId, string? title) =>
        Tag(JsonSerializer.Serialize(new object?[]
        {
            id.ToString("D").ToLowerInvariant(),
            blogId.ToString("D").ToLowerInvariant(),
            Normalize(title)
        }));

    private static string? Normalize(string? value) => value?.Normalize(NormalizationForm.FormC);

    private static string Tag(string json)
    {
        // Re-escape to the specified canonical JSON string rules.
        var canonical = CanonicalizeStrings(json);
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return "\"" + Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    private static string CanonicalizeStrings(string json)
    {
        using var document = JsonDocument.Parse(json);
        return WriteValue(document.RootElement);
    }

    private static string WriteValue(JsonElement value) => value.ValueKind switch
    {
        JsonValueKind.Array => "[" + string.Join(",", value.EnumerateArray().Select(WriteValue)) + "]",
        JsonValueKind.String => WriteString(value.GetString() ?? ""),
        _ => value.GetRawText()
    };

    private static string WriteString(string value)
    {
        var b = new StringBuilder("\"");
        foreach (var c in value.Normalize(NormalizationForm.FormC))
        {
            switch (c)
            {
                case '"': b.Append("\\\""); break;
                case '\\': b.Append("\\\\"); break;
                case '\b': b.Append("\\b"); break;
                case '\f': b.Append("\\f"); break;
                case '\n': b.Append("\\n"); break;
                case '\r': b.Append("\\r"); break;
                case '\t': b.Append("\\t"); break;
                default:
                    if (c < 0x20) b.Append("\\u").Append(((int)c).ToString("x4"));
                    else b.Append(c);
                    break;
            }
        }
        return b.Append('"').ToString();
    }

    public static bool Matches(HttpRequest request, string tag)
    {
        var values = request.Headers.IfMatch;
        return values.Any(value => value == "*" ||
            value!.Split(',').Select(x => x.Trim()).Contains(tag, StringComparer.Ordinal));
    }

    public static bool NotModified(HttpRequest request, string tag) =>
        request.Headers.IfNoneMatch.Any(value =>
            value == "*" || value!.Split(',').Select(x => x.Trim()).Contains(tag, StringComparer.Ordinal));

    public static ObjectResult Problem(int status, string title) =>
        new ProblemDetails { Status = status, Title = title } is var problem
            ? new ObjectResult(problem) { StatusCode = status, ContentTypes = { "application/problem+json" } }
            : throw new InvalidOperationException();

    public static bool IsUniqueViolation(Exception exception) =>
        exception is DbUpdateException { InnerException: SqliteException sqlite } &&
        (sqlite.SqliteErrorCode == 19);
}
