using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/blogs")]
public sealed class BlogsController(BlogPostDbContext db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, Microsoft.AspNetCore.Mvc.ModelBinding.BindRequired] BlogRequest? body, CancellationToken ct)
    {
        if (body is null || body.Id == Guid.Empty || string.IsNullOrWhiteSpace(body.Name))
            return ApiHelpers.Problem(400, "Invalid blog");

        var name = body.Name.Normalize(System.Text.NormalizationForm.FormC);
        var tag = ApiHelpers.BlogTag(body.Id, name);
        var hash = tag;
        var blog = new Blog { Id = body.Id, Name = name, ETag = tag, CreateHash = hash };
        db.Blogs.Add(blog);

        try
        {
            await db.SaveChangesAsync(ct);
            Response.Headers.ETag = tag;
            return CreatedAtAction(nameof(Get), new { id = body.Id }, new BlogResponse(body.Id, name));
        }
        catch (DbUpdateException ex) when (ApiHelpers.IsUniqueViolation(ex))
        {
            db.Entry(blog).State = EntityState.Detached;
            var existing = await db.Blogs.IgnoreQueryFilters().SingleOrDefaultAsync(x => x.Id == body.Id, ct);
            if (existing?.DeletedAt != null) return ApiHelpers.Problem(410, "Blog was deleted");
            if (existing is null || existing.CreateHash != hash) return ApiHelpers.Problem(409, "Blog id conflicts");
            Response.Headers.ETag = existing.ETag;
            return Ok(new BlogResponse(existing.Id, existing.Name));
        }
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var blog = await db.Blogs.SingleOrDefaultAsync(x => x.Id == id, ct);
        if (blog is null)
        {
            if (await db.Blogs.IgnoreQueryFilters().AnyAsync(x => x.Id == id, ct))
                return ApiHelpers.Problem(410, "Blog was deleted");
            return ApiHelpers.Problem(404, "Blog not found");
        }

        Response.Headers.ETag = blog.ETag;
        if (ApiHelpers.NotModified(Request, blog.ETag)) return StatusCode(304);
        return Ok(new BlogResponse(blog.Id, blog.Name));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromBody, Microsoft.AspNetCore.Mvc.ModelBinding.BindRequired] BlogRequest? body,
        [FromHeader(Name = "If-Match", Required = true)] string? ifMatch, CancellationToken ct)
    {
        if (body is null || body.Id == Guid.Empty || string.IsNullOrWhiteSpace(body.Name) || body.Id != id)
            return ApiHelpers.Problem(400, "Invalid blog");
        if (string.IsNullOrEmpty(ifMatch)) return ApiHelpers.Problem(428, "If-Match required");

        var blog = await db.Blogs.SingleOrDefaultAsync(x => x.Id == id, ct);
        if (blog is null) return await GoneOrMissingBlog(id, ct);

        var name = body.Name.Normalize(System.Text.NormalizationForm.FormC);
        var newTag = ApiHelpers.BlogTag(id, name);
        if (blog.ETag == newTag) { Response.Headers.ETag = newTag; return NoContent(); }
        if (!ApiHelpers.Matches(Request, blog.ETag)) { Response.Headers.ETag = blog.ETag; return ApiHelpers.Problem(412, "Precondition failed"); }

        var oldTag = blog.ETag;
        blog.Name = name;
        blog.ETag = newTag;
        db.Entry(blog).Property(x => x.ETag).OriginalValue = oldTag;
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException)
        {
            return await BlogRace(id, newTag, ct);
        }
        Response.Headers.ETag = newTag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match", Required = true)] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch)) return ApiHelpers.Problem(428, "If-Match required");
        var blog = await db.Blogs.Include(x => x.Posts).SingleOrDefaultAsync(x => x.Id == id, ct);
        if (blog is null) return NoContent();
        if (!ApiHelpers.Matches(Request, blog.ETag)) { Response.Headers.ETag = blog.ETag; return ApiHelpers.Problem(412, "Precondition failed"); }

        var now = DateTimeOffset.UtcNow;
        blog.DeletedAt = now;
        foreach (var post in blog.Posts) post.DeletedAt = now;
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { return ApiHelpers.Problem(412, "Precondition failed"); }
        return NoContent();
    }

    private async Task<IActionResult> GoneOrMissingBlog(Guid id, CancellationToken ct) =>
        await db.Blogs.IgnoreQueryFilters().AnyAsync(x => x.Id == id, ct)
            ? ApiHelpers.Problem(410, "Blog was deleted")
            : ApiHelpers.Problem(404, "Blog not found");

    private async Task<IActionResult> BlogRace(Guid id, string requestedTag, CancellationToken ct)
    {
        var current = await db.Blogs.AsNoTracking().SingleOrDefaultAsync(x => x.Id == id, ct);
        if (current is null) return await GoneOrMissingBlog(id, ct);
        if (current.ETag == requestedTag) return NoContent();
        Response.Headers.ETag = current.ETag;
        return ApiHelpers.Problem(412, "Precondition failed");
    }
}
