    public static bool MatchesIfNoneMatch(HttpRequest request, string etag)
    {
        var values = request.Headers["If-None-Match"];
        return values.Any(v => v!.Split(',').Any(x =>
        {
            var t = x.Trim();
            return t == "*" || t == etag || t.StartsWith("W/", StringComparison.Ordinal) && t[2..] == etag;
        }));
    }

    public static bool MatchesIfMatch(HttpRequest request, string etag)
    {
        var values = request.Headers["If-Match"];
        return values.Any(v => v!.Split(',').Any(x => x.Trim() == "*" || x.Trim() == etag));
    }

    public static bool HasIfMatch(HttpRequest request) =>
        request.Headers.ContainsKey("If-Match") && request.Headers["If-Match"].Count > 0;

    public static IActionResult ProblemResult(ControllerBase c, int status, string title) =>
        c.Problem(statusCode: status, title: title, type: "about:blank");

    public static void SetETag(HttpResponse response, string etag) => response.Headers.ETag = etag;

    public static bool ValidName(string? s) => !string.IsNullOrWhiteSpace(s);
