public sealed record PostResponse(Guid Id, Guid BlogId, string Title);

internal static class ApiHelpers
{
    public static string Normalize(string value) => value.Normalize(NormalizationForm.FormC);

    public static string Quote(string value)
    {
        var s = new StringBuilder("\"");
        foreach (var c in Normalize(value))
        {
            switch (c)
            {
                case '"': s.Append("\\\""); break;
                case '\\': s.Append("\\\\"); break;
                case '\b': s.Append("\\b"); break;
                case '\f': s.Append("\\f"); break;
                case '\n': s.Append("\\n"); break;
                case '\r': s.Append("\\r"); break;
                case '\t': s.Append("\\t"); break;
                default:
                    if (c < 0x20) s.Append("\\u").Append(((int)c).ToString("x4"));
                    else s.Append(c);
                    break;
            }
        }
        return s.Append('"').ToString();
    }

    private static string Hash(string json)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(json));
        return "\"" + Convert.ToBase64String(bytes).TrimEnd('=')
            .Replace('+', '-').Replace('/', '_') + "\"";
    }

    public static string BlogTag(Guid id, string name) =>
        Hash("{\"id\":\"" + id.ToString("D") + "\",\"name\":" + Quote(name) + "}");

    public static string PostTag(Guid id, Guid blogId, string title) =>
        Hash("{\"id\":\"" + id.ToString("D") + "\",\"blogId\":\"" +
             blogId.ToString("D") + "\",\"title\":" + Quote(title) + "}");

    public static string BlogCreateHash(Guid id, string name) => BlogTag(id, name);
    public static string PostCreateHash(Guid id, Guid blogId, string title) =>
        PostTag(id, blogId, title);

    public static bool Matches(string? header, string etag) =>
        header == "*" || header?.Split(',').Any(x => x.Trim() == etag) == true;

    public static ObjectResult Problem(int status, string title, string detail)
    {
        var result = new ObjectResult(new ProblemDetails
        {
            Status = status,
            Title = title,
            Detail = detail
        })
        {
            StatusCode = status
        };
        result.ContentTypes.Add("application/problem+json");
        return result;
    }

    public static bool Valid(ModelStateDictionary state) => state.IsValid;

    public static bool UniqueViolation(DbUpdateException ex) =>
        ex.InnerException?.Message.Contains("UNIQUE constraint failed",
            StringComparison.OrdinalIgnoreCase) == true;
}

