    {
        if (!ApiHelpers.Valid(ModelState) || request?.Id is null ||
            string.IsNullOrWhiteSpace(request.Name))
            return ApiHelpers.Problem(400, "Bad Request", "A valid id and name are required.");

        var name = ApiHelpers.Normalize(request.Name);
        var hash = ApiHelpers.BlogCreateHash(request.Id.Value, name);
        var entity = new Blog
        {
            Id = request.Id.Value,
            Name = name,
            CreateHash = hash,
            ETag = hash
        };

        db.Blogs.Add(entity);
        try
        {
            await db.SaveChangesAsync(cancellationToken);
            Response.Headers.ETag = entity.ETag;
            return Created($"/api/blogs/{entity.Id:D}",
                new BlogResponse(entity.Id, entity.Name));
        }
        catch (DbUpdateException ex) when (ApiHelpers.UniqueViolation(ex))
        {
            db.Entry(entity).State = EntityState.Detached;
            var existing = await db.Blogs.IgnoreQueryFilters()
                .SingleOrDefaultAsync(x => x.Id == request.Id.Value, cancellationToken);
            if (existing is null)
                return ApiHelpers.Problem(409, "Conflict", "The id is already in use.");
            if (existing.DeletedAt is not null)
                return ApiHelpers.Problem(410, "Gone", "This blog has been deleted.");
            if (existing.CreateHash != hash)
                return ApiHelpers.Problem(409, "Conflict", "The id has different content.");

            Response.Headers.ETag = existing.ETag;
            return Ok(new BlogResponse(existing.Id, existing.Name));
        }
