    public async Task<IActionResult> Update(
        Guid id,
        [FromBody, Required] BlogRequest? request,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        CancellationToken cancellationToken)
    {
        if (!ApiHelpers.Valid(ModelState) || request?.Id is null ||
            request.Id != id || string.IsNullOrWhiteSpace(request.Name))
            return ApiHelpers.Problem(400, "Bad Request", "The body must contain this id and a name.");

        var name = ApiHelpers.Normalize(request.Name);
        var nextTag = ApiHelpers.BlogTag(id, name);
        var item = await db.Blogs.SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (item is null)
            return await GoneOrMissingBlog(id, cancellationToken);
        if (item.ETag == nextTag) return NoContent();
        if (string.IsNullOrWhiteSpace(ifMatch))
            return ApiHelpers.Problem(428, "Precondition Required", "If-Match is required.");
        if (!ApiHelpers.Matches(ifMatch, item.ETag))
        {
            Response.Headers.ETag = item.ETag;
            return ApiHelpers.Problem(412, "Precondition Failed", "The item has changed.");
        }

        item.Name = name;
        item.ETag = nextTag;
        try
        {
            await db.SaveChangesAsync(cancellationToken);
            Response.Headers.ETag = item.ETag;
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            return await StaleBlog(id, cancellationToken);
        }
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 412, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 428, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return ApiHelpers.Problem(428, "Precondition Required", "If-Match is required.");

        var item = await db.Blogs.Include(x => x.Posts)
            .SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (item is null) return NoContent();
        if (!ApiHelpers.Matches(ifMatch, item.ETag))
        {
            Response.Headers.ETag = item.ETag;
            return ApiHelpers.Problem(412, "Precondition Failed", "The item has changed.");
        }

        var now = DateTimeOffset.UtcNow;
        item.DeletedAt = now;
        foreach (var post in item.Posts) post.DeletedAt = now;
        try
        {
            await db.SaveChangesAsync(cancellationToken);
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            return await StaleBlog(id, cancellationToken);
        }
    }

    private async Task<IActionResult> GoneOrMissingBlog(Guid id, CancellationToken ct)
    {
        var deleted = await db.Blogs.IgnoreQueryFilters().AnyAsync(
            x => x.Id == id && x.DeletedAt != null, ct);
        return deleted
            ? ApiHelpers.Problem(410, "Gone", "This blog has been deleted.")
            : ApiHelpers.Problem(404, "Not Found", "Blog not found.");
    }

    private async Task<IActionResult> StaleBlog(Guid id, CancellationToken ct)
    {
        var live = await db.Blogs.AsNoTracking().SingleOrDefaultAsync(x => x.Id == id, ct);
        if (live is null) return await GoneOrMissingBlog(id, ct);
        Response.Headers.ETag = live.ETag;
        return ApiHelpers.Problem(412, "Precondition Failed", "The item has changed.");
    }
