        blog.Property(x => x.PublicId).IsRequired();
        blog.Property(x => x.Name).IsRequired();
        blog.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
        blog.Property(x => x.CreateHash).IsRequired().Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
        blog.HasQueryFilter(x => x.DeletedAt == null);

        var post = modelBuilder.Entity<Post>();
        post.HasKey(x => x.Id);
        post.HasIndex(x => x.PublicId).IsUnique();
        post.Property(x => x.PublicId).IsRequired();
        post.Property(x => x.BlogPublicId).IsRequired();
        post.Property(x => x.Title).IsRequired();
