internal static class ApiSupport
{
    private static string Hash(string canonicalJson)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson));
        return "\"" + Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    private static string Text(string value)
    {
        var normalized = value.Normalize(NormalizationForm.FormC);
        var result = new StringBuilder("\"");
        foreach (var c in normalized)
        {
            switch (c)
            {
                case '"': result.Append("\\\""); break;
                case '\\': result.Append("\\\\"); break;
                case '\b': result.Append("\\b"); break;
                case '\f': result.Append("\\f"); break;
                case '\n': result.Append("\\n"); break;
                case '\r': result.Append("\\r"); break;
                case '\t': result.Append("\\t"); break;
                default:
                    if (c < 0x20) result.Append("\\u00").Append(((int)c).ToString("x2"));
                    else result.Append(c);
                    break;
            }
        }
        return result.Append('"').ToString();
    }

    public static string BlogTag(Guid id, string name) =>
        Hash("{\"id\":\"" + id.ToString("D") + "\",\"name\":" + Text(name) + "}");

    public static string PostTag(Guid id, Guid blogId, string title) =>
        Hash("{\"id\":\"" + id.ToString("D") + "\",\"blogId\":\"" + blogId.ToString("D") +
             "\",\"title\":" + Text(title) + "}");

    public static string CanonicalBlog(Guid id, string name) =>
        "{\"id\":\"" + id.ToString("D") + "\",\"name\":" + Text(name) + "}";

    public static string CanonicalPost(Guid id, Guid blogId, string title) =>
        "{\"id\":\"" + id.ToString("D") + "\",\"blogId\":\"" + blogId.ToString("D") +
        "\",\"title\":" + Text(title) + "}";

    public static string CreateHash(string canonical) =>
        Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(canonical)));

    public static bool Matches(string? header, string etag)
    {
        if (header is null) return false;
        return header.Split(',').Select(x => x.Trim()).Any(x =>
            x == "*" || string.Equals(x, etag, StringComparison.Ordinal));
    }

    public static ObjectResult Error(int status, string title, string detail)
    {
        var problem = new ProblemDetails { Status = status, Title = title, Detail = detail };
        var result = new ObjectResult(problem) { StatusCode = status };
        result.ContentTypes.Add("application/problem+json");
        return result;
    }

    public static bool Valid(string? value) => !string.IsNullOrWhiteSpace(value);

    public static async Task<bool> IsGoneBlog(BlogsDbContext db, Guid id, CancellationToken ct) =>
        await db.Blogs.IgnoreQueryFilters().AnyAsync(x => x.PublicId == id && x.DeletedAt != null, ct);

    public static async Task<bool> IsGonePost(BlogsDbContext db, Guid id, CancellationToken ct) =>
        await db.Posts.IgnoreQueryFilters().AnyAsync(x => x.PublicId == id && x.DeletedAt != null, ct);

    public static bool IsUniqueViolation(DbUpdateException ex) =>
        ex.InnerException is Microsoft.Data.Sqlite.SqliteException sqlite &&
        (sqlite.SqliteErrorCode == 19 || sqlite.SqliteExtendedErrorCode == 2067);
}

