public sealed class BlogsDbContext(DbContextOptions<BlogsDbContext> options)
    : DbContext(options)
{
    public DbSet<Blog> Blogs => Set<Blog>();
    public DbSet<Post> Posts => Set<Post>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        var blog = modelBuilder.Entity<Blog>();
        blog.HasKey(x => x.InternalId);
        blog.HasIndex(x => x.Id).IsUnique();
        blog.Property(x => x.Id).IsRequired();
        blog.Property(x => x.Name).IsRequired();
        blog.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
        blog.Property(x => x.CreateHash).IsRequired().Metadata
            .SetAfterSaveBehavior(PropertySaveBehavior.Throw);
        blog.HasQueryFilter(x => x.DeletedAt == null);

        var post = modelBuilder.Entity<Post>();
        post.HasKey(x => x.InternalId);
        post.HasIndex(x => x.Id).IsUnique();
        post.Property(x => x.Id).IsRequired();
        post.Property(x => x.BlogId).IsRequired();
        post.Property(x => x.Title).IsRequired();
        post.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
        post.Property(x => x.CreateHash).IsRequired().Metadata
            .SetAfterSaveBehavior(PropertySaveBehavior.Throw);
        post.HasQueryFilter(x => x.DeletedAt == null);
        post.HasOne(x => x.Blog).WithMany(x => x.Posts)
            .HasForeignKey(x => x.BlogId).OnDelete(DeleteBehavior.Restrict);
    }
}

