    public Guid? Id { get; set; }

    [Required]
    public string? Name { get; set; }
}

public sealed class PostRequest
{
    [Required]
    public Guid? Id { get; set; }

    [Required]
    public Guid? BlogId { get; set; }

    [Required]
    public string? Title { get; set; }
}

public sealed record BlogResponse(Guid Id, string Name);
public sealed record PostResponse(Guid Id, Guid BlogId, string Title);

internal static class ApiHelpers
{
    public static string BlogETag(Guid id, string name) =>
        Hash($"{{\"id\":\"{id:D}\",\"name\":\"{Escape(name)}\"}}");

    public static string PostETag(Guid id, Guid blogId, string title) =>
        Hash($"{{\"id\":\"{id:D}\",\"blogId\":\"{blogId:D}\",\"title\":\"{Escape(title)}\"}}");

    public static string Escape(string value)
    {
        var normalized = value.Normalize(NormalizationForm.FormC);
        var result = new StringBuilder(normalized.Length + 2);
        foreach (var c in normalized)
        {
            switch (c)
            {
                case '"': result.Append("\\\""); break;
                case '\\': result.Append("\\\\"); break;
                case '\b': result.Append("\\b"); break;
                case '\f': result.Append("\\f"); break;
                case '\n': result.Append("\\n"); break;
                case '\r': result.Append("\\r"); break;
                case '\t': result.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        result.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else
                        result.Append(c);
                    break;
            }
        }
        return result.ToString();
    }

    private static string Hash(string json)
    {
        var digest = SHA256.HashData(Encoding.UTF8.GetBytes(json));
        return "\"" + Convert.ToBase64String(digest).TrimEnd('=')
            .Replace('+', '-').Replace('/', '_') + "\"";
    }

    public static bool Valid(string? value) => !string.IsNullOrWhiteSpace(value);

    public static bool Matches(string? ifMatch, string current) =>
        ifMatch == "*" || ifMatch == current;

    public static ObjectResult Problem(int status, string title, string detail) =>
        new(new ProblemDetails { Status = status, Title = title, Detail = detail })
        {
            StatusCode = status,
            ContentTypes = { "application/problem+json" }
        };

    public static bool IsUniqueViolation(DbUpdateException exception) =>
        exception.InnerException is SqliteException sqlite && sqlite.SqliteErrorCode == 19;
}

