[ApiController]
[Route("api/support-tickets")]
public sealed class SupportTicketsController : ControllerBase
{
    private readonly TicketDbContext _db;

    public SupportTicketsController(TicketDbContext db)
    {
        _db = db;
    }

    [HttpPost]
    public async Task<ActionResult<TicketResponse>> Create(
        [FromBody] TicketRequest request,
        CancellationToken cancellationToken)
    {
        if (!IsValid(request))
            return BadRequest();

        var ticket = new Ticket
        {
            Id = request.Id,
            Subject = request.Subject,
            Priority = request.Priority,
            Escalated = request.Escalated,
            Category = request.Category
        };

        _db.Tickets.Add(ticket);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            // Treat a retry with the same ID and payload as the original create.
            _db.Entry(ticket).State = EntityState.Detached;
            var existing = await _db.Tickets
                .AsNoTracking()
                .SingleOrDefaultAsync(t => t.Id == request.Id, cancellationToken);

            if (existing is null || !HasSameFields(existing, request))
                return Conflict();

            ticket = existing;
        }

        SetETag(ticket);
        return CreatedAtAction(nameof(Get), new { id = ticket.Id }, ToResponse(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> Get(Guid id, CancellationToken cancellationToken)
    {
        var viewedAt = DateTime.UtcNow;
        var updated = await _db.Tickets
            .Where(ticket => ticket.Id == id)
            .ExecuteUpdateAsync(setters => setters
                .SetProperty(ticket => ticket.ViewCount, ticket => ticket.ViewCount + 1)
                .SetProperty(ticket => ticket.LastViewedAt, viewedAt),
                cancellationToken);

        if (updated == 0)
            return NotFound();

        var ticket = await _db.Tickets.AsNoTracking()
            .SingleAsync(t => t.Id == id, cancellationToken);

        SetETag(ticket);
        return Ok(ToResponse(ticket));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> Update(
        Guid id,
        [FromBody] TicketRequest request,
        CancellationToken cancellationToken)
    {
        if (request.Id != id || !IsValid(request))
            return BadRequest();

        var ticket = await _db.Tickets.SingleOrDefaultAsync(t => t.Id == id, cancellationToken);
        if (ticket is null)
            return NotFound();

        if (!MatchesIfMatch(ticket))
            return StatusCode(StatusCodes.Status412PreconditionFailed);

        ticket.Subject = request.Subject;
        ticket.Priority = request.Priority;
        ticket.Escalated = request.Escalated;
        ticket.Category = request.Category;
        ticket.Version++;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }

        SetETag(ticket);
        return Ok(ToResponse(ticket));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken cancellationToken)
    {
        var ticket = await _db.Tickets.SingleOrDefaultAsync(t => t.Id == id, cancellationToken);
        if (ticket is null)
            return NotFound();

        if (!MatchesIfMatch(ticket))
            return StatusCode(StatusCodes.Status412PreconditionFailed);

        _db.Tickets.Remove(ticket);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }

        return NoContent();
    }

    private bool MatchesIfMatch(Ticket ticket)
    {
        if (!Request.Headers.TryGetValue("If-Match", out var values))
            return true;

        var expected = $"\"{ticket.Version}\"";
        return values.Any(value => value == expected || value == "*");
    }

    private void SetETag(Ticket ticket) =>
        Response.Headers.ETag = $"\"{ticket.Version}\"";

    private static bool IsValid(TicketRequest request) =>
        request.Id != Guid.Empty &&
        !string.IsNullOrWhiteSpace(request.Subject) &&
        !string.IsNullOrWhiteSpace(request.Category);

    private static bool HasSameFields(Ticket ticket, TicketRequest request) =>
        ticket.Subject == request.Subject &&
        ticket.Priority == request.Priority &&
        ticket.Escalated == request.Escalated &&
        ticket.Category == request.Category;

    private static TicketResponse ToResponse(Ticket ticket) =>
        new(ticket.Id, ticket.Subject, ticket.Priority, ticket.Escalated, ticket.Category);
}
