[ApiController]
[Route("api/support-tickets")]
public sealed class SupportTicketsController : ControllerBase
{
    private readonly SupportTicketsDbContext _db;

    public SupportTicketsController(SupportTicketsDbContext db)
    {
        _db = db;
    }

    [HttpPost]
    public async Task<ActionResult<TicketResponse>> Create(
        [FromBody] CreateTicketRequest request,
        CancellationToken cancellationToken)
    {
        if (request.Id == Guid.Empty ||
            string.IsNullOrWhiteSpace(request.Subject) ||
            string.IsNullOrWhiteSpace(request.Category))
        {
            return BadRequest();
        }

        var ticket = new Ticket
        {
            Id = request.Id,
            Subject = request.Subject,
            Priority = request.Priority,
            Escalated = request.Escalated,
            Category = request.Category,
            Version = 1
        };

        _db.Tickets.Add(ticket);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            // A repeated POST with the same ID and content is safe to retry.
            var existing = await _db.Tickets
                .AsNoTracking()
                .SingleOrDefaultAsync(t => t.Id == request.Id, cancellationToken);

            if (existing is null)
            {
                return Conflict();
            }

            if (existing.Subject != request.Subject ||
                existing.Priority != request.Priority ||
                existing.Escalated != request.Escalated ||
                existing.Category != request.Category)
            {
                return Conflict();
            }

            SetEtag(existing.Version);
            return CreatedAtAction(nameof(Get), new { id = existing.Id }, ToResponse(existing));
        }

        SetEtag(ticket.Version);
        return CreatedAtAction(nameof(Get), new { id = ticket.Id }, ToResponse(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> Get(
        Guid id,
        CancellationToken cancellationToken)
    {
        var ticket = await _db.Tickets
            .SingleOrDefaultAsync(t => t.Id == id, cancellationToken);

        if (ticket is null)
        {
            return NotFound();
        }

        ticket.ViewCount++;
        ticket.LastViewedAt = DateTime.UtcNow;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }

        SetEtag(ticket.Version);
        return Ok(ToResponse(ticket));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> Update(
        Guid id,
        [FromBody] UpdateTicketRequest request,
        CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) ||
            string.IsNullOrWhiteSpace(request.Category))
        {
            return BadRequest();
        }

        var ticket = await _db.Tickets
            .SingleOrDefaultAsync(t => t.Id == id, cancellationToken);

        if (ticket is null)
        {
            return NotFound();
        }

        var expectedVersion = ticket.Version;
        if (Request.Headers.TryGetValue("If-Match", out var ifMatch))
        {
            if (!TryParseEtag(ifMatch.ToString(), out var suppliedVersion))
            {
                return BadRequest("If-Match must contain a ticket ETag.");
            }

            if (suppliedVersion != expectedVersion)
            {
                return StatusCode(StatusCodes.Status412PreconditionFailed);
            }
        }

        ticket.Subject = request.Subject;
        ticket.Priority = request.Priority;
        ticket.Escalated = request.Escalated;
        ticket.Category = request.Category;
        ticket.Version++;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }

        SetEtag(ticket.Version);
        return Ok(ToResponse(ticket));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(
        Guid id,
        CancellationToken cancellationToken)
    {
        var ticket = await _db.Tickets
            .SingleOrDefaultAsync(t => t.Id == id, cancellationToken);

        if (ticket is null)
        {
            // Repeated DELETE requests are safe to retry.
            return NoContent();
        }

        _db.Tickets.Remove(ticket);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }

        return NoContent();
    }

    private void SetEtag(int version) =>
        Response.Headers.ETag = $"\"{version}\"";

    private static bool TryParseEtag(string value, out int version)
    {
        version = 0;
        var normalized = value.Trim();

        if (normalized.StartsWith("W/", StringComparison.OrdinalIgnoreCase))
        {
            normalized = normalized[2..];
        }

        normalized = normalized.Trim('"');
        return int.TryParse(normalized, out version);
    }

    private static TicketResponse ToResponse(Ticket ticket) =>
        new(
            ticket.Id,
            ticket.Subject,
            ticket.Priority,
            ticket.Escalated,
            ticket.Category,
            ticket.ViewCount,
            ticket.LastViewedAt);
