    [HttpPost]
    public async Task<ActionResult<TicketResponse>> Create(
        [FromBody] TicketRequest request,
        CancellationToken cancellationToken)
    {
        if (request.Id == Guid.Empty)
        {
            return BadRequest("A non-empty ticket id is required.");
        }

        var ticket = new Ticket
        {
            Id = request.Id,
            Subject = request.Subject,
            Priority = request.Priority,
            Escalated = request.Escalated,
            Category = request.Category
        };

        _db.Tickets.Add(ticket);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            // A retry with the same id and payload is treated as the original create.
            var existing = await _db.Tickets.AsNoTracking()
                .SingleOrDefaultAsync(t => t.Id == request.Id, cancellationToken);

            if (existing is null)
            {
                throw;
            }

            if (!Matches(existing, request))
            {
                return Conflict();
            }

            SetETag(existing.Version);
            return Ok(TicketResponse.From(existing));
        }

        SetETag(ticket.Version);
        return CreatedAtAction(nameof(GetById), new { id = ticket.Id }, TicketResponse.From(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> GetById(
        Guid id,
        CancellationToken cancellationToken)
    {
        var now = DateTime.UtcNow;
        var updated = await _db.Tickets
            .Where(ticket => ticket.Id == id)
            .ExecuteUpdateAsync(setters => setters
                .SetProperty(ticket => ticket.ViewCount, ticket => ticket.ViewCount + 1)
                .SetProperty(ticket => ticket.LastViewedAt, now),
                cancellationToken);

        if (updated == 0)
        {
            return NotFound();
        }

        var ticket = await _db.Tickets.AsNoTracking()
            .SingleAsync(t => t.Id == id, cancellationToken);

        SetETag(ticket.Version);
        return Ok(TicketResponse.From(ticket));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> Update(
        Guid id,
        [FromBody] TicketRequest request,
        CancellationToken cancellationToken)
    {
        if (id != request.Id)
        {
            return BadRequest("The route id must match the body id.");
        }

        var ticket = await _db.Tickets.SingleOrDefaultAsync(t => t.Id == id, cancellationToken);
        if (ticket is null)
        {
            return NotFound();
        }

        if (!TryCheckETag(ticket.Version))
        {
            return StatusCode(StatusCodes.Status412PreconditionFailed);
        }

        ticket.Subject = request.Subject;
        ticket.Priority = request.Priority;
        ticket.Escalated = request.Escalated;
        ticket.Category = request.Category;
        ticket.Version++;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }

        SetETag(ticket.Version);
        return Ok(TicketResponse.From(ticket));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken cancellationToken)
    {
        var ticket = await _db.Tickets.SingleOrDefaultAsync(t => t.Id == id, cancellationToken);
        if (ticket is null)
        {
            return NotFound();
        }

        if (!TryCheckETag(ticket.Version))
        {
            return StatusCode(StatusCodes.Status412PreconditionFailed);
        }

        _db.Tickets.Remove(ticket);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }

        return NoContent();
    }

    private bool TryCheckETag(int currentVersion)
    {
        // If-Match is optional for compatibility; when supplied, stale edits are rejected.
        if (!Request.Headers.TryGetValue("If-Match", out var values))
        {
            return true;
        }

        var value = values.ToString().Trim();
        if (value.StartsWith("W/", StringComparison.OrdinalIgnoreCase))
        {
            value = value[2..].Trim();
        }

        value = value.Trim('"');
        return int.TryParse(value, NumberStyles.None, CultureInfo.InvariantCulture, out var version)
            && version == currentVersion;
    }

    private void SetETag(int version)
    {
        Response.Headers.ETag = $"\"{version.ToString(CultureInfo.InvariantCulture)}\"";
    }

    private static bool Matches(Ticket ticket, TicketRequest request) =>
        ticket.Subject == request.Subject
        && ticket.Priority == request.Priority
        && ticket.Escalated == request.Escalated
        && ticket.Category == request.Category;
}
