[Route("api/support-tickets")]
public sealed class SupportTicketsController : ControllerBase
{
    private readonly TicketDbContext _db;

    public SupportTicketsController(TicketDbContext db) => _db = db;

    [HttpPost]
    public async Task<ActionResult<TicketResponse>> Create(
        [FromBody] TicketRequest request,
        CancellationToken cancellationToken)
    {
        var ticket = new Ticket
        {
            Id = request.Id,
            Subject = request.Subject!,
            Priority = request.Priority,
            Escalated = request.Escalated,
            Category = request.Category!,
            Revision = 1
        };

        _db.Tickets.Add(ticket);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            // A retried POST with the same ID and contents is treated as successful.
            _db.Entry(ticket).State = EntityState.Detached;
            var existing = await _db.Tickets.AsNoTracking()
                .SingleOrDefaultAsync(t => t.Id == request.Id, cancellationToken);

            if (existing is null)
                throw;

            if (!SameContents(existing, request))
                return Conflict();

            SetEtag(existing.Revision);
            return CreatedAtAction(nameof(Get), new { id = existing.Id }, ToResponse(existing));
        }

        SetEtag(ticket.Revision);
        return CreatedAtAction(nameof(Get), new { id = ticket.Id }, ToResponse(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> Get(Guid id, CancellationToken cancellationToken)
    {
        var viewedAt = DateTime.UtcNow;

        // Increment atomically so simultaneous reads do not lose counter updates.
        var updated = await _db.Tickets
            .Where(t => t.Id == id)
            .ExecuteUpdateAsync(setters => setters
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, viewedAt), cancellationToken);

        if (updated == 0)
            return NotFound();

        var ticket = await _db.Tickets.AsNoTracking()
            .SingleAsync(t => t.Id == id, cancellationToken);

        SetEtag(ticket.Revision);
        return Ok(ToResponse(ticket));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> Update(
        Guid id,
        [FromBody] TicketRequest request,
        CancellationToken cancellationToken)
    {
        if (id != request.Id)
            return BadRequest("The body ID must match the route ID.");

        var ticket = await _db.Tickets.SingleOrDefaultAsync(t => t.Id == id, cancellationToken);
        if (ticket is null)
            return NotFound();

        if (!TryGetExpectedRevision(out var expectedRevision))
            expectedRevision = ticket.Revision;

        if (expectedRevision != ticket.Revision)
            return StatusCode(StatusCodes.Status412PreconditionFailed);

        var currentRevision = ticket.Revision;
        var changed = await _db.Tickets
            .Where(t => t.Id == id && t.Revision == currentRevision)
            .ExecuteUpdateAsync(setters => setters
                .SetProperty(t => t.Subject, request.Subject!)
                .SetProperty(t => t.Priority, request.Priority)
                .SetProperty(t => t.Escalated, request.Escalated)
                .SetProperty(t => t.Category, request.Category!)
                .SetProperty(t => t.Revision, t => t.Revision + 1), cancellationToken);

        if (changed == 0)
            return StatusCode(StatusCodes.Status412PreconditionFailed);

        ticket.Subject = request.Subject!;
        ticket.Priority = request.Priority;
        ticket.Escalated = request.Escalated;
        ticket.Category = request.Category!;
        ticket.Revision++;

        SetEtag(ticket.Revision);
        return Ok(ToResponse(ticket));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken cancellationToken)
    {
        var ticket = await _db.Tickets.SingleOrDefaultAsync(t => t.Id == id, cancellationToken);
        if (ticket is null)
            return NotFound();

        if (TryGetExpectedRevision(out var expectedRevision) &&
            expectedRevision != ticket.Revision)
            return StatusCode(StatusCodes.Status412PreconditionFailed);

        var deleted = await _db.Tickets
            .Where(t => t.Id == id && t.Revision == ticket.Revision)
            .ExecuteDeleteAsync(cancellationToken);

        return deleted == 0
            ? StatusCode(StatusCodes.Status412PreconditionFailed)
            : NoContent();
    }

    private bool TryGetExpectedRevision(out int revision)
    {
        revision = 0;
        var value = Request.Headers.IfMatch.ToString().Trim();
        if (value.Length < 3 || value[0] != '"' || value[^1] != '"')
            return false;

        return int.TryParse(value[1..^1], out revision);
    }

    private void SetEtag(int revision) => Response.Headers.ETag = $"\"{revision}\"";

    private static bool SameContents(Ticket ticket, TicketRequest request) =>
        ticket.Subject == request.Subject &&
        ticket.Priority == request.Priority &&
        ticket.Escalated == request.Escalated &&
        ticket.Category == request.Category;

    private static TicketResponse ToResponse(Ticket ticket) =>
        new(ticket.Id, ticket.Subject, ticket.Priority, ticket.Escalated,
            ticket.Category, ticket.ViewCount, ticket.LastViewedAt);
}
