[ApiController]
[Route("api/support-tickets")]
public sealed class SupportTicketsController(TicketsDbContext db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create(
        [FromBody, Required] TicketRequest? body,
        CancellationToken cancellationToken)
    {
        if (!Valid(body))
            return ProblemResult(400, "Invalid ticket", "A non-empty id, subject, and category are required.");

        var request = Normalize(body!);
        var hash = TicketEtags.For(request);
        var ticket = new Ticket
        {
            Id = request.Id,
            Subject = request.Subject,
            Priority = request.Priority,
            Escalated = request.Escalated,
            Category = request.Category,
            ETag = hash,
            CreateHash = hash
        };

        db.Tickets.Add(ticket);
        try
        {
            await db.SaveChangesAsync(cancellationToken);
            Response.Headers.ETag = hash;
            return CreatedAtAction(nameof(Get), new { id = ticket.Id }, ToResponse(ticket));
        }
        catch (DbUpdateException exception) when (IsUniqueViolation(exception))
        {
            db.Entry(ticket).State = EntityState.Detached;

            var existing = await db.Tickets.IgnoreQueryFilters()
                .AsNoTracking()
                .SingleOrDefaultAsync(t => t.Id == request.Id, cancellationToken);

            if (existing is null)
                return ProblemResult(409, "Ticket conflict", "The ticket could not be created.");

            if (existing.DeletedAt is not null)
                return ProblemResult(410, "Ticket deleted", "This ticket id belongs to a deleted ticket.");

            if (!StringComparer.Ordinal.Equals(existing.CreateHash, hash))
                return ProblemResult(409, "Ticket conflict", "The id is already used by different ticket content.");

            Response.Headers.ETag = existing.ETag;
            return Ok(ToResponse(existing));
        }
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken cancellationToken)
    {
        var ticket = await db.Tickets.AsNoTracking()
            .SingleOrDefaultAsync(t => t.Id == id, cancellationToken);

        if (ticket is null)
        {
            var deleted = await db.Tickets.IgnoreQueryFilters().AsNoTracking()
                .AnyAsync(t => t.Id == id && t.DeletedAt != null, cancellationToken);
            return deleted
                ? ProblemResult(410, "Ticket deleted", "This ticket has been deleted.")
                : ProblemResult(404, "Ticket not found", "No ticket has this id.");
        }

        var etag = ticket.ETag;
        await db.Tickets.Where(t => t.InternalId == ticket.InternalId)
            .ExecuteUpdateAsync(update => update
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, DateTime.UtcNow), cancellationToken);

        Response.Headers.ETag = etag;
        if (MatchesIfNoneMatch(Request.Headers.IfNoneMatch, etag))
            return StatusCode(StatusCodes.Status304NotModified);

        return Ok(ToResponse(ticket));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(
        Guid id,
        [FromBody, Required] TicketRequest? body,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        CancellationToken cancellationToken)
    {
        if (!Valid(body) || body!.Id != id)
            return ProblemResult(400, "Invalid ticket", "The body must be valid and its id must match the route.");

        if (string.IsNullOrWhiteSpace(ifMatch))
            return ProblemResult(428, "Precondition required", "The If-Match header is required.");

        var request = Normalize(body);
        var newETag = TicketEtags.For(request);

        var ticket = await db.Tickets.AsNoTracking()
            .SingleOrDefaultAsync(t => t.Id == id, cancellationToken);
        if (ticket is null)
            return await MissingOrDeleted(id, cancellationToken);

        if (StringComparer.Ordinal.Equals(ticket.ETag, newETag))
        {
            Response.Headers.ETag = ticket.ETag;
            return NoContent();
        }

        if (!MatchesIfMatch(ifMatch, ticket.ETag))
        {
            Response.Headers.ETag = ticket.ETag;
            return ProblemResult(412, "Precondition failed", "The ticket has changed.");
        }

        try
        {
            var updated = await db.Tickets
                .Where(t => t.InternalId == ticket.InternalId && t.ETag == ticket.ETag)
                .ExecuteUpdateAsync(update => update
                    .SetProperty(t => t.Subject, request.Subject)
                    .SetProperty(t => t.Priority, request.Priority)
