internal static class TicketEtags
{
    public static string For(SupportTicketResponse ticket)
    {
        var canonical = string.Concat(
            "{\"id\":", Quote(ticket.Id.ToString("D").ToLowerInvariant()),
            ",\"subject\":", Quote(ticket.Subject.Normalize(NormalizationForm.FormC)),
            ",\"priority\":", ticket.Priority.ToString(CultureInfo.InvariantCulture),
            ",\"escalated\":", ticket.Escalated ? "true" : "false",
            ",\"category\":", Quote(ticket.Category.Normalize(NormalizationForm.FormC)),
            "}");

        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return "\"" + Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    private static string Quote(string value)
    {
        var builder = new StringBuilder(value.Length + 2).Append('"');
        foreach (var c in value)
        {
            switch (c)
            {
                case '"': builder.Append("\\\""); break;
                case '\\': builder.Append("\\\\"); break;
                case '\b': builder.Append("\\b"); break;
                case '\f': builder.Append("\\f"); break;
                case '\n': builder.Append("\\n"); break;
                case '\r': builder.Append("\\r"); break;
                case '\t': builder.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        builder.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else
                        builder.Append(c);
                    break;
            }
        }

        return builder.Append('"').ToString();
    }
}
