    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<ShipmentResponse>> Update(
        Guid id,
        [FromBody] ShipmentRequest request,
        CancellationToken cancellationToken)
    {
        var consignment = await _db.Consignments.FindAsync([id], cancellationToken);
        if (consignment is null)
            return NotFound();

        var depot = await _db.Depots.FindAsync([request.WarehouseId], cancellationToken);
        if (depot is null)
            return NotFound();

        consignment.WarehouseId = request.WarehouseId;
        consignment.Reference = request.Reference;
        consignment.WeightKg = request.WeightKg;
        consignment.Fragile = request.Fragile;
        depot.LastAuditAt = DateTime.UtcNow;

        await _db.SaveChangesAsync(cancellationToken);
        return Ok(ToResponse(consignment));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(
        Guid id,
        CancellationToken cancellationToken)
    {
        var consignment = await _db.Consignments.FindAsync([id], cancellationToken);
        if (consignment is null)
            return NotFound();

        var depot = await _db.Depots.FindAsync([consignment.WarehouseId], cancellationToken);
        if (depot is not null)
            depot.LastAuditAt = DateTime.UtcNow;

        _db.Consignments.Remove(consignment);
        await _db.SaveChangesAsync(cancellationToken);
        return NoContent();
    }

    internal static ShipmentResponse ToResponse(Consignment consignment) =>
        new(
            consignment.Id,
            consignment.WarehouseId,
            consignment.Reference,
            consignment.WeightKg,
            consignment.Fragile);
}
