[ApiController]
[Route("api/support-tickets")]
public sealed class SupportTicketsController(TicketDbContext db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create(
        [FromBody, BindRequired] TicketRequest? request,
        CancellationToken cancellationToken)
    {
        if (!IsValid(request))
            return ProblemResult(400, "Invalid support ticket.");

        var ticket = new Ticket
        {
            Id = request!.Id!.Value,
            Subject = Normalize(request.Subject!),
            Priority = request.Priority,
            Escalated = request.Escalated,
            Category = Normalize(request.Category!)
        };

        ticket.ETag = TicketHash(ticket);
        ticket.CreateHash = ticket.ETag;

        db.Tickets.Add(ticket);
        try
        {
            await db.SaveChangesAsync(cancellationToken);
            SetETag(ticket.ETag);
            return CreatedAtAction(nameof(GetById), new { id = ticket.Id },
                ToResponse(ticket));
        }
        catch (DbUpdateException exception) when (IsUniqueViolation(exception))
        {
            db.Entry(ticket).State = EntityState.Detached;

            var existing = await db.Tickets.IgnoreQueryFilters()
                .SingleOrDefaultAsync(t => t.Id == ticket.Id, cancellationToken);

            if (existing is null)
                return ProblemResult(409, "The ticket could not be created.");

            if (existing.DeletedAt is not null)
                return ProblemResult(410, "This ticket was deleted.");

            if (existing.CreateHash != ticket.CreateHash)
                return ProblemResult(409, "A ticket with this id already exists.");

            SetETag(existing.ETag);
            return Ok(ToResponse(existing));
        }
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> GetById(Guid id, CancellationToken cancellationToken)
    {
        var ticket = await db.Tickets.SingleOrDefaultAsync(t => t.Id == id, cancellationToken);
        if (ticket is null)
        {
            var deleted = await db.Tickets.IgnoreQueryFilters()
                .AnyAsync(t => t.Id == id && t.DeletedAt != null, cancellationToken);
            return deleted
                ? ProblemResult(410, "This ticket was deleted.")
                : ProblemResult(404, "Ticket not found.");
        }

        var ifNoneMatch = Request.Headers.IfNoneMatch;
        if (ifNoneMatch.Any(value => ETagMatches(value, ticket.ETag)))
        {
            SetETag(ticket.ETag);
            return StatusCode(StatusCodes.Status304NotModified);
        }

        var now = DateTime.UtcNow;
        await db.Tickets.Where(t => t.TicketId == ticket.TicketId && t.DeletedAt == null)
            .ExecuteUpdateAsync(update => update
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, now), cancellationToken);

        var stillLive = await db.Tickets.AnyAsync(t => t.TicketId == ticket.TicketId, cancellationToken);
        if (!stillLive)
            return ProblemResult(410, "This ticket was deleted.");

        SetETag(ticket.ETag);
        return Ok(ToResponse(ticket));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(
        Guid id,
        [FromBody, BindRequired] TicketRequest? request,
        [FromHeader(Name = "If-Match"), BindRequired] string ifMatch,
        CancellationToken cancellationToken)
    {
        if (!IsValid(request) || request!.Id != id)
            return ProblemResult(400, "Invalid support ticket or id mismatch.");

        if (string.IsNullOrWhiteSpace(ifMatch))
            return ProblemResult(428, "The If-Match header is required.");

        var normalized = new Ticket
        {
            Id = id,
            Subject = Normalize(request.Subject!),
            Priority = request.Priority,
            Escalated = request.Escalated,
            Category = Normalize(request.Category!)
        };
        var newETag = TicketHash(normalized);

        for (var attempt = 0; attempt < 3; attempt++)
        {
            var current = await db.Tickets.SingleOrDefaultAsync(t => t.Id == id, cancellationToken);
            if (current is null)
            {
                var deleted = await db.Tickets.IgnoreQueryFilters()
                    .AnyAsync(t => t.Id == id && t.DeletedAt != null, cancellationToken);
                return deleted
                    ? ProblemResult(410, "This ticket was deleted.")
                    : ProblemResult(404, "Ticket not found.");
            }

            if (current.ETag == newETag)
            {
                SetETag(current.ETag);
                return NoContent();
            }

            if (!IfMatchMatches(ifMatch, current.ETag))
            {
                SetETag(current.ETag);
                return ProblemResult(412, "The ticket has changed.");
            }

            current.Subject = normalized.Subject;
            current.Priority = normalized.Priority;
            current.Escalated = normalized.Escalated;
            current.Category = normalized.Category;
            current.ETag = newETag;

            try
            {
                await db.SaveChangesAsync(cancellationToken);
                SetETag(newETag);
                return NoContent();
            }
            catch (DbUpdateConcurrencyException)
            {
                db.ChangeTracker.Clear();
            }
            catch (DbUpdateException exception) when (IsSqliteBusy(exception))
            {
                db.ChangeTracker.Clear();
            }
        }

        var latest = await db.Tickets.SingleOrDefaultAsync(t => t.Id == id, cancellationToken);
        if (latest is null)
        {
            var deleted = await db.Tickets.IgnoreQueryFilters()
                .AnyAsync(t => t.Id == id && t.DeletedAt != null, cancellationToken);
            return deleted
                ? ProblemResult(410, "This ticket was deleted.")
                : ProblemResult(404, "Ticket not found.");
        }

        SetETag(latest.ETag);
        return ProblemResult(412, "The ticket has changed.");
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [FromHeader(Name = "If-Match"), BindRequired] string ifMatch,
        CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return ProblemResult(428, "The If-Match header is required.");

        var current = await db.Tickets.SingleOrDefaultAsync(t => t.Id == id, cancellationToken);
        if (current is null)
            return NoContent();

        if (!IfMatchMatches(ifMatch, current.ETag))
        {
            SetETag(current.ETag);
            return ProblemResult(412, "The ticket has changed.");
        }

        current.DeletedAt = DateTime.UtcNow;
        try
        {
            await db.SaveChangesAsync(cancellationToken);
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var latest = await db.Tickets.SingleOrDefaultAsync(t => t.Id == id, cancellationToken);
            if (latest is null)
                return NoContent();

            SetETag(latest.ETag);
            return ProblemResult(412, "The ticket has changed.");
        }
        catch (DbUpdateException exception) when (IsSqliteBusy(exception))
        {
            db.ChangeTracker.Clear();
            var latest = await db.Tickets.SingleOrDefaultAsync(t => t.Id == id, cancellationToken);
            if (latest is null)
                return NoContent();

            SetETag(latest.ETag);
            return ProblemResult(412, "The ticket has changed.");
        }
    }

    private IActionResult ProblemResult(int status, string detail) =>
        Problem(statusCode: status, title: detail, detail: detail,
            type: "about:blank", instance: HttpContext.Request.Path);

    private void SetETag(string etag) => Response.Headers.ETag = etag;

    private static bool IsValid(TicketRequest? request) =>
        request?.Id is not null &&
        !string.IsNullOrWhiteSpace(request.Subject) &&
        !string.IsNullOrWhiteSpace(request.Category) &&
        request.Subject.Length <= 200 &&
        request.Category.Length <= 100;

    private static TicketResponse ToResponse(Ticket ticket) =>
        new(ticket.Id, ticket.Subject, ticket.Priority, ticket.Escalated, ticket.Category);

    private static string Normalize(string value) => value.Normalize(NormalizationForm.FormC);

    private static string TicketHash(Ticket ticket)
    {
        var json = new StringBuilder()
            .Append("{\"id\":\"").Append(ticket.Id.ToString("D").ToLowerInvariant())
            .Append("\",\"subject\":\"").Append(Escape(ticket.Subject))
            .Append("\",\"priority\":").Append(ticket.Priority.ToString(CultureInfo.InvariantCulture))
            .Append(",\"escalated\":").Append(ticket.Escalated ? "true" : "false")
            .Append(",\"category\":\"").Append(Escape(ticket.Category)).Append("\"}")
            .ToString();

        var digest = SHA256.HashData(Encoding.UTF8.GetBytes(json));
        return "\"" + Convert.ToBase64String(digest).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    private static string Escape(string value)
    {
        var result = new StringBuilder();
        foreach (var c in value)
        {
            switch (c)
            {
                case '"': result.Append("\\\""); break;
                case '\\': result.Append("\\\\"); break;
                case '\b': result.Append("\\b"); break;
                case '\f': result.Append("\\f"); break;
                case '\n': result.Append("\\n"); break;
                case '\r': result.Append("\\r"); break;
                case '\t': result.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        result.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else
                        result.Append(c);
                    break;
            }
        }
        return result.ToString();
    }

    private static bool IfMatchMatches(string header, string currentETag) =>
        header.Split(',').Select(v => v.Trim()).Any(v => v == "*" || ETagMatches(v, currentETag));

    private static bool ETagMatches(string candidate, string currentETag) =>
        candidate.Trim().Equals(currentETag, StringComparison.Ordinal);

    private static bool IsUniqueViolation(DbUpdateException exception) =>
        exception.InnerException is SqliteException sqlite && sqlite.SqliteErrorCode == 19;

    private static bool IsSqliteBusy(DbUpdateException exception) =>
        exception.InnerException is SqliteException sqlite &&
        (sqlite.SqliteErrorCode == 5 || sqlite.SqliteErrorCode == 6);
}
