            Response.Headers.ETag = ticket.ETag;
            return CreatedAtAction(nameof(Get), new { id = ticket.Id }, response);
        }
        catch (DbUpdateException exception) when (IsUniqueViolation(exception))
        {
            db.Entry(ticket).State = EntityState.Detached;

            var existing = await db.Tickets.IgnoreQueryFilters()
                .AsNoTracking()
                .SingleOrDefaultAsync(t => t.Id == response.Id, cancellationToken);

            if (existing is null)
                return ConflictProblem();

            if (existing.DeletedAt is not null)
                return GoneProblem();

            if (!string.Equals(existing.CreateHash, hash, StringComparison.Ordinal))
                return ConflictProblem();

            Response.Headers.ETag = existing.ETag;
