internal static class TicketEtags
{
    public static string Hash(TicketResponse ticket)
    {
        var canonical = new StringBuilder()
            .Append("{\"id\":").Append(Quote(ticket.Id.ToString("D").ToLowerInvariant()))
            .Append(",\"subject\":").Append(Quote(ticket.Subject.Normalize(NormalizationForm.FormC)))
            .Append(",\"priority\":").Append(ticket.Priority.ToString(CultureInfo.InvariantCulture))
            .Append(",\"escalated\":").Append(ticket.Escalated ? "true" : "false")
            .Append(",\"category\":").Append(Quote(ticket.Category.Normalize(NormalizationForm.FormC)))
            .Append('}');

        var digest = SHA256.HashData(Encoding.UTF8.GetBytes(canonical.ToString()));
        return "\"" + Convert.ToBase64String(digest).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    private static string Quote(string value)
    {
        var result = new StringBuilder().Append('"');
        foreach (var c in value)
        {
            switch (c)
            {
                case '"': result.Append("\\\""); break;
                case '\\': result.Append("\\\\"); break;
                case '\b': result.Append("\\b"); break;
                case '\f': result.Append("\\f"); break;
                case '\n': result.Append("\\n"); break;
                case '\r': result.Append("\\r"); break;
                case '\t': result.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        result.Append("\\u00").Append(((int)c).ToString("x2", CultureInfo.InvariantCulture));
                    else
                        result.Append(c);
                    break;
            }
        }
        return result.Append('"').ToString();
    }
}
