public sealed class ShipmentsController : ControllerBase
{
    private readonly WarehouseApiDbContext _db;

    public ShipmentsController(WarehouseApiDbContext db)
    {
        _db = db;
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<ShipmentResponse>> GetById(
        Guid id,
        CancellationToken cancellationToken)
    {
        var shipment = await _db.Consignments
            .AsNoTracking()
            .FirstOrDefaultAsync(item => item.Id == id, cancellationToken);

        return shipment is null ? NotFound() : Ok(ToResponse(shipment));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<ShipmentResponse>> Update(
        Guid id,
        [FromBody] ShipmentRequest request,
        CancellationToken cancellationToken)
    {
        var shipment = await _db.Consignments.FindAsync(new object[] { id }, cancellationToken);
        if (shipment is null)
        {
            return NotFound();
        }

        var warehouseExists = await _db.Depots
            .AnyAsync(depot => depot.Id == request.WarehouseId, cancellationToken);

        if (!warehouseExists)
        {
            return NotFound();
        }

        shipment.WarehouseId = request.WarehouseId;
        shipment.Reference = request.Reference;
        shipment.WeightKg = request.WeightKg;
        shipment.Fragile = request.Fragile;

        await _db.SaveChangesAsync(cancellationToken);
        return Ok(ToResponse(shipment));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken cancellationToken)
    {
        var shipment = await _db.Consignments.FindAsync(new object[] { id }, cancellationToken);
        if (shipment is null)
        {
            return NotFound();
        }

        _db.Consignments.Remove(shipment);
        await _db.SaveChangesAsync(cancellationToken);
        return NoContent();
    }

    private static ShipmentResponse ToResponse(Consignment shipment) => new()
    {
        Id = shipment.Id,
        WarehouseId = shipment.WarehouseId,
        Reference = shipment.Reference,
        WeightKg = shipment.WeightKg,
        Fragile = shipment.Fragile
    };
}
