[Microsoft.AspNetCore.Mvc.Route("api")]
public sealed class ShipmentsController : Microsoft.AspNetCore.Mvc.ControllerBase
{
    private readonly LogisticsDbContext _db;

    public ShipmentsController(LogisticsDbContext db) => _db = db;

    [Microsoft.AspNetCore.Mvc.HttpPost("warehouses/{warehouseId:guid}/shipments")]
    public async Task<Microsoft.AspNetCore.Mvc.ActionResult<Consignment>> Create(
        Guid warehouseId,
        [Microsoft.AspNetCore.Mvc.FromBody] CreateShipmentRequest request,
        CancellationToken cancellationToken)
    {
        var warehouse = await _db.Depots
            .SingleOrDefaultAsync(depot => depot.Id == warehouseId, cancellationToken);

        if (warehouse is null)
            return NotFound();

        var shipment = new Consignment
        {
            Id = Guid.NewGuid(),
            WarehouseId = warehouseId,
            Reference = request.Reference,
            WeightKg = request.WeightKg,
            Fragile = request.Fragile
        };

        warehouse.LastAuditAt = DateTime.UtcNow;
        _db.Consignments.Add(shipment);
        await _db.SaveChangesAsync(cancellationToken);

        return CreatedAtAction(nameof(Get), new { id = shipment.Id }, shipment);
    }

    [Microsoft.AspNetCore.Mvc.HttpGet("shipments/{id:guid}")]
    public async Task<Microsoft.AspNetCore.Mvc.ActionResult<Consignment>> Get(
        Guid id,
        CancellationToken cancellationToken)
    {
        var shipment = await _db.Consignments
            .Include(consignment => consignment.Depot)
            .SingleOrDefaultAsync(consignment => consignment.Id == id, cancellationToken);

        if (shipment is null)
            return NotFound();

        shipment.DownloadCount++;
        await _db.SaveChangesAsync(cancellationToken);

        return Ok(shipment);
    }

    [Microsoft.AspNetCore.Mvc.HttpPut("shipments/{id:guid}")]
    public async Task<Microsoft.AspNetCore.Mvc.IActionResult> Update(
        Guid id,
        [Microsoft.AspNetCore.Mvc.FromBody] UpdateShipmentRequest request,
        CancellationToken cancellationToken)
    {
        var shipment = await _db.Consignments
            .SingleOrDefaultAsync(consignment => consignment.Id == id, cancellationToken);

        if (shipment is null)
            return NotFound();

        var warehouse = await _db.Depots
            .SingleOrDefaultAsync(depot => depot.Id == request.WarehouseId, cancellationToken);

        if (warehouse is null)
            return NotFound();

        if (shipment.WarehouseId != warehouse.Id)
        {
            var previousWarehouse = await _db.Depots
                .SingleOrDefaultAsync(
                    depot => depot.Id == shipment.WarehouseId,
                    cancellationToken);

            if (previousWarehouse is not null)
                previousWarehouse.LastAuditAt = DateTime.UtcNow;
        }

        shipment.WarehouseId = warehouse.Id;
        shipment.Reference = request.Reference;
        shipment.WeightKg = request.WeightKg;
        shipment.Fragile = request.Fragile;
        warehouse.LastAuditAt = DateTime.UtcNow;

        await _db.SaveChangesAsync(cancellationToken);
        return NoContent();
    }

    [Microsoft.AspNetCore.Mvc.HttpDelete("shipments/{id:guid}")]
    public async Task<Microsoft.AspNetCore.Mvc.IActionResult> Delete(
        Guid id,
        CancellationToken cancellationToken)
    {
        var shipment = await _db.Consignments
            .SingleOrDefaultAsync(consignment => consignment.Id == id, cancellationToken);

        if (shipment is null)
            return NotFound();

        var warehouse = await _db.Depots
            .SingleOrDefaultAsync(depot => depot.Id == shipment.WarehouseId, cancellationToken);

        if (warehouse is not null)
            warehouse.LastAuditAt = DateTime.UtcNow;

        _db.Consignments.Remove(shipment);
        await _db.SaveChangesAsync(cancellationToken);
        return NoContent();
    }
}
