The API below uses the client-supplied GUID as a stable create key: retrying a `POST` with the same ID and payload returns the existing resource, while reusing that ID with different data returns `409 Conflict`. Updates use an EF Core concurrency token to detect competing edits. `LastAuditAt` is set by the server, and `DownloadCount` is preserved by updates.

```csharp
using Microsoft.EntityFrameworkCore;

public sealed class Depot
{
    public Guid Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public int CapacityCubicMeters { get; set; }
    public DateTime? LastAuditAt { get; set; }

    // Incremented on each update to detect concurrent edits with SQLite.
    public int Version { get; set; }
}

public sealed class Consignment
{
    public Guid Id { get; set; }
    public Guid WarehouseId { get; set; }
    public string Reference { get; set; } = string.Empty;
    public decimal WeightKg { get; set; }
    public bool Fragile { get; set; }
    public int DownloadCount { get; set; }

    // Incremented on each update to detect concurrent edits with SQLite.
    public int Version { get; set; }

    public Depot? Warehouse { get; set; }
}

public sealed class WarehouseDbContext : DbContext
{
    public WarehouseDbContext(DbContextOptions<WarehouseDbContext> options)
        : base(options)
    {
    }

    public DbSet<Depot> Depots => Set<Depot>();
    public DbSet<Consignment> Consignments => Set<Consignment>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Depot>(entity =>
        {
            entity.HasKey(x => x.Id);
            entity.Property(x => x.Code).IsRequired();
            entity.Property(x => x.Version).IsConcurrencyToken();
        });

        modelBuilder.Entity<Consignment>(entity =>
        {
            entity.HasKey(x => x.Id);
            entity.Property(x => x.Reference).IsRequired();
            entity.Property(x => x.WeightKg).HasPrecision(18, 3);
            entity.Property(x => x.Version).IsConcurrencyToken();
            entity.HasOne(x => x.Warehouse)
                .WithMany()
                .HasForeignKey(x => x.WarehouseId)
                .OnDelete(DeleteBehavior.Cascade);
        });
    }
}

public static class AppSetup
{
    public static void ConfigureServices(
        IServiceCollection services,
        string sqliteConnectionString)
    {
        services.AddDbContext<WarehouseDbContext>(options =>
            options.UseSqlite(sqliteConnectionString));

        services.AddControllers();
    }
}
