```csharp
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/warehouses")]
public sealed class WarehousesController : ControllerBase
{
    private readonly WarehouseDbContext _db;

    public WarehousesController(WarehouseDbContext db) => _db = db;

    [HttpPost]
    public async Task<ActionResult<WarehouseResponse>> Create(
        [FromBody] WarehouseRequest request,
        CancellationToken cancellationToken)
    {
        if (request.Id == Guid.Empty)
            return BadRequest("A non-empty id is required.");

        if (request.CapacityCubicMeters < 0)
            return BadRequest("Capacity must not be negative.");

        var existing = await _db.Depots.FindAsync(
            new object[] { request.Id }, cancellationToken);

        if (existing is not null)
        {
            if (existing.Code != request.Code ||
                existing.CapacityCubicMeters != request.CapacityCubicMeters)
                return Conflict("This id already exists with different values.");

            return Ok(ToResponse(existing));
        }

        var depot = new Depot
        {
            Id = request.Id,
            Code = request.Code,
            CapacityCubicMeters = request.CapacityCubicMeters,
            LastAuditAt = DateTime.UtcNow
        };

        _db.Depots.Add(depot);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            // Another request may have created the same id concurrently.
            _db.Entry(depot).State = EntityState.Detached;
            existing = await _db.Depots.FindAsync(
                new object[] { request.Id }, cancellationToken);

            if (existing is null)
                throw;

            if (existing.Code != request.Code ||
                existing.CapacityCubicMeters != request.CapacityCubicMeters)
                return Conflict("This id already exists with different values.");

            return Ok(ToResponse(existing));
        }

        return CreatedAtAction(nameof(Get), new { id = depot.Id }, ToResponse(depot));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<WarehouseResponse>> Get(
        Guid id,
        CancellationToken cancellationToken)
    {
        var depot = await _db.Depots.FindAsync(new object[] { id }, cancellationToken);
        return depot is null ? NotFound() : Ok(ToResponse(depot));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<WarehouseResponse>> Update(
        Guid id,
        [FromBody] WarehouseRequest request,
        CancellationToken cancellationToken)
    {
        if (request.Id != id)
            return BadRequest("The route id must match the body id.");

        if (request.CapacityCubicMeters < 0)
            return BadRequest("Capacity must not be negative.");

        var depot = await _db.Depots.FindAsync(new object[] { id }, cancellationToken);
        if (depot is null)
            return NotFound();

        depot.Code = request.Code;
        depot.CapacityCubicMeters = request.CapacityCubicMeters;
        depot.LastAuditAt = DateTime.UtcNow;
        depot.Version++;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict("The warehouse was changed by another request.");
        }

        return Ok(ToResponse(depot));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken cancellationToken)
    {
        var depot = await _db.Depots.FindAsync(new object[] { id }, cancellationToken);
        if (depot is null)
            return NotFound();

        _db.Depots.Remove(depot);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict("The warehouse was changed by another request.");
        }

        return NoContent();
    }

    private static WarehouseResponse ToResponse(Depot depot) =>
        new(depot.Id, depot.Code, depot.CapacityCubicMeters);
}

public sealed record WarehouseRequest(
    Guid Id,
    string Code,
    int CapacityCubicMeters);

public sealed record WarehouseResponse(
    Guid Id,
    string Code,
    int CapacityCubicMeters);
