public sealed class WarehousesController : ControllerBase
{
    private readonly LogisticsDbContext _db;

    public WarehousesController(LogisticsDbContext db) => _db = db;

    [HttpPost]
    public async Task<IActionResult> Create(
        [FromBody] WarehouseRequest request,
        CancellationToken cancellationToken)
    {
        if (request.Id == Guid.Empty || string.IsNullOrWhiteSpace(request.Code) ||
            request.CapacityCubicMeters < 0)
        {
            return BadRequest();
        }

        var existing = await _db.Depots.FindAsync(
            new object[] { request.Id }, cancellationToken);

        // Repeating the same POST is safe when the client retries after a timeout.
        if (existing is not null)
        {
            if (existing.Code != request.Code ||
                existing.CapacityCubicMeters != request.CapacityCubicMeters)
            {
                return Conflict();
            }

            return Ok(ToResponse(existing));
        }

        var depot = new Depot
        {
            Id = request.Id,
            Code = request.Code,
            CapacityCubicMeters = request.CapacityCubicMeters,
            LastAuditAt = DateTime.UtcNow
        };

        _db.Depots.Add(depot);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            // Another request may have created this ID concurrently.
            _db.Entry(depot).State = EntityState.Detached;
            existing = await _db.Depots.AsNoTracking()
                .SingleOrDefaultAsync(x => x.Id == request.Id, cancellationToken);

            if (existing is not null &&
                existing.Code == request.Code &&
                existing.CapacityCubicMeters == request.CapacityCubicMeters)
            {
                return Ok(ToResponse(existing));
            }

            return Conflict();
        }

        return CreatedAtAction(nameof(Get), new { id = depot.Id }, ToResponse(depot));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken cancellationToken)
    {
        var depot = await _db.Depots.AsNoTracking()
            .SingleOrDefaultAsync(x => x.Id == id, cancellationToken);

        return depot is null ? NotFound() : Ok(ToResponse(depot));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(
        Guid id,
        [FromBody] WarehouseRequest request,
        CancellationToken cancellationToken)
    {
        if (request.Id != id || string.IsNullOrWhiteSpace(request.Code) ||
            request.CapacityCubicMeters < 0)
        {
            return BadRequest();
        }

        var depot = await _db.Depots.SingleOrDefaultAsync(
            x => x.Id == id, cancellationToken);

        if (depot is null)
        {
            return NotFound();
        }

        depot.Code = request.Code;
        depot.CapacityCubicMeters = request.CapacityCubicMeters;
        depot.LastAuditAt = DateTime.UtcNow;
        depot.Version++;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }

        return Ok(ToResponse(depot));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken cancellationToken)
    {
        var depot = await _db.Depots.SingleOrDefaultAsync(
            x => x.Id == id, cancellationToken);

        if (depot is null)
        {
            return NotFound();
        }

        _db.Depots.Remove(depot);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }
        catch (DbUpdateException)
        {
            // The warehouse cannot be deleted while it still has shipments.
            return Conflict();
        }

        return NoContent();
    }

    internal static WarehouseResponse ToResponse(Depot depot) =>
        new(depot.Id, depot.Code, depot.CapacityCubicMeters);
}

public sealed record WarehouseRequest(
    Guid Id,
    string Code,
    int CapacityCubicMeters);

public sealed record WarehouseResponse(
    Guid Id,
    string Code,
    int CapacityCubicMeters);
