using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api")]
public sealed class ShipmentsController : ControllerBase
{
    private readonly LogisticsDbContext _db;

    public ShipmentsController(LogisticsDbContext db) => _db = db;

    [HttpPost("warehouses/{warehouseId:guid}/shipments")]
    public async Task<IActionResult> Create(
        Guid warehouseId,
        [FromBody] ShipmentRequest request,
        CancellationToken cancellationToken)
    {
        if (request.Id == Guid.Empty ||
            request.WarehouseId != warehouseId ||
            string.IsNullOrWhiteSpace(request.Reference) ||
            request.WeightKg < 0)
        {
            return BadRequest();
        }

        if (!await _db.Depots.AnyAsync(x => x.Id == warehouseId, cancellationToken))
        {
            return NotFound();
        }

        var existing = await _db.Consignments.FindAsync(
            new object[] { request.Id }, cancellationToken);

        if (existing is not null)
        {
            if (Matches(existing, request))
            {
                return Ok(ToResponse(existing));
            }

            return Conflict();
        }

        var consignment = new Consignment
        {
            Id = request.Id,
            WarehouseId = warehouseId,
            Reference = request.Reference,
            WeightKg = request.WeightKg,
            Fragile = request.Fragile
        };

        _db.Consignments.Add(consignment);
        var depot = await _db.Depots.SingleAsync(
            x => x.Id == warehouseId, cancellationToken);
        depot.LastAuditAt = DateTime.UtcNow;
        depot.Version++;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }
        catch (DbUpdateException)
        {
            // Handle a concurrent retry that inserted the same shipment ID.
            _db.ChangeTracker.Clear();
            existing = await _db.Consignments.AsNoTracking()
                .SingleOrDefaultAsync(x => x.Id == request.Id, cancellationToken);

            if (existing is not null && Matches(existing, request))
            {
                return Ok(ToResponse(existing));
            }

            return Conflict();
        }

        return CreatedAtAction(
            nameof(Get), new { id = consignment.Id }, ToResponse(consignment));
    }

    [HttpGet("shipments/{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken cancellationToken)
    {
        var shipment = await _db.Consignments.AsNoTracking()
            .SingleOrDefaultAsync(x => x.Id == id, cancellationToken);

        return shipment is null ? NotFound() : Ok(ToResponse(shipment));
    }

    [HttpPut("shipments/{id:guid}")]
    public async Task<IActionResult> Update(
        Guid id,
        [FromBody] ShipmentRequest request,
        CancellationToken cancellationToken)
    {
        if (request.Id != id ||
            string.IsNullOrWhiteSpace(request.Reference) ||
            request.WeightKg < 0)
        {
            return BadRequest();
        }

        var shipment = await _db.Consignments.SingleOrDefaultAsync(
            x => x.Id == id, cancellationToken);

        if (shipment is null)
        {
            return NotFound();
        }

        if (!await _db.Depots.AnyAsync(
                x => x.Id == request.WarehouseId, cancellationToken))
        {
            return BadRequest();
        }

        var oldWarehouseId = shipment.WarehouseId;
        shipment.WarehouseId = request.WarehouseId;
        shipment.Reference = request.Reference;
        shipment.WeightKg = request.WeightKg;
        shipment.Fragile = request.Fragile;
        shipment.Version++;

        var affectedWarehouses = await _db.Depots
            .Where(x => x.Id == oldWarehouseId || x.Id == request.WarehouseId)
            .ToListAsync(cancellationToken);

        foreach (var depot in affectedWarehouses)
        {
            depot.LastAuditAt = DateTime.UtcNow;
            depot.Version++;
        }

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }

        return Ok(ToResponse(shipment));
    }

    [HttpDelete("shipments/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken cancellationToken)
    {
        var shipment = await _db.Consignments.SingleOrDefaultAsync(
            x => x.Id == id, cancellationToken);

        if (shipment is null)
        {
            return NotFound();
        }

        var depot = await _db.Depots.SingleOrDefaultAsync(
            x => x.Id == shipment.WarehouseId, cancellationToken);

        if (depot is not null)
        {
            depot.LastAuditAt = DateTime.UtcNow;
            depot.Version++;
        }

        _db.Consignments.Remove(shipment);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }

        return NoContent();
    }

    private static bool Matches(Consignment entity, ShipmentRequest request) =>
        entity.WarehouseId == request.WarehouseId &&
        entity.Reference == request.Reference &&
        entity.WeightKg == request.WeightKg &&
        entity.Fragile == request.Fragile;

    private static ShipmentResponse ToResponse(Consignment shipment) =>
        new(
            shipment.Id,
            shipment.WarehouseId,
            shipment.Reference,
            shipment.WeightKg,
            shipment.Fragile);

    private sealed record ShipmentResponse(
        Guid Id,
        Guid WarehouseId,
        string Reference,
        decimal WeightKg,
        bool Fragile);
}

public sealed record ShipmentRequest(
    Guid Id,
    Guid WarehouseId,
    string Reference,
    decimal WeightKg,
    bool Fragile);
