[Microsoft.AspNetCore.Mvc.Route("api/warehouses")]
public sealed class WarehousesController : Microsoft.AspNetCore.Mvc.ControllerBase
{
    private readonly LogisticsDbContext _db;

    public WarehousesController(LogisticsDbContext db) => _db = db;

    [Microsoft.AspNetCore.Mvc.HttpPost]
    public async Task<Microsoft.AspNetCore.Mvc.IActionResult> Create(
        CreateDepotRequest request, CancellationToken cancellationToken)
    {
        if (request.CapacityCubicMeters < 0)
            return BadRequest("Capacity cannot be negative.");

        var id = request.Id == Guid.Empty ? Guid.NewGuid() : request.Id;
        var existing = await _db.Depots.FindAsync(new object[] { id }, cancellationToken);
        if (existing is not null)
        {
            if (existing.Code == request.Code &&
                existing.CapacityCubicMeters == request.CapacityCubicMeters)
                return Ok(existing);

            return Conflict();
        }

        var depot = new Depot
        {
            Id = id,
            Code = request.Code,
            CapacityCubicMeters = request.CapacityCubicMeters,
            LastAuditAt = DateTime.UtcNow
        };

        _db.Depots.Add(depot);
        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            return Conflict();
        }

        return CreatedAtAction(nameof(Get), new { id = depot.Id }, depot);
    }

    [Microsoft.AspNetCore.Mvc.HttpGet("{id:guid}")]
    public async Task<Microsoft.AspNetCore.Mvc.IActionResult> Get(
        Guid id, CancellationToken cancellationToken)
    {
        var depot = await _db.Depots.FindAsync(new object[] { id }, cancellationToken);
        return depot is null ? NotFound() : Ok(depot);
    }

    [Microsoft.AspNetCore.Mvc.HttpPut("{id:guid}")]
    public async Task<Microsoft.AspNetCore.Mvc.IActionResult> Update(
        Guid id, UpdateDepotRequest request, CancellationToken cancellationToken)
    {
        if (request.CapacityCubicMeters < 0)
            return BadRequest("Capacity cannot be negative.");

        var depot = await _db.Depots.FindAsync(new object[] { id }, cancellationToken);
        if (depot is null) return NotFound();

        depot.Code = request.Code;
