        Guid id, CancellationToken cancellationToken)
    {
        var consignment = await _db.Consignments.FindAsync(new object[] { id }, cancellationToken);
        if (consignment is null) return NotFound();

        // Persist the download counter atomically so simultaneous reads do not lose increments.
        var updated = await _db.Database.ExecuteSqlInterpolatedAsync(
            $"UPDATE Consignments SET DownloadCount = DownloadCount + 1 WHERE Id = {id}",
            cancellationToken);
        if (updated == 0) return NotFound();

        consignment.DownloadCount++;
        return Ok(consignment);
    }

