internal static class ApiSupport
{
    public static string Hash(string canonicalJson) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson)))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";

    public static string Normalize(string? value) =>
        (value ?? "").Normalize(NormalizationForm.FormC);

    public static string Quote(string value)
    {
        var result = new StringBuilder("\"");
        foreach (var c in Normalize(value))
        {
            switch (c)
            {
                case '"': result.Append("\\\""); break;
                case '\\': result.Append("\\\\"); break;
                case '\b': result.Append("\\b"); break;
                case '\f': result.Append("\\f"); break;
                case '\n': result.Append("\\n"); break;
                case '\r': result.Append("\\r"); break;
                case '\t': result.Append("\\t"); break;
                default:
                    if (c < 0x20) result.Append("\\u").Append(((int)c).ToString("x4"));
                    else result.Append(c);
                    break;
            }
        }
        return result.Append('"').ToString();
    }

    public static string WarehouseJson(WarehouseRequest value) =>
        "{\"id\":" + Quote(value.Id.ToString("D")) +
        ",\"code\":" + Quote(value.Code ?? "") +
        ",\"capacityCubicMeters\":" + value.CapacityCubicMeters.ToString(
            System.Globalization.CultureInfo.InvariantCulture) + "}";

    public static string ShipmentJson(ShipmentRequest value) =>
        "{\"id\":" + Quote(value.Id.ToString("D")) +
        ",\"warehouseId\":" + Quote(value.WarehouseId.ToString("D")) +
        ",\"reference\":" + Quote(value.Reference ?? "") +
        ",\"weightKg\":" + value.WeightKg.ToString(
            "G", System.Globalization.CultureInfo.InvariantCulture) +
        ",\"fragile\":" + (value.Fragile ? "true" : "false") + "}";

    public static WarehouseResponse ToResponse(Depot x) =>
        new(x.Id, x.Code, x.CapacityCubicMeters);

    public static ShipmentResponse ToResponse(Consignment x) =>
        new(x.Id, x.WarehouseId, x.Reference, x.WeightKg, x.Fragile);

    public static bool Valid(WarehouseRequest? x) =>
        x is not null && x.Id != Guid.Empty &&
        !string.IsNullOrWhiteSpace(x.Code) && x.CapacityCubicMeters > 0;

    public static bool Valid(ShipmentRequest? x) =>
        x is not null && x.Id != Guid.Empty && x.WarehouseId != Guid.Empty &&
        !string.IsNullOrWhiteSpace(x.Reference) && x.WeightKg > 0;

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        return header.Split(',').Select(x => x.Trim()).Any(x =>
            x == "*" || x == etag || x.TrimStart().StartsWith("W/", StringComparison.Ordinal)
                && x[2..].Trim() == etag);
    }

    public static ProblemDetails Problem(int status, string title, string detail) =>
        new() { Status = status, Title = title, Detail = detail };
}

[ApiController]
[Route("api/warehouses")]
public sealed class WarehousesController(WarehouseDbContext db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(WarehouseResponse), 201)]
    [ProducesResponseType(typeof(WarehouseResponse), 200)]
    [ProducesResponseType(typeof(ProblemDetails), 400, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 409, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    public async Task<IActionResult> Create(
        [FromBody, Required] WarehouseRequest? body,
        CancellationToken cancellationToken)
    {
        if (!ApiSupport.Valid(body))
            return BadRequest(ApiSupport.Problem(400, "Invalid request", "A valid id, code, and positive capacity are required."));

        var etag = ApiSupport.Hash(ApiSupport.WarehouseJson(body!));
        var entity = new Depot
        {
            Id = body!.Id,
            Code = ApiSupport.Normalize(body.Code),
            CapacityCubicMeters = body.CapacityCubicMeters,
            ETag = etag,
            CreateHash = etag
        };
        db.Depots.Add(entity);
        try
        {
            await db.SaveChangesAsync(cancellationToken);
            Response.Headers.ETag = etag;
            return CreatedAtAction(nameof(Get), new { id = entity.Id },
                ApiSupport.ToResponse(entity));
        }
        catch (DbUpdateException)
        {
            db.Entry(entity).State = EntityState.Detached;
            var existing = await db.Depots.IgnoreQueryFilters()
                .SingleOrDefaultAsync(x => x.Id == body.Id, cancellationToken);
            if (existing is null) throw;
            if (existing.DeletedAt is not null)
                return StatusCode(410, ApiSupport.Problem(410, "Gone", "This id belonged to a deleted warehouse."));
            if (existing.CreateHash != etag)
                return Conflict(ApiSupport.Problem(409, "Conflict", "This id was created with different content."));
            Response.Headers.ETag = existing.ETag;
            return Ok(ApiSupport.ToResponse(existing));
        }
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(WarehouseResponse), 200)]
    [ProducesResponseType(304)]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken cancellationToken)
    {
        var item = await db.Depots.SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (item is null) return await GoneOrNotFound(id, cancellationToken);
        Response.Headers.ETag = item.ETag;
        if (ApiSupport.Matches(Request.Headers.IfNoneMatch, item.ETag))
            return StatusCode(304);
        return Ok(ApiSupport.ToResponse(item));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 400, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 412, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 428, "application/problem+json")]
    public async Task<IActionResult> Update(
        Guid id,
        [FromBody, Required] WarehouseRequest? body,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        CancellationToken cancellationToken)
    {
        if (!ApiSupport.Valid(body) || body!.Id != id)
            return BadRequest(ApiSupport.Problem(400, "Invalid request", "The body must contain a valid warehouse with the route id."));
        if (string.IsNullOrWhiteSpace(ifMatch))
            return StatusCode(428, ApiSupport.Problem(428, "Precondition required", "If-Match is required."));

        var item = await db.Depots.SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (item is null) return await GoneOrNotFound(id, cancellationToken);
        var newTag = ApiSupport.Hash(ApiSupport.WarehouseJson(body));
        if (item.ETag == newTag) return NoContent();
        if (!ApiSupport.Matches(ifMatch, item.ETag))
        {
            Response.Headers.ETag = item.ETag;
            return StatusCode(412, ApiSupport.Problem(412, "Precondition failed", "The warehouse has changed."));
        }

        item.Code = ApiSupport.Normalize(body.Code);
        item.CapacityCubicMeters = body.CapacityCubicMeters;
