public sealed record WarehouseResponse(Guid Id, string Code, int CapacityCubicMeters);
public sealed record ShipmentResponse(Guid Id, Guid WarehouseId, string Reference, decimal WeightKg, bool Fragile);

internal static class ApiRepresentation
{
    public static WarehouseResponse ToResponse(Depot x) =>
        new(x.Id, x.Code, x.CapacityCubicMeters);

    public static ShipmentResponse ToResponse(Consignment x) =>
        new(x.Id, x.WarehouseId, x.Reference, x.WeightKg, x.Fragile);

    public static string WarehouseJson(Guid id, string code, int capacity) =>
        $"{{\"id\":\"{id.ToString("D").ToLowerInvariant()}\",\"code\":{Quote(code)},\"capacityCubicMeters\":{capacity.ToString(CultureInfo.InvariantCulture)}}}";

    public static string ShipmentJson(Guid id, Guid warehouseId, string reference, decimal weight, bool fragile) =>
        $"{{\"id\":\"{id.ToString("D").ToLowerInvariant()}\",\"warehouseId\":\"{warehouseId.ToString("D").ToLowerInvariant()}\",\"reference\":{Quote(reference)},\"weightKg\":{weight.ToString("G29", CultureInfo.InvariantCulture)},\"fragile\":{(fragile ? "true" : "false")}}}";

    public static string ETag(string canonicalJson)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson));
        return "\"" + Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    public static string Quote(string value)
    {
        var normalized = value.Normalize(NormalizationForm.FormC);
        var result = new StringBuilder("\"");
        foreach (var c in normalized)
        {
            switch (c)
            {
                case '"': result.Append("\\\""); break;
                case '\\': result.Append("\\\\"); break;
                case '\b': result.Append("\\b"); break;
                case '\f': result.Append("\\f"); break;
                case '\n': result.Append("\\n"); break;
                case '\r': result.Append("\\r"); break;
                case '\t': result.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        result.Append("\\u00").Append(((int)c).ToString("x2", CultureInfo.InvariantCulture));
                    else
                        result.Append(c);
                    break;
            }
        }
        return result.Append('"').ToString();
    }

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        return header.Split(',')
            .Select(value => value.Trim())
            .Any(value => value == "*" || value == etag);
    }

    public static bool IsUniqueViolation(Exception exception)
    {
        for (var current = exception; current != null; current = current.InnerException!)
        {
            if (current is SqliteException sqlite && sqlite.SqliteErrorCode == 19)
                return true;
        }
        return false;
    }

    public static ProblemDetails Problem(int status, string title) =>
        new() { Status = status, Title = title };
}

