public sealed class WarehouseShipmentsController(WarehouseDbContext db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(ShipmentResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(ShipmentResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create(
        Guid warehouseId, [FromBody, Required] ShipmentRequest? body, CancellationToken cancellationToken)
    {
        if (!Valid(body) || body!.WarehouseId!.Value != warehouseId)
            return BadRequest(ApiRepresentation.Problem(400, "Invalid shipment"));

        var warehouse = await db.Depots.SingleOrDefaultAsync(x => x.Id == warehouseId, cancellationToken);
        if (warehouse == null)
        {
            var deletedWarehouse = await db.Depots.IgnoreQueryFilters()
                .AnyAsync(x => x.Id == warehouseId, cancellationToken);
            return deletedWarehouse ? StatusCode(410, ApiRepresentation.Problem(410, "Warehouse deleted"))
                : NotFound(ApiRepresentation.Problem(404, "Warehouse not found"));
        }

        var id = body.Id!.Value;
        var reference = body.Reference!;
        var weight = body.WeightKg!.Value;
        var fragile = body.Fragile!.Value;
        var canonical = ApiRepresentation.ShipmentJson(id, warehouseId, reference, weight, fragile);
        var tag = ApiRepresentation.ETag(canonical);
        var entity = new Consignment
        {
            Id = id, WarehouseId = warehouseId, DepotInternalId = warehouse.InternalId,
            Reference = reference.Normalize(NormalizationForm.FormC), WeightKg = weight,
            Fragile = fragile, ETag = tag, CreateHash = tag
        };
        db.Consignments.Add(entity);

        try
        {
            await db.SaveChangesAsync(cancellationToken);
            return Created($"/api/shipments/{id:D}", ApiRepresentation.ToResponse(entity)).WithEtag(tag);
        }
        catch (DbUpdateException ex) when (ApiRepresentation.IsUniqueViolation(ex))
        {
            db.Entry(entity).State = EntityState.Detached;
            var existing = await db.Consignments.IgnoreQueryFilters()
                .SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
            if (existing == null) return Conflict(ApiRepresentation.Problem(409, "Identifier conflict"));
            if (existing.DeletedAt != null) return StatusCode(410, ApiRepresentation.Problem(410, "Shipment deleted"));
            if (existing.WarehouseId != warehouseId || existing.CreateHash != tag)
                return Conflict(ApiRepresentation.Problem(409, "Identifier conflict"));
            return Ok(ApiRepresentation.ToResponse(existing)).WithEtag(existing.ETag);
        }
    }

    private static bool Valid(ShipmentRequest? body) =>
        body?.Id is Guid id && id != Guid.Empty &&
        body.WarehouseId is Guid warehouseId && warehouseId != Guid.Empty &&
        !string.IsNullOrWhiteSpace(body.Reference) &&
        body.WeightKg is >= 0 &&
        body.Fragile.HasValue;
}

