    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(
        Guid id, [FromBody, Required] ShipmentRequest? body,
        [FromHeader(Name = "If-Match", IsRequired = true)] string? ifMatch,
        CancellationToken cancellationToken)
    {
        if (!Valid(body) || body!.Id!.Value != id)
            return BadRequest(ApiRepresentation.Problem(400, "Invalid shipment"));
        if (string.IsNullOrWhiteSpace(ifMatch))
            return StatusCode(428, ApiRepresentation.Problem(428, "If-Match header required"));

        var entity = await db.Consignments.SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (entity == null) return await Missing(id, cancellationToken);
