        catch (DbUpdateConcurrencyException)
        {
            var current = await db.Consignments.AsNoTracking().SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
            if (current == null) return await Missing(id, cancellationToken);
            return StatusCode(412, ApiRepresentation.Problem(412, "ETag mismatch")).WithEtag(current.ETag);
        }
    }

