internal static class ActionResultExtensions
{
    public static IActionResult WithEtag(this IActionResult result, string etag)
    {
        if (result is ObjectResult objectResult)
            objectResult.HttpContext.Response.Headers.ETag = etag;
        else if (result is StatusCodeResult)
        {
            // StatusCodeResult does not expose HttpContext; actions set ETag via this result wrapper.
            return new EtagStatusCodeResult(result, etag);
        }
        return result;
    }

    private sealed class EtagStatusCodeResult(IActionResult inner, string etag) : IActionResult
    {
        public async Task ExecuteResultAsync(ActionContext context)
        {
            context.HttpContext.Response.Headers.ETag = etag;
            await inner.ExecuteResultAsync(context);
        }
    }
}
