internal static class ApiSupport
{
    public static string Canonical(DepotBody body) =>
        "{\"id\":" + Q(body.Id.ToString("D").ToLowerInvariant()) +
        ",\"code\":" + Q((body.Code ?? "").Normalize(NormalizationForm.FormC)) +
        ",\"capacityCubicMeters\":" + body.CapacityCubicMeters.ToString(CultureInfo.InvariantCulture) + "}";

    public static string Canonical(ConsignmentBody body) =>
        "{\"id\":" + Q(body.Id.ToString("D").ToLowerInvariant()) +
        ",\"warehouseId\":" + Q(body.WarehouseId.ToString("D").ToLowerInvariant()) +
        ",\"reference\":" + Q((body.Reference ?? "").Normalize(NormalizationForm.FormC)) +
        ",\"weightKg\":" + body.WeightKg.ToString("G29", CultureInfo.InvariantCulture) +
        ",\"fragile\":" + (body.Fragile ? "true" : "false") + "}";

    public static string Hash(string canonical)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return "\"" + Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    private static string Q(string value)
    {
        var b = new StringBuilder("\"");
        foreach (var c in value)
        {
            switch (c)
            {
                case '"': b.Append("\\\""); break;
                case '\\': b.Append("\\\\"); break;
                case '\b': b.Append("\\b"); break;
                case '\f': b.Append("\\f"); break;
                case '\n': b.Append("\\n"); break;
                case '\r': b.Append("\\r"); break;
                case '\t': b.Append("\\t"); break;
                default:
                    if (c < 0x20) b.Append("\\u").Append(((int)c).ToString("x4"));
                    else b.Append(c);
                    break;
            }
        }
        return b.Append('"').ToString();
    }

    public static bool Valid(DepotBody? body) =>
        body is not null && body.Id != Guid.Empty &&
        !string.IsNullOrWhiteSpace(body.Code) && body.CapacityCubicMeters > 0;

    public static bool Valid(ConsignmentBody? body) =>
        body is not null && body.Id != Guid.Empty && body.WarehouseId != Guid.Empty &&
        !string.IsNullOrWhiteSpace(body.Reference) && body.WeightKg >= 0;

    public static bool Matches(string? header, string etag) =>
        header?.Split(',').Select(x => x.Trim()).Any(x => x == "*" || x == etag) == true;

    public static void SetEtag(ControllerBase controller, string etag) =>
        controller.Response.Headers.ETag = etag;

    public static ObjectResult Problem(ControllerBase controller, int status, string title, string detail)
    {
        var result = controller.Problem(statusCode: status, title: title, detail: detail);
        result.ContentTypes.Add("application/problem+json");
        return result;
    }

    public static bool IsSqliteUnique(DbUpdateException exception) =>
        exception.InnerException is SqliteException sqlite &&
        (sqlite.SqliteErrorCode == 19 || sqlite.SqliteExtendedErrorCode == 2067 ||
         sqlite.SqliteExtendedErrorCode == 1555);

    public static bool IsSqliteBusy(Exception exception) =>
        exception is DbUpdateException { InnerException: SqliteException sqlite } &&
        (sqlite.SqliteErrorCode == 5 || sqlite.SqliteErrorCode == 6);
}

