internal static class ApiSupport
{
    public static string Hash(string value) =>
        Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(value)))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_');

    public static string ETag(string canonical) => $"\"{Hash(canonical)}\"";

    public static string WarehouseCanonical(Guid id, string code, int capacity) =>
        $"{{\"id\":\"{GuidText(id)}\",\"code\":{JsonString(code)},\"capacityCubicMeters\":{capacity.ToString(CultureInfo.InvariantCulture)}}}";

    public static string ShipmentCanonical(Guid id, Guid warehouseId, string reference, decimal weight, bool fragile) =>
        $"{{\"id\":\"{GuidText(id)}\",\"warehouseId\":\"{GuidText(warehouseId)}\",\"reference\":{JsonString(reference)},\"weightKg\":{weight.ToString("G29", CultureInfo.InvariantCulture)},\"fragile\":{(fragile ? "true" : "false")}}}";

    private static string GuidText(Guid id) => id.ToString("D").ToLowerInvariant();

    private static string JsonString(string value)
    {
        var normalized = value.Normalize(NormalizationForm.FormC);
        var result = new StringBuilder("\"");
        foreach (var c in normalized)
        {
            switch (c)
            {
                case '"': result.Append("\\\""); break;
                case '\\': result.Append("\\\\"); break;
                case '\b': result.Append("\\b"); break;
                case '\f': result.Append("\\f"); break;
                case '\n': result.Append("\\n"); break;
                case '\r': result.Append("\\r"); break;
                case '\t': result.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        result.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else
                        result.Append(c);
                    break;
            }
        }
        return result.Append('"').ToString();
    }

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        return header.Split(',').Select(x => x.Trim()).Any(x => x == "*" || x == etag);
    }

    public static bool ValidWarehouse(WarehouseRequest? request) =>
        request is not null && request.Id != Guid.Empty &&
        !string.IsNullOrWhiteSpace(request.Code) &&
        request.CapacityCubicMeters >= 0;

    public static bool ValidShipment(ShipmentRequest? request) =>
        request is not null && request.Id != Guid.Empty &&
        request.WarehouseId != Guid.Empty &&
        !string.IsNullOrWhiteSpace(request.Reference) &&
        request.WeightKg >= 0 && request.WeightKg != decimal.MaxValue;

    public static ObjectResult Problem(int status, string title)
    {
        var details = new ProblemDetails { Status = status, Title = title };
        var result = new ObjectResult(details) { StatusCode = status };
        result.ContentTypes.Add("application/problem+json");
        return result;
    }

    public static ObjectResult WithEtag(object response, string etag, int status = 200)
    {
        var result = new ObjectResult(response) { StatusCode = status };
        result.HttpContext.Response.Headers.ETag = etag;
        return result;
    }

    public static bool IsUniqueViolation(DbUpdateException exception) =>
        exception.InnerException is Microsoft.Data.Sqlite.SqliteException sqlite &&
        (sqlite.SqliteErrorCode == 19 || sqlite.SqliteExtendedErrorCode == 1555 ||
         sqlite.SqliteExtendedErrorCode == 2067);
}

