internal static class ApiSupport
{
    public static string ETag(Depot depot) =>
        Hash(Canonical(w => WriteWarehouse(w, depot.Id, depot.Code, depot.CapacityCubicMeters)));

    public static string ETag(Guid id, string code, int capacity) =>
        Hash(Canonical(w => WriteWarehouse(w, id, code, capacity)));

    public static string ETag(Consignment item) =>
        Hash(Canonical(w => WriteShipment(w, item.Id, item.WarehouseId, item.Reference, item.WeightKg, item.Fragile)));

    public static string ETag(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile) =>
        Hash(Canonical(w => WriteShipment(w, id, warehouseId, reference, weightKg, fragile)));

    public static string Hash(string value) =>
        '"' + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(value)))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_') + '"';

    public static string Canonical(Action<Utf8JsonWriter> write)
    {
        using var stream = new MemoryStream();
        using (var writer = new Utf8JsonWriter(stream, new JsonWriterOptions { Indented = false }))
            write(writer);
        return Encoding.UTF8.GetString(stream.ToArray());
    }

    private static void WriteWarehouse(Utf8JsonWriter w, Guid id, string code, int capacity)
    {
        w.WriteStartObject();
        w.WriteString("id", id.ToString("D").ToLowerInvariant());
        w.WriteString("code", Normalize(code));
        w.WriteNumber("capacityCubicMeters", capacity);
        w.WriteEndObject();
    }

    private static void WriteShipment(Utf8JsonWriter w, Guid id, Guid warehouseId, string reference, decimal weight, bool fragile)
    {
        w.WriteStartObject();
        w.WriteString("id", id.ToString("D").ToLowerInvariant());
        w.WriteString("warehouseId", warehouseId.ToString("D").ToLowerInvariant());
        w.WriteString("reference", Normalize(reference));
        w.WriteRawValue(weight.ToString("G29", CultureInfo.InvariantCulture));
        w.WriteBoolean("fragile", fragile);
        w.WriteEndObject();
    }

    public static string Normalize(string value) => value.Normalize(NormalizationForm.FormC);

    public static bool Matches(string? ifMatch, string etag) =>
        ifMatch?.Split(',').Select(x => x.Trim()).Any(x => x == "*" || x == etag) == true;

    public static bool IsUniqueViolation(Exception exception) =>
        exception is DbUpdateException db &&
        (db.InnerException is SqliteException sqlite && sqlite.SqliteErrorCode == 19);

    public static ObjectResult Problem(int status, string title, string detail) =>
        new(new ProblemDetails { Status = status, Title = title, Detail = detail })
        {
            StatusCode = status,
            ContentTypes = { "application/problem+json" }
        };

    public static IActionResult Error(int status, string title, string detail) =>
        Problem(status, title, detail);

    public static IActionResult PreconditionRequired() =>
        Error(428, "Precondition required", "The If-Match header is required.");

    public static void SetEtag(HttpResponse response, string value) => response.Headers.ETag = value;
}

