public sealed class Depot
{
    public int InternalId { get; set; }
    public Guid Id { get; set; }
    public string Code { get; set; } = "";
    public int CapacityCubicMeters { get; set; }
    public DateTime? LastAuditAt { get; set; }
    public string ETag { get; set; } = "";
    public string CreateHash { get; set; } = "";
    public DateTime? DeletedAt { get; set; }
    public List<Consignment> Consignments { get; set; } = [];
}

public sealed class Consignment
{
    public int InternalId { get; set; }
    public Guid Id { get; set; }
    public Guid WarehouseId { get; set; }
    public Depot? Warehouse { get; set; }
    public string Reference { get; set; } = "";
    public decimal WeightKg { get; set; }
    public bool Fragile { get; set; }
    public int DownloadCount { get; set; }
    public string ETag { get; set; } = "";
    public string CreateHash { get; set; } = "";
    public DateTime? DeletedAt { get; set; }
}

public sealed class WarehouseDbContext(DbContextOptions<WarehouseDbContext> options)
    : DbContext(options)
{
    public DbSet<Depot> Depots => Set<Depot>();
    public DbSet<Consignment> Consignments => Set<Consignment>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        var depot = modelBuilder.Entity<Depot>();
        depot.HasKey(x => x.InternalId);
        depot.HasIndex(x => x.Id).IsUnique();
        depot.Property(x => x.Id).IsRequired();
        depot.Property(x => x.Code).IsRequired();
        depot.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
        depot.Property(x => x.CreateHash).IsRequired().Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
        depot.HasQueryFilter(x => x.DeletedAt == null);
        depot.HasMany(x => x.Consignments).WithOne(x => x.Warehouse)
            .HasForeignKey(x => x.WarehouseId).HasPrincipalKey(x => x.Id);

        var consignment = modelBuilder.Entity<Consignment>();
        consignment.HasKey(x => x.InternalId);
        consignment.HasIndex(x => x.Id).IsUnique();
        consignment.Property(x => x.Id).IsRequired();
        consignment.Property(x => x.Reference).IsRequired();
        consignment.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
        consignment.Property(x => x.CreateHash).IsRequired().Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
        consignment.HasQueryFilter(x => x.DeletedAt == null);
    }
}

public static class AppSetup
{
    public static void ConfigureServices(IServiceCollection services, string sqliteConnectionString)
    {
        services.AddDbContext<WarehouseDbContext>(options => options.UseSqlite(sqliteConnectionString));
        services.AddControllers();
    }
}

public sealed record WarehouseRequest(
    [property: Required] Guid Id,
    [property: Required, StringLength(200)] string? Code,
    [property: Range(0, int.MaxValue)] int CapacityCubicMeters);

public sealed record ShipmentRequest(
    [property: Required] Guid Id,
    [property: Required] Guid WarehouseId,
    [property: Required, StringLength(200)] string? Reference,
    [property: Range(typeof(decimal), "0", "79228162514264337593543950335")] decimal WeightKg,
    bool Fragile);

public sealed record WarehouseResponse(Guid Id, string Code, int CapacityCubicMeters);
public sealed record ShipmentResponse(Guid Id, Guid WarehouseId, string Reference, decimal WeightKg, bool Fragile);

internal static class ApiSupport
{
    public static string Hash(string canonicalJson) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson)))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";

    public static string WarehouseJson(Guid id, string code, int capacity) =>
        "{\"id\":" + Quote(id.ToString("D").ToLowerInvariant()) +
        ",\"code\":" + Quote(code.Normalize(NormalizationForm.FormC)) +
        ",\"capacityCubicMeters\":" + capacity.ToString(CultureInfo.InvariantCulture) + "}";

    public static string ShipmentJson(Guid id, Guid warehouseId, string reference, decimal weight, bool fragile) =>
        "{\"id\":" + Quote(id.ToString("D").ToLowerInvariant()) +
        ",\"warehouseId\":" + Quote(warehouseId.ToString("D").ToLowerInvariant()) +
        ",\"reference\":" + Quote(reference.Normalize(NormalizationForm.FormC)) +
        ",\"weightKg\":" + weight.ToString("0.############################", CultureInfo.InvariantCulture) +
        ",\"fragile\":" + (fragile ? "true" : "false") + "}";

    private static string Quote(string value)
    {
        var b = new StringBuilder("\"");
        foreach (var c in value)
        {
            switch (c)
            {
                case '"': b.Append("\\\""); break;
                case '\\': b.Append("\\\\"); break;
                case '\b': b.Append("\\b"); break;
                case '\f': b.Append("\\f"); break;
                case '\n': b.Append("\\n"); break;
                case '\r': b.Append("\\r"); break;
                case '\t': b.Append("\\t"); break;
                default:
                    if (c < 0x20) b.Append("\\u").Append(((int)c).ToString("x4"));
                    else b.Append(c);
                    break;
            }
        }
        return b.Append('"').ToString();
    }

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        return header.Split(',').Select(x => x.Trim()).Any(x => x == "*" || x == etag);
    }

    public static bool IsUniqueViolation(DbUpdateException ex) =>
        ex.InnerException is SqliteException sqlite &&
        (sqlite.SqliteErrorCode == 19 || sqlite.SqliteErrorCode == 1555 || sqlite.SqliteErrorCode == 2067);

    public static ObjectResult Problem(int status, string title, string detail) =>
        new ProblemDetails { Status = status, Title = title, Detail = detail } is var p
            ? new ObjectResult(p) { StatusCode = status, ContentTypes = { "application/problem+json" } }
            : throw new InvalidOperationException();
}

[ApiController]
[Route("api/warehouses")]
public sealed class WarehousesController(WarehouseDbContext db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(WarehouseResponse), 201)]
    [ProducesResponseType(typeof(WarehouseResponse), 200)]
    [ProducesResponseType(typeof(ProblemDetails), 400, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 409, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, Required] WarehouseRequest? request, CancellationToken cancellationToken)
    {
        if (request is null || request.Id == Guid.Empty || string.IsNullOrWhiteSpace(request.Code) ||
            request.CapacityCubicMeters < 0)
            return ApiSupport.Problem(400, "Invalid request", "The warehouse body is invalid.");

        var code = request.Code.Normalize(NormalizationForm.FormC);
        var canonical = ApiSupport.WarehouseJson(request.Id, code, request.CapacityCubicMeters);
        var etag = ApiSupport.Hash(canonical);
        var now = DateTime.UtcNow;
        var depot = new Depot
        {
            Id = request.Id, Code = code, CapacityCubicMeters = request.CapacityCubicMeters,
            ETag = etag, CreateHash = etag, LastAuditAt = now
        };
        db.Depots.Add(depot);
        try
        {
            await db.SaveChangesAsync(cancellationToken);
            Response.Headers.ETag = etag;
            Response.Headers.Location = $"/api/warehouses/{request.Id:D}";
            return StatusCode(201, new WarehouseResponse(depot.Id, depot.Code, depot.CapacityCubicMeters));
        }
        catch (DbUpdateException ex) when (ApiSupport.IsUniqueViolation(ex))
        {
            db.Entry(depot).State = EntityState.Detached;
            var existing = await db.Depots.IgnoreQueryFilters().SingleOrDefaultAsync(x => x.Id == request.Id, cancellationToken);
            if (existing is null) return ApiSupport.Problem(409, "Conflict", "The warehouse id is already in use.");
            if (existing.DeletedAt != null) return ApiSupport.Problem(410, "Gone", "The warehouse was deleted.");
            if (existing.CreateHash != etag) return ApiSupport.Problem(409, "Conflict", "The id already exists with different content.");
            Response.Headers.ETag = existing.ETag;
            return Ok(new WarehouseResponse(existing.Id, existing.Code, existing.CapacityCubicMeters));
        }
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(WarehouseResponse), 200)]
    [ProducesResponseType(304)]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, [FromHeader(Name = "If-None-Match")] string? ifNoneMatch, CancellationToken cancellationToken)
    {
        var depot = await db.Depots.IgnoreQueryFilters().SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (depot is null) return ApiSupport.Problem(404, "Not found", "The warehouse does not exist.");
        if (depot.DeletedAt != null) return ApiSupport.Problem(410, "Gone", "The warehouse was deleted.");
        Response.Headers.ETag = depot.ETag;
        if (ApiSupport.Matches(ifNoneMatch, depot.ETag)) return StatusCode(304);

        depot.LastAuditAt = DateTime.UtcNow;
        await db.SaveChangesAsync(cancellationToken);
        return Ok(new WarehouseResponse(depot.Id, depot.Code, depot.CapacityCubicMeters));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 400, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 409, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 412, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 428, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromBody, Required] WarehouseRequest? request,
        [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken cancellationToken)
    {
        if (request is null || request.Id == Guid.Empty || request.Id != id ||
            string.IsNullOrWhiteSpace(request.Code) || request.CapacityCubicMeters < 0)
            return ApiSupport.Problem(400, "Invalid request", "The warehouse body is invalid or its id does not match.");
        if (string.IsNullOrWhiteSpace(ifMatch)) return ApiSupport.Problem(428, "Precondition required", "If-Match is required.");

        var depot = await db.Depots.SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (depot is null) return await GoneOrMissingDepot(id, cancellationToken);
        var code = request.Code.Normalize(NormalizationForm.FormC);
        var newTag = ApiSupport.Hash(ApiSupport.WarehouseJson(id, code, request.CapacityCubicMeters));
        if (depot.ETag == newTag) return NoContent();
        if (!ApiSupport.Matches(ifMatch, depot.ETag))
        {
            Response.Headers.ETag = depot.ETag;
            return ApiSupport.Problem(412, "Precondition failed", "The warehouse has changed.");
        }
        depot.Code = code;
        depot.CapacityCubicMeters = request.CapacityCubicMeters;
        depot.ETag = newTag;
        depot.LastAuditAt = DateTime.UtcNow;
        try
        {
            await db.SaveChangesAsync(cancellationToken);
            Response.Headers.ETag = newTag;
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            return await CurrentDepotConflict(id, cancellationToken);
        }
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 412, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 428, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(ifMatch)) return ApiSupport.Problem(428, "Precondition required", "If-Match is required.");
        var depot = await db.Depots.SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (depot is null) return NoContent();
        if (!ApiSupport.Matches(ifMatch, depot.ETag))
        {
            Response.Headers.ETag = depot.ETag;
            return ApiSupport.Problem(412, "Precondition failed", "The warehouse has changed.");
        }

        var now = DateTime.UtcNow;
        depot.DeletedAt = now;
        depot.LastAuditAt = now;
        var shipments = await db.Consignments.Where(x => x.WarehouseId == depot.Id).ToListAsync(cancellationToken);
        foreach (var shipment in shipments) shipment.DeletedAt = now;
        try
        {
            await db.SaveChangesAsync(cancellationToken);
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            return await CurrentDepotConflict(id, cancellationToken);
        }
    }

