[Route("api/warehouses/{warehouseId:guid}/shipments")]
public sealed class WarehouseShipmentsController(WarehouseDbContext db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(ShipmentResponse), 201)]
    [ProducesResponseType(typeof(ShipmentResponse), 200)]
    [ProducesResponseType(typeof(ProblemDetails), 400, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 409, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    public async Task<IActionResult> Create(Guid warehouseId, [FromBody, Required] ShipmentRequest? request, CancellationToken cancellationToken)
    {
        if (request is null || request.Id == Guid.Empty || request.WarehouseId == Guid.Empty ||
            request.WarehouseId != warehouseId || string.IsNullOrWhiteSpace(request.Reference) || request.WeightKg < 0)
            return ApiSupport.Problem(400, "Invalid request", "The shipment body is invalid or its warehouseId does not match the route.");

        var warehouse = await db.Depots.IgnoreQueryFilters().SingleOrDefaultAsync(x => x.Id == warehouseId, cancellationToken);
        if (warehouse is null) return ApiSupport.Problem(404, "Not found", "The warehouse does not exist.");
        if (warehouse.DeletedAt != null) return ApiSupport.Problem(410, "Gone", "The warehouse was deleted.");

        var reference = request.Reference.Normalize(NormalizationForm.FormC);
        var canonical = ApiSupport.ShipmentJson(request.Id, warehouseId, reference, request.WeightKg, request.Fragile);
        var etag = ApiSupport.Hash(canonical);
        var item = new Consignment
        {
            Id = request.Id, WarehouseId = warehouseId, Reference = reference,
            WeightKg = request.WeightKg, Fragile = request.Fragile, ETag = etag, CreateHash = etag
        };
        db.Consignments.Add(item);
        try
        {
            await db.SaveChangesAsync(cancellationToken);
            Response.Headers.ETag = etag;
            Response.Headers.Location = $"/api/shipments/{request.Id:D}";
            return StatusCode(201, new ShipmentResponse(item.Id, item.WarehouseId, item.Reference, item.WeightKg, item.Fragile));
        }
        catch (DbUpdateException ex) when (ApiSupport.IsUniqueViolation(ex))
        {
            db.Entry(item).State = EntityState.Detached;
            var existing = await db.Consignments.IgnoreQueryFilters().SingleOrDefaultAsync(x => x.Id == request.Id, cancellationToken);
            if (existing is null) return ApiSupport.Problem(409, "Conflict", "The shipment id is already in use.");
            if (existing.DeletedAt != null) return ApiSupport.Problem(410, "Gone", "The shipment was deleted.");
            if (existing.WarehouseId != warehouseId) return ApiSupport.Problem(409, "Conflict", "The shipment id belongs to another warehouse.");
            if (existing.CreateHash != etag) return ApiSupport.Problem(409, "Conflict", "The id already exists with different content.");
            Response.Headers.ETag = existing.ETag;
            return Ok(new ShipmentResponse(existing.Id, existing.WarehouseId, existing.Reference, existing.WeightKg, existing.Fragile));
        }
    }
}

