[Route("api/shipments")]
public sealed class ShipmentsController(WarehouseDbContext db) : ControllerBase
{
    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(ShipmentResponse), 200)]
    [ProducesResponseType(304)]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, [FromHeader(Name = "If-None-Match")] string? ifNoneMatch, CancellationToken cancellationToken)
    {
        var item = await db.Consignments.IgnoreQueryFilters().SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (item is null) return ApiSupport.Problem(404, "Not found", "The shipment does not exist.");
        if (item.DeletedAt != null) return ApiSupport.Problem(410, "Gone", "The shipment was deleted.");
        Response.Headers.ETag = item.ETag;
        if (ApiSupport.Matches(ifNoneMatch, item.ETag)) return StatusCode(304);
        item.DownloadCount++;
        await db.SaveChangesAsync(cancellationToken);
        return Ok(new ShipmentResponse(item.Id, item.WarehouseId, item.Reference, item.WeightKg, item.Fragile));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 400, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 409, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 412, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 428, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromBody, Required] ShipmentRequest? request,
        [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken cancellationToken)
    {
        if (request is null || request.Id == Guid.Empty || request.Id != id || request.WarehouseId == Guid.Empty ||
            string.IsNullOrWhiteSpace(request.Reference) || request.WeightKg < 0)
            return ApiSupport.Problem(400, "Invalid request", "The shipment body is invalid or its id does not match.");
        if (string.IsNullOrWhiteSpace(ifMatch)) return ApiSupport.Problem(428, "Precondition required", "If-Match is required.");

        var item = await db.Consignments.SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (item is null) return await GoneOrMissing(id, cancellationToken);
        if (item.WarehouseId != request.WarehouseId)
            return ApiSupport.Problem(409, "Conflict", "A shipment cannot be moved to another warehouse.");

        var reference = request.Reference.Normalize(NormalizationForm.FormC);
        var newTag = ApiSupport.Hash(ApiSupport.ShipmentJson(id, item.WarehouseId, reference, request.WeightKg, request.Fragile));
        if (item.ETag == newTag) return NoContent();
        if (!ApiSupport.Matches(ifMatch, item.ETag))
        {
            Response.Headers.ETag = item.ETag;
            return ApiSupport.Problem(412, "Precondition failed", "The shipment has changed.");
        }

        item.Reference = reference;
        item.WeightKg = request.WeightKg;
        item.Fragile = request.Fragile;
        item.ETag = newTag;
        try
        {
            await db.SaveChangesAsync(cancellationToken);
            Response.Headers.ETag = newTag;
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            return await CurrentConflict(id, cancellationToken);
        }
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 412, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 428, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(ifMatch)) return ApiSupport.Problem(428, "Precondition required", "If-Match is required.");
        var item = await db.Consignments.SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (item is null) return NoContent();
        if (!ApiSupport.Matches(ifMatch, item.ETag))
        {
            Response.Headers.ETag = item.ETag;
            return ApiSupport.Problem(412, "Precondition failed", "The shipment has changed.");
        }
        item.DeletedAt = DateTime.UtcNow;
        try
        {
            await db.SaveChangesAsync(cancellationToken);
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            return await CurrentConflict(id, cancellationToken);
        }
    }

    private async Task<IActionResult> GoneOrMissing(Guid id, CancellationToken ct) =>
        await db.Consignments.IgnoreQueryFilters().AnyAsync(x => x.Id == id, ct)
            ? ApiSupport.Problem(410, "Gone", "The shipment was deleted.")
            : ApiSupport.Problem(404, "Not found", "The shipment does not exist.");

    private async Task<IActionResult> CurrentConflict(Guid id, CancellationToken ct)
    {
        var current = await db.Consignments.AsNoTracking().SingleOrDefaultAsync(x => x.Id == id, ct);
        if (current is null) return await GoneOrMissing(id, ct);
        Response.Headers.ETag = current.ETag;
        return ApiSupport.Problem(412, "Precondition failed", "The shipment has changed.");
    }
}
