public static class AppSetup
{
    public static void ConfigureServices(IServiceCollection services, string sqliteConnectionString)
    {
        services.AddDbContext<DepotDbContext>(options => options.UseSqlite(sqliteConnectionString));
        services.AddControllers().ConfigureApiBehaviorOptions(options =>
        {
            options.InvalidModelStateResponseFactory = context =>
            {
                var errors = context.ModelState
                    .Where(entry => entry.Value?.Errors.Count > 0)
                    .ToArray();

                // A missing If-Match is 428, unless another validation error takes precedence.
                if (errors.Length > 0 &&
                    errors.All(entry => entry.Key.Contains("ifMatch", StringComparison.OrdinalIgnoreCase)))
                {
                    return new ObjectResult(new ProblemDetails
                    {
                        Status = 428,
                        Title = "Precondition required",
                        Detail = "The If-Match header is required."
                    }) { StatusCode = 428, ContentTypes = { "application/problem+json" } };
                }

                return new BadRequestObjectResult(new ValidationProblemDetails(context.ModelState)
                {
                    Status = 400
                });
            };
        });
    }
}

public sealed class DepotDbContext(DbContextOptions<DepotDbContext> options) : DbContext(options)
{
    public DbSet<Depot> Depots => Set<Depot>();
    public DbSet<Consignment> Consignments => Set<Consignment>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        var depot = modelBuilder.Entity<Depot>();
        depot.HasKey(x => x.InternalId);
        depot.HasIndex(x => x.Id).IsUnique();
        depot.Property(x => x.Id).IsRequired();
        depot.Property(x => x.Code).IsRequired();
        depot.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
        depot.Property(x => x.CreateHash).IsRequired().Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
        depot.HasQueryFilter(x => x.DeletedAt == null);

        var consignment = modelBuilder.Entity<Consignment>();
        consignment.HasKey(x => x.InternalId);
        consignment.HasIndex(x => x.Id).IsUnique();
        consignment.Property(x => x.Id).IsRequired();
        consignment.Property(x => x.Reference).IsRequired();
        consignment.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
        consignment.Property(x => x.CreateHash).IsRequired().Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
        consignment.HasQueryFilter(x => x.DeletedAt == null);
        consignment.HasOne<Depot>()
            .WithMany()
            .HasForeignKey(x => x.WarehouseInternalId)
            .OnDelete(DeleteBehavior.Restrict);
    }
