internal static class EntityTags
{
    public static string For(WarehouseRepresentation value) =>
        Hash(Canonical(value.Id, null, value.Code, value.CapacityCubicMeters));

    public static string For(ShipmentRepresentation value) =>
        Hash(Canonical(value.Id, value.WarehouseId, value.Reference, value.WeightKg, value.Fragile));

    private static string Hash(string canonical)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return "\"" + Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    private static string Canonical(Guid id, Guid? parent, string text, int number) =>
        "{\"id\":\"" + id.ToString("D").ToLowerInvariant() + "\"," +
        "\"code\":\"" + Escape(text.Normalize(NormalizationForm.FormC)) + "\"," +
        "\"capacityCubicMeters\":" + number.ToString(CultureInfo.InvariantCulture) + "}";

    private static string Canonical(Guid id, Guid? parent, string text, decimal weight, bool fragile) =>
        "{\"id\":\"" + id.ToString("D").ToLowerInvariant() + "\"," +
        "\"warehouseId\":\"" + parent!.Value.ToString("D").ToLowerInvariant() + "\"," +
        "\"reference\":\"" + Escape(text.Normalize(NormalizationForm.FormC)) + "\"," +
        "\"weightKg\":" + weight.ToString("G29", CultureInfo.InvariantCulture) + "," +
        "\"fragile\":" + (fragile ? "true" : "false") + "}";

    private static string Escape(string value)
    {
        var result = new StringBuilder(value.Length);
        foreach (var c in value)
        {
            switch (c)
            {
                case '"': result.Append("\\\""); break;
                case '\\': result.Append("\\\\"); break;
                case '\b': result.Append("\\b"); break;
                case '\f': result.Append("\\f"); break;
                case '\n': result.Append("\\n"); break;
                case '\r': result.Append("\\r"); break;
                case '\t': result.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        result.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else
                        result.Append(c);
                    break;
            }
        }
        return result.ToString();
    }

    public static bool Matches(string? ifMatch, string currentTag) =>
        ifMatch?.Split(',').Select(x => x.Trim()).Any(x => x == "*" || x == currentTag) == true;
}

