    public async Task<IActionResult> Create(
        [FromBody, BindRequired] WarehouseWrite? body, CancellationToken cancellationToken)
    {
        if (!Valid(body?.Id, body?.Code, body?.CapacityCubicMeters))
            return ProblemResult(400, "Invalid warehouse", "A non-empty id, code, and non-negative capacity are required.");

        var representation = new WarehouseRepresentation(body!.Id, body.Code!.Normalize(NormalizationForm.FormC), body.CapacityCubicMeters);
        var tag = EntityTags.For(representation);
        var item = new Depot
        {
            Id = representation.Id,
            Code = representation.Code,
            CapacityCubicMeters = representation.CapacityCubicMeters,
            LastAuditAt = DateTime.UtcNow,
            ETag = tag,
            CreateHash = tag
        };

        db.Depots.Add(item);
        try
        {
            await db.SaveChangesAsync(cancellationToken);
            Response.Headers.ETag = tag;
            return CreatedAtAction(nameof(Get), new { id = item.Id }, representation);
        }
        catch (DbUpdateException ex) when (IsUniqueViolation(ex))
        {
            db.Entry(item).State = EntityState.Detached;
            var existing = await db.Depots.IgnoreQueryFilters()
                .SingleOrDefaultAsync(x => x.Id == representation.Id, cancellationToken);
            if (existing is null) return ProblemResult(409, "Conflict", "The warehouse id is already in use.");
            if (existing.DeletedAt != null) return ProblemResult(410, "Gone", "The warehouse was deleted.");
            if (existing.CreateHash != tag) return ProblemResult(409, "Conflict", "The id was created with different content.");

            Response.Headers.ETag = existing.ETag;
            return Ok(ToRepresentation(existing));
        }
    }

