            return PreconditionFailed(item.ETag);

        item.Code = representation.Code;
        item.CapacityCubicMeters = representation.CapacityCubicMeters;
        item.LastAuditAt = DateTime.UtcNow;
        item.ETag = newTag;

        try
        {
            await db.SaveChangesAsync(cancellationToken);
            Response.Headers.ETag = newTag;
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            return await CurrentWarehouseTag(id, cancellationToken);
        }
