    public async Task<IActionResult> Delete(
        Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return ProblemResult(428, "Precondition required", "The If-Match header is required.");

        var item = await db.Depots.SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (item is null) return NoContent();
        if (!EntityTags.Matches(ifMatch, item.ETag)) return PreconditionFailed(item.ETag);

        await using var transaction = await db.Database.BeginTransactionAsync(cancellationToken);
        var now = DateTime.UtcNow;
        var shipments = await db.Consignments
            .Where(x => x.WarehouseInternalId == item.InternalId)
            .ToListAsync(cancellationToken);
        foreach (var shipment in shipments) shipment.DeletedAt = now;
        item.DeletedAt = now;

        try
        {
