        return deleted ? ProblemResult(410, "Gone", "The warehouse was deleted.") : ProblemResult(404, "Not found", "The warehouse does not exist.");
    }

    private async Task<IActionResult> CurrentWarehouseTag(Guid id, CancellationToken cancellationToken)
    {
        var current = await db.Depots.AsNoTracking().SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (current is null) return await GoneOrNotFoundDepot(id, cancellationToken);
        return PreconditionFailed(current.ETag);
    }

