        id.HasValue && id != Guid.Empty && !string.IsNullOrWhiteSpace(code) && capacity >= 0;

    internal static bool IsUniqueViolation(DbUpdateException ex) =>
        ex.InnerException is SqliteException sqlite && sqlite.SqliteErrorCode == 19;

    internal ObjectResult ProblemResult(int status, string title, string detail) =>
        new(new ProblemDetails { Status = status, Title = title, Detail = detail })
        { StatusCode = status, ContentTypes = { "application/problem+json" } };

    internal ObjectResult PreconditionFailed(string tag)
    {
        Response.Headers.ETag = tag;
        return ProblemResult(412, "Precondition failed", "The resource has changed.");
    }
