// Retry helper: SQLite serializes writers; retry briefly on contention.
// Db.cs
using Microsoft.EntityFrameworkCore;

public static class Db
{
    public static async Task<T> RunWithRetry<T>(Func<Task<T>> work)
    {
        const int maxAttempts = 8;
        for (var attempt = 1; ; attempt++)
        {
            try
            {
                return await work();
            }
            catch (DbUpdateException) when (attempt < maxAttempts)
            {
                await Task.Delay(TimeSpan.FromMilliseconds(20 * attempt));
            }
        }
    }

    public static Task RunWithRetry(Func<Task> work) =>
        RunWithRetry(async () => { await work(); return 0; });
}
