```csharp
// BlogsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/blogs")]
public class BlogsController : ControllerBase
{
    private readonly AppDbContext _db;

    public BlogsController(AppDbContext db) => _db = db;

    private static BlogResponse ToDto(Blog b) => new(b.Id, b.Name);

    [HttpPost]
    public async Task<ActionResult<BlogResponse>> Create([FromBody] BlogRequest req)
    {
        if (string.IsNullOrWhiteSpace(req.Name))
            return ValidationProblem("A blog name is required.");

        // Idempotent create: a retry carrying the same id returns the existing blog.
        if (req.Id is { } requestedId)
        {
            var existing = await _db.Blogs.FindAsync(requestedId);
            if (existing != null)
                return Ok(ToDto(existing));
        }

        var blog = new Blog
        {
            Id = req.Id ?? Guid.NewGuid(),
            Name = req.Name
        };

        _db.Blogs.Add(blog);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            // Concurrent insert with the same key — treat as already created.
            _db.Entry(blog).State = EntityState.Detached;
            var existing = await _db.Blogs.FindAsync(blog.Id);
            if (existing != null)
                return Ok(ToDto(existing));
            throw;
        }

        return CreatedAtAction(nameof(Get), new { id = blog.Id }, ToDto(blog));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<BlogResponse>> Get(Guid id)
    {
        var blog = await _db.Blogs.FindAsync(id);
        return blog is null ? NotFound() : Ok(ToDto(blog));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<BlogResponse>> Update(Guid id, [FromBody] BlogRequest req)
    {
        if (string.IsNullOrWhiteSpace(req.Name))
            return ValidationProblem("A blog name is required.");

        for (var attempt = 0; attempt < 2; attempt++)
        {
            var blog = await _db.Blogs.FindAsync(id);
            if (blog is null)
                return NotFound();

            blog.Name = req.Name;
            blog.Version++;
            try
            {
                await _db.SaveChangesAsync();
                return Ok(ToDto(blog));
            }
            catch (DbUpdateConcurrencyException)
            {
                _db.Entry(blog).State = EntityState.Detached;
            }
        }

        var fresh = await _db.Blogs.FindAsync(id);
        return fresh is null ? NotFound() : Ok(ToDto(fresh));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        for (var attempt = 0; attempt < 2; attempt++)
        {
            var blog = await _db.Blogs.FindAsync(id);
            if (blog is null)
                return NotFound();

            _db.Blogs.Remove(blog);
            try
            {
                await _db.SaveChangesAsync();
                return NoContent();
            }
            catch (DbUpdateConcurrencyException)
