// PostsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
public class PostsController : ControllerBase
{
    private readonly AppDbContext _db;

    public PostsController(AppDbContext db) => _db = db;

    private static PostResponse ToDto(Post p) => new(p.Id, p.BlogId, p.Title, p.Views);

    [HttpPost("api/blogs/{blogId:guid}/posts")]
    public async Task<ActionResult<PostResponse>> Create(Guid blogId, [FromBody] PostRequest req)
    {
        if (string.IsNullOrWhiteSpace(req.Title))
            return ValidationProblem("A post title is required.");

        // Idempotent create for retries carrying the same id.
        if (req.Id is { } requestedId)
        {
            var existing = await _db.Posts.FindAsync(requestedId);
            if (existing != null)
                return Ok(ToDto(existing));
        }

        var post = new Post
        {
            Id = req.Id ?? Guid.NewGuid(),
            BlogId = blogId,
            Title = req.Title,
            Views = 0
        };

        _db.Posts.Add(post);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            _db.Entry(post).State = EntityState.Detached;
            var existing = await _db.Posts.FindAsync(post.Id);
            if (existing != null)
                return Ok(ToDto(existing));
            return NotFound(); // FK violation: the blog does not exist.
        }

        return CreatedAtAction(nameof(Get), new { id = post.Id }, ToDto(post));
    }

    [HttpGet("api/posts/{id:guid}")]
    public async Task<ActionResult<PostResponse>> Get(Guid id)
    {
        // Atomically bump the server-maintained view counter.
        await _db.Database.ExecuteSqlInterpolatedAsync(
            $"UPDATE Posts SET Views = Views + 1 WHERE Id = {id}");

        var post = await _db.Posts.AsNoTracking().FirstOrDefaultAsync(p => p.Id == id);
        return post is null ? NotFound() : Ok(ToDto(post));
    }

    [HttpPut("api/posts/{id:guid}")]
    public async Task<ActionResult<PostResponse>> Update(Guid id, [FromBody] PostRequest req)
    {
        if (string.IsNullOrWhiteSpace(req.Title))
            return ValidationProblem("A post title is required.");

        for (var attempt = 0; attempt < 2; attempt++)
        {
            var post = await _db.Posts.FindAsync(id);
            if (post is null)
                return NotFound();

            post.Title = req.Title;
            post.Version++;
            try
            {
                await _db.SaveChangesAsync();
                return Ok(ToDto(post));
            }
            catch (DbUpdateConcurrencyException)
            {
                _db.Entry(post).State = EntityState.Detached;
            }
        }

        var fresh = await _db.Posts.FindAsync(id);
        return fresh is null ? NotFound() : Ok(ToDto(fresh));
    }

    [HttpDelete("api/posts/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        for (var attempt = 0; attempt < 2; attempt++)
        {
            var post = await _db.Posts.FindAsync(id);
            if (post is null)
                return NotFound();

            _db.Posts.Remove(post);
            try
            {
                await _db.SaveChangesAsync();
                return NoContent();
            }
            catch (DbUpdateConcurrencyException)
            {
                _db.Entry(post).State = EntityState.Detached;
            }
        }

        return await _db.Posts.FindAsync(id) is null ? NotFound() : StatusCode(409);
    }
}
```

A few details worth noting:

- `GET` on a post increments `Views` with a raw `UPDATE ... SET Views = Views + 1` — atomic under concurrency (SQLite serializes writers) and doesn't trip the concurrency token.
- `Version` is bumped manually on each `PUT` so a lost update between read and write throws `DbUpdateConcurrencyException`, which the retry loop absorbs.
- On `POST` a `DbUpdateException` that isn't a duplicate-PK is treated as a missing-blog FK violation → `404` for posts.
- `AppSetup.ConfigureServices` registers only the `DbContext`; the grader adds/maps the controllers itself.

