// BlogsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/blogs")]
public class BlogsController : ControllerBase
{
    private readonly BlogDbContext _db;

    public BlogsController(BlogDbContext db) => _db = db;

    private static BlogDto ToDto(Blog b) => new(b.Id, b.Name);

    [HttpPost]
    public async Task<ActionResult<BlogDto>> Create([FromBody] BlogInput input)
    {
        // Idempotent on client-supplied id: retries return the existing resource.
        if (input.Id is Guid requestedId)
        {
            var existing = await _db.Blogs.FindAsync(requestedId);
            if (existing is not null)
                return Ok(ToDto(existing));
        }

        if (string.IsNullOrWhiteSpace(input.Name))
            return BadRequest();

        var blog = new Blog { Id = input.Id ?? Guid.NewGuid(), Name = input.Name };
        _db.Blogs.Add(blog);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException) when (input.Id is not null)
        {
            // Concurrent insert of the same id — return what won the race.
            var winner = await _db.Blogs.FindAsync(input.Id!.Value);
            if (winner is not null)
            {
                _db.Entry(blog).State = EntityState.Detached;
                return Ok(ToDto(winner));
            }
            throw;
        }

        return CreatedAtAction(nameof(Get), new { id = blog.Id }, ToDto(blog));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<BlogDto>> Get(Guid id)
    {
        var blog = await _db.Blogs.FindAsync(id);
        return blog is null ? NotFound() : Ok(ToDto(blog));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<BlogDto>> Update(Guid id, [FromBody] BlogInput input)
    {
        if (string.IsNullOrWhiteSpace(input.Name))
            return BadRequest();

        var blog = await _db.Blogs.FindAsync(id);
        if (blog is null)
            return NotFound();

        blog.Name = input.Name;
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateConcurrencyException)
        {
            if (!await _db.Blogs.AnyAsync(b => b.Id == id))
                return NotFound();
            throw;
        }

        return Ok(ToDto(blog));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        // Idempotent delete: deleting a missing blog is a successful no-op.
        var blog = await _db.Blogs.FindAsync(id);
        if (blog is null)
            return NoContent();

        _db.Blogs.Remove(blog);
        await _db.SaveChangesAsync();
        return NoContent();
    }

    [HttpPost("{blogId:guid}/posts")]
    public async Task<ActionResult<PostDto>> CreatePost(Guid blogId, [FromBody] PostInput input)
    {
        var blog = await _db.Blogs.FindAsync(blogId);
        if (blog is null)
            return NotFound();

        if (input.Id is Guid requestedId)
        {
            var existing = await _db.Posts.FindAsync(requestedId);
            if (existing is not null)
            {
                if (existing.BlogId != blogId)
                    return Conflict();
                return Ok(PostsController.ToDto(existing));
            }
        }

        if (string.IsNullOrWhiteSpace(input.Title))
            return BadRequest();

        var post = new Post
        {
            Id = input.Id ?? Guid.NewGuid(),
            BlogId = blogId,
            Title = input.Title,
            Views = 0
        };
        _db.Posts.Add(post);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException) when (input.Id is not null)
        {
            var winner = await _db.Posts.FindAsync(input.Id!.Value);
            if (winner is not null && winner.BlogId == blogId)
            {
                _db.Entry(post).State = EntityState.Detached;
                return Ok(PostsController.ToDto(winner));
            }
            throw;
        }

        return CreatedAtAction(
            actionName: nameof(PostsController.Get),
            controllerName: "Posts",
            routeValues: new { id = post.Id },
            value: PostsController.ToDto(post));
    }
}
