```csharp
// BlogsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/blogs")]
public class BlogsController : ControllerBase
{
    private readonly AppDbContext _db;

    public BlogsController(AppDbContext db) => _db = db;

    [HttpPost]
    public async Task<ActionResult<BlogDto>> Create([FromBody] BlogDto dto)
    {
        // Idempotent under client retries: if the id was already created, return it.
        var existing = await _db.Blogs.FindAsync(dto.Id);
        if (existing is not null)
            return Ok(ToDto(existing));

        var blog = new Blog { Id = dto.Id == Guid.Empty ? Guid.NewGuid() : dto.Id, Name = dto.Name };
        _db.Blogs.Add(blog);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            // Concurrent create with the same id won; treat as success.
            var winner = await _db.Blogs.AsNoTracking().FirstOrDefaultAsync(b => b.Id == blog.Id);
            if (winner is not null)
                return Ok(ToDto(winner));
            throw;
        }
        return CreatedAtAction(nameof(Get), new { id = blog.Id }, ToDto(blog));
    }

    [HttpGet("{id}")]
    public async Task<ActionResult<BlogDto>> Get(Guid id)
    {
        var blog = await _db.Blogs.FindAsync(id);
        return blog is null ? NotFound() : Ok(ToDto(blog));
    }

    [HttpPut("{id}")]
    public async Task<ActionResult<BlogDto>> Update(Guid id, [FromBody] BlogDto dto)
    {
        var blog = await _db.Blogs.FindAsync(id);
        if (blog is null)
            return NotFound();
        blog.Name = dto.Name;
        await SaveIgnoringConcurrencyAsync();
        var fresh = await _db.Blogs.AsNoTracking().FirstAsync(b => b.Id == id);
        return Ok(ToDto(fresh));
    }

    [HttpDelete("{id}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var blog = await _db.Blogs.FindAsync(id);
        if (blog is null)
            return NotFound();
        _db.Blogs.Remove(blog);
        await SaveIgnoringConcurrencyAsync();
        return NoContent();
    }

    // A concurrent update/delete may have already committed; last-writer-wins
    // is acceptable and a retried request should see a successful result.
    private async Task SaveIgnoringConcurrencyAsync()
    {
        try { await _db.SaveChangesAsync(); }
        catch (DbUpdateConcurrencyException) { }
    }

    private static BlogDto ToDto(Blog b) => new() { Id = b.Id, Name = b.Name };
}
