// PostsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
public class PostsController : ControllerBase
{
    private readonly AppDbContext _db;

    public PostsController(AppDbContext db) => _db = db;

    [HttpPost("api/blogs/{blogId}/posts")]
    public async Task<ActionResult<PostDto>> Create(Guid blogId, [FromBody] PostDto dto)
    {
        if (await _db.Blogs.FindAsync(blogId) is null)
            return NotFound();

        // Idempotent under client retries: same id returns the existing post.
        var existing = await _db.Posts.FindAsync(dto.Id);
        if (existing is not null)
            return existing.BlogId == blogId ? Ok(ToDto(existing)) : Conflict();

        var post = new Post
        {
            Id = dto.Id == Guid.Empty ? Guid.NewGuid() : dto.Id,
            BlogId = blogId,
            Title = dto.Title,
            Views = 0 // server-maintained; client input ignored
        };
        _db.Posts.Add(post);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            var winner = await _db.Posts.AsNoTracking().FirstOrDefaultAsync(p => p.Id == post.Id);
            if (winner is not null)
                return winner.BlogId == blogId ? Ok(ToDto(winner)) : Conflict();
            throw;
        }
        return CreatedAtAction(nameof(Get), new { id = post.Id }, ToDto(post));
    }

    [HttpGet("api/posts/{id}")]
    public async Task<ActionResult<PostDto>> Get(Guid id)
    {
        var post = await _db.Posts.FindAsync(id);
        if (post is null)
            return NotFound();

        // Server maintains the view counter.
        post.Views++;
        try { await _db.SaveChangesAsync(); }
        catch (DbUpdateConcurrencyException)
        {
            var fresh = await _db.Posts.AsNoTracking().FirstOrDefaultAsync(p => p.Id == id);
            if (fresh is null) return NotFound();
            return Ok(ToDto(fresh));
        }
        return Ok(ToDto(post));
    }

    [HttpPut("api/posts/{id}")]
    public async Task<ActionResult<PostDto>> Update(Guid id, [FromBody] PostDto dto)
    {
        var post = await _db.Posts.FindAsync(id);
        if (post is null)
            return NotFound();
        post.Title = dto.Title; // Views and BlogId are not client-editable
        try { await _db.SaveChangesAsync(); }
        catch (DbUpdateConcurrencyException) { }
        var fresh = await _db.Posts.AsNoTracking().FirstOrDefaultAsync(p => p.Id == id);
        return fresh is null ? NotFound() : Ok(ToDto(fresh));
    }

    [HttpDelete("api/posts/{id}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var post = await _db.Posts.FindAsync(id);
        if (post is null)
            return NotFound();
        _db.Posts.Remove(post);
        try { await _db.SaveChangesAsync(); }
        catch (DbUpdateConcurrencyException) { }
        return NoContent();
    }

    private static PostDto ToDto(Post p) => new() { Id = p.Id, BlogId = p.BlogId, Title = p.Title };
}
```

Notes on the design:

- `AppSetup.ConfigureServices` registers `AppDbContext` with the given SQLite connection string; the grader maps controllers and calls `EnsureCreated()`.
- `Post.Views` is initialized to 0, never read from request bodies, and incremented on `GET /api/posts/{id}`.
- Retry-safety: `POST` honors a client-supplied `id` and returns the existing entity on a duplicate instead of erroring, so a retried create is safe. `PUT`/`DELETE` are naturally idempotent.
- Concurrency: `DbUpdateConcurrencyException` is swallowed where last-writer-wins is fine, and the entity is re-read so responses reflect committed state. Controllers return DTOs, so the `Blog.Posts` navigation never leaks into JSON.

