// File: Representation.cs
using System;
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public static class Representation
{
    public static string CanonicalBlog(Guid id, string name)
        => "{\"id\":" + Q(id) + ",\"name\":" + Str(name) + "}";

    public static string CanonicalPost(Guid id, Guid blogId, string title)
        => "{\"id\":" + Q(id) + ",\"blogId\":" + Q(blogId) + ",\"title\":" + Str(title) + "}";

    public static string ETagOf(string canonical)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return "\"" + Convert.ToBase64String(hash)
            .TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    private static string Q(Guid g) => "\"" + g.ToString("d") + "\""; // lowercase

    private static string Str(string s)
    {
        var sb = new StringBuilder();
        sb.Append('"');
        foreach (var c in s.Normalize(NormalizationForm.FormC))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < ' ') sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
        return sb.ToString();
    }
}
