    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id,
        [FromBody, Required] BlogRequest? body,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        CancellationToken ct)
    {
        if (body?.Id is null || body.Id == Guid.Empty || body.Name is null) return Prob(400);
        if (body.Id.Value != id) return Prob(400);

        var blog = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null) return Prob(404);
        if (blog.DeletedAt is not null) return Prob(410);

        var newHash = Representation.ETagOf(Representation.CanonicalBlog(id, body.Name));
        if (blog.ETag == newHash) { Response.Headers.ETag = blog.ETag; return NoContent(); }

        if (ifMatch is null) return Prob(428);
        if (!IsStar(ifMatch) && ifMatch != blog.ETag)
        { Response.Headers.ETag = blog.ETag; return Prob(412); }

        blog.Name = body.Name;
        var old = blog.ETag;
        blog.ETag = newHash;
        _db.Entry(blog).Property(b => b.ETag).OriginalValue = old;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await _db.Blogs.IgnoreQueryFilters()
                .Where(b => b.PublicId == id).Select(b => b.ETag).FirstOrDefaultAsync(ct);
            Response.Headers.ETag = cur ?? newHash;
            return Prob(412);
        }
        Response.Headers.ETag = newHash;
        return NoContent();
    }

