        var blog = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null || blog.DeletedAt is not null) return NoContent();
        if (!IsStar(ifMatch) && ifMatch != blog.ETag)
        { Response.Headers.ETag = blog.ETag; return Prob(412); }

        await using var tx = await _db.Database.BeginTransactionAsync(ct);
        var now = DateTime.UtcNow;
        var posts = await _db.Posts.Where(p => p.BlogId == blog.Id).ToListAsync(ct);
        foreach (var p in posts)
        {
            p.DeletedAt = now;
            p.ETag = Representation.ETagOf(Representation.CanonicalPost(p.PublicId, blog.PublicId, p.Title) + "|del|" + now.Ticks);
        }
        blog.DeletedAt = now;
        var old = blog.ETag;
        blog.ETag = Representation.ETagOf(Representation.CanonicalBlog(blog.PublicId, blog.Name) + "|del|" + now.Ticks);
        _db.Entry(blog).Property(b => b.ETag).OriginalValue = old;
        try
        {
            await _db.SaveChangesAsync(ct);
            await tx.CommitAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Prob(412);
        }
        return NoContent();
    }
