public static class CanonicalJson
{
    public static void WriteString(StringBuilder sb, string value)
    {
        var s = (value ?? "").Normalize(NormalizationForm.FormC);
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < ' ') sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }

    public static string Blog(Guid id, string name)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("d")).Append("\",\"name\":");
        WriteString(sb, name);
        sb.Append('}');
        return sb.ToString();
    }

    public static string Post(Guid id, Guid blogId, string title)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("d"))
          .Append("\",\"blogId\":\"").Append(blogId.ToString("d"))
          .Append("\",\"title\":");
        WriteString(sb, title);
        sb.Append('}');
        return sb.ToString();
    }
}

public static class ETags
{
    public static string Compute(string canonicalJson)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson));
        var b64 = Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + b64 + "\"";
    }

    public static bool Matches(string? headerValue, string current)
    {
        if (string.IsNullOrWhiteSpace(headerValue)) return false;
        foreach (var part in headerValue.Split(','))
        {
            var t = part.Trim();
            if (t == "*" || string.Equals(t, current, StringComparison.Ordinal)) return true;
        }
        return false;
    }
}
