// File: BlogsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/blogs")]
public class BlogsController : ControllerBase
{
    private readonly AppDbContext _db;
    public BlogsController(AppDbContext db) => _db = db;

    internal static bool IsUniqueViolation(DbUpdateException ex) =>
        ex.InnerException is SqliteException s && s.SqliteErrorCode == 19;

    internal ObjectResult Error(int status, string title) =>
        (ObjectResult)Problem(statusCode: status, title: title);

    [HttpPost]
    [Consumes("application/json")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] BlogRequest body, CancellationToken ct)
    {
        if (body?.Id is null || body.Name is null)
            return Error(400, "A valid body with id and name is required.");

        var hash = ETags.Compute(CanonicalJson.Blog(body.Id.Value, body.Name));
        var blog = new Blog { Id = body.Id.Value, Name = body.Name, ETag = hash, CreateHash = hash };
        _db.Blogs.Add(blog);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (IsUniqueViolation(ex))
        {
            _db.Entry(blog).State = EntityState.Detached;
            var existing = await _db.Blogs.IgnoreQueryFilters()
                .FirstOrDefaultAsync(b => b.Id == body.Id.Value, ct);
            if (existing!.DeletedAt != null)
                return Error(410, "A blog with this id existed and was deleted.");
            if (existing.CreateHash != hash)
                return Error(409, "A different blog already uses this id.");
            Response.Headers.ETag = existing.ETag;
            return Ok(ToResponse(existing));
        }

        Response.Headers.ETag = blog.ETag;
        return Created($"/api/blogs/{blog.Id}", ToResponse(blog));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var blog = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.Id == id, ct);
        if (blog is null) return Error(404, "Blog not found.");
        if (blog.DeletedAt != null) return Error(410, "Blog was deleted.");

        Response.Headers.ETag = blog.ETag;
        if (ETags.Matches(Request.Headers.IfNoneMatch, blog.ETag))
            return StatusCode(304);
        return Ok(ToResponse(blog));
    }

    [HttpPut("{id:guid}")]
    [Consumes("application/json")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(
        Guid id,
        [FromBody] BlogRequest body,
        [FromHeader(Name = "If-Match")] string ifMatch,
        CancellationToken ct)
    {
        if (body?.Id is null || body.Name is null || body.Id.Value != id)
            return Error(400, "Body is invalid or its id does not match the route.");

        var blog = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.Id == id, ct);
        if (blog is null) return Error(404, "Blog not found.");
        if (blog.DeletedAt != null) return Error(410, "Blog was deleted.");

        if (string.IsNullOrWhiteSpace(ifMatch))
            return Error(428, "The If-Match header is required.");

        var newHash = ETags.Compute(CanonicalJson.Blog(id, body.Name));
        if (newHash == blog.ETag)
        {
            Response.Headers.ETag = blog.ETag;
            return NoContent();
        }
        if (!ETags.Matches(ifMatch, blog.ETag))
        {
            Response.Headers.ETag = blog.ETag;
            return Error(412, "ETag precondition failed.");
        }

        blog.Name = body.Name;
        blog.ETag = newHash;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await _db.Blogs.IgnoreQueryFilters()
                .Where(b => b.Id == id).Select(b => new { b.ETag, b.DeletedAt })
                .FirstOrDefaultAsync(ct);
            if (current is null) return Error(404, "Blog not found.");
            if (current.DeletedAt != null) return Error(410, "Blog was deleted.");
            Response.Headers.ETag = current.ETag;
            return Error(412, "ETag precondition failed.");
        }

        Response.Headers.ETag = newHash;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [FromHeader(Name = "If-Match")] string ifMatch,
        CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Error(428, "The If-Match header is required.");

        var blog = await _db.Blogs.IgnoreQueryFilters()
            .Include(b => b.Posts)
            .FirstOrDefaultAsync(b => b.Id == id, ct);
        if (blog is null || blog.DeletedAt != null)
            return NoContent();

        if (!ETags.Matches(ifMatch, blog.ETag))
        {
            Response.Headers.ETag = blog.ETag;
            return Error(412, "ETag precondition failed.");
        }

        var now = DateTimeOffset.UtcNow;
        blog.DeletedAt = now;
        foreach (var p in blog.Posts.Where(p => p.DeletedAt == null))
            p.DeletedAt = now;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Error(412, "ETag precondition failed.");
        }
        return NoContent();
    }

    internal static BlogResponse ToResponse(Blog b) =>
        new() { Id = b.Id, Name = b.Name };
}
