            return Error(400, "A valid body with id, blogId and title is required.");
        if (body.BlogId != blogId)
            return Error(400, "The body blogId must equal the blog in the route.");

        var blog = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.Id == blogId, ct);
        if (blog is null) return Error(404, "Blog not found.");
        if (blog.DeletedAt != null) return Error(410, "Blog was deleted.");

        var hash = ETags.Compute(CanonicalJson.Post(body.Id.Value, blogId, body.Title));
        var post = new Post
        {
            Id = body.Id.Value,
            BlogKey = blog.Key,
            Title = body.Title,
            ETag = hash,
            CreateHash = hash
        };
