                .Include(p => p.Blog)
                .FirstOrDefaultAsync(p => p.Id == body.Id.Value, ct);
            if (existing!.DeletedAt != null)
                return Error(410, "A post with this id existed and was deleted.");
            if (existing.CreateHash != hash)
                return Error(409, "A different post already uses this id.");
            Response.Headers.ETag = existing.ETag;
            return Ok(ToResponse(existing));
        }

        Response.Headers.ETag = post.ETag;
        return Created($"/api/posts/{post.Id}", ToResponse(post));
