        if (post.Blog.Id != body.BlogId.Value)
            return Error(409, "A post cannot be moved to another blog.");

        var newHash = ETags.Compute(CanonicalJson.Post(id, body.BlogId.Value, body.Title));
        if (newHash == post.ETag)
        {
