        catch (DbUpdateConcurrencyException)
        {
            var current = await _db.Posts.IgnoreQueryFilters()
                .Where(p => p.Id == id).Select(p => new { p.ETag, p.DeletedAt })
                .FirstOrDefaultAsync(ct);
            if (current is null) return Error(404, "Post not found.");
            if (current.DeletedAt != null) return Error(410, "Post was deleted.");
            Response.Headers.ETag = current.ETag;
            return Error(412, "ETag precondition failed.");
        }

        Response.Headers.ETag = newHash;
        return NoContent();
    }

