            .FirstOrDefaultAsync(p => p.Id == id, ct);
        if (post is null || post.DeletedAt != null)
            return NoContent();

        if (!ETags.Matches(ifMatch, post.ETag))
        {
            Response.Headers.ETag = post.ETag;
            return Error(412, "ETag precondition failed.");
        }

        post.DeletedAt = DateTimeOffset.UtcNow;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Error(412, "ETag precondition failed.");
        }
        return NoContent();
    }

    internal static PostResponse ToResponse(Post p) =>
        new() { Id = p.Id, BlogId = p.Blog.Id, Title = p.Title };
}
