```csharp
// ETagger.cs
using System.Security.Cryptography;
using System.Text;

public static class ETagger
{
    private static string Esc(string s)
    {
        s = s.Normalize(NormalizationForm.FormC);
        var sb = new StringBuilder(s.Length + 8);
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < ' ')
                        sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else
                        sb.Append(c);
                    break;
            }
        }
        return sb.ToString();
    }

    public static string Hash(string canonical)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return "\"" + Convert.ToBase64String(bytes)
            .TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    public static string BlogCanonical(Guid id, string name) =>
        "{\"id\":\"" + id + "\",\"name\":\"" + Esc(name) + "\"}";

    public static string PostCanonical(Guid id, Guid blogId, string title) =>
        "{\"id\":\"" + id + "\",\"blogId\":\"" + blogId + "\",\"title\":\"" + Esc(title) + "\"}";

    public static string BlogETag(Guid id, string name) => Hash(BlogCanonical(id, name));
    public static string PostETag(Guid id, Guid blogId, string title) => Hash(PostCanonical(id, blogId, title));

    public static bool Matches(string header, string current)
    {
        foreach (var t in header.Split(','))
        {
            var v = t.Trim();
            if (v == "*") return true;
            if (v.StartsWith("W/", StringComparison.Ordinal)) v = v[2..];
            if (v == current) return true;
        }
        return false;
    }
}
