// Controllers.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

[ApiController]
public abstract class CrudControllerBase : ControllerBase
{
    protected static bool IsUniqueViolation(DbUpdateException ex) =>
        ex.InnerException is SqliteException s && s.SqliteErrorCode == 19;

    protected ObjectResult Error(int status, string title) =>
        Problem(statusCode: status, title: title);

    protected bool IfNoneMatchHits(string etag) =>
        Request.Headers.TryGetValue("If-None-Match", out var h) &&
        !string.IsNullOrEmpty(h) && ETagger.Matches(h!, etag);
}

[ApiController]
[Route("api/blogs")]
public class BlogsController : CrudControllerBase
{
    private readonly AppDbContext _db;
    public BlogsController(AppDbContext db) => _db = db;

