    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] BlogInput? body, CancellationToken ct)
    {
        if (body is null || !body.Id.HasValue || body.Name is null)
            return Error(400, "Invalid request body.");
        var etag = ETagger.BlogETag(body.Id.Value, body.Name);
        var blog = new Blog { Id = body.Id.Value, Name = body.Name, ETag = etag, CreateHash = etag };
        _db.Blogs.Add(blog);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (IsUniqueViolation(ex))
        {
            _db.Entry(blog).State = EntityState.Detached;
            var existing = await _db.Blogs.IgnoreQueryFilters()
                .FirstOrDefaultAsync(b => b.Id == body.Id.Value, ct);
            if (existing is null) return Error(409, "Conflict.");
            if (existing.DeletedAt is not null) return Error(410, "Resource is gone.");
            if (existing.CreateHash != etag) return Error(409, "Conflict.");
            Response.Headers.ETag = existing.ETag;
            return Ok(Rep(existing));
        }
        Response.Headers.ETag = etag;
        return CreatedAtAction(nameof(Get), new { id = blog.Id }, Rep(blog));
    }

    [HttpGet("{id}")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var b = await _db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.Id == id, ct);
        if (b is null) return Error(404, "Not found.");
        if (b.DeletedAt is not null) return Error(410, "Resource is gone.");
        Response.Headers.ETag = b.ETag;
        if (IfNoneMatchHits(b.ETag)) return StatusCode(304);
        return Ok(Rep(b));
    }

    [HttpPut("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromBody] BlogInput? body,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken ct)
    {
        if (body is null || !body.Id.HasValue || body.Name is null || body.Id.Value != id)
            return Error(400, "Invalid request body.");
        if (string.IsNullOrEmpty(ifMatch)) return Error(428, "If-Match header is required.");
        var b = await _db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.Id == id, ct);
        if (b is null) return Error(404, "Not found.");
        if (b.DeletedAt is not null) return Error(410, "Resource is gone.");
        var newEtag = ETagger.BlogETag(id, body.Name);
        if (newEtag == b.ETag) return NoContent();
        if (!ETagger.Matches(ifMatch, b.ETag))
        {
            Response.Headers.ETag = b.ETag;
            return Error(412, "Precondition failed.");
        }
        b.Name = body.Name;
        b.ETag = newEtag;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.Entry(b).State = EntityState.Detached;
            var cur = await _db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.Id == id, ct);
            if (cur is not null) Response.Headers.ETag = cur.ETag;
            return Error(412, "Precondition failed.");
        }
        Response.Headers.ETag = newEtag;
        return NoContent();
    }

    [HttpDelete("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch)) return Error(428, "If-Match header is required.");
        var b = await _db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.Id == id, ct);
        if (b is null || b.DeletedAt is not null) return NoContent();
        if (!ETagger.Matches(ifMatch, b.ETag))
        {
            Response.Headers.ETag = b.ETag;
            return Error(412, "Precondition failed.");
        }
        var now = DateTimeOffset.UtcNow;
        var posts = await _db.Posts.IgnoreQueryFilters()
            .Where(p => p.BlogKey == b.Key && p.DeletedAt == null).ToListAsync(ct);
        b.DeletedAt = now;
        b.ETag = ETagger.Hash(ETagger.BlogCanonical(b.Id, b.Name) + "|deleted");
        foreach (var p in posts)
        {
            p.DeletedAt = now;
            p.ETag = ETagger.Hash(ETagger.PostCanonical(p.Id, p.BlogId, p.Title) + "|deleted");
        }
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Error(412, "Precondition failed.");
        }
        return NoContent();
    }
}

