            return Error(400, "Invalid request body.");
        if (string.IsNullOrEmpty(ifMatch)) return Error(428, "If-Match header is required.");
        var p = await _db.Posts.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.Id == id, ct);
        if (p is null) return Error(404, "Not found.");
        if (p.DeletedAt is not null) return Error(410, "Resource is gone.");
        if (body.BlogId.Value != p.BlogId) return Error(409, "Conflict.");
        var newEtag = ETagger.PostETag(id, p.BlogId, body.Title);
        if (newEtag == p.ETag) return NoContent();
        if (!ETagger.Matches(ifMatch, p.ETag))
        {
            Response.Headers.ETag = p.ETag;
            return Error(412, "Precondition failed.");
        }
        p.Title = body.Title;
        p.ETag = newEtag;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.Entry(p).State = EntityState.Detached;
            var cur = await _db.Posts.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.Id == id, ct);
            if (cur is not null) Response.Headers.ETag = cur.ETag;
            return Error(412, "Precondition failed.");
        }
        Response.Headers.ETag = newEtag;
        return NoContent();
    }

    [HttpDelete("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch)) return Error(428, "If-Match header is required.");
        var p = await _db.Posts.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.Id == id, ct);
        if (p is null || p.DeletedAt is not null) return NoContent();
        if (!ETagger.Matches(ifMatch, p.ETag))
        {
            Response.Headers.ETag = p.ETag;
            return Error(412, "Precondition failed.");
        }
        p.DeletedAt = DateTimeOffset.UtcNow;
        p.ETag = ETagger.Hash(ETagger.PostCanonical(p.Id, p.BlogId, p.Title) + "|deleted");
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Error(412, "Precondition failed.");
        }
        return NoContent();
    }
}
```

Key design points:

- **ETag** is the quoted base64url SHA-256 of the canonical representation (`id` + `blogId` for posts + writable fields), with the specified escaping rules and NFC normalization. `Views` never participates.
- **Idempotent create**: insert-first, classify the SQLite `SQLITE_CONSTRAINT` (19) violation — tombstoned → 410, `CreateHash` match → 200 replay, otherwise → 409. `CreateHash` is `AfterSaveBehavior.Throw` so it can never change.
- **Concurrency**: the stored `ETag` column is the EF concurrency token; every mutation writes a new ETag, so a racing writer hits `DbUpdateConcurrencyException` → 412, never 5xx.
- **Tombstones**: `DeletedAt` + `HasQueryFilter`; lookups use `IgnoreQueryFilters` to distinguish 404 from 410. Blog delete soft-deletes its posts in the same `SaveChanges` transaction.
- **PUT ordering**: body validation → 428 → 404/410 → (post blog move → 409) → already-applied → 204 → If-Match → 412/update.
- **Views** is incremented with raw SQL so it never touches the concurrency token.

