// ETags.cs
using System.Security.Cryptography;
using System.Text;

namespace BlogApi;

public static class ETagging
{
    public static string Base64UrlSha256(string s)
    {
        var b64 = Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(s)));
        return b64.TrimEnd('=').Replace('+', '-').Replace('/', '_');
    }

    public static string ETag(string canonicalJson) => "\"" + Base64UrlSha256(canonicalJson) + "\"";

    // Canonical JSON: id, parent id, then client-writable fields, compact, lowercase GUIDs,
    // NFC strings, only quote/backslash/control chars escaped.
    public static string BlogCanonical(Guid id, string name)
        => "{\"id\":\"" + id.ToString("D") + "\",\"name\":" + JsonString(name) + "}";

    public static string PostCanonical(Guid id, Guid blogId, string title)
        => "{\"id\":\"" + id.ToString("D") + "\",\"blogId\":\"" + blogId.ToString("D")
           + "\",\"title\":" + JsonString(title) + "}";

    public static string JsonString(string s)
    {
        s = (s ?? "").Normalize(NormalizationForm.FormC);
        var sb = new StringBuilder(s.Length + 2);
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < ' ') sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
        return sb.ToString();
    }

    public static bool HeaderMatches(string? headerValue, string etag)
    {
        if (string.IsNullOrEmpty(headerValue)) return false;
        foreach (var raw in headerValue.Split(','))
        {
            var t = raw.Trim();
            if (t == "*") return true;
            if (t.StartsWith("W/", StringComparison.Ordinal)) t = t.Substring(2);
            if (t == etag) return true;
        }
        return false;
    }
}
