using System.Text.Json;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace BlogApi;

[ApiController]
[Route("api/blogs")]
[Produces("application/json")]
public class BlogsController : ControllerBase
{
    private readonly AppDbContext _db;
    public BlogsController(AppDbContext db) => _db = db;

    // ---------- POST /api/blogs ----------
    [HttpPost]
    [Consumes("application/json")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> CreateBlog([FromBody] JsonElement body, CancellationToken ct)
    {
        if (body.ValueKind != JsonValueKind.Object
            || !body.TryGetProperty("id", out var idEl) || idEl.ValueKind != JsonValueKind.String
            || !Guid.TryParse(idEl.GetString(), out var id)
            || !body.TryGetProperty("name", out var nameEl) || nameEl.ValueKind != JsonValueKind.String)
            return Problem(statusCode: 400);
        var name = nameEl.GetString()!;

        var canonical = ETagging.BlogCanonical(id, name);
        var hash = ETagging.Base64UrlSha256(canonical);
        var etag = "\"" + hash + "\"";

        var existing = await _db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (existing is { DeletedAt: not null }) return Problem(statusCode: 410);
        if (existing != null)
            return existing.CreateHash == hash ? OkBlog(existing) : Problem(statusCode: 409);

        var row = new Blog { PublicId = id, Name = name, ETag = etag, CreateHash = hash };
        _db.Blogs.Add(row);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.Entry(row).State = EntityState.Detached;
            var raced = await _db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == id, ct);
            if (raced == null) throw;
            if (raced.DeletedAt != null) return Problem(statusCode: 410);
            return raced.CreateHash == hash ? OkBlog(raced) : Problem(statusCode: 409);
        }

        Response.Headers.ETag = etag;
        return Created($"/api/blogs/{id}", new BlogResponse(row.PublicId, row.Name));
    }

    // ---------- GET /api/blogs/{id} ----------
    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> GetBlog(Guid id, CancellationToken ct)
    {
        var row = await _db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (row == null) return Problem(statusCode: 404);
        if (row.DeletedAt != null) return Problem(statusCode: 410);
        Response.Headers.ETag = row.ETag;
        if (ETagging.HeaderMatches(Request.Headers.IfNoneMatch, row.ETag)) return StatusCode(304);
        return Ok(new BlogResponse(row.PublicId, row.Name));
    }

    // ---------- PUT /api/blogs/{id} ----------
    [HttpPut("{id:guid}")]
    [Consumes("application/json")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> UpdateBlog(Guid id, [FromBody] JsonElement body,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken ct)
    {
        // Body validation first: 400 beats a missing If-Match.
        if (body.ValueKind != JsonValueKind.Object
            || !body.TryGetProperty("id", out var idEl) || idEl.ValueKind != JsonValueKind.String
            || !Guid.TryParse(idEl.GetString(), out var bodyId) || bodyId != id
            || !body.TryGetProperty("name", out var nameEl) || nameEl.ValueKind != JsonValueKind.String)
            return Problem(statusCode: 400);
        var name = nameEl.GetString()!;

        if (string.IsNullOrEmpty(ifMatch)) return Problem(statusCode: 428);

        var row = await _db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (row == null) return Problem(statusCode: 404);
        if (row.DeletedAt != null) return Problem(statusCode: 410);

        var newEtag = ETagging.ETag(ETagging.BlogCanonical(id, name));
        if (row.ETag == newEtag)                    // change already applied
        {
            Response.Headers.ETag = row.ETag;
            return NoContent();
        }
        if (!ETagging.HeaderMatches(ifMatch, row.ETag))
        {
            Response.Headers.ETag = row.ETag;
            return Problem(statusCode: 412);
        }

        row.Name = name;
        row.ETag = newEtag;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await Current412(id, ct);
        }
        Response.Headers.ETag = newEtag;
        return NoContent();
    }

    // ---------- DELETE /api/blogs/{id} ----------
    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> DeleteBlog(Guid id,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch)) return Problem(statusCode: 428);

        var row = await _db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (row == null || row.DeletedAt != null) return NoContent();
        if (!ETagging.HeaderMatches(ifMatch, row.ETag))
        {
            Response.Headers.ETag = row.ETag;
            return Problem(statusCode: 412);
        }

        row.DeletedAt = DateTimeOffset.UtcNow;
        await _db.Posts.Where(p => p.BlogId == row.Id)
            .ExecuteUpdateAsync(s => s.SetProperty(p => p.DeletedAt, row.DeletedAt), ct);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await Current412(id, ct);
        }
        return NoContent();
    }

    // ---------- POST /api/blogs/{blogId}/posts ----------
    [HttpPost("{blogId:guid}/posts")]
    [Consumes("application/json")]
    [ProducesResponseType(typeof(PostResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(PostResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> CreatePost(Guid blogId, [FromBody] JsonElement body, CancellationToken ct)
    {
        if (body.ValueKind != JsonValueKind.Object
            || !body.TryGetProperty("id", out var idEl) || idEl.ValueKind != JsonValueKind.String
            || !Guid.TryParse(idEl.GetString(), out var id)
            || !body.TryGetProperty("blogId", out var bEl) || bEl.ValueKind != JsonValueKind.String
            || !Guid.TryParse(bEl.GetString(), out var bodyBlogId) || bodyBlogId != blogId
            || !body.TryGetProperty("title", out var tEl) || tEl.ValueKind != JsonValueKind.String)
            return Problem(statusCode: 400);
        var title = tEl.GetString()!;

        var blog = await _db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == blogId, ct);
        if (blog == null) return Problem(statusCode: 404);
        if (blog.DeletedAt != null) return Problem(statusCode: 410);

        var canonical = ETagging.PostCanonical(id, blogId, title);
        var hash = ETagging.Base64UrlSha256(canonical);
        var etag = "\"" + hash + "\"";

        var existing = await _db.Posts.IgnoreQueryFilters().FirstOrDefaultAsync(p => p.PublicId == id, ct);
        if (existing is { DeletedAt: not null }) return Problem(statusCode: 410);
        if (existing != null)
            return existing.CreateHash == hash
                ? OkPost(existing, blogId)
                : Problem(statusCode: 409);

        var row = new Post { PublicId = id, BlogId = blog.Id, Title = title, ETag = etag, CreateHash = hash };
        _db.Posts.Add(row);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.Entry(row).State = EntityState.Detached;
            var raced = await _db.Posts.IgnoreQueryFilters().FirstOrDefaultAsync(p => p.PublicId == id, ct);
            if (raced == null) throw;
            if (raced.DeletedAt != null) return Problem(statusCode: 410);
            return raced.CreateHash == hash ? OkPost(raced, blogId) : Problem(statusCode: 409);
        }

        Response.Headers.ETag = etag;
        return Created($"/api/posts/{id}", new PostResponse(row.PublicId, blogId, row.Title));
    }

    // ---------- helpers ----------
    private IActionResult OkBlog(Blog b)
    {
        Response.Headers.ETag = b.ETag;
        return Ok(new BlogResponse(b.PublicId, b.Name));
    }

    private IActionResult OkPost(Post p, Guid blogPublicId)
    {
        Response.Headers.ETag = p.ETag;
        return Ok(new PostResponse(p.PublicId, blogPublicId, p.Title));
    }

    private async Task<IActionResult> Current412(Guid id, CancellationToken ct)
    {
        var cur = await _db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (cur != null) Response.Headers.ETag = cur.ETag;
        return Problem(statusCode: 412);
    }
