// ETagging.cs — canonical JSON + SHA-256 base64url ETag
using System.Buffers.Text;
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public static class ETagging
{
    public static string BlogETag(Guid id, string name) =>
        Quote(CanonicalHash(w => { w.Prop("id", id); w.Prop("name", name); }));

    public static string PostETag(Guid id, Guid blogId, string title) =>
        Quote(CanonicalHash(w => { w.Prop("id", id); w.Prop("blogId", blogId); w.Prop("title", title); }));

    public static string Quote(string base64url) => "\"" + base64url + "\"";

    public static string CanonicalHash(Action<Writer> write)
    {
        var sb = new StringBuilder("{");
        var w = new Writer(sb);
        write(w);
        sb.Append('}');
        var bytes = Encoding.UTF8.GetBytes(sb.ToString());
        return Base64Url.EncodeToString(SHA256.HashData(bytes));
    }

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var raw in header.Split(','))
        {
            var t = raw.Trim();
            if (t == "*") return true;
            if (t.StartsWith("W/", StringComparison.Ordinal)) t = t.Substring(2);
            if (string.Equals(t, etag, StringComparison.Ordinal)) return true;
        }
        return false;
    }

    public sealed class Writer
    {
        private readonly StringBuilder _sb;
        private bool _first = true;
        public Writer(StringBuilder sb) { _sb = sb; }

        private void Comma() { if (!_first) _sb.Append(','); _first = false; }

        public void Prop(string name, Guid value)
        {
            Comma();
            _sb.Append('"').Append(name).Append("\":\"");
            _sb.Append(value.ToString()); // lowercase 'd' format
            _sb.Append('"');
        }

        public void Prop(string name, string value)
        {
            Comma();
            _sb.Append('"').Append(name).Append("\":\"");
            Escape(_sb, value ?? "");
            _sb.Append('"');
        }

        private static void Escape(StringBuilder sb, string s)
        {
            foreach (var c in s.Normalize(NormalizationForm.FormC))
            {
                switch (c)
                {
                    case '"': sb.Append("\\\""); break;
                    case '\\': sb.Append("\\\\"); break;
                    case '\b': sb.Append("\\b"); break;
                    case '\f': sb.Append("\\f"); break;
                    case '\n': sb.Append("\\n"); break;
                    case '\r': sb.Append("\\r"); break;
                    case '\t': sb.Append("\\t"); break;
                    default:
                        if (c < 0x20)
                            sb.Append("\\u00").Append(((int)c).ToString("x2", CultureInfo.InvariantCulture));
                        else
                            sb.Append(c);
                        break;
                }
            }
        }
    }
}
