// BlogsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Primitives;

[ApiController]
[Route("api/blogs")]
public class BlogsController : ControllerBase
{
    private readonly AppDbContext _db;
    public BlogsController(AppDbContext db) => _db = db;

    private ObjectResult Problem(int status, string title) =>
        new ObjectResult(new ProblemDetails { Status = status, Title = title })
        { StatusCode = status, ContentTypes = { "application/problem+json" } };

    [HttpPost]
    [Consumes("application/json")]
    [Produces("application/json")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] BlogRequest body, CancellationToken ct)
    {
        if (body is null || body.Id is null || body.Name is null)
            return Problem(400, "Invalid body: 'id' and 'name' are required.");
        var id = body.Id.Value;
        var etag = ETagging.BlogETag(id, body.Name);
        var hash = etag.Trim('"');

        var blog = new Blog { PublicId = id, Name = body.Name, ETag = etag, CreateHash = hash };
        _db.Blogs.Add(blog);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.Entry(blog).State = EntityState.Detached;
            var existing = await _db.Blogs.IgnoreQueryFilters()
                .FirstOrDefaultAsync(b => b.PublicId == id, ct);
            if (existing is null) throw;
            if (existing.DeletedAt is not null)
                return Problem(410, "A blog with this id existed and was deleted.");
            if (existing.CreateHash != hash)
                return Problem(409, "A blog with this id exists with different content.");
            Response.Headers.ETag = existing.ETag;
            return Ok(new BlogResponse { Id = existing.PublicId, Name = existing.Name });
        }

        Response.Headers.ETag = etag;
        return Created($"/api/blogs/{id}", new BlogResponse { Id = id, Name = body.Name });
    }

    [HttpGet("{id:guid}")]
    [Produces("application/json")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var any = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (any is null) return Problem(404, "Blog not found.");
        if (any.DeletedAt is not null) return Problem(410, "Blog was deleted.");

        Response.Headers.ETag = any.ETag;
        if (ETagging.Matches(Request.Headers.IfNoneMatch, any.ETag))
            return StatusCode(304);
        return Ok(new BlogResponse { Id = any.PublicId, Name = any.Name });
    }

    [HttpPut("{id:guid}")]
    [Consumes("application/json")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id,
        [FromBody] BlogRequest body,
        [FromHeader(Name = "If-Match")] string ifMatch,
        CancellationToken ct)
    {
        if (body is null || body.Id is null || body.Name is null || body.Id.Value != id)
            return Problem(400, "Invalid body or body id differs from the route id.");
        if (StringValues.IsNullOrEmpty(ifMatch))
            return Problem(428, "If-Match header is required.");

        var any = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (any is null) return Problem(404, "Blog not found.");
        if (any.DeletedAt is not null) return Problem(410, "Blog was deleted.");

        var bodyHash = ETagging.CanonicalHash(w => { w.Prop("id", id); w.Prop("name", body.Name); });
        var currentHash = any.ETag.Trim('"');
        if (bodyHash == currentHash)
        {
            Response.Headers.ETag = any.ETag;
            return NoContent();
        }
        if (!ETagging.Matches(ifMatch, any.ETag))
        {
            Response.Headers.ETag = any.ETag;
            return Problem(412, "ETag does not match the current representation.");
        }

        var newEtag = ETagging.Quote(bodyHash);
        any.Name = body.Name;
        any.ETag = newEtag;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var latest = await _db.Blogs.IgnoreQueryFilters()
                .AsNoTracking().FirstOrDefaultAsync(b => b.PublicId == id, ct);
            if (latest is not null) Response.Headers.ETag = latest.ETag;
            return Problem(412, "ETag does not match the current representation.");
        }
        Response.Headers.ETag = newEtag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")] string ifMatch,
        CancellationToken ct)
    {
        if (StringValues.IsNullOrEmpty(ifMatch))
            return Problem(428, "If-Match header is required.");

        var blog = await _db.Blogs.Include(b => b.Posts)
            .FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null) return NoContent(); // unknown or already deleted

        if (!ETagging.Matches(ifMatch, blog.ETag))
        {
            Response.Headers.ETag = blog.ETag;
            return Problem(412, "ETag does not match the current representation.");
        }

        var now = DateTimeOffset.UtcNow;
        blog.DeletedAt = now;
        foreach (var p in blog.Posts) p.DeletedAt = now;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return NoContent();
        }
        return NoContent();
    }
}
