// File: ETags.cs — canonical JSON + SHA-256 base64url ETag computation and If-Match handling
using System.Security.Cryptography;
using System.Text;

public static class ETags
{
    // Canonical JSON: compact, lowercase GUIDs, NFC strings, minimal escaping.
    public static string Canonical(params (string Key, string Value)[] fields)
    {
        var sb = new StringBuilder("{");
        for (int i = 0; i < fields.Length; i++)
        {
            if (i > 0) sb.Append(',');
            sb.Append('"').Append(fields[i].Key).Append("\":\"");
            Escape(sb, fields[i].Value);
            sb.Append('"');
        }
        return sb.Append('}').ToString();
    }

    private static void Escape(StringBuilder sb, string s)
    {
        foreach (char c in s.Normalize(NormalizationForm.FormC))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
    }

    public static string Hash(string canonicalJson)
    {
        byte[] digest = SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson));
        return Convert.ToBase64String(digest).Replace('+', '-').Replace('/', '_').TrimEnd('=');
    }

    public static string BlogTag(Guid id, string name) =>
        Hash(Canonical(("id", id.ToString()), ("name", name)));

    public static string PostTag(Guid id, Guid blogId, string title) =>
        Hash(Canonical(("id", id.ToString()), ("blogId", blogId.ToString()), ("title", title)));

    public static string Quoted(string tag) => "\"" + tag + "\"";

    public static bool Matches(string? header, string currentTag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        string quoted = Quoted(currentTag);
        foreach (var part in header.Split(','))
        {
            var t = part.Trim();
            if (t == "*" || t.Equals(quoted, StringComparison.Ordinal)) return true;
            if (t.StartsWith("W/", StringComparison.Ordinal) &&
                t.Substring(2).Equals(quoted, StringComparison.Ordinal)) return true;
        }
        return false;
    }
}
