// File: BlogsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.ComponentModel.DataAnnotations;

[ApiController]
[Route("api/blogs")]
public class BlogsController : ControllerBase
{
    private readonly AppDbContext _db;
    public BlogsController(AppDbContext db) => _db = db;

    private ObjectResult Error(int status, string title) =>
        Problem(title: title, statusCode: status);

    private void SetETag(string tag) => Response.Headers.ETag = ETags.Quoted(tag);

    [HttpPost]
    [ProducesResponseType(typeof(BlogResponse), 201)]
    [ProducesResponseType(typeof(BlogResponse), 200)]
    [ProducesResponseType(typeof(ProblemDetails), 400, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 409, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    public async Task<IActionResult> Create([Required][FromBody] BlogBody? body, CancellationToken ct)
    {
        if (body is null || body.Id == Guid.Empty || body.Name is null)
            return Error(400, "Invalid request body.");

        string tag = ETags.BlogTag(body.Id, body.Name);
        var blog = new Blog { PublicId = body.Id, Name = body.Name, ETag = tag, CreateHash = tag };
        _db.Blogs.Add(blog);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.Entry(blog).State = EntityState.Detached;
            var existing = await _db.Blogs.IgnoreQueryFilters()
                .FirstOrDefaultAsync(b => b.PublicId == body.Id, ct);
            if (existing is null) throw;
            if (existing.DeletedAt is not null)
                return Error(410, "Blog is gone.");
            if (existing.CreateHash != tag)
                return Error(409, "A blog with this id already exists with different content.");
            SetETag(existing.ETag);
            return Ok(new BlogResponse { Id = existing.PublicId, Name = existing.Name });
        }

        SetETag(tag);
        return CreatedAtAction(nameof(Get), new { id = body.Id },
            new BlogResponse { Id = blog.PublicId, Name = blog.Name });
    }

    [HttpGet("{id}")]
    [ProducesResponseType(typeof(BlogResponse), 200)]
    [ProducesResponseType(304)]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var blog = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null) return Error(404, "Blog not found.");
        if (blog.DeletedAt is not null) return Error(410, "Blog is gone.");

        SetETag(blog.ETag);
        if (ETags.Matches(Request.Headers.IfNoneMatch, blog.ETag))
            return StatusCode(304);
        return Ok(new BlogResponse { Id = blog.PublicId, Name = blog.Name });
    }

    [HttpPut("{id}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 400, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 412, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 428, "application/problem+json")]
    public async Task<IActionResult> Update(
        Guid id,
        [Required][FromBody] BlogBody? body,
        [Required][FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken ct)
    {
        if (body is null || body.Id == Guid.Empty || body.Name is null || body.Id != id)
            return Error(400, "Invalid request body.");
        if (string.IsNullOrEmpty(ifMatch))
            return Error(428, "If-Match header is required.");

        var blog = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null) return Error(404, "Blog not found.");
        if (blog.DeletedAt is not null) return Error(410, "Blog is gone.");

        string newTag = ETags.BlogTag(id, body.Name);
        if (newTag == blog.ETag)
        {
            SetETag(blog.ETag);
            return NoContent();
        }
        if (!ETags.Matches(ifMatch, blog.ETag))
        {
            SetETag(blog.ETag);
            return Error(412, "Precondition failed.");
        }

        blog.Name = body.Name;
        blog.ETag = newTag;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await _db.Blogs.IgnoreQueryFilters()
                .FirstOrDefaultAsync(b => b.PublicId == id, CancellationToken.None);
            if (current is not null) SetETag(current.ETag);
            return Error(412, "Precondition failed.");
        }
        SetETag(newTag);
        return NoContent();
    }

    [HttpDelete("{id}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 412, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 428, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [Required][FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch))
            return Error(428, "If-Match header is required.");

        var blog = await _db.Blogs.IgnoreQueryFilters()
            .Include(b => b.Posts)
            .FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null || blog.DeletedAt is not null) return NoContent();

        if (!ETags.Matches(ifMatch, blog.ETag))
        {
            SetETag(blog.ETag);
            return Error(412, "Precondition failed.");
        }

        var now = DateTimeOffset.UtcNow;
        blog.DeletedAt = now;
        foreach (var post in blog.Posts)
            post.DeletedAt = now;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await _db.Blogs.IgnoreQueryFilters()
                .FirstOrDefaultAsync(b => b.PublicId == id, CancellationToken.None);
            if (current is not null) SetETag(current.ETag);
            return Error(412, "Precondition failed.");
        }
        return NoContent();
    }
}
