using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.ComponentModel.DataAnnotations;

[ApiController]
[Route("api")]
public class PostsController : ControllerBase
{
    private readonly AppDbContext _db;
    public PostsController(AppDbContext db) => _db = db;

    private ObjectResult Error(int status, string title) =>
        Problem(title: title, statusCode: status);

    private void SetETag(string tag) => Response.Headers.ETag = ETags.Quoted(tag);

    [HttpPost("blogs/{blogId}/posts")]
    [ProducesResponseType(typeof(PostResponse), 201)]
    [ProducesResponseType(typeof(PostResponse), 200)]
    [ProducesResponseType(typeof(ProblemDetails), 400, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 409, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    public async Task<IActionResult> Create(
        Guid blogId, [Required][FromBody] PostBody? body, CancellationToken ct)
    {
        if (body is null || body.Id == Guid.Empty || body.BlogId == Guid.Empty || body.Title is null)
            return Error(400, "Invalid request body.");
        if (body.BlogId != blogId)
            return Error(400, "Body blogId must match the route blog id.");

        var blog = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.PublicId == blogId, ct);
        if (blog is null) return Error(404, "Blog not found.");
        if (blog.DeletedAt is not null) return Error(410, "Blog is gone.");

        string tag = ETags.PostTag(body.Id, blogId, body.Title);
        var post = new Post
        {
            PublicId = body.Id,
            BlogId = blog.Id,
            Title = body.Title,
            ETag = tag,
            CreateHash = tag
        };
        _db.Posts.Add(post);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.Entry(post).State = EntityState.Detached;
            var existing = await _db.Posts.IgnoreQueryFilters()
                .Include(p => p.Blog)
                .FirstOrDefaultAsync(p => p.PublicId == body.Id, ct);
            if (existing is null) throw;
            if (existing.DeletedAt is not null)
                return Error(410, "Post is gone.");
            if (existing.CreateHash != tag)
                return Error(409, "A post with this id already exists with different content.");
            SetETag(existing.ETag);
            return Ok(new PostResponse
            {
                Id = existing.PublicId,
                BlogId = existing.Blog.PublicId,
                Title = existing.Title
            });
        }

        SetETag(tag);
        return CreatedAtAction(nameof(Get), new { id = body.Id },
            new PostResponse { Id = post.PublicId, BlogId = blogId, Title = post.Title });
    }

    [HttpGet("posts/{id}")]
    [ProducesResponseType(typeof(PostResponse), 200)]
    [ProducesResponseType(304)]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var post = await _db.Posts.IgnoreQueryFilters()
            .Include(p => p.Blog)
            .AsNoTracking()
            .FirstOrDefaultAsync(p => p.PublicId == id, ct);
        if (post is null) return Error(404, "Post not found.");
        if (post.DeletedAt is not null) return Error(410, "Post is gone.");

        SetETag(post.ETag);
        if (ETags.Matches(Request.Headers.IfNoneMatch, post.ETag))
            return StatusCode(304);

        // Server-maintained counter; never part of the representation or the ETag.
        await _db.Posts.Where(p => p.PublicId == id)
            .ExecuteUpdateAsync(s => s.SetProperty(p => p.Views, p => p.Views + 1), ct);

        return Ok(new PostResponse
        {
            Id = post.PublicId,
            BlogId = post.Blog.PublicId,
            Title = post.Title
        });
    }

    [HttpPut("posts/{id}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 400, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 404, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 409, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 410, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 412, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 428, "application/problem+json")]
    public async Task<IActionResult> Update(
        Guid id,
        [Required][FromBody] PostBody? body,
        [Required][FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken ct)
    {
        if (body is null || body.Id == Guid.Empty || body.BlogId == Guid.Empty ||
            body.Title is null || body.Id != id)
            return Error(400, "Invalid request body.");
        if (string.IsNullOrEmpty(ifMatch))
            return Error(428, "If-Match header is required.");

        var post = await _db.Posts.IgnoreQueryFilters()
            .Include(p => p.Blog)
            .FirstOrDefaultAsync(p => p.PublicId == id, ct);
        if (post is null) return Error(404, "Post not found.");
        if (post.DeletedAt is not null) return Error(410, "Post is gone.");

        if (body.BlogId != post.Blog.PublicId)
            return Error(409, "A post cannot be moved to another blog.");

        string newTag = ETags.PostTag(id, body.BlogId, body.Title);
        if (newTag == post.ETag)
        {
            SetETag(post.ETag);
            return NoContent();
        }
        if (!ETags.Matches(ifMatch, post.ETag))
        {
            SetETag(post.ETag);
            return Error(412, "Precondition failed.");
        }

        post.Title = body.Title;
        post.ETag = newTag;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await _db.Posts.IgnoreQueryFilters()
                .FirstOrDefaultAsync(p => p.PublicId == id, CancellationToken.None);
            if (current is not null) SetETag(current.ETag);
            return Error(412, "Precondition failed.");
        }
        SetETag(newTag);
        return NoContent();
    }

    [HttpDelete("posts/{id}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 412, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 428, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [Required][FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch))
            return Error(428, "If-Match header is required.");

        var post = await _db.Posts.IgnoreQueryFilters()
            .FirstOrDefaultAsync(p => p.PublicId == id, ct);
        if (post is null || post.DeletedAt is not null) return NoContent();

        if (!ETags.Matches(ifMatch, post.ETag))
        {
            SetETag(post.ETag);
            return Error(412, "Precondition failed.");
        }

        post.DeletedAt = DateTimeOffset.UtcNow;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await _db.Posts.IgnoreQueryFilters()
                .FirstOrDefaultAsync(p => p.PublicId == id, CancellationToken.None);
            if (current is not null) SetETag(current.ETag);
            return Error(412, "Precondition failed.");
        }
        return NoContent();
    }
}
