using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly AppDbContext _db;

    public SupportTicketsController(AppDbContext db) => _db = db;

    public sealed class TicketRequest
    {
        public Guid Id { get; set; }

        [Required]
        public string Subject { get; set; } = string.Empty;

        public int Priority { get; set; }
        public bool Escalated { get; set; }

        [Required]
        public string Category { get; set; } = string.Empty;
    }

    public sealed class TicketResponse
    {
        public Guid Id { get; set; }
        public string Subject { get; set; } = string.Empty;
        public int Priority { get; set; }
        public bool Escalated { get; set; }
        public string Category { get; set; } = string.Empty;
    }

    private static TicketResponse ToResponse(Ticket t) => new()
    {
        Id = t.Id,
        Subject = t.Subject,
        Priority = t.Priority,
        Escalated = t.Escalated,
        Category = t.Category
    };

    [HttpPost]
    public async Task<ActionResult<TicketResponse>> Create([FromBody] TicketRequest request)
    {
        var id = request.Id == Guid.Empty ? Guid.NewGuid() : request.Id;

        // Safe under client retries: if the ticket already exists, return it.
        var existing = await _db.Tickets.FindAsync(id);
        if (existing is not null)
            return Ok(ToResponse(existing));

        var ticket = new Ticket
        {
            Id = id,
            Subject = request.Subject,
            Priority = request.Priority,
            Escalated = request.Escalated,
            Category = request.Category,
            ViewCount = 0,
            LastViewedAt = null
        };

        _db.Tickets.Add(ticket);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            // Lost a concurrent insert race for the same id; return the winner.
            _db.Entry(ticket).State = EntityState.Detached;
            existing = await _db.Tickets.FindAsync(id);
            if (existing is not null)
                return Ok(ToResponse(existing));
            throw;
        }

        return CreatedAtAction(nameof(GetById), new { id = ticket.Id }, ToResponse(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> GetById(Guid id)
    {
        var ticket = await _db.Tickets.FindAsync(id);
        if (ticket is null)
            return NotFound();

        ticket.ViewCount++;
        ticket.LastViewedAt = DateTime.UtcNow;
        await _db.SaveChangesAsync();

        return Ok(ToResponse(ticket));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> Update(Guid id, [FromBody] TicketRequest request)
    {
        var ticket = await _db.Tickets.FindAsync(id);
