        if (ticket is null)
            return NotFound();

        ticket.Subject = req.Subject ?? ticket.Subject;
        ticket.Priority = req.Priority ?? ticket.Priority;
        ticket.Escalated = req.Escalated ?? ticket.Escalated;
        ticket.Category = req.Category ?? ticket.Category;

        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            if (!await _db.Tickets.AnyAsync(t => t.Id == id))
                return NotFound();
            throw;
        }

        return Ok(ToResponse(ticket));
