// SupportTicketsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly TicketsDbContext _db;

    public SupportTicketsController(TicketsDbContext db) => _db = db;

    private static TicketResponse ToResponse(Ticket t) =>
        new(t.Id, t.Subject, t.Priority, t.Escalated, t.Category, t.ViewCount, t.LastViewedAt);

    // POST is idempotent: a client retrying after a timeout sends the same id
    // (if it supplied one) and gets the already-created ticket back instead of
    // a duplicate. When no id is supplied the server generates one; safe
    // because the retry body is identical and the first insert wins by PK.
    [HttpPost]
    public async Task<ActionResult<TicketResponse>> Create(
        [FromBody] TicketCreateRequest request, CancellationToken ct)
    {
        var id = request.Id ?? Guid.NewGuid();

        var existing = await _db.Tickets.FindAsync(new object[] { id }, ct);
        if (existing is not null)
            return Ok(ToResponse(existing)); // retry of an already-committed create

        var ticket = new Ticket
        {
            Id = id,
            Subject = request.Subject,
            Priority = request.Priority,
            Escalated = request.Escalated,
            Category = request.Category,
            ViewCount = 0,
            LastViewedAt = null,
            ConcurrencyToken = Guid.NewGuid()
        };

        _db.Tickets.Add(ticket);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            // Lost the race with a concurrent insert of the same id.
            var winner = await _db.Tickets.FindAsync(new object[] { id }, ct);
            if (winner is not null)
                return Ok(ToResponse(winner));
            throw;
        }

        return CreatedAtAction(nameof(GetById), new { id = ticket.Id }, ToResponse(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> GetById(Guid id, CancellationToken ct)
    {
        // Retrying a read that also bumps ViewCount is safe: the increment is a
        // side effect of viewing and does not corrupt data.
        var ticket = await _db.Tickets.FindAsync(new object[] { id }, ct);
        if (ticket is null)
            return NotFound();

        ticket.ViewCount += 1;
        ticket.LastViewedAt = DateTime.UtcNow;
        ticket.ConcurrencyToken = Guid.NewGuid();
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            // Concurrent editor won; re-read the current state for the response.
            _db.Entry(ticket).State = EntityState.Detached;
            ticket = await _db.Tickets.FindAsync(new object[] { id }, ct);
            if (ticket is null)
                return NotFound();
        }

        return Ok(ToResponse(ticket));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> Update(
        Guid id, [FromBody] TicketWriteRequest request, CancellationToken ct)
    {
        // Retry the read-modify-write a few times so one editor's update is not
        // silently lost when two clients save at the same moment.
        for (var attempt = 0; attempt < 3; attempt++)
        {
            var ticket = await _db.Tickets.FindAsync(new object[] { id }, ct);
            if (ticket is null)
                return NotFound();

            ticket.Subject = request.Subject;
            ticket.Priority = request.Priority;
            ticket.Escalated = request.Escalated;
            ticket.Category = request.Category;
            ticket.ConcurrencyToken = Guid.NewGuid();

            try
            {
                await _db.SaveChangesAsync(ct);
                return Ok(ToResponse(ticket));
            }
            catch (DbUpdateConcurrencyException)
            {
                _db.Entry(ticket).State = EntityState.Detached;
            }
        }

        return Conflict();
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        for (var attempt = 0; attempt < 3; attempt++)
        {
            var ticket = await _db.Tickets.FindAsync(new object[] { id }, ct);
            if (ticket is null)
                return NotFound();

            _db.Tickets.Remove(ticket);
            try
            {
                await _db.SaveChangesAsync(ct);
                return NoContent();
            }
            catch (DbUpdateConcurrencyException)
            {
                _db.Entry(ticket).State = EntityState.Detached;
            }
        }

        return Conflict();
    }
}

