// ETags.cs — canonical JSON and ETag computation
using System.Buffers.Text;
using System.Security.Cryptography;
using System.Text;

public static class ETags
{
    private static string Esc(string s)
    {
        var n = s.Normalize(NormalizationForm.FormC);
        var sb = new StringBuilder(n.Length);
        foreach (var c in n)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.ToString();
    }

    private static string G(Guid g) => g.ToString("D");

    private static string Hash(string canonical)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return "\"" + Base64Url.EncodeToString(bytes) + "\"";
    }

    public static string ForBlog(Guid id, string name) =>
        Hash("{\"id\":\"" + G(id) + "\",\"name\":\"" + Esc(name) + "\"}");

    public static string ForPost(Guid id, Guid blogId, string title) =>
        Hash("{\"id\":\"" + G(id) + "\",\"blogId\":\"" + G(blogId) +
             "\",\"title\":\"" + Esc(title) + "\"}");
}
