// CrudControllerBase.cs — shared helpers
using Microsoft.AspNetCore.Mvc;

public abstract class CrudControllerBase : ControllerBase
{
    protected static bool ETagMatches(string? header, string etag, bool allowStar)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var raw in header.Split(','))
        {
            var t = raw.Trim();
            if (t.StartsWith("W/", StringComparison.Ordinal)) t = t[2..].Trim();
            if (allowStar && t == "*") return true;
            if (t == etag) return true;
        }
        return false;
    }

    protected bool IfMatchMatches(string? header, string etag) =>
        ETagMatches(header, etag, allowStar: true);

    protected bool IfNoneMatchMatches(string etag) =>
        ETagMatches(Request.Headers.IfNoneMatch.ToString(), etag, allowStar: true);

    protected IActionResult WithETag(IActionResult result, string etag)
    {
        Response.Headers.ETag = etag;
        return result;
    }

    protected IActionResult Problem(int status, string title)
    {
        var pd = new ProblemDetails { Status = status, Title = title };
        return new ObjectResult(pd)
        {
            StatusCode = status,
            ContentTypes = { "application/problem+json" }
        };
    }
}
