// BlogsController.cs
using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/blogs")]
public sealed class BlogsController : CrudControllerBase
{
    private readonly AppDbContext _db;
    public BlogsController(AppDbContext db) => _db = db;

    private static BlogResponse ToResponse(Blog b) =>
        new() { Id = b.PublicId, Name = b.Name };

    [HttpPost]
    [Consumes("application/json")]
    [Produces("application/json")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody][Required] BlogWriteRequest? req, CancellationToken ct)
    {
        if (req is null || !req.Id.HasValue || req.Id.Value == Guid.Empty || req.Name is null)
            return Problem(400, "Invalid request body.");

        var etag = ETags.ForBlog(req.Id.Value, req.Name);
        var blog = new Blog { PublicId = req.Id.Value, Name = req.Name, ETag = etag, CreateHash = etag };
        _db.Blogs.Add(blog);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.Entry(blog).State = EntityState.Detached;
            var existing = await _db.Blogs.IgnoreQueryFilters()
                .SingleOrDefaultAsync(b => b.PublicId == req.Id.Value, ct);
            if (existing is null) throw;
            if (existing.DeletedAt != null) return Problem(410, "Gone.");
            if (existing.CreateHash == etag)
                return WithETag(Ok(ToResponse(existing)), existing.ETag);
            return Problem(409, "A different resource already uses this id.");
        }

        return WithETag(
            CreatedAtAction(nameof(Get), new { id = blog.PublicId }, ToResponse(blog)), etag);
    }

    [HttpGet("{id:guid}")]
    [Produces("application/json")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var blog = await _db.Blogs.IgnoreQueryFilters()
            .SingleOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null) return Problem(404, "Not found.");
        if (blog.DeletedAt != null) return Problem(410, "Gone.");
        if (IfNoneMatchMatches(blog.ETag))
            return WithETag(StatusCode(StatusCodes.Status304NotModified), blog.ETag);
        return WithETag(Ok(ToResponse(blog)), blog.ETag);
    }

    [HttpPut("{id:guid}")]
    [Consumes("application/json")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(
        Guid id,
        [FromBody][Required] BlogWriteRequest? req,
        [FromHeader(Name = "If-Match")][Required] string? ifMatch,
        CancellationToken ct)
    {
        if (req is null || !req.Id.HasValue || req.Name is null || req.Id.Value != id)
            return Problem(400, "Invalid request body.");
        if (string.IsNullOrWhiteSpace(ifMatch)) return Problem(428, "If-Match is required.");

        var blog = await _db.Blogs.IgnoreQueryFilters()
            .SingleOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null) return Problem(404, "Not found.");
        if (blog.DeletedAt != null) return Problem(410, "Gone.");

        var newEtag = ETags.ForBlog(id, req.Name);
        if (newEtag == blog.ETag)
            return WithETag(NoContent(), blog.ETag);
        if (!IfMatchMatches(ifMatch, blog.ETag))
            return WithETag(Problem(412, "ETag does not match."), blog.ETag);

        blog.Name = req.Name;
        blog.ETag = newEtag;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await Stale412Blog(id, ct);
        }
        return WithETag(NoContent(), newEtag);
    }

    private async Task<IActionResult> Stale412Blog(Guid id, CancellationToken ct)
    {
        _db.ChangeTracker.Clear();
        var cur = await _db.Blogs.IgnoreQueryFilters()
            .SingleOrDefaultAsync(b => b.PublicId == id, ct);
        if (cur is null) return Problem(404, "Not found.");
        if (cur.DeletedAt != null) return Problem(410, "Gone.");
        return WithETag(Problem(412, "ETag does not match."), cur.ETag);
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [FromHeader(Name = "If-Match")][Required] string? ifMatch,
        CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch)) return Problem(428, "If-Match is required.");

        var blog = await _db.Blogs.IgnoreQueryFilters()
            .SingleOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null || blog.DeletedAt != null) return NoContent();
        if (!IfMatchMatches(ifMatch, blog.ETag))
            return WithETag(Problem(412, "ETag does not match."), blog.ETag);

        await using var tx = await _db.Database.BeginTransactionAsync(ct);
        var now = DateTimeOffset.UtcNow;
        blog.DeletedAt = now;
        var posts = await _db.Posts.Where(p => p.BlogId == blog.Id).ToListAsync(ct);
        foreach (var p in posts) p.DeletedAt = now;
        try
        {
            await _db.SaveChangesAsync(ct);
            await tx.CommitAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.ChangeTracker.Clear();
            var cur = await _db.Blogs.IgnoreQueryFilters()
                .SingleOrDefaultAsync(b => b.PublicId == id, ct);
            if (cur is null || cur.DeletedAt != null) return NoContent();
            return WithETag(Problem(412, "ETag does not match."), cur.ETag);
        }
        return NoContent();
    }
}
