// AppSetup.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

public static class AppSetup
{
    public static void ConfigureServices(IServiceCollection services, string sqliteConnectionString)
    {
        services.AddDbContext<AppDbContext>(o => o.UseSqlite(sqliteConnectionString));
        services.AddControllers();

        // A missing If-Match on PUT/DELETE must be 428, not the automatic 400
        // produced by [ApiController] model validation. If the body is also
        // invalid, the 400 wins (validation comes first).
        services.Configure<ApiBehaviorOptions>(o =>
        {
            o.InvalidModelStateResponseFactory = ctx =>
            {
                var method = ctx.HttpContext.Request.Method;
                var onlyIfMatch = ctx.ModelState.Count > 0 &&
                    ctx.ModelState.Keys.All(k =>
                        string.Equals(k, "ifMatch", StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(k, "If-Match", StringComparison.OrdinalIgnoreCase));
                if (onlyIfMatch &&
                    (HttpMethods.IsPut(method) || HttpMethods.IsDelete(method)))
                {
                    return new ObjectResult(new ProblemDetails
                    {
                        Status = StatusCodes.Status428PreconditionRequired,
                        Title = "If-Match is required."
                    })
                    {
                        StatusCode = StatusCodes.Status428PreconditionRequired,
                        ContentTypes = { "application/problem+json" }
                    };
                }
                return new BadRequestObjectResult(new ValidationProblemDetails(ctx.ModelState));
            };
        });
    }
}
