    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> Get(Guid id)
    {
        var ticket = await _db.Tickets.FirstOrDefaultAsync(t => t.Id == id);
        if (ticket is null) return NotFound();

        ticket.ViewCount++;
        ticket.LastViewedAt = DateTime.UtcNow;
        ticket.RowVersion = Guid.NewGuid().ToByteArray();
        await _db.SaveChangesAsync();

        return Ok(TicketResponse.From(ticket));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> Update(Guid id, TicketRequest request)
    {
        var ticket = await _db.Tickets.FirstOrDefaultAsync(t => t.Id == id);
        if (ticket is null) return NotFound();

        ticket.Subject = request.Subject;
        ticket.Priority = request.Priority;
        ticket.Escalated = request.Escalated;
        ticket.Category = request.Category;
        ticket.RowVersion = Guid.NewGuid().ToByteArray();

        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateConcurrencyException)
        {
            // Row deleted between load and save; treat as gone.
            if (!await _db.Tickets.AnyAsync(t => t.Id == id)) return NotFound();
            return Conflict();
        }

        return Ok(TicketResponse.From(ticket));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        // Idempotent delete: safe under client retries.
        var deleted = await _db.Tickets.Where(t => t.Id == id).ExecuteDeleteAsync();
        if (deleted == 0) return NotFound();
        return NoContent();
    }
