using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/support-tickets")]
public sealed class SupportTicketsController : ControllerBase
{
    private readonly TicketDbContext _db;

    public SupportTicketsController(TicketDbContext db)
    {
        _db = db;
    }

    [HttpPost]
    public async Task<ActionResult<TicketResponse>> Create([FromBody] TicketRequest request)
    {
        if (request is null || string.IsNullOrWhiteSpace(request.Subject) || string.IsNullOrWhiteSpace(request.Category))
        {
            return BadRequest();
        }

        var id = request.Id ?? Guid.NewGuid();

        // Idempotent create: if a retried POST already created the ticket,
        // return the existing row instead of failing on a duplicate key.
        var existing = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id);
        if (existing is not null)
        {
            return CreatedAtAction(nameof(GetById), new { id = existing.Id }, ToResponse(existing));
        }

        var ticket = new Ticket
        {
            Id = id,
            Subject = request.Subject!,
            Priority = request.Priority,
            Escalated = request.Escalated,
            Category = request.Category!,
            ViewCount = 0,
            LastViewedAt = null,
            RowVersion = Guid.NewGuid(),
        };

        _db.Tickets.Add(ticket);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            // A concurrent create with the same id won the race; treat as a retry.
            var winner = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id);
            if (winner is not null)
            {
                return CreatedAtAction(nameof(GetById), new { id = winner.Id }, ToResponse(winner));
            }
            throw;
        }

        return CreatedAtAction(nameof(GetById), new { id = ticket.Id }, ToResponse(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> GetById(Guid id)
    {
        var ticket = await _db.Tickets.FirstOrDefaultAsync(t => t.Id == id);
        if (ticket is null)
        {
            return NotFound();
        }

        ticket.ViewCount++;
        ticket.LastViewedAt = DateTime.UtcNow;
        ticket.RowVersion = Guid.NewGuid();
        await _db.SaveChangesAsync();

        return Ok(ToResponse(ticket));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<TicketResponse>> Update(Guid id, [FromBody] TicketRequest request)
    {
        if (request is null || string.IsNullOrWhiteSpace(request.Subject) || string.IsNullOrWhiteSpace(request.Category))
        {
            return BadRequest();
        }

        // Retry a bounded number of times when concurrent updates collide.
        for (var attempt = 0; attempt < 3; attempt++)
        {
            var ticket = await _db.Tickets.FirstOrDefaultAsync(t => t.Id == id);
            if (ticket is null)
            {
                return NotFound();
            }

            ticket.Subject = request.Subject!;
            ticket.Priority = request.Priority;
            ticket.Escalated = request.Escalated;
            ticket.Category = request.Category!;
            ticket.RowVersion = Guid.NewGuid();

            try
            {
                await _db.SaveChangesAsync();
                return Ok(ToResponse(ticket));
            }
            catch (DbUpdateConcurrencyException)
            {
                _db.Entry(ticket).State = EntityState.Detached;
                if (attempt == 2)
                {
                    return Conflict();
                }
            }
        }

        return Conflict();
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        for (var attempt = 0; attempt < 3; attempt++)
        {
            var ticket = await _db.Tickets.FirstOrDefaultAsync(t => t.Id == id);
            if (ticket is null)
            {
                return NotFound();
            }

            _db.Tickets.Remove(ticket);
            try
            {
                await _db.SaveChangesAsync();
                return NoContent();
            }
            catch (DbUpdateConcurrencyException)
            {
                _db.Entry(ticket).State = EntityState.Detached;
                if (attempt == 2)
                {
                    return Conflict();
                }
            }
        }

        return Conflict();
    }

    private static TicketResponse ToResponse(Ticket t) => new()
    {
        Id = t.Id,
        Subject = t.Subject,
        Priority = t.Priority,
        Escalated = t.Escalated,
        Category = t.Category,
        ViewCount = t.ViewCount,
        LastViewedAt = t.LastViewedAt,
    };
}
