// File: Ticket.cs — EF entity and DbContext
using System;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

public class Ticket
{
    // Internal surrogate key; never exposed outside the service.
    public int Id { get; set; }

    // Public identity chosen by the client.
    public Guid PublicId { get; set; }

    public string Subject { get; set; } = "";
    public int Priority { get; set; }
    public bool Escalated { get; set; }
    public string Category { get; set; } = "";

    // Server-maintained; never part of the representation or the hash.
    public int ViewCount { get; set; }
    public DateTime? LastViewedAt { get; set; }

    // Stored ETag, also the EF concurrency token.
    public string ETag { get; set; } = "";

    // Immutable hash of the create request, to distinguish replay from conflict.
    public string CreateHash { get; set; } = "";

    // Tombstone; non-null means soft-deleted.
    public DateTime? DeletedAt { get; set; }
}

public class AppDbContext : DbContext
{
    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }

    public DbSet<Ticket> Tickets => Set<Ticket>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        var e = modelBuilder.Entity<Ticket>();
        e.HasKey(t => t.Id);
        e.Property(t => t.Id).ValueGeneratedOnAdd();

        e.HasIndex(t => t.PublicId).IsUnique();

        e.Property(t => t.Subject).IsRequired();
        e.Property(t => t.Category).IsRequired();
        e.Property(t => t.ETag).IsRequired().IsConcurrencyToken();
        e.Property(t => t.CreateHash).IsRequired()
            .Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);

        e.Property(t => t.DeletedAt).IsRequired(false);
        e.HasQueryFilter(t => t.DeletedAt == null);
    }
}
