// File: CanonicalJson.cs — canonical representation and ETag hashing
using System;
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public static class CanonicalJson
{
    // Escapes only quote, backslash and control characters; everything else literal.
    public static void WriteString(StringBuilder sb, string s)
    {
        sb.Append('"');
        foreach (var c in s.Normalize(NormalizationForm.FormC))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else
                        sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }

    // Canonical JSON: id + client-writable fields in declared order, compact.
    public static string Of(Guid id, string subject, int priority, bool escalated, string category)
    {
        var sb = new StringBuilder();
        sb.Append('{');
        sb.Append("\"id\":\"").Append(id.ToString("D")).Append("\",");
        sb.Append("\"subject\":"); WriteString(sb, subject); sb.Append(',');
        sb.Append("\"priority\":").Append(priority.ToString(CultureInfo.InvariantCulture)).Append(',');
        sb.Append("\"escalated\":").Append(escalated ? "true" : "false").Append(',');
        sb.Append("\"category\":"); WriteString(sb, category);
        sb.Append('}');
        return sb.ToString();
    }

    // Quoted, unpadded base64url SHA-256.
    public static string ETagOf(Guid id, string subject, int priority, bool escalated, string category)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(Of(id, subject, priority, escalated, category)));
        var b64 = Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + b64 + "\"";
    }

    public static bool ETagMatches(string? headerValue, string current)
    {
        if (string.IsNullOrWhiteSpace(headerValue)) return false;
        foreach (var raw in headerValue.Split(','))
        {
            var v = raw.Trim();
            if (v == "*") return true;
            if (v.StartsWith("W/", StringComparison.Ordinal)) v = v.Substring(2).Trim();
            if (string.Equals(v, current, StringComparison.Ordinal)) return true;
        }
        return false;
    }
}
