// File: SupportTicketsController.cs
using System;
using System.ComponentModel.DataAnnotations;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly AppDbContext _db;

    public SupportTicketsController(AppDbContext db) => _db = db;

    private static TicketResponse ToResponse(Ticket t) => new()
    {
        Id = t.PublicId,
        Subject = t.Subject,
        Priority = t.Priority,
        Escalated = t.Escalated,
        Category = t.Category
    };

    private static string ETagOf(Ticket t) =>
        CanonicalJson.ETagOf(t.PublicId, t.Subject, t.Priority, t.Escalated, t.Category);

    private ObjectResult Problem(int status, string title) =>
        Problem(statusCode: status, title: title);

    // Include tombstoned rows so 410 can be distinguished from 404.
    private Task<Ticket?> FindAnyAsync(Guid id, CancellationToken ct) =>
        _db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(t => t.PublicId == id, ct);

    private bool BodyInvalid(TicketRequest? body) =>
        body is null || !body.Id.HasValue || body.Id.Value == Guid.Empty
        || body.Subject is null || body.Category is null;

    [HttpPost]
    [Consumes("application/json")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, Required] TicketRequest? body, CancellationToken cancellationToken)
    {
        if (BodyInvalid(body))
            return Problem(StatusCodes.Status400BadRequest, "Invalid request body.");

        var etag = CanonicalJson.ETagOf(body!.Id!.Value, body.Subject!, body.Priority, body.Escalated, body.Category!);
        var ticket = new Ticket
        {
            PublicId = body.Id.Value,
            Subject = body.Subject!,
            Priority = body.Priority,
            Escalated = body.Escalated,
            Category = body.Category!,
            ETag = etag,
            CreateHash = CanonicalJson.Of(body.Id.Value, body.Subject!, body.Priority, body.Escalated, body.Category!)
        };

        _db.Tickets.Add(ticket);
        try
        {
            await _db.SaveChangesAsync(cancellationToken);
            Response.Headers.ETag = etag;
            return CreatedAtAction(nameof(GetById), new { id = ticket.PublicId }, ToResponse(ticket));
        }
        catch (DbUpdateException)
        {
            _db.Entry(ticket).State = EntityState.Detached;
            var existing = await FindAnyAsync(body.Id.Value, cancellationToken);
            if (existing is null)
                return Problem(StatusCodes.Status409Conflict, "A ticket with this id already exists.");
            if (existing.DeletedAt.HasValue)
                return Problem(StatusCodes.Status410Gone, "This ticket has been deleted.");

            Response.Headers.ETag = existing.ETag;
            var requestHash = CanonicalJson.Of(body.Id.Value, body.Subject!, body.Priority, body.Escalated, body.Category!);
            if (existing.CreateHash == requestHash)
                return Ok(ToResponse(existing)); // idempotent replay

            return Problem(StatusCodes.Status409Conflict, "A ticket with this id already exists with different content.");
        }
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> GetById(Guid id, CancellationToken cancellationToken)
    {
        var ticket = await FindAnyAsync(id, cancellationToken);
        if (ticket is null)
            return Problem(StatusCodes.Status404NotFound, "Ticket not found.");
        if (ticket.DeletedAt.HasValue)
            return Problem(StatusCodes.Status410Gone, "This ticket has been deleted.");

        Response.Headers.ETag = ticket.ETag;
        if (CanonicalJson.ETagMatches(Request.Headers.IfNoneMatch.ToString(), ticket.ETag))
            return StatusCode(StatusCodes.Status304NotModified);

        ticket.ViewCount++;
        ticket.LastViewedAt = DateTime.UtcNow;
        await _db.SaveChangesAsync(cancellationToken);

        return Ok(ToResponse(ticket));
    }

    [HttpPut("{id:guid}")]
    [Consumes("application/json")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(
        Guid id,
        [FromBody, Required] TicketRequest? body,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        CancellationToken cancellationToken)
    {
        // Validation precedes the If-Match requirement.
        if (BodyInvalid(body) || body!.Id!.Value != id)
            return Problem(StatusCodes.Status400BadRequest, "Invalid request body.");

        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(StatusCodes.Status428PreconditionRequired, "If-Match header is required.");

        var ticket = await FindAnyAsync(id, cancellationToken);
        if (ticket is null)
            return Problem(StatusCodes.Status404NotFound, "Ticket not found.");
        if (ticket.DeletedAt.HasValue)
            return Problem(StatusCodes.Status410Gone, "This ticket has been deleted.");

        var newEtag = CanonicalJson.ETagOf(id, body.Subject!, body.Priority, body.Escalated, body.Category!);
        if (newEtag == ticket.ETag)
            return NoContent(); // change already applied

        if (!CanonicalJson.ETagMatches(ifMatch, ticket.ETag))
        {
            Response.Headers.ETag = ticket.ETag;
            return Problem(StatusCodes.Status412PreconditionFailed, "ETag does not match the current representation.");
        }

        ticket.Subject = body.Subject!;
        ticket.Priority = body.Priority;
        ticket.Escalated = body.Escalated;
        ticket.Category = body.Category!;
        _db.Entry(ticket).Property(t => t.ETag).OriginalValue = ticket.ETag;
        ticket.ETag = newEtag;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await FindAnyAsync(id, cancellationToken);
            if (current is not null && !current.DeletedAt.HasValue)
                Response.Headers.ETag = current.ETag;
            return Problem(StatusCodes.Status412PreconditionFailed, "The ticket was modified concurrently.");
        }

        Response.Headers.ETag = newEtag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(StatusCodes.Status428PreconditionRequired, "If-Match header is required.");

        var ticket = await FindAnyAsync(id, cancellationToken);
        if (ticket is null || ticket.DeletedAt.HasValue)
            return NoContent();

        if (!CanonicalJson.ETagMatches(ifMatch, ticket.ETag))
        {
            Response.Headers.ETag = ticket.ETag;
            return Problem(StatusCodes.Status412PreconditionFailed, "ETag does not match the current representation.");
        }

        _db.Entry(ticket).Property(t => t.ETag).OriginalValue = ticket.ETag;
        ticket.DeletedAt = DateTime.UtcNow;
        ticket.ETag = ETagOf(ticket); // recompute to satisfy non-null concurrency token

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await FindAnyAsync(id, cancellationToken);
            if (current is not null && !current.DeletedAt.HasValue)
            {
                Response.Headers.ETag = current.ETag;
                return Problem(StatusCodes.Status412PreconditionFailed, "The ticket was modified concurrently.");
            }
        }

        return NoContent();
    }
}
```

Key design points:

- **Replay vs. conflict**: `CreateHash` is written once and configured with `PropertySaveBehavior.Throw` so it can never be updated; a unique-violation on POST compares it to tell an idempotent replay (200) from a true conflict (409).
- **Concurrency**: `ETag` is the concurrency token; PUT/DELETE set its original value before updating, so racing writers hit `DbUpdateConcurrencyException` → 412, never 5xx. `ViewCount`/`LastViewedAt` are server-owned, excluded from canonical JSON, and never part of the concurrency check.
- **Tombstones**: `DeletedAt` is nullable with a global query filter; lookups use `IgnoreQueryFilters` so 404 vs. 410 is distinguishable and deleted ids return 410 on re-create.
- **ETag**: quoted unpadded base64url SHA-256 over compact canonical JSON with lowercase GUIDs, NFC strings, and minimal escaping; weak `W/` prefixes and `*` are tolerated when matching.

