// ETags.cs — canonical JSON + ETag hashing per spec
using System.Globalization;
using System.Text;
using System.Security.Cryptography;

public static class ETags
{
    // Canonical representation: id + client-writable fields in declared order.
    // Compact JSON, lowercase GUID, NFC strings, minimal escaping.
    public static string CanonicalJson(Guid id, string subject, int priority,
        bool escalated, string category)
    {
        var sb = new StringBuilder();
        sb.Append('{');
        sb.Append("\"id\":\"").Append(id.ToString("D").ToLowerInvariant()).Append('\"');
        sb.Append(",\"subject\":").Append(JsonString(subject));
        sb.Append(",\"priority\":").Append(priority.ToString(CultureInfo.InvariantCulture));
        sb.Append(",\"escalated\":").Append(escalated ? "true" : "false");
        sb.Append(",\"category\":").Append(JsonString(category));
        sb.Append('}');
        return sb.ToString();
    }

    public static string JsonString(string value)
    {
        var s = value.Normalize(NormalizationForm.FormC);
        var sb = new StringBuilder(s.Length + 2);
        sb.Append('\"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '\"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else
                        sb.Append(c);
                    break;
            }
        }
        sb.Append('\"');
        return sb.ToString();
    }

    // Quoted unpadded base64url SHA-256 of the canonical JSON.
    public static string Hash(string canonicalJson)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson));
        var b64 = Convert.ToBase64String(bytes)
            .TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + b64 + "\"";
    }

    public static string ForRepresentation(Guid id, string subject, int priority,
        bool escalated, string category)
        => Hash(CanonicalJson(id, subject, priority, escalated, category));

    // Matches a comma-separated precondition header against an ETag.
    public static bool Matches(string? headerValue, string etag)
    {
        if (string.IsNullOrWhiteSpace(headerValue)) return false;
        foreach (var part in headerValue.Split(','))
        {
            var v = part.Trim();
            if (v == "*") return true;
            if (v == etag) return true;
            if (v.StartsWith("W/", StringComparison.Ordinal) && v.Substring(2) == etag) return true;
        }
        return false;
    }
}
