// SupportTicketsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Data.Sqlite;
using System.ComponentModel.DataAnnotations;

[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly AppDbContext _db;
    public SupportTicketsController(AppDbContext db) => _db = db;

    private ObjectResult Problem(int status, string title)
        => new ObjectResult(new ProblemDetails { Status = status, Title = title })
        {
            StatusCode = status,
            ContentTypes = { "application/problem+json" }
        };

    [HttpPost]
    [Consumes("application/json")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create(
        [Required][FromBody] TicketRequest? body, CancellationToken ct)
    {
        if (body?.Id is not Guid id || body.Subject is null ||
            body.Category is null || body.Priority is null || body.Escalated is null)
            return Problem(400, "Invalid request body.");

        var requestHash = ETags.ForRepresentation(id, body.Subject,
            body.Priority.Value, body.Escalated.Value, body.Category);

        var ticket = new Ticket
        {
            PublicId = id,
            Subject = body.Subject,
            Priority = body.Priority.Value,
            Escalated = body.Escalated.Value,
            Category = body.Category,
            ETag = requestHash,
            RequestHash = requestHash
        };

        _db.Tickets.Add(ticket);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (IsUniqueViolation(ex))
        {
            _db.Entry(ticket).State = EntityState.Detached;
            var existing = await _db.Tickets.IgnoreQueryFilters()
                .FirstOrDefaultAsync(t => t.PublicId == id, ct);
            if (existing is null) throw;
            if (existing.DeletedAt is not null)
                return Problem(410, "Ticket was deleted.");
            if (existing.RequestHash != requestHash)
                return Problem(409, "A different ticket already exists with this id.");

            Response.Headers.ETag = existing.ETag;
            return Ok(TicketResponse.From(existing));
        }

        Response.Headers.ETag = ticket.ETag;
        return Created($"/api/support-tickets/{id:D}", TicketResponse.From(ticket));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var ticket = await _db.Tickets.IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.PublicId == id, ct);
        if (ticket is null) return Problem(404, "Ticket not found.");
        if (ticket.DeletedAt is not null) return Problem(410, "Ticket was deleted.");

        var etag = ticket.ETag;
        Response.Headers.ETag = etag;
        if (ETags.Matches(Request.Headers.IfNoneMatch, etag))
            return StatusCode(304);

        // Server-maintained counters; direct SQL so they never touch the
        // concurrency token or invalidate preconditions.
        await _db.Database.ExecuteSqlAsyncInterpolated(
            ct,
            $"UPDATE Tickets SET ViewCount = ViewCount + 1, LastViewedAt = {DateTime.UtcNow} WHERE Id = {ticket.Id}");

        return Ok(TicketResponse.From(ticket));
    }

    [HttpPut("{id:guid}")]
    [Consumes("application/json")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id,
        [Required][FromBody] TicketRequest? body,
        [Required][FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken ct)
    {
        // Validation first, even before the If-Match check.
        if (body?.Id is not Guid bodyId || body.Subject is null ||
            body.Category is null || body.Priority is null || body.Escalated is null ||
            bodyId != id)
            return Problem(400, "Invalid request body.");

        if (string.IsNullOrEmpty(ifMatch))
            return Problem(428, "If-Match header is required.");

        var ticket = await _db.Tickets.IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.PublicId == id, ct);
        if (ticket is null) return Problem(404, "Ticket not found.");
        if (ticket.DeletedAt is not null) return Problem(410, "Ticket was deleted.");

        var newEtag = ETags.ForRepresentation(id, body.Subject,
            body.Priority.Value, body.Escalated.Value, body.Category);

        // Change already applied.
        if (newEtag == ticket.ETag)
        {
            Response.Headers.ETag = ticket.ETag;
            return NoContent();
        }

        if (!ETags.Matches(ifMatch, ticket.ETag))
        {
            Response.Headers.ETag = ticket.ETag;
            return Problem(412, "Precondition failed.");
        }

        ticket.Subject = body.Subject;
        ticket.Priority = body.Priority.Value;
        ticket.Escalated = body.Escalated.Value;
        ticket.Category = body.Category;
        ticket.ETag = newEtag;

        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await _db.Tickets.IgnoreQueryFilters()
                .Where(t => t.PublicId == id)
                .Select(t => t.ETag)
                .FirstOrDefaultAsync(ct);
            Response.Headers.ETag = current ?? newEtag;
            return Problem(412, "Precondition failed.");
        }

        Response.Headers.ETag = newEtag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [Required][FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken ct)
    {
        // If-Match is required even for unknown ids.
        if (string.IsNullOrEmpty(ifMatch))
            return Problem(428, "If-Match header is required.");

        var ticket = await _db.Tickets.IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.PublicId == id, ct);

        // Unknown or already deleted: idempotent 204.
        if (ticket is null || ticket.DeletedAt is not null)
            return NoContent();

        if (!ETags.Matches(ifMatch, ticket.ETag))
        {
            Response.Headers.ETag = ticket.ETag;
            return Problem(412, "Precondition failed.");
        }

        ticket.DeletedAt = DateTime.UtcNow;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var gone = await _db.Tickets.IgnoreQueryFilters()
                .Where(t => t.PublicId == id)
                .Select(t => t.DeletedAt != null)
                .FirstOrDefaultAsync(ct);
            if (gone) return NoContent();
            return Problem(412, "Precondition failed.");
        }

        return NoContent();
    }

    private static bool IsUniqueViolation(DbUpdateException ex)
        => ex.InnerException is SqliteException s && s.SqliteErrorCode == 19;
}
