// ETags.cs — canonical JSON and content hashing
using System;
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public static class ETags
{
    // Canonical JSON of the representation: id + client-writable fields in
    // declared order. Compact, lowercase GUIDs, NFC strings, minimal escaping.
    public static string CanonicalJson(Guid id, string subject, int priority, bool escalated, string category)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":");
        WriteString(sb, id.ToString("d"));
        sb.Append(",\"subject\":");
        WriteString(sb, subject);
        sb.Append(",\"priority\":");
        sb.Append(priority.ToString("R", CultureInfo.InvariantCulture));
        sb.Append(",\"escalated\":");
        sb.Append(escalated ? "true" : "false");
        sb.Append(",\"category\":");
        WriteString(sb, category);
        sb.Append('}');
        return sb.ToString();
    }

    // Quoted, unpadded base64url SHA-256 of the canonical JSON.
    public static string Hash(Guid id, string subject, int priority, bool escalated, string category)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(CanonicalJson(id, subject, priority, escalated, category)));
        return "\"" + Convert.ToBase64String(bytes)
            .Replace('+', '-').Replace('/', '_').TrimEnd('=') + "\"";
    }

    private static void WriteString(StringBuilder sb, string value)
    {
        value = value.Normalize(NormalizationForm.FormC);
        sb.Append('"');
        foreach (var c in value)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }

    // True when an If-Match / If-None-Match header value matches the entity tag.
    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var raw in header.Split(','))
        {
            var s = raw.Trim();
            if (s == "*") return true;
            if (s.StartsWith("W/", StringComparison.Ordinal)) s = s.Substring(2).Trim();
            if (string.Equals(s, etag, StringComparison.Ordinal)) return true;
        }
        return false;
    }
}
