using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

public class TicketRequest
{
    public Guid? Id { get; set; }
    public string? Subject { get; set; }
    public int? Priority { get; set; }
    public bool? Escalated { get; set; }
    public string? Category { get; set; }
}

public record TicketResponse(Guid Id, string Subject, int Priority, bool Escalated, string Category);

[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly AppDbContext _db;

    public SupportTicketsController(AppDbContext db) => _db = db;

    private static TicketResponse ToResponse(Ticket t) =>
        new(t.PublicId, t.Subject, t.Priority, t.Escalated, t.Category);

    private static bool IsUniqueViolation(DbUpdateException ex) =>
        ex.InnerException is SqliteException s && s.SqliteErrorCode == 19; // SQLITE_CONSTRAINT

    private IActionResult Error(int status, string title) =>
        Problem(statusCode: status, title: title);

    [HttpPost]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] TicketRequest body, CancellationToken ct)
    {
        if (body is null || body.Id is null || body.Id == Guid.Empty ||
            body.Subject is null || body.Priority is null || body.Escalated is null || body.Category is null)
            return Error(400, "Invalid request body.");

        var id = body.Id.Value;
        var hash = ETags.Hash(id, body.Subject, body.Priority.Value, body.Escalated.Value, body.Category);
        var ticket = new Ticket
        {
            PublicId = id,
            Subject = body.Subject,
            Priority = body.Priority.Value,
            Escalated = body.Escalated.Value,
            Category = body.Category,
            ETag = hash,
            RequestHash = hash,
        };
        _db.Tickets.Add(ticket);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (IsUniqueViolation(ex))
        {
            _db.Entry(ticket).State = EntityState.Detached;
            var existing = await _db.Tickets.IgnoreQueryFilters()
                .SingleAsync(t => t.PublicId == id, ct);
            if (existing.DeletedAt is not null)
                return Error(410, "The resource has been deleted.");
            Response.Headers.ETag = existing.ETag;
            if (existing.RequestHash == hash)
                return Ok(ToResponse(existing)); // idempotent replay
            return Error(409, "A resource with this id already exists with different content.");
        }

        Response.Headers.ETag = hash;
        return CreatedAtAction(nameof(Get), new { id }, ToResponse(ticket));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var ticket = await _db.Tickets.IgnoreQueryFilters()
            .SingleOrDefaultAsync(t => t.PublicId == id, ct);
        if (ticket is null)
            return Error(404, "Resource not found.");
        if (ticket.DeletedAt is not null)
            return Error(410, "The resource has been deleted.");

        // Server-side counters: updated outside the concurrency token so they
        // never invalidate ETags or If-Match headers.
        await _db.Tickets.Where(t => t.Id == ticket.Id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, DateTime.UtcNow), ct);

        Response.Headers.ETag = ticket.ETag;
        if (ETags.Matches(Request.Headers.IfNoneMatch.ToString(), ticket.ETag))
            return StatusCode(304);
        return Ok(ToResponse(ticket));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody] TicketRequest body,
        [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken ct)
    {
        // Body validation precedes the If-Match precondition check.
        if (body is null || body.Id is null || body.Id == Guid.Empty || body.Id.Value != id ||
            body.Subject is null || body.Priority is null || body.Escalated is null || body.Category is null)
            return Error(400, "Invalid request body or body id does not match the route id.");

        if (string.IsNullOrWhiteSpace(ifMatch))
            return Error(428, "If-Match header is required.");

        var ticket = await _db.Tickets.IgnoreQueryFilters()
            .SingleOrDefaultAsync(t => t.PublicId == id, ct);
        if (ticket is null)
            return Error(404, "Resource not found.");
        if (ticket.DeletedAt is not null)
            return Error(410, "The resource has been deleted.");

        var newHash = ETags.Hash(id, body.Subject, body.Priority.Value, body.Escalated.Value, body.Category);
        if (ticket.ETag == newHash)
            return NoContent(); // change already applied

        if (!ETags.Matches(ifMatch, ticket.ETag))
        {
            Response.Headers.ETag = ticket.ETag;
            return Error(412, "If-Match does not match the current entity tag.");
        }

        ticket.Subject = body.Subject;
        ticket.Priority = body.Priority.Value;
        ticket.Escalated = body.Escalated.Value;
        ticket.Category = body.Category;
        var oldEtag = ticket.ETag;
        ticket.ETag = newHash;
        _db.Entry(ticket).Property(t => t.ETag).OriginalValue = oldEtag;

        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            // Lost a race: report the winner's ETag.
            var current = await _db.Tickets.IgnoreQueryFilters()
                .SingleOrDefaultAsync(t => t.PublicId == id, ct);
            if (current is null || current.DeletedAt is not null)
                return Error(410, "The resource has been deleted.");
            Response.Headers.ETag = current.ETag;
            return Error(412, "If-Match does not match the current entity tag.");
        }

        Response.Headers.ETag = newHash;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Error(428, "If-Match header is required.");

        var ticket = await _db.Tickets.IgnoreQueryFilters()
            .SingleOrDefaultAsync(t => t.PublicId == id, ct);
        if (ticket is null || ticket.DeletedAt is not null)
            return NoContent();

        if (!ETags.Matches(ifMatch, ticket.ETag))
        {
            Response.Headers.ETag = ticket.ETag;
            return Error(412, "If-Match does not match the current entity tag.");
        }

        ticket.DeletedAt = DateTime.UtcNow;
        _db.Entry(ticket).Property(t => t.ETag).OriginalValue = ticket.ETag;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await _db.Tickets.IgnoreQueryFilters()
                .SingleOrDefaultAsync(t => t.PublicId == id, ct);
            if (current is null || current.DeletedAt is not null)
                return NoContent();
            Response.Headers.ETag = current.ETag;
            return Error(412, "If-Match does not match the current entity tag.");
        }

        return NoContent();
    }
}
```

Key design points:

- **`Ticket` entity**: internal `int Id` PK, unique index on `PublicId`, `ETag` as the EF concurrency token, `RequestHash` configured with `SetAfterSaveBehavior(PropertySaveBehavior.Throw)` so replays are distinguishable from conflicts, nullable `DeletedAt` tombstone with a global query filter.
- **ETag**: quoted unpadded base64url SHA-256 over canonical JSON (`id`, `subject`, `priority`, `escalated`, `category` in declared order) — NFC strings, lowercase GUIDs, minimal escaping.
- **Idempotent POST**: insert first, classify `SQLITE_CONSTRAINT` (error 19) — replay → 200, divergent content → 409, tombstoned id → 410.
- **Counters** use `ExecuteUpdateAsync` so `ViewCount`/`LastViewedAt` updates bypass the concurrency token and never change the ETag.
- **PUT ordering**: body/id validation (400) → If-Match presence (428) → existence (404/410) → already-applied (204) → stale precondition (412). `DbUpdateConcurrencyException` maps to 412 with the winner's ETag, so racing writers never see a 5xx.
- **DELETE**: 428 before existence check; unknown/tombstoned → 204; soft-delete via `DeletedAt` with the same concurrency handling.

