// CanonicalJson.cs
using System.Globalization;
using System.Text;

// Builds the canonical JSON used for hashing:
// id, (parent id when there is one — tickets have none), then the
// client-writable fields in declared order. Compact JSON, lowercase GUIDs,
// NFC-normalized strings, minimal string escaping.
public static class CanonicalJson
{
    public static string OfTicket(Guid id, string subject, int priority, bool escalated, string category)
    {
        var sb = new StringBuilder();
        sb.Append('{');
        sb.Append("\"id\":").Append(JsonString(id.ToString("d"))).Append(',');
        sb.Append("\"subject\":").Append(JsonString(subject)).Append(',');
        sb.Append("\"priority\":").Append(priority.ToString(CultureInfo.InvariantCulture)).Append(',');
        sb.Append("\"escalated\":").Append(escalated ? "true" : "false").Append(',');
        sb.Append("\"category\":").Append(JsonString(category));
        sb.Append('}');
        return sb.ToString();
    }

    private static string JsonString(string value)
    {
        var s = value.Normalize(NormalizationForm.FormC);
        var sb = new StringBuilder(s.Length + 2);
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        sb.Append("\\u00").Append(((int)c).ToString("x2", CultureInfo.InvariantCulture));
                    else
                        sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
        return sb.ToString();
    }
}
