```csharp
// ETags.cs
using System.Buffers.Text;
using System.Security.Cryptography;
using System.Text;

public static class ETags
{
    public static string Compute(string canonicalJson)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson));
        return "\"" + Base64Url.EncodeToString(hash).TrimEnd('=') + "\"";
    }

    public static string ForTicket(TicketWriteRequest r) =>
        Compute(CanonicalJson.OfTicket(r.Id!.Value, r.Subject!, r.Priority!.Value, r.Escalated!.Value, r.Category!));

    public static string ForTicket(Ticket t) =>
        Compute(CanonicalJson.OfTicket(t.Id, t.Subject, t.Priority, t.Escalated, t.Category));

    // Parses If-Match / If-None-Match values; supports "*", a single value,
    // lists, and weak validators (W/"...").
    public static (bool isStar, string? value) Parse(string? header)
    {
        if (string.IsNullOrWhiteSpace(header))
            return (false, null);

        var trimmed = header.Trim();
        if (trimmed == "*")
            return (true, null);

        // Take the first tag if a list is sent.
        var comma = trimmed.IndexOf(',');
        if (comma >= 0) trimmed = trimmed[..comma].Trim();

        if (trimmed.StartsWith("W/", StringComparison.Ordinal))
            trimmed = trimmed[2..].TrimStart();

        if (trimmed.Length >= 2 && trimmed[0] == '"' && trimmed[^1] == '"')
            return (false, trimmed);

        return (false, null);
    }

    public static bool Matches(string? header, string current)
    {
        var (star, value) = Parse(header);
        return star || (value is not null && string.Equals(value, current, StringComparison.Ordinal));
    }
}
