using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly TicketDbContext _db;

    public SupportTicketsController(TicketDbContext db) => _db = db;

    private ProblemHttpResult Problem(int status, string title, string? detail = null) =>
        TypedResults.Problem(
            statusCode: status,
            title: title,
            detail: detail,
            contentType: "application/problem+json");

    [HttpPost]
    [Consumes("application/json")]
    [Produces("application/json")]
    [ProducesResponseType<TicketResponse>(StatusCodes.Status201Created)]
    [ProducesResponseType<TicketResponse>(StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IResult> Create(
        [FromBody] TicketWriteRequest? body,
        CancellationToken ct)
    {
        if (body is null || body.Id is null || body.Subject is null ||
            body.Priority is null || body.Escalated is null || body.Category is null)
        {
            return Problem(StatusCodes.Status400BadRequest, "Invalid request body",
                "The body must contain id, subject, priority, escalated and category.");
        }

        var createHash = ETags.ForTicket(body);
        var etag = ETags.ForTicket(body);
        var response = new TicketResponse
        {
            Id = body.Id.Value,
            Subject = body.Subject!,
            Priority = body.Priority.Value,
            Escalated = body.Escalated.Value,
            Category = body.Category!,
        };

        var ticket = new Ticket
        {
            Id = body.Id.Value,
            Subject = body.Subject!,
            Priority = body.Priority.Value,
            Escalated = body.Escalated.Value,
            Category = body.Category!,
            ETag = etag,
            CreateHash = createHash,
        };

        _db.Tickets.Add(ticket);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            // Unique violation on Id: an item with this public id already exists.
            _db.ChangeTracker.Clear();

            var existing = await _db.Tickets
                .IgnoreQueryFilters()
                .AsNoTracking()
                .FirstOrDefaultAsync(t => t.Id == body.Id.Value, ct);

            if (existing is null)
                return Problem(StatusCodes.Status409Conflict, "Conflict");

            if (existing.DeletedAt is not null)
                return Problem(StatusCodes.Status410Gone, "Ticket was deleted",
                    "A ticket with this id existed and has been deleted.");

            if (string.Equals(existing.CreateHash, createHash, StringComparison.Ordinal))
            {
                // Idempotent replay of the original create.
                var r = TicketResponse.From(existing);
                return Results.Ok(r).WithETag(existing.ETag);
            }

            return Problem(StatusCodes.Status409Conflict, "Conflict",
                "A different ticket with this id already exists.");
        }

        var location = $"/api/support-tickets/{response.Id}";
        return Results.Created(location, response).WithETag(etag);
    }

    [HttpGet("{id:guid}")]
    [Produces("application/json")]
    [ProducesResponseType<TicketResponse>(StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IResult> Get(
        [FromRoute] Guid id,
        [FromHeader(Name = "If-None-Match")] string? ifNoneMatch,
        CancellationToken ct)
    {
        // Include tombstoned rows so a deleted id can be told apart from an unknown one.
        var row = await _db.Tickets
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.Id == id, ct);

        if (row is null)
            return Problem(StatusCodes.Status404NotFound, "Ticket not found");

        if (row.DeletedAt is not null)
            return Problem(StatusCodes.Status410Gone, "Ticket was deleted");

        // Server-owned bookkeeping; never changes the ETag.
        row.ViewCount++;
        row.LastViewedAt = DateTime.UtcNow;
        await _db.SaveChangesAsync(ct);

        if (ETags.Matches(ifNoneMatch, row.ETag))
            return Results.StatusCode(StatusCodes.Status304NotModified).WithETag(row.ETag);

        return Results.Ok(TicketResponse.From(row)).WithETag(row.ETag);
    }

    [HttpPut("{id:guid}")]
    [Consumes("application/json")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IResult> Put(
        [FromRoute] Guid id,
        [FromBody] TicketWriteRequest? body,
        [FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken ct)
    {
        // Validation comes before the If-Match requirement.
        if (body is null || body.Id is null || body.Subject is null ||
            body.Priority is null || body.Escalated is null || body.Category is null)
        {
            return Problem(StatusCodes.Status400BadRequest, "Invalid request body");
        }
        if (body.Id.Value != id)
            return Problem(StatusCodes.Status400BadRequest, "Id mismatch",
                "The body id must equal the route id.");

        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(StatusCodes.Status428PreconditionRequired, "If-Match required");

        var row = await _db.Tickets
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.Id == id, ct);

        if (row is null)
            return Problem(StatusCodes.Status404NotFound, "Ticket not found");

        if (row.DeletedAt is not null)
            return Problem(StatusCodes.Status410Gone, "Ticket was deleted");

        var newHash = ETags.ForTicket(body);

        // Change already applied: the current representation equals the PUT body.
        if (string.Equals(row.ETag, newHash, StringComparison.Ordinal))
            return Results.NoContent().WithETag(row.ETag);

        if (!ETags.Matches(ifMatch, row.ETag))
            return TypedResults.Problem(
                statusCode: StatusCodes.Status412PreconditionFailed,
                title: "Precondition failed",
                contentType: "application/problem+json")
                .WithETag(row.ETag);

        var newEtag = newHash;

        // Retry loop for optimistic concurrency races: two writers from the same
        // ETag — first commit wins, the loser sees a 412, never a 5xx.
        while (true)
        {
            row.Subject = body.Subject!;
            row.Priority = body.Priority.Value;
            row.Escalated = body.Escalated.Value;
            row.Category = body.Category!;
            row.ETag = newEtag;

            try
            {
                await _db.SaveChangesAsync(ct);
                return Results.NoContent().WithETag(newEtag);
            }
            catch (DbUpdateConcurrencyException) when (!ct.IsCancellationRequested)
            {
                _db.ChangeTracker.Clear();
                row = await _db.Tickets
                    .IgnoreQueryFilters()
                    .FirstOrDefaultAsync(t => t.Id == id, ct);

                if (row is null)
                    return Problem(StatusCodes.Status404NotFound, "Ticket not found");
                if (row.DeletedAt is not null)
                    return Problem(StatusCodes.Status410Gone, "Ticket was deleted");
                if (string.Equals(row.ETag, newHash, StringComparison.Ordinal))
                    return Results.NoContent().WithETag(row.ETag);

                // Someone else updated from the same base ETag: this writer loses.
                return TypedResults.Problem(
                    statusCode: StatusCodes.Status412PreconditionFailed,
                    title: "Precondition failed",
                    contentType: "application/problem+json")
                    .WithETag(row.ETag);
            }
        }
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IResult> Delete(
        [FromRoute] Guid id,
        [FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(StatusCodes.Status428PreconditionRequired, "If-Match required");

        var row = await _db.Tickets
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.Id == id, ct);

        // Unknown or already deleted: delete is idempotent.
        if (row is null || row.DeletedAt is not null)
            return Results.NoContent();

        if (!ETags.Matches(ifMatch, row.ETag))
            return TypedResults.Problem(
                statusCode: StatusCodes.Status412PreconditionFailed,
                title: "Precondition failed",
                contentType: "application/problem+json")
                .WithETag(row.ETag);

        row.DeletedAt = DateTime.UtcNow;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException) when (!ct.IsCancellationRequested)
        {
            // A race changed or deleted the row under us; delete is idempotent
            // once the precondition was satisfied on a live row, so re-check.
            _db.ChangeTracker.Clear();
            var again = await _db.Tickets
                .IgnoreQueryFilters()
                .AsNoTracking()
                .FirstOrDefaultAsync(t => t.Id == id, ct);
            if (again is not null && again.DeletedAt is null)
            {
                return TypedResults.Problem(
                    statusCode: StatusCodes.Status412PreconditionFailed,
                    title: "Precondition failed",
                    contentType: "application/problem+json")
                    .WithETag(again.ETag);
            }
        }

        return Results.NoContent();
    }
}
