public class Consignment
{
    public Guid Id { get; set; }
    public Guid DepotId { get; set; }
    public Depot? Depot { get; set; }
    public string Reference { get; set; } = "";
    public decimal WeightKg { get; set; }
    public bool Fragile { get; set; }
    public int DownloadCount { get; set; }
}

public class AppDbContext : DbContext
{
    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }

    public DbSet<Depot> Depots => Set<Depot>();
    public DbSet<Consignment> Consignments => Set<Consignment>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Depot>(e =>
        {
            e.HasKey(d => d.Id);
            e.Property(d => d.Code).IsRequired();
            e.HasMany(d => d.Consignments)
             .WithOne(c => c.Depot!)
             .HasForeignKey(c => c.DepotId)
             .OnDelete(DeleteBehavior.Cascade);
        });

        modelBuilder.Entity<Consignment>(e =>
        {
            e.HasKey(c => c.Id);
            e.Property(c => c.Reference).IsRequired();
        });
    }
