```csharp
// ETags.cs — canonical JSON + hashing
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public static class ETags
{
    public static string CanonicalJson(Guid id, string subject, int priority, bool escalated, string category)
    {
        var sb = new StringBuilder();
        sb.Append('{');
        sb.Append("\"id\":").Append('"').Append(id.ToString()).Append('"').Append(',');
        sb.Append("\"subject\":").Append(Quote(subject)).Append(',');
        sb.Append("\"priority\":").Append(priority.ToString(CultureInfo.InvariantCulture)).Append(',');
        sb.Append("\"escalated\":").Append(escalated ? "true" : "false").Append(',');
        sb.Append("\"category\":").Append(Quote(category));
        sb.Append('}');
        return sb.ToString();
    }

    private static string Quote(string s)
    {
        s = s.Normalize(NormalizationForm.FormC);
        var sb = new StringBuilder(s.Length + 2);
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else
                        sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
        return sb.ToString();
    }

    public static string Compute(Guid id, string subject, int priority, bool escalated, string category)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(CanonicalJson(id, subject, priority, escalated, category)));
        var b64 = Convert.ToBase64String(hash).Replace('+', '-').Replace('/', '_').TrimEnd('=');
        return "\"" + b64 + "\"";
    }

    // True if the header value matches the (quoted) etag; honors * and weak validators.
    public static bool Matches(string? headerValue, string etag)
    {
        if (string.IsNullOrWhiteSpace(headerValue)) return false;
        foreach (var part in headerValue.Split(','))
        {
            var v = part.Trim();
            if (v == "*") return true;
            if (v.StartsWith("W/", StringComparison.Ordinal)) v = v.Substring(2).Trim();
            if (string.Equals(v, etag, StringComparison.Ordinal)) return true;
        }
        return false;
    }
}
