// SupportTicketsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly TicketsDbContext _db;
    public SupportTicketsController(TicketsDbContext db) => _db = db;

    private static TicketResponse ToDto(Ticket t) => new()
    {
        Id = t.PublicId, Subject = t.Subject, Priority = t.Priority,
        Escalated = t.Escalated, Category = t.Category
    };

    private ProblemDetails Prob(int status, string title) =>
        new() { Status = status, Title = title };

    private ObjectResult ProbResult(int status, string title)
    {
        var p = Prob(status, title);
        return new ObjectResult(p) { StatusCode = status, ContentTypes = { "application/problem+json" } };
    }

    private static bool ValidBody(TicketWriteRequest? b) =>
        b is not null && b.Id.HasValue && b.Id.Value != Guid.Empty
        && b.Subject is not null && b.Priority.HasValue
        && b.Escalated.HasValue && b.Category is not null;

    [HttpPost]
    [Consumes("application/json")]
    [Produces("application/json")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] TicketWriteRequest? body, CancellationToken ct)
    {
        if (!ValidBody(body))
            return ProbResult(400, "Invalid ticket body.");

        var etag = ETags.Compute(body!.Id!.Value, body.Subject!, body.Priority!.Value, body.Escalated!.Value, body.Category!);
        var ticket = new Ticket
        {
            PublicId = body.Id.Value,
            Subject = body.Subject!,
            Priority = body.Priority.Value,
            Escalated = body.Escalated.Value,
            Category = body.Category!,
            ETag = etag,
            CreateHash = etag
        };

        _db.Tickets.Add(ticket);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.Entry(ticket).State = EntityState.Detached;
            var existing = await _db.Tickets.IgnoreQueryFilters()
                .FirstOrDefaultAsync(t => t.PublicId == body.Id.Value, ct);
            if (existing is null) throw;
            if (existing.DeletedAt is not null)
                return ProbResult(410, "Ticket was deleted.");
            if (existing.CreateHash == etag)
            {
                Response.Headers.ETag = existing.ETag;
                return Ok(ToDto(existing));
            }
            return ProbResult(409, "A ticket with this id already exists with different content.");
        }

        Response.Headers.ETag = ticket.ETag;
        return CreatedAtAction(nameof(GetById), new { id = ticket.PublicId }, ToDto(ticket));
    }

    [HttpGet("{id:guid}")]
    [Produces("application/json")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> GetById(Guid id, CancellationToken ct)
    {
        var t = await _db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null) return ProbResult(404, "Ticket not found.");
        if (t.DeletedAt is not null) return ProbResult(410, "Ticket was deleted.");

        // server-maintained read counters; never part of representation or ETag
        t.ViewCount++;
        t.LastViewedAt = DateTime.UtcNow;
        try { await _db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { _db.Entry(t).State = EntityState.Detached; }

        Response.Headers.ETag = t.ETag;
        if (ETags.Matches(Request.Headers.IfNoneMatch.ToString(), t.ETag))
            return StatusCode(304);
        return Ok(ToDto(t));
    }

    [HttpPut("{id:guid}")]
    [Consumes("application/json")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Replace(
        Guid id,
        [FromBody] TicketWriteRequest? body,
        [FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken ct)
    {
        if (!ValidBody(body) || body!.Id!.Value != id)
            return ProbResult(400, "Invalid ticket body or body id does not match route id.");

        if (string.IsNullOrEmpty(ifMatch))
            return ProbResult(428, "If-Match header is required.");

        var t = await _db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null) return ProbResult(404, "Ticket not found.");
        if (t.DeletedAt is not null) return ProbResult(410, "Ticket was deleted.");

        var newEtag = ETags.Compute(id, body.Subject!, body.Priority!.Value, body.Escalated!.Value, body.Category!);
        if (newEtag == t.ETag)
            return NoContent(); // change already applied

        if (!ETags.Matches(ifMatch, t.ETag))
        {
            Response.Headers.ETag = t.ETag;
            return ProbResult(412, "ETag does not match current representation.");
        }

        t.Subject = body.Subject!;
        t.Priority = body.Priority.Value;
        t.Escalated = body.Escalated.Value;
        t.Category = body.Category!;
        t.ETag = newEtag;

        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.Entry(t).State = EntityState.Detached;
            var current = await _db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (current is not null) Response.Headers.ETag = current.ETag;
            return ProbResult(412, "Ticket was modified concurrently.");
        }

        Response.Headers.ETag = t.ETag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch))
            return ProbResult(428, "If-Match header is required.");

        var t = await _db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null || t.DeletedAt is not null)
            return NoContent();

        if (!ETags.Matches(ifMatch, t.ETag))
        {
            Response.Headers.ETag = t.ETag;
            return ProbResult(412, "ETag does not match current representation.");
        }

        t.DeletedAt = DateTime.UtcNow;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.Entry(t).State = EntityState.Detached;
            var current = await _db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (current is null || current.DeletedAt is not null) return NoContent();
            Response.Headers.ETag = current.ETag;
            return ProbResult(412, "Ticket was modified concurrently.");
        }

        return NoContent();
    }
}
