// Representations.cs — DTOs and canonical-JSON / ETag computation

using System.Security.Cryptography;
using System.Text;
using System.Buffers.Text;

// Body for POST and PUT. All fields the client writes.
public sealed class TicketWriteRequest
{
    public Guid? Id { get; set; }
    public string? Subject { get; set; }
    public int? Priority { get; set; }
    public bool? Escalated { get; set; }
    public string? Category { get; set; }
}

// The only shape ever returned to clients — never an EF entity.
public sealed record TicketResponse(
    Guid Id,
    string Subject,
    int Priority,
    bool Escalated,
    string Category);

public static class Canonical
{
    public static string ETagFor(Ticket t) =>
        ETagOf(t.PublicId, t.Subject, t.Priority, t.Escalated, t.Category);

    public static string ETagOf(Guid id, string subject, int priority, bool escalated, string category)
    {
        var json = CanonicalJson(id, subject, priority, escalated, category);
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(json));
        return Base64Url.EncodeToString(hash); // unpadded base64url
    }

    public static string Quoted(string etag) => "\"" + etag + "\"";

    // Declared field order: id, subject, priority, escalated, category.
    public static string CanonicalJson(Guid id, string subject, int priority, bool escalated, string category)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("D")).Append('"');
        sb.Append(",\"subject\":").Append(JsonString(subject));
        sb.Append(",\"priority\":").Append(priority);
        sb.Append(",\"escalated\":").Append(escalated ? "true" : "false");
        sb.Append(",\"category\":").Append(JsonString(category));
        sb.Append('}');
        return sb.ToString();
    }

    private static string JsonString(string s)
    {
        var sb = new StringBuilder(s.Length + 2);
        sb.Append('"');
        foreach (var c in s.Normalize(NormalizationForm.FormC))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else
                        sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
        return sb.ToString();
    }
}
