// SupportTicketsController.cs

using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/support-tickets")]
public sealed class SupportTicketsController : ControllerBase
{
    private const string ProblemJson = "application/problem+json";
    private readonly AppDbContext _db;

    public SupportTicketsController(AppDbContext db) => _db = db;

    private static TicketResponse ToResponse(Ticket t) =>
        new(t.PublicId, t.Subject, t.Priority, t.Escalated, t.Category);

    private ObjectResult Problem(int status, string title) =>
        new(new ProblemDetails { Status = status, Title = title })
        {
            StatusCode = status,
            ContentTypes = { ProblemJson }
        };

    private static bool ValidBody(TicketWriteRequest? b) =>
        b is not null
        && b.Id is Guid id && id != Guid.Empty
        && b.Subject is not null
        && b.Priority is not null
        && b.Escalated is not null
        && b.Category is not null;

    private static bool IsUniqueViolation(DbUpdateException ex) =>
        ex.InnerException is SqliteException s
        && (s.SqliteErrorCode == 19 || s.SqliteExtendedErrorCode is 1555 or 2067);

    private static bool IfMatchSatisfied(string? header, string currentEtag)
    {
        if (header is null) return false;
        foreach (var raw in header.Split(','))
        {
            var v = raw.Trim();
            if (v == "*") return true;
            if (v.StartsWith("W/", StringComparison.Ordinal)) v = v[2..].Trim();
            if (v == Canonical.Quoted(currentEtag)) return true;
        }
        return false;
    }

    private bool IfNoneMatchHit(string currentEtag)
    {
        foreach (var raw in Request.Headers.IfNoneMatch.ToString().Split(','))
        {
            var v = raw.Trim();
            if (v.StartsWith("W/", StringComparison.Ordinal)) v = v[2..].Trim();
            if (v == "*" || v == Canonical.Quoted(currentEtag)) return true;
        }
        return false;
    }

    [HttpPost]
    [Consumes("application/json")]
    [Produces("application/json")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, ProblemJson)]
    public async Task<IActionResult> Create(
        [FromBody] TicketWriteRequest? body, CancellationToken ct)
    {
        if (!ValidBody(body))
            return Problem(400, "Invalid request body.");

        var hash = Canonical.ETagOf(
            body!.Id!.Value, body.Subject!, body.Priority!.Value,
            body.Escalated!.Value, body.Category!);

        var ticket = new Ticket
        {
            PublicId = body.Id.Value,
            Subject = body.Subject!,
            Priority = body.Priority.Value,
            Escalated = body.Escalated.Value,
            Category = body.Category!,
            ETag = hash,
            CreateHash = hash,
        };
        _db.Tickets.Add(ticket);

        try
        {
            await _db.SaveChangesAsync(ct);
            Response.Headers.ETag = Canonical.Quoted(ticket.ETag);
            return CreatedAtAction(
                nameof(GetById), new { id = ticket.PublicId }, ToResponse(ticket));
        }
        catch (DbUpdateException ex) when (IsUniqueViolation(ex))
        {
            _db.Entry(ticket).State = EntityState.Detached;
            var existing = await _db.Tickets
                .IgnoreQueryFilters()
                .SingleAsync(t => t.PublicId == body.Id.Value, ct);

            if (existing.DeletedAt is not null)
                return Problem(410, "This ticket has been deleted.");
            if (existing.CreateHash != hash)
                return Problem(409, "A ticket with this id already exists with different content.");

            Response.Headers.ETag = Canonical.Quoted(existing.ETag);
            return Ok(ToResponse(existing));
        }
    }

    [HttpGet("{id:guid}")]
    [Produces("application/json")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, ProblemJson)]
    public async Task<IActionResult> GetById(Guid id, CancellationToken ct)
    {
        var ticket = await _db.Tickets
            .IgnoreQueryFilters()
            .SingleOrDefaultAsync(t => t.PublicId == id, ct);

        if (ticket is null)
            return Problem(404, "Ticket not found.");
        if (ticket.DeletedAt is not null)
            return Problem(410, "This ticket has been deleted.");

        if (IfNoneMatchHit(ticket.ETag))
        {
            Response.Headers.ETag = Canonical.Quoted(ticket.ETag);
            return StatusCode(304);
        }

        // Server-maintained counters; never part of the ETag. Written with a
        // direct UPDATE so reads can never fail on a concurrency conflict.
        var now = DateTime.UtcNow;
        await _db.Tickets
            .Where(t => t.Key == ticket.Key && t.DeletedAt == null)
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, now), ct);

        Response.Headers.ETag = Canonical.Quoted(ticket.ETag);
        return Ok(ToResponse(ticket));
    }

    [HttpPut("{id:guid}")]
    [Consumes("application/json")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, ProblemJson)]
    public async Task<IActionResult> Update(
        Guid id,
        [FromBody] TicketWriteRequest? body,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        CancellationToken ct)
    {
        // Body validation precedes the If-Match requirement.
        if (!ValidBody(body))
            return Problem(400, "Invalid request body.");
        if (body!.Id!.Value != id)
            return Problem(400, "Body id does not match route id.");
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(428, "If-Match header is required.");

        var ticket = await _db.Tickets
            .IgnoreQueryFilters()
            .SingleOrDefaultAsync(t => t.PublicId == id, ct);

        if (ticket is null)
            return Problem(404, "Ticket not found.");
        if (ticket.DeletedAt is not null)
            return Problem(410, "This ticket has been deleted.");

        var newEtag = Canonical.ETagOf(
            id, body.Subject!, body.Priority!.Value,
            body.Escalated!.Value, body.Category!);

        // Already applied — idempotent success.
        if (newEtag == ticket.ETag)
        {
            Response.Headers.ETag = Canonical.Quoted(ticket.ETag);
            return NoContent();
        }

        if (!IfMatchSatisfied(ifMatch, ticket.ETag))
        {
            Response.Headers.ETag = Canonical.Quoted(ticket.ETag);
            return Problem(412, "ETag does not match the current representation.");
        }

        ticket.Subject = body.Subject!;
        ticket.Priority = body.Priority.Value;
        ticket.Escalated = body.Escalated.Value;
        ticket.Category = body.Category!;
        ticket.ETag = newEtag;

        try
        {
            await _db.SaveChangesAsync(ct);
            Response.Headers.ETag = Canonical.Quoted(newEtag);
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            // Lost a race: report the current truth.
            var current = await _db.Tickets
                .IgnoreQueryFilters()
                .SingleOrDefaultAsync(t => t.PublicId == id, ct);
            if (current is null)
                return Problem(404, "Ticket not found.");
            if (current.DeletedAt is not null)
                return Problem(410, "This ticket has been deleted.");
            if (current.ETag == newEtag)
            {
                Response.Headers.ETag = Canonical.Quoted(newEtag);
                return NoContent(); // our exact change already landed
            }
            Response.Headers.ETag = Canonical.Quoted(current.ETag);
            return Problem(412, "ETag does not match the current representation.");
        }
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, ProblemJson)]
    public async Task<IActionResult> Delete(
        Guid id,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch,
        CancellationToken ct)
    {
        // Required even when the id is unknown.
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(428, "If-Match header is required.");

        var ticket = await _db.Tickets
            .IgnoreQueryFilters()
            .SingleOrDefaultAsync(t => t.PublicId == id, ct);

        // Unknown or already deleted is an idempotent success, never 404.
        if (ticket is null || ticket.DeletedAt is not null)
            return NoContent();

        if (!IfMatchSatisfied(ifMatch, ticket.ETag))
        {
            Response.Headers.ETag = Canonical.Quoted(ticket.ETag);
            return Problem(412, "ETag does not match the current representation.");
        }

        ticket.DeletedAt = DateTime.UtcNow;
        try
        {
            await _db.SaveChangesAsync(ct);
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await _db.Tickets
                .IgnoreQueryFilters()
                .SingleOrDefaultAsync(t => t.PublicId == id, ct);
            if (current is null || current.DeletedAt is not null)
                return NoContent(); // delete already landed
            Response.Headers.ETag = Canonical.Quoted(current.ETag);
            return Problem(412, "ETag does not match the current representation.");
        }
    }
}
