using System;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json.Serialization;

namespace SupportTickets;

public class TicketInput
{
    public Guid? Id { get; set; }
    public string? Subject { get; set; }
    public int? Priority { get; set; }
    public bool? Escalated { get; set; }
    public string? Category { get; set; }

    public bool IsValid =>
        Id.HasValue && Subject != null && Priority.HasValue &&
        Escalated.HasValue && Category != null;
}

public class TicketResponse
{
    public Guid Id { get; set; }
    public string Subject { get; set; } = "";
    public int Priority { get; set; }
    public bool Escalated { get; set; }
    public string Category { get; set; } = "";

    public static TicketResponse From(Ticket t) => new()
    {
        Id = t.PublicId,
        Subject = t.Subject,
        Priority = t.Priority,
        Escalated = t.Escalated,
        Category = t.Category
    };
}

public static class Etags
{
    public static string Hash(Guid id, string subject, int priority, bool escalated, string category)
    {
        var canonical = CanonicalJson(id, subject, priority, escalated, category);
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return Convert.ToBase64String(bytes).Replace('+', '-').Replace('/', '_').TrimEnd('=');
    }

    public static string Quote(string hash) => "\"" + hash + "\"";

    static string CanonicalJson(Guid id, string subject, int priority, bool escalated, string category)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString().ToLowerInvariant()).Append("\"");
        sb.Append(",\"subject\":\"").Append(Escape(subject)).Append("\"");
        sb.Append(",\"priority\":").Append(priority.ToString(System.Globalization.CultureInfo.InvariantCulture));
        sb.Append(",\"escalated\":").Append(escalated ? "true" : "false");
        sb.Append(",\"category\":\"").Append(Escape(category)).Append("\"");
        sb.Append('}');
        return sb.ToString();
    }

    static string Escape(string s)
    {
        var normalized = s.Normalize(NormalizationForm.FormC);
        var sb = new StringBuilder(normalized.Length);
        foreach (var c in normalized)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.ToString();
    }

    public static bool Matches(string? headerValue, string quotedEtag)
    {
        if (string.IsNullOrEmpty(headerValue)) return false;
        foreach (var raw in headerValue.Split(','))
        {
            var v = raw.Trim();
            if (v.StartsWith("W/", StringComparison.Ordinal)) v = v.Substring(2);
            if (v == "*" || v == quotedEtag) return true;
        }
        return false;
    }
}
