using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace SupportTickets;

[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly TicketDbContext _db;

    public SupportTicketsController(TicketDbContext db) => _db = db;

    [HttpPost]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] TicketInput body, CancellationToken cancellationToken)
    {
        if (body == null || !body.IsValid)
            return Problem(statusCode: 400, title: "Bad Request", detail: "Invalid ticket representation.");

        var hash = Etags.Hash(body.Id!.Value, body.Subject!, body.Priority!.Value, body.Escalated!.Value, body.Category!);

        var ticket = new Ticket
        {
            PublicId = body.Id.Value,
            Subject = body.Subject!,
            Priority = body.Priority.Value,
            Escalated = body.Escalated.Value,
            Category = body.Category!,
            ETag = hash,
            CreateHash = hash,
            ViewCount = 0
        };

        _db.Tickets.Add(ticket);
        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            _db.Entry(ticket).State = EntityState.Detached;
            var existing = await _db.Tickets.IgnoreQueryFilters()
                .FirstOrDefaultAsync(t => t.PublicId == body.Id.Value, cancellationToken);
            if (existing == null) throw;
            if (existing.DeletedAt != null)
                return Problem(statusCode: 410, title: "Gone");
            if (existing.CreateHash == hash)
            {
                Response.Headers.ETag = Etags.Quote(existing.ETag);
                return Ok(TicketResponse.From(existing));
            }
            return Problem(statusCode: 409, title: "Conflict",
                detail: "A ticket with this id already exists with different content.");
        }

        Response.Headers.ETag = Etags.Quote(hash);
        return Created($"/api/support-tickets/{ticket.PublicId}", TicketResponse.From(ticket));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken cancellationToken)
    {
        var ticket = await _db.Tickets.IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);
        if (ticket == null)
            return Problem(statusCode: 404, title: "Not Found");
        if (ticket.DeletedAt != null)
            return Problem(statusCode: 410, title: "Gone");

        var etag = Etags.Quote(ticket.ETag);
        Response.Headers.ETag = etag;

        if (Etags.Matches(Request.Headers.IfNoneMatch.ToString(), etag))
            return StatusCode(304);

        await _db.Database.ExecuteSqlInterpolatedAsync(
            $"UPDATE Tickets SET ViewCount = ViewCount + 1, LastViewedAt = {DateTime.UtcNow} WHERE PublicId = {id}",
            cancellationToken);

        return Ok(TicketResponse.From(ticket));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 428, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody] TicketInput body,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken cancellationToken)
    {
        if (body == null || !body.IsValid)
            return Problem(statusCode: 400, title: "Bad Request", detail: "Invalid ticket representation.");
        if (body.Id!.Value != id)
            return Problem(statusCode: 400, title: "Bad Request",
                detail: "Body id does not match the route id.");
        if (string.IsNullOrEmpty(ifMatch))
            return Problem(statusCode: 428, title: "Precondition Required",
                detail: "The If-Match header is required.");

        var ticket = await _db.Tickets.IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);
        if (ticket == null)
            return Problem(statusCode: 404, title: "Not Found");
        if (ticket.DeletedAt != null)
            return Problem(statusCode: 410, title: "Gone");

        var currentEtag = Etags.Quote(ticket.ETag);
        var newHash = Etags.Hash(id, body.Subject!, body.Priority!.Value, body.Escalated!.Value, body.Category!);

        if (newHash == ticket.ETag)
        {
            Response.Headers.ETag = currentEtag;
            return NoContent();
        }

        if (!Etags.Matches(ifMatch, currentEtag))
        {
            Response.Headers.ETag = currentEtag;
            return Problem(statusCode: 412, title: "Precondition Failed");
        }

        ticket.Subject = body.Subject!;
        ticket.Priority = body.Priority.Value;
        ticket.Escalated = body.Escalated.Value;
        ticket.Category = body.Category!;
        ticket.ETag = newHash;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await _db.Tickets.IgnoreQueryFilters()
                .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);
            if (current == null)
                return Problem(statusCode: 404, title: "Not Found");
            if (current.DeletedAt != null)
                return Problem(statusCode: 410, title: "Gone");
            Response.Headers.ETag = Etags.Quote(current.ETag);
            return Problem(statusCode: 412, title: "Precondition Failed");
        }

        Response.Headers.ETag = Etags.Quote(newHash);
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), 428, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken cancellationToken)
    {
        if (string.IsNullOrEmpty(ifMatch))
            return Problem(statusCode: 428, title: "Precondition Required",
                detail: "The If-Match header is required.");

        var ticket = await _db.Tickets.IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);
        if (ticket == null || ticket.DeletedAt != null)
            return NoContent();

        var currentEtag = Etags.Quote(ticket.ETag);
        if (!Etags.Matches(ifMatch, currentEtag))
        {
            Response.Headers.ETag = currentEtag;
            return Problem(statusCode: 412, title: "Precondition Failed");
        }

        ticket.DeletedAt = DateTime.UtcNow;
        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await _db.Tickets.IgnoreQueryFilters()
                .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);
            if (current == null || current.DeletedAt != null)
                return NoContent();
            Response.Headers.ETag = Etags.Quote(current.ETag);
            return Problem(statusCode: 412, title: "Precondition Failed");
        }

        return NoContent();
    }
}
