// File: WarehousesController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/warehouses")]
public class WarehousesController : ControllerBase
{
    private readonly AppDbContext _db;
    public WarehousesController(AppDbContext db) => _db = db;

    private static WarehouseDto ToDto(Depot d) => new(d.Id, d.Code, d.CapacityCubicMeters);

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] WarehouseUpsertRequest req)
    {
        var id = req.Id ?? Guid.NewGuid();

        // Idempotent create: a retried POST with the same client id returns the existing row.
        var existing = await _db.Depots.FindAsync(id);
        if (existing != null)
            return Ok(ToDto(existing));

        var depot = new Depot
        {
            Id = id,
            Code = req.Code ?? "",
            CapacityCubicMeters = req.CapacityCubicMeters ?? 0,
            LastAuditAt = DateTime.UtcNow
        };
        _db.Depots.Add(depot);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            // Lost an insert race with a concurrent retry — return the winner.
            _db.Entry(depot).State = EntityState.Detached;
            var winner = await _db.Depots.FindAsync(id);
            if (winner != null) return Ok(ToDto(winner));
            throw;
        }
        return Created($"/api/warehouses/{depot.Id}", ToDto(depot));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id)
    {
        var depot = await _db.Depots.FindAsync(id);
        return depot == null ? NotFound() : Ok(ToDto(depot));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Put(Guid id, [FromBody] WarehouseUpsertRequest req)
    {
        var depot = await _db.Depots.FindAsync(id);
        if (depot == null)
        {
            // Upsert: retried PUTs against a missing row create it deterministically.
            depot = new Depot
            {
                Id = id,
                Code = req.Code ?? "",
                CapacityCubicMeters = req.CapacityCubicMeters ?? 0,
                LastAuditAt = DateTime.UtcNow
            };
            _db.Depots.Add(depot);
            try { await _db.SaveChangesAsync(); }
            catch (DbUpdateException)
            {
                _db.Entry(depot).State = EntityState.Detached;
                var winner = await _db.Depots.FindAsync(id);
                if (winner != null) return Ok(ToDto(winner));
                throw;
            }
            return Created($"/api/warehouses/{id}", ToDto(depot));
        }

        depot.Code = req.Code ?? depot.Code;
        depot.CapacityCubicMeters = req.CapacityCubicMeters ?? depot.CapacityCubicMeters;
        depot.LastAuditAt = DateTime.UtcNow;
        depot.RowVersion++;
        try { await _db.SaveChangesAsync(); }
        catch (DbUpdateConcurrencyException)
        {
            return StatusCode(409);
        }
        return Ok(ToDto(depot));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        // Idempotent delete: missing rows still return 204.
        await _db.Depots.Where(d => d.Id == id).ExecuteDeleteAsync();
        return NoContent();
    }
}
