        new(c.Id, c.DepotId, c.Reference, c.WeightKg, c.Fragile);

    [HttpPost("api/warehouses/{warehouseId:guid}/shipments")]
    public async Task<IActionResult> Create(Guid warehouseId, [FromBody] ShipmentCreateRequest req)
    {
        if (await _db.Depots.FindAsync(warehouseId) == null)
            return NotFound();

        var id = req.Id ?? Guid.NewGuid();

        var existing = await _db.Consignments.FindAsync(id);
        if (existing != null)
        {
            return existing.DepotId == warehouseId ? Ok(ToDto(existing)) : Conflict();
        }

        var consignment = new Consignment
        {
            Id = id,
            DepotId = warehouseId,
            Reference = req.Reference ?? "",
            WeightKg = req.WeightKg ?? 0m,
            Fragile = req.Fragile,
            DownloadCount = 0
        };
        _db.Consignments.Add(consignment);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            _db.Entry(consignment).State = EntityState.Detached;
            var winner = await _db.Consignments.FindAsync(id);
            if (winner != null)
                return winner.DepotId == warehouseId ? Ok(ToDto(winner)) : Conflict();
            throw;
        }
        return Created($"/api/shipments/{consignment.Id}", ToDto(consignment));
    }

    [HttpGet("api/shipments/{id:guid}")]
    public async Task<IActionResult> Get(Guid id)
    {
        var c = await _db.Consignments.FindAsync(id);
        return c == null ? NotFound() : Ok(ToDto(c));
    }

    [HttpPut("api/shipments/{id:guid}")]
    public async Task<IActionResult> Put(Guid id, [FromBody] ShipmentUpdateRequest req)
    {
        var c = await _db.Consignments.FindAsync(id);
        if (c == null) return NotFound();

        c.Reference = req.Reference ?? c.Reference;
        c.WeightKg = req.WeightKg ?? c.WeightKg;
        c.Fragile = req.Fragile;
        c.RowVersion++;
        try { await _db.SaveChangesAsync(); }
        catch (DbUpdateConcurrencyException)
        {
            return StatusCode(409);
        }
        return Ok(ToDto(c));
    }

    [HttpDelete("api/shipments/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        await _db.Consignments.Where(c => c.Id == id).ExecuteDeleteAsync();
        return NoContent();
    }
