            _db.Entry(depot).State = EntityState.Detached;
            var winner = await _db.Depots.FindAsync(id);
            if (winner != null) return Ok(ToDto(winner));
            throw;
        }
        return CreatedAtAction(nameof(Get), new { id = depot.Id }, ToDto(depot));
