        if (req.WarehouseId.HasValue && req.WarehouseId.Value != c.DepotId)
        {
            if (!await _db.Depots.AnyAsync(d => d.Id == req.WarehouseId.Value))
                return NotFound();
            c.DepotId = req.WarehouseId.Value;
