// WarehousesController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/warehouses")]
public class WarehousesController : ControllerBase
{
    private readonly AppDbContext _db;

    public WarehousesController(AppDbContext db) => _db = db;

    private static WarehouseDto ToDto(Depot d) =>
        new(d.Id, d.Code, d.CapacityCubicMeters);

    [HttpPost]
    public async Task<ActionResult<WarehouseDto>> Create([FromBody] WarehouseUpsert body)
    {
        var id = body.Id is { } given && given != Guid.Empty ? given : Guid.NewGuid();

        // Idempotent for client retries: if a depot with this id already
        // exists, return it rather than failing on the duplicate key.
        var existing = await _db.Depots.FindAsync(id);
        if (existing is not null)
            return Ok(ToDto(existing));

        var depot = new Depot
        {
            Id = id,
            Code = body.Code ?? string.Empty,
            CapacityCubicMeters = body.CapacityCubicMeters
        };
        _db.Depots.Add(depot);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            var raced = await _db.Depots.AsNoTracking().FirstOrDefaultAsync(d => d.Id == id);
            if (raced is not null)
                return Ok(ToDto(raced));
            throw;
        }

        return CreatedAtAction(nameof(Get), new { id = depot.Id }, ToDto(depot));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<WarehouseDto>> Get(Guid id)
    {
        var depot = await _db.Depots.AsNoTracking().FirstOrDefaultAsync(d => d.Id == id);
        if (depot is null) return NotFound();
        depot.LastAuditAt = null; // never exposed anyway; DTO excludes it
        return Ok(ToDto(depot));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<WarehouseDto>> Update(Guid id, [FromBody] WarehouseUpsert body)
    {
        var depot = await _db.Depots.FindAsync(id);
        if (depot is null) return NotFound();

        depot.Code = body.Code ?? depot.Code;
        depot.CapacityCubicMeters = body.CapacityCubicMeters;
        depot.ConcurrencyStamp = Guid.NewGuid();
        depot.LastAuditAt = DateTime.UtcNow;

        await _db.SaveChangesAsync();
        return Ok(ToDto(depot));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        // Delete-if-present: idempotent under retries and concurrent deletes.
        var affected = await _db.Depots.Where(d => d.Id == id).ExecuteDeleteAsync();
        return affected > 0 ? NoContent() : NotFound();
    }

    [HttpPost("{warehouseId:guid}/shipments")]
    public async Task<ActionResult<ShipmentDto>> CreateShipment(Guid warehouseId, [FromBody] ShipmentUpsert body)
    {
        if (!await _db.Depots.AnyAsync(d => d.Id == warehouseId))
            return NotFound();

        var id = body.Id is { } given && given != Guid.Empty ? given : Guid.NewGuid();

        var existing = await _db.Consignments.FindAsync(id);
        if (existing is not null)
            return Ok(ShipmentsController.ToDto(existing));

        var consignment = new Consignment
        {
            Id = id,
            DepotId = warehouseId,
            Reference = body.Reference ?? string.Empty,
            WeightKg = body.WeightKg,
            Fragile = body.Fragile,
            DownloadCount = 0
        };
        _db.Consignments.Add(consignment);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            var raced = await _db.Consignments.AsNoTracking().FirstOrDefaultAsync(c => c.Id == id);
            if (raced is not null)
                return Ok(ShipmentsController.ToDto(raced));
            if (!await _db.Depots.AnyAsync(d => d.Id == warehouseId))
                return NotFound();
            throw;
        }

        return CreatedAtAction(
            actionName: nameof(ShipmentsController.Get),
            controllerName: "Shipments",
            routeValues: new { id = consignment.Id },
            value: ShipmentsController.ToDto(consignment));
    }
}
