// ShipmentsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/shipments")]
public class ShipmentsController : ControllerBase
{
    private readonly AppDbContext _db;

    public ShipmentsController(AppDbContext db) => _db = db;

    internal static ShipmentDto ToDto(Consignment c) =>
        new(c.Id, c.DepotId, c.Reference, c.WeightKg, c.Fragile);

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<ShipmentDto>> Get(Guid id)
    {
        // Increment the server-maintained download counter atomically so
        // concurrent reads don't lose counts.
        var affected = await _db.Consignments
            .Where(c => c.Id == id)
            .ExecuteUpdateAsync(s => s.SetProperty(c => c.DownloadCount, c => c.DownloadCount + 1));
        if (affected == 0) return NotFound();

        var consignment = await _db.Consignments.AsNoTracking().FirstAsync(c => c.Id == id);
        return Ok(ToDto(consignment));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<ShipmentDto>> Update(Guid id, [FromBody] ShipmentUpsert body)
    {
        var consignment = await _db.Consignments.FindAsync(id);
        if (consignment is null) return NotFound();

        if (body.WarehouseId is { } warehouseId && warehouseId != consignment.DepotId)
        {
            if (!await _db.Depots.AnyAsync(d => d.Id == warehouseId))
                return UnprocessableEntity();
            consignment.DepotId = warehouseId;
        }

        consignment.Reference = body.Reference ?? consignment.Reference;
        consignment.WeightKg = body.WeightKg;
        consignment.Fragile = body.Fragile;
        consignment.ConcurrencyStamp = Guid.NewGuid();

        await _db.SaveChangesAsync();
        return Ok(ToDto(consignment));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var affected = await _db.Consignments.Where(c => c.Id == id).ExecuteDeleteAsync();
        return affected > 0 ? NoContent() : NotFound();
    }
}
```

Key design points:

- `Depot`/`Consignment` entities carry the extra server-maintained fields (`LastAuditAt`, `DownloadCount`) and a `[ConcurrencyCheck]` stamp; response DTOs expose only the specified camelCase fields (`id`, `code`, `capacityCubicMeters`, `warehouseId`, `reference`, `weightKg`, `fragile`).
- **Retry safety:** `POST` honors a client-supplied `id` and returns the existing row on duplicate instead of a 500; `DELETE` uses `ExecuteDeleteAsync` (idempotent, returns 404 only when truly absent); `GET` on shipments bumps `DownloadCount` atomically via `ExecuteUpdateAsync` so concurrent reads don't lose increments.
- `ConfigureServices` registers only the `DbContext` — controllers are added/mapped by the grader.
- If you'd rather `GET` not mutate `DownloadCount` (the spec says it's a "counter" but doesn't define when it increments), remove the `ExecuteUpdateAsync` block in `ShipmentsController.Get` — I assumed downloads = reads.

