using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/warehouses")]
public class WarehousesController : ControllerBase
{
    private readonly AppDbContext _db;

    public WarehousesController(AppDbContext db) => _db = db;

    [HttpPost]
    public async Task<ActionResult<WarehouseResponse>> Create([FromBody] WarehouseRequest req)
    {
        var id = req.Id == Guid.Empty ? Guid.NewGuid() : req.Id;

        // Idempotent create: a retry with the same id returns the existing row.
        var existing = await _db.Depots.FindAsync(id);
        if (existing != null)
            return Ok(WarehouseResponse.From(existing));

        var depot = new Depot
        {
            Id = id,
            Code = req.Code,
            CapacityCubicMeters = req.CapacityCubicMeters,
            LastAuditAt = DateTime.UtcNow
        };
        _db.Depots.Add(depot);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            _db.Entry(depot).State = EntityState.Detached;
            var winner = await _db.Depots.FindAsync(id);
            if (winner != null)
                return Ok(WarehouseResponse.From(winner));
            return Conflict();
        }

        return CreatedAtAction(nameof(Get), new { id = depot.Id }, WarehouseResponse.From(depot));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<WarehouseResponse>> Get(Guid id)
    {
        var depot = await _db.Depots.FindAsync(id);
        if (depot == null)
            return NotFound();
        return Ok(WarehouseResponse.From(depot));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<WarehouseResponse>> Update(Guid id, [FromBody] WarehouseRequest req)
    {
        var depot = await _db.Depots.FindAsync(id);
        if (depot == null)
            return NotFound();

        depot.Code = req.Code;
        depot.CapacityCubicMeters = req.CapacityCubicMeters;
        depot.LastAuditAt = DateTime.UtcNow;

        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateConcurrencyException)
        {
            if (!await _db.Depots.AnyAsync(d => d.Id == id))
                return NotFound();
            // Last-writer-wins retry for concurrent updates.
            _db.Entry(depot).Reload();
            depot.Code = req.Code;
            depot.CapacityCubicMeters = req.CapacityCubicMeters;
            depot.LastAuditAt = DateTime.UtcNow;
            await _db.SaveChangesAsync();
        }

        return Ok(WarehouseResponse.From(depot));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var depot = await _db.Depots.FindAsync(id);
        if (depot == null)
            return NotFound();

        _db.Depots.Remove(depot);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateConcurrencyException)
        {
            return NotFound();
        }
        return NoContent();
    }

    [HttpPost("{warehouseId:guid}/shipments")]
    public async Task<ActionResult<ShipmentResponse>> CreateShipment(Guid warehouseId, [FromBody] ShipmentRequest req)
    {
        var depot = await _db.Depots.FindAsync(warehouseId);
        if (depot == null)
            return NotFound();

        var id = req.Id == Guid.Empty ? Guid.NewGuid() : req.Id;

        var existing = await _db.Consignments.FindAsync(id);
        if (existing != null)
            return Ok(ShipmentResponse.From(existing));

        var consignment = new Consignment
        {
            Id = id,
            DepotId = warehouseId,
            Reference = req.Reference,
            WeightKg = req.WeightKg,
            Fragile = req.Fragile,
            DownloadCount = 0
        };
        _db.Consignments.Add(consignment);
        try
        {
            await _db.SaveChangesAsync();
