    [HttpGet("{id:guid}")]
    public async Task<ActionResult<ShipmentResponse>> Get(Guid id)
    {
        var c = await _db.Consignments.FindAsync(id);
        if (c == null)
            return NotFound();

        c.DownloadCount++;
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateConcurrencyException)
        {
            return NotFound();
        }

        return Ok(ShipmentResponse.From(c));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<ShipmentResponse>> Update(Guid id, [FromBody] ShipmentRequest req)
    {
        var c = await _db.Consignments.FindAsync(id);
        if (c == null)
            return NotFound();

        if (req.WarehouseId != Guid.Empty && req.WarehouseId != c.DepotId)
        {
            if (!await _db.Depots.AnyAsync(d => d.Id == req.WarehouseId))
                return NotFound();
            c.DepotId = req.WarehouseId;
        }

        c.Reference = req.Reference;
        c.WeightKg = req.WeightKg;
        c.Fragile = req.Fragile;

        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateConcurrencyException)
        {
            if (!await _db.Consignments.AnyAsync(x => x.Id == id))
                return NotFound();
            await _db.Entry(c).ReloadAsync();
            c.Reference = req.Reference;
            c.WeightKg = req.WeightKg;
            c.Fragile = req.Fragile;
            if (req.WarehouseId != Guid.Empty)
                c.DepotId = req.WarehouseId;
            await _db.SaveChangesAsync();
        }

        return Ok(ShipmentResponse.From(c));
