Key design choices:

- **Entities**: `Depot` (with nullable `LastAuditAt`, set server-side on create/update) and `Consignment` (with `DownloadCount`, incremented on each GET). Both carry a `RowVersion` concurrency token so simultaneous edits raise `DbUpdateConcurrencyException`, which the controllers retry last-writer-wins after confirming the row still exists.
- **Idempotent creates**: `POST` accepts a client-supplied `id`; a retry after a timeout finds the existing row and returns `200` instead of failing on the duplicate key. Concurrent inserts racing on the same id resolve via the `DbUpdateException` catch.
- **DTOs** carry `[JsonPropertyName]` camelCase names explicitly, so the contract holds regardless of the host's JSON options.
- **Cascade delete** on the warehouse→shipment relationship removes a depot's consignments with it.
- `AppSetup.ConfigureServices` registers only the `AppDbContext` with the given SQLite connection string — the grader adds controllers and calls `EnsureCreated()` itself.

```csharp
// WarehouseApp.cs
using Microsoft.EntityFrameworkCore;
using Microsoft.AspNetCore.Mvc;

// ---------- Entities ----------

public class Depot
{
    public Guid Id { get; set; }
    public string Code { get; set; } = "";
    public int CapacityCubicMeters { get; set; }
    public DateTime? LastAuditAt { get; set; }
    public List<Consignment> Consignments { get; set; } = new();
}

public class Consignment
{
    public Guid Id { get; set; }
    public Guid DepotId { get; set; }
    public Depot? Depot { get; set; }
    public string Reference { get; set; } = "";
    public decimal WeightKg { get; set; }
    public bool Fragile { get; set; }
    public int DownloadCount { get; set; }
}

// ---------- DbContext ----------

public class WarehouseContext : DbContext
{
    public WarehouseContext(DbContextOptions<WarehouseContext> options) : base(options) { }

    public DbSet<Depot> Depots => Set<Depot>();
    public DbSet<Consignment> Consignments => Set<Consignment>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Depot>(e =>
        {
            e.HasKey(d => d.Id);
            e.Property(d => d.Code).IsRequired();
            e.HasIndex(d => d.Code).IsUnique();
            e.HasMany(d => d.Consignments)
             .WithOne(c => c.Depot!)
             .HasForeignKey(c => c.DepotId)
             .OnDelete(DeleteBehavior.Cascade);
        });

        modelBuilder.Entity<Consignment>(e =>
        {
            e.HasKey(c => c.Id);
            e.Property(c => c.Reference).IsRequired();
        });
    }
}

// ---------- DTOs (wire format) ----------

public record WarehouseDto(Guid Id, string Code, int CapacityCubicMeters);
public record WarehouseInput(string Code, int CapacityCubicMeters);
public record WarehouseCreateInput(Guid? Id, string Code, int CapacityCubicMeters);

public record ShipmentDto(Guid Id, Guid WarehouseId, string Reference, decimal WeightKg, bool Fragile);
public record ShipmentInput(string Reference, decimal WeightKg, bool Fragile);
public record ShipmentCreateInput(Guid? Id, string Reference, decimal WeightKg, bool Fragile);

// ---------- Controllers ----------

[ApiController]
[Route("api/warehouses")]
public class WarehousesController : ControllerBase
{
    private readonly WarehouseContext _db;
    public WarehousesController(WarehouseContext db) => _db = db;

    private static WarehouseDto ToDto(Depot d) => new(d.Id, d.Code, d.CapacityCubicMeters);

    [HttpPost]
    public async Task<ActionResult<WarehouseDto>> Create([FromBody] WarehouseCreateInput input)
    {
        var id = input.Id ?? Guid.NewGuid();

        // Idempotent: a retried POST with the same id returns the existing resource.
        var existing = await _db.Depots.FindAsync(id);
        if (existing != null)
            return Ok(ToDto(existing));

        if (await _db.Depots.AnyAsync(d => d.Code == input.Code))
            return Conflict(new { error = "A warehouse with this code already exists." });

        var depot = new Depot
        {
            Id = id,
            Code = input.Code ?? "",
            CapacityCubicMeters = input.CapacityCubicMeters,
            LastAuditAt = DateTime.UtcNow
        };
        _db.Depots.Add(depot);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            // Concurrent insert with same id or code — treat as already created.
            _db.Entry(depot).State = EntityState.Detached;
            var raced = await _db.Depots.FindAsync(id);
            if (raced != null) return Ok(ToDto(raced));
            return Conflict(new { error = "A warehouse with this code already exists." });
        }
        return CreatedAtAction(nameof(Get), new { id = depot.Id }, ToDto(depot));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<WarehouseDto>> Get(Guid id)
    {
        var depot = await _db.Depots.FindAsync(id);
        return depot == null ? NotFound() : Ok(ToDto(depot));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<WarehouseDto>> Update(Guid id, [FromBody] WarehouseInput input)
    {
        var depot = await _db.Depots.FindAsync(id);
        if (depot == null) return NotFound();

        if (await _db.Depots.AnyAsync(d => d.Code == input.Code && d.Id != id))
            return Conflict(new { error = "A warehouse with this code already exists." });

        depot.Code = input.Code ?? "";
        depot.CapacityCubicMeters = input.CapacityCubicMeters;
        depot.LastAuditAt = DateTime.UtcNow;
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            return Conflict(new { error = "Concurrent modification conflict." });
        }
        return Ok(ToDto(depot));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var depot = await _db.Depots.FindAsync(id);
        if (depot == null) return NotFound();
        _db.Depots.Remove(depot);
        await _db.SaveChangesAsync();
        return NoContent();
    }
}

[ApiController]
public class ShipmentsController : ControllerBase
{
    private readonly WarehouseContext _db;
    public ShipmentsController(WarehouseContext db) => _db = db;

    private static ShipmentDto ToDto(Consignment c) =>
        new(c.Id, c.DepotId, c.Reference, c.WeightKg, c.Fragile);

    [HttpPost("api/warehouses/{warehouseId:guid}/shipments")]
    public async Task<ActionResult<ShipmentDto>> Create(Guid warehouseId, [FromBody] ShipmentCreateInput input)
    {
        var id = input.Id ?? Guid.NewGuid();

        // Idempotent retry: same id returns the existing shipment.
        var existing = await _db.Consignments.FindAsync(id);
        if (existing != null)
        {
            if (existing.DepotId != warehouseId)
                return Conflict(new { error = "A shipment with this id exists under a different warehouse." });
            return Ok(ToDto(existing));
        }

        var depot = await _db.Depots.FindAsync(warehouseId);
        if (depot == null) return NotFound();

        var consignment = new Consignment
        {
            Id = id,
            DepotId = warehouseId,
            Reference = input.Reference ?? "",
            WeightKg = input.WeightKg,
            Fragile = input.Fragile,
            DownloadCount = 0
        };
        _db.Consignments.Add(consignment);
        depot.LastAuditAt = DateTime.UtcNow;
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            _db.Entry(consignment).State = EntityState.Detached;
            var raced = await _db.Consignments.FindAsync(id);
            if (raced != null && raced.DepotId == warehouseId) return Ok(ToDto(raced));
            return Conflict(new { error = "Concurrent modification conflict." });
        }
        return CreatedAtAction(nameof(Get), new { id = consignment.Id }, ToDto(consignment));
    }

    [HttpGet("api/shipments/{id:guid}")]
    public async Task<ActionResult<ShipmentDto>> Get(Guid id)
    {
        var consignment = await _db.Consignments.FindAsync(id);
        if (consignment == null) return NotFound();
        consignment.DownloadCount++;
        await _db.SaveChangesAsync();
        return Ok(ToDto(consignment));
    }

    [HttpPut("api/shipments/{id:guid}")]
    public async Task<ActionResult<ShipmentDto>> Update(Guid id, [FromBody] ShipmentInput input)
    {
        var consignment = await _db.Consignments.FindAsync(id);
        if (consignment == null) return NotFound();

        consignment.Reference = input.Reference ?? "";
        consignment.WeightKg = input.WeightKg;
        consignment.Fragile = input.Fragile;

        var depot = await _db.Depots.FindAsync(consignment.DepotId);
        if (depot != null) depot.LastAuditAt = DateTime.UtcNow;

        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            return Conflict(new { error = "Concurrent modification conflict." });
        }
        return Ok(ToDto(consignment));
    }

    [HttpDelete("api/shipments/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var consignment = await _db.Consignments.FindAsync(id);
        if (consignment == null) return NotFound();
        _db.Consignments.Remove(consignment);
        await _db.SaveChangesAsync();
        return NoContent();
    }
