using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/warehouses")]
public class WarehousesController : ControllerBase
{
    private readonly AppDbContext _db;

    public WarehousesController(AppDbContext db) => _db = db;

    private static WarehouseDto ToDto(Depot d) => new()
    {
        Id = d.Id,
        Code = d.Code,
        CapacityCubicMeters = d.CapacityCubicMeters
    };

    [HttpPost]
    public async Task<ActionResult<WarehouseDto>> Create([FromBody] WarehouseDto dto)
    {
        var existing = await _db.Depots.FindAsync(dto.Id);
        if (existing is not null)
        {
            // Idempotent retry: same payload returns the existing resource.
            if (existing.Code == dto.Code && existing.CapacityCubicMeters == dto.CapacityCubicMeters)
                return Ok(ToDto(existing));
            return Conflict();
        }

        var depot = new Depot
        {
            Id = dto.Id == Guid.Empty ? Guid.NewGuid() : dto.Id,
            Code = dto.Code,
            CapacityCubicMeters = dto.CapacityCubicMeters,
            LastAuditAt = DateTime.UtcNow
        };
        _db.Depots.Add(depot);
        await _db.SaveChangesAsync();
        return CreatedAtAction(nameof(GetById), new { id = depot.Id }, ToDto(depot));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<WarehouseDto>> GetById(Guid id)
    {
        var depot = await _db.Depots.FindAsync(id);
        return depot is null ? NotFound() : Ok(ToDto(depot));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<WarehouseDto>> Update(Guid id, [FromBody] WarehouseDto dto)
    {
        var depot = await _db.Depots.FindAsync(id);
        if (depot is null) return NotFound();

        depot.Code = dto.Code;
        depot.CapacityCubicMeters = dto.CapacityCubicMeters;
        depot.LastAuditAt = DateTime.UtcNow;
        await _db.SaveChangesAsync();
        return Ok(ToDto(depot));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var depot = await _db.Depots.FindAsync(id);
        if (depot is null) return NotFound();
        _db.Depots.Remove(depot);
        await _db.SaveChangesAsync();
        return NoContent();
    }
}
