// ShipmentsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
public class ShipmentsController : ControllerBase
{
    private readonly AppDbContext _db;

    public ShipmentsController(AppDbContext db) => _db = db;

    private static ShipmentDto ToDto(Consignment c) => new()
    {
        Id = c.Id,
        WarehouseId = c.DepotId,
        Reference = c.Reference,
        WeightKg = c.WeightKg,
        Fragile = c.Fragile
    };

    [HttpPost("api/warehouses/{warehouseId:guid}/shipments")]
    public async Task<ActionResult<ShipmentDto>> Create(Guid warehouseId, [FromBody] ShipmentDto dto)
    {
        var depot = await _db.Depots.FindAsync(warehouseId);
        if (depot is null) return NotFound();

        var existing = await _db.Consignments.FindAsync(dto.Id);
        if (existing is not null)
        {
            // Idempotent retry of the same create.
            if (existing.DepotId == warehouseId &&
                existing.Reference == dto.Reference &&
                existing.WeightKg == dto.WeightKg &&
                existing.Fragile == dto.Fragile)
                return Ok(ToDto(existing));
            return Conflict();
        }

        var consignment = new Consignment
        {
            Id = dto.Id == Guid.Empty ? Guid.NewGuid() : dto.Id,
            DepotId = warehouseId,
            Reference = dto.Reference,
            WeightKg = dto.WeightKg,
            Fragile = dto.Fragile,
            DownloadCount = 0
        };
        _db.Consignments.Add(consignment);
        depot.LastAuditAt = DateTime.UtcNow;
        await _db.SaveChangesAsync();
        return CreatedAtAction(nameof(GetById), new { id = consignment.Id }, ToDto(consignment));
    }

    [HttpGet("api/shipments/{id:guid}")]
    public async Task<ActionResult<ShipmentDto>> GetById(Guid id)
    {
        var c = await _db.Consignments.FindAsync(id);
        if (c is null) return NotFound();

        c.DownloadCount++;
        await _db.SaveChangesAsync();
        return Ok(ToDto(c));
    }

    [HttpPut("api/shipments/{id:guid}")]
    public async Task<ActionResult<ShipmentDto>> Update(Guid id, [FromBody] ShipmentDto dto)
    {
        var c = await _db.Consignments.FindAsync(id);
        if (c is null) return NotFound();

        if (dto.WarehouseId != Guid.Empty && dto.WarehouseId != c.DepotId)
        {
            var depot = await _db.Depots.FindAsync(dto.WarehouseId);
            if (depot is null) return NotFound();
            c.DepotId = dto.WarehouseId;
        }

        c.Reference = dto.Reference;
        c.WeightKg = dto.WeightKg;
        c.Fragile = dto.Fragile;
        await _db.SaveChangesAsync();
        return Ok(ToDto(c));
    }

    [HttpDelete("api/shipments/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var c = await _db.Consignments.FindAsync(id);
        if (c is null) return NotFound();
        _db.Consignments.Remove(c);
        await _db.SaveChangesAsync();
        return NoContent();
    }
}
