// File: Infrastructure.cs
using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;
using Microsoft.Extensions.DependencyInjection;

public class Depot
{
    public int Id { get; set; }                      // internal PK, never exposed
    public Guid PublicId { get; set; }
    public string Code { get; set; } = "";
    public int CapacityCubicMeters { get; set; }
    public string ETag { get; set; } = "";           // concurrency token
    public string CreateHash { get; set; } = "";     // immutable hash of the create representation
    public DateTime? DeletedAt { get; set; }         // tombstone
    public DateTime? LastAuditAt { get; set; }       // server-owned
    public List<Consignment> Consignments { get; set; } = new();
}

public class Consignment
{
    public int Id { get; set; }
    public Guid PublicId { get; set; }
    public int DepotId { get; set; }
    public Depot Depot { get; set; } = null!;
    public Guid DepotPublicId { get; set; }
    public string Reference { get; set; } = "";
    public decimal WeightKg { get; set; }
    public bool Fragile { get; set; }
    public int DownloadCount { get; set; }           // server-owned, changes on reads
    public string ETag { get; set; } = "";
    public string CreateHash { get; set; } = "";
    public DateTime? DeletedAt { get; set; }
}

public class AppDbContext : DbContext
{
    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }

    public DbSet<Depot> Depots => Set<Depot>();
    public DbSet<Consignment> Consignments => Set<Consignment>();

    protected override void OnModelCreating(ModelBuilder mb)
    {
        mb.Entity<Depot>(e =>
        {
            e.HasKey(x => x.Id);
            e.HasIndex(x => x.PublicId).IsUnique();
            e.Property(x => x.Code).IsRequired();
            e.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
            e.Property(x => x.CreateHash).IsRequired()
                .Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            e.HasQueryFilter(x => x.DeletedAt == null);
        });
        mb.Entity<Consignment>(e =>
        {
            e.HasKey(x => x.Id);
            e.HasIndex(x => x.PublicId).IsUnique();
            e.Property(x => x.Reference).IsRequired();
            e.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
            e.Property(x => x.CreateHash).IsRequired()
                .Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            e.HasOne(x => x.Depot).WithMany(d => d.Consignments).HasForeignKey(x => x.DepotId);
            e.HasQueryFilter(x => x.DeletedAt == null);
        });
    }
}

