// ---------- Canonical JSON + ETag ----------

public static class ETags
{
    public static string Compute(string canonicalJson)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson));
        return "\"" + System.Buffers.Text.Base64Url.EncodeToString(hash) + "\"";
    }

    public static string DepotJson(Guid id, string code, int capacity)
        => "{\"id\":" + Str(id.ToString())
         + ",\"code\":" + Str(code)
         + ",\"capacityCubicMeters\":" + capacity.ToString(CultureInfo.InvariantCulture) + "}";

    public static string ConsignmentJson(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile)
        => "{\"id\":" + Str(id.ToString())
         + ",\"warehouseId\":" + Str(warehouseId.ToString())
         + ",\"reference\":" + Str(reference)
         + ",\"weightKg\":" + Num(weightKg)
         + ",\"fragile\":" + (fragile ? "true" : "false") + "}";

    static string Num(decimal d)
    {
        if (d == decimal.Truncate(d) && Math.Abs(d) < 1e18m)
            return ((long)d).ToString(CultureInfo.InvariantCulture);
        return d.ToString("0.############################", CultureInfo.InvariantCulture);
    }

    static string Str(string s)
    {
        s = s.Normalize(NormalizationForm.FormC);
        var sb = new StringBuilder(s.Length + 2).Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }

    // Does an If-Match / If-None-Match header value match the current quoted etag?
    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var part in header.Split(','))
        {
            var t = part.Trim();
            if (t == "*") return true;
            if (t.StartsWith("W/")) t = t.Substring(2).Trim();
            if (t == etag) return true;
        }
        return false;
    }
}
