[ApiController]
[Route("api/warehouses")]
public class WarehousesController : ControllerBase
{
    private readonly AppDbContext _db;
    public WarehousesController(AppDbContext db) => _db = db;

    static WarehouseResponse ToResponse(Depot d)
        => new WarehouseResponse { Id = d.PublicId, Code = d.Code, CapacityCubicMeters = d.CapacityCubicMeters };

    void SetETag(string etag) => Response.Headers.ETag = etag;

    [HttpPost]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] WarehouseBody? body, CancellationToken ct)
    {
        if (body is null || body.Id is null || body.Code is null || body.CapacityCubicMeters is null)
            return ApiHelpers.Problem(400, "Invalid body.");

        var json = ETags.DepotJson(body.Id.Value, body.Code, body.CapacityCubicMeters.Value);
        var hash = ETags.Compute(json);

        var existing = await _db.Depots.IgnoreQueryFilters()
            .FirstOrDefaultAsync(d => d.PublicId == body.Id.Value, ct);
        if (existing is not null)
        {
            if (existing.DeletedAt is not null) return ApiHelpers.Problem(410, "Gone.");
            if (existing.CreateHash == hash)
            {
                SetETag(existing.ETag);
                return Ok(ToResponse(existing));
            }
            return ApiHelpers.Problem(409, "Id already exists with different content.");
        }

        var depot = new Depot
        {
            PublicId = body.Id.Value,
            Code = body.Code,
            CapacityCubicMeters = body.CapacityCubicMeters.Value,
            ETag = hash,
            CreateHash = hash,
            LastAuditAt = DateTime.UtcNow
        };
        _db.Depots.Add(depot);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (ApiHelpers.IsUniqueViolation(ex))
        {
            _db.Entry(depot).State = EntityState.Detached;
            var raced = await _db.Depots.IgnoreQueryFilters()
                .FirstAsync(d => d.PublicId == body.Id.Value, ct);
            if (raced.DeletedAt is not null) return ApiHelpers.Problem(410, "Gone.");
            if (raced.CreateHash == hash)
            {
                SetETag(raced.ETag);
                return Ok(ToResponse(raced));
            }
            return ApiHelpers.Problem(409, "Id already exists with different content.");
        }

        SetETag(depot.ETag);
        return CreatedAtAction(nameof(Get), new { id = depot.PublicId }, ToResponse(depot));
    }

    [HttpGet("{id}")]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var depot = await _db.Depots.IgnoreQueryFilters()
            .FirstOrDefaultAsync(d => d.PublicId == id, ct);
        if (depot is null) return ApiHelpers.Problem(404, "Not found.");
        if (depot.DeletedAt is not null) return ApiHelpers.Problem(410, "Gone.");

        SetETag(depot.ETag);
        if (ETags.Matches(Request.Headers.IfNoneMatch.ToString(), depot.ETag))
            return StatusCode(304);
        return Ok(ToResponse(depot));
    }

    [HttpPut("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody] WarehouseBody? body,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken ct)
    {
        if (body is null || body.Id is null || body.Code is null || body.CapacityCubicMeters is null)
            return ApiHelpers.Problem(400, "Invalid body.");
        if (body.Id.Value != id)
            return ApiHelpers.Problem(400, "Body id differs from route id.");
        if (string.IsNullOrWhiteSpace(ifMatch))
            return ApiHelpers.Problem(428, "If-Match is required.");

        var depot = await _db.Depots.IgnoreQueryFilters()
            .FirstOrDefaultAsync(d => d.PublicId == id, ct);
        if (depot is null) return ApiHelpers.Problem(404, "Not found.");
        if (depot.DeletedAt is not null) return ApiHelpers.Problem(410, "Gone.");

        var newJson = ETags.DepotJson(id, body.Code, body.CapacityCubicMeters.Value);
        var newHash = ETags.Compute(newJson);

        if (newHash == depot.ETag) { SetETag(depot.ETag); return NoContent(); }

        if (!ETags.Matches(ifMatch, depot.ETag))
        {
            SetETag(depot.ETag);
            return ApiHelpers.Problem(412, "ETag mismatch.");
        }

        depot.Code = body.Code;
        depot.CapacityCubicMeters = body.CapacityCubicMeters.Value;
        depot.ETag = newHash;
        depot.LastAuditAt = DateTime.UtcNow;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await _db.Depots.IgnoreQueryFilters()
                .AsNoTracking().FirstOrDefaultAsync(d => d.PublicId == id, ct);
            if (current is not null) SetETag(current.ETag);
            return ApiHelpers.Problem(412, "ETag mismatch.");
        }
        SetETag(newHash);
        return NoContent();
    }

    [HttpDelete("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return ApiHelpers.Problem(428, "If-Match is required.");

        var depot = await _db.Depots.IgnoreQueryFilters()
            .Include(d => d.Consignments)
            .FirstOrDefaultAsync(d => d.PublicId == id, ct);
        if (depot is null || depot.DeletedAt is not null) return NoContent();

        if (!ETags.Matches(ifMatch, depot.ETag))
        {
            SetETag(depot.ETag);
            return ApiHelpers.Problem(412, "ETag mismatch.");
        }

        var now = DateTime.UtcNow;
        depot.DeletedAt = now;
        depot.LastAuditAt = now;
        foreach (var c in depot.Consignments.Where(c => c.DeletedAt is null))
            c.DeletedAt = now;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return ApiHelpers.Problem(412, "ETag mismatch.");
        }
        return NoContent();
    }
}

