    [HttpPost("api/warehouses/{warehouseId}/shipments")]
    [ProducesResponseType(typeof(ConsignmentResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(ConsignmentResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create(Guid warehouseId, [FromBody] ConsignmentBody? body, CancellationToken ct)
    {
        if (body is null || body.Id is null || body.WarehouseId is null
            || body.Reference is null || body.WeightKg is null || body.Fragile is null)
            return ApiHelpers.Problem(400, "Invalid body.");
        if (body.WarehouseId.Value != warehouseId)
            return ApiHelpers.Problem(400, "Body warehouseId differs from route.");

        var depot = await _db.Depots.IgnoreQueryFilters()
            .FirstOrDefaultAsync(d => d.PublicId == warehouseId, ct);
        if (depot is null) return ApiHelpers.Problem(404, "Warehouse not found.");
        if (depot.DeletedAt is not null) return ApiHelpers.Problem(410, "Warehouse is gone.");

        var json = ETags.ConsignmentJson(body.Id.Value, warehouseId, body.Reference,
            body.WeightKg.Value, body.Fragile.Value);
        var hash = ETags.Compute(json);

        var existing = await _db.Consignments.IgnoreQueryFilters()
            .FirstOrDefaultAsync(c => c.PublicId == body.Id.Value, ct);
        if (existing is not null)
        {
            if (existing.DepotPublicId != warehouseId)
                return ApiHelpers.Problem(409, "Id exists under a different warehouse.");
            if (existing.DeletedAt is not null) return ApiHelpers.Problem(410, "Gone.");
            if (existing.CreateHash == hash)
            {
                SetETag(existing.ETag);
                return Ok(ToResponse(existing));
            }
            return ApiHelpers.Problem(409, "Id already exists with different content.");
        }

        var cons = new Consignment
        {
            PublicId = body.Id.Value,
            DepotId = depot.Id,
            DepotPublicId = warehouseId,
            Reference = body.Reference,
            WeightKg = body.WeightKg.Value,
            Fragile = body.Fragile.Value,
            ETag = hash,
            CreateHash = hash
        };
        _db.Consignments.Add(cons);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (ApiHelpers.IsUniqueViolation(ex))
        {
            _db.Entry(cons).State = EntityState.Detached;
            var raced = await _db.Consignments.IgnoreQueryFilters()
                .FirstAsync(c => c.PublicId == body.Id.Value, ct);
            if (raced.DepotPublicId != warehouseId)
                return ApiHelpers.Problem(409, "Id exists under a different warehouse.");
            if (raced.DeletedAt is not null) return ApiHelpers.Problem(410, "Gone.");
            if (raced.CreateHash == hash)
            {
                SetETag(raced.ETag);
                return Ok(ToResponse(raced));
            }
            return ApiHelpers.Problem(409, "Id already exists with different content.");
        }

        SetETag(cons.ETag);
        return CreatedAtAction(nameof(Get), new { id = cons.PublicId }, ToResponse(cons));
    }

    [HttpGet("api/shipments/{id}")]
    [ProducesResponseType(typeof(ConsignmentResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var cons = await _db.Consignments.IgnoreQueryFilters()
            .FirstOrDefaultAsync(c => c.PublicId == id, ct);
        if (cons is null) return ApiHelpers.Problem(404, "Not found.");
        if (cons.DeletedAt is not null) return ApiHelpers.Problem(410, "Gone.");

        // Server-owned read counter; never part of the representation or ETag.
        cons.DownloadCount++;
        try { await _db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { /* stale token on a read — ignore */ }

        SetETag(cons.ETag);
        if (ETags.Matches(Request.Headers.IfNoneMatch.ToString(), cons.ETag))
            return StatusCode(304);
        return Ok(ToResponse(cons));
    }

    [HttpPut("api/shipments/{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody] ConsignmentBody? body,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken ct)
    {
        if (body is null || body.Id is null || body.WarehouseId is null
            || body.Reference is null || body.WeightKg is null || body.Fragile is null)
            return ApiHelpers.Problem(400, "Invalid body.");
        if (body.Id.Value != id)
            return ApiHelpers.Problem(400, "Body id differs from route id.");
        if (string.IsNullOrWhiteSpace(ifMatch))
            return ApiHelpers.Problem(428, "If-Match is required.");

        var cons = await _db.Consignments.IgnoreQueryFilters()
            .FirstOrDefaultAsync(c => c.PublicId == id, ct);
        if (cons is null) return ApiHelpers.Problem(404, "Not found.");
        if (cons.DeletedAt is not null) return ApiHelpers.Problem(410, "Gone.");

        if (body.WarehouseId.Value != cons.DepotPublicId)
            return ApiHelpers.Problem(409, "Shipments cannot move warehouses.");

        var newJson = ETags.ConsignmentJson(id, cons.DepotPublicId, body.Reference,
            body.WeightKg.Value, body.Fragile.Value);
        var newHash = ETags.Compute(newJson);

        if (newHash == cons.ETag) { SetETag(cons.ETag); return NoContent(); }

        if (!ETags.Matches(ifMatch, cons.ETag))
        {
            SetETag(cons.ETag);
            return ApiHelpers.Problem(412, "ETag mismatch.");
        }

        cons.Reference = body.Reference;
        cons.WeightKg = body.WeightKg.Value;
        cons.Fragile = body.Fragile.Value;
        cons.ETag = newHash;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await _db.Consignments.IgnoreQueryFilters()
                .AsNoTracking().FirstOrDefaultAsync(c => c.PublicId == id, ct);
            if (current is not null) SetETag(current.ETag);
            return ApiHelpers.Problem(412, "ETag mismatch.");
        }
        SetETag(newHash);
        return NoContent();
    }

    [HttpDelete("api/shipments/{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return ApiHelpers.Problem(428, "If-Match is required.");

        var cons = await _db.Consignments.IgnoreQueryFilters()
            .FirstOrDefaultAsync(c => c.PublicId == id, ct);
        if (cons is null || cons.DeletedAt is not null) return NoContent();

        if (!ETags.Matches(ifMatch, cons.ETag))
        {
            SetETag(cons.ETag);
            return ApiHelpers.Problem(412, "ETag mismatch.");
        }

        cons.DeletedAt = DateTime.UtcNow;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return ApiHelpers.Problem(412, "ETag mismatch.");
        }
        return NoContent();
    }
}
