using System;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;

public class AppDbContext : DbContext
{
    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }

    public DbSet<Depot> Depots => Set<Depot>();
    public DbSet<Consignment> Consignments => Set<Consignment>();

    protected override void OnModelCreating(ModelBuilder mb)
    {
        mb.Entity<Depot>(e =>
        {
            e.HasKey(d => d.Key);
            e.HasIndex(d => d.PublicId).IsUnique();
            e.Property(d => d.Code).IsRequired();
            e.Property(d => d.ETag).IsRequired().IsConcurrencyToken();
            e.Property(d => d.CreateHash).IsRequired()
                .Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            e.HasQueryFilter(d => d.DeletedAt == null);
            e.HasMany(d => d.Consignments).WithOne(c => c.Depot!)
                .HasForeignKey(c => c.DepotKey).OnDelete(DeleteBehavior.Cascade);
        });

        mb.Entity<Consignment>(e =>
        {
            e.HasKey(c => c.Key);
            e.HasIndex(c => c.PublicId).IsUnique();
            e.Property(c => c.Reference).IsRequired();
            e.Property(c => c.ETag).IsRequired().IsConcurrencyToken();
            e.Property(c => c.CreateHash).IsRequired()
                .Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            e.HasQueryFilter(c => c.DeletedAt == null);
        });
    }
}
