// CanonicalJson.cs — canonical JSON + ETag hashing
using System;
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public static class CanonicalJson
{
    public static string Warehouse(Guid id, string code, int capacityCubicMeters)
        => "{\"id\":" + Str(id.ToString("D"))
         + ",\"code\":" + Str(code)
         + ",\"capacityCubicMeters\":" + capacityCubicMeters.ToString(CultureInfo.InvariantCulture)
         + "}";

    public static string Shipment(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile)
        => "{\"id\":" + Str(id.ToString("D"))
         + ",\"warehouseId\":" + Str(warehouseId.ToString("D"))
         + ",\"reference\":" + Str(reference)
         + ",\"weightKg\":" + Num(weightKg)
         + ",\"fragile\":" + (fragile ? "true" : "false")
         + "}";

    public static string ETagOf(string canonical)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        var b64 = Convert.ToBase64String(hash)
            .TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + b64 + "\"";
    }

    private static string Num(decimal d)
    {
        var s = d.ToString(CultureInfo.InvariantCulture);
        if (s.Contains('.')) s = s.TrimEnd('0').TrimEnd('.');
        return s is "-0" or "" ? "0" : s;
    }

    private static string Str(string value)
    {
        var s = value.Normalize(NormalizationForm.FormC);
        var sb = new StringBuilder(s.Length + 2).Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }
}
