// Helpers shared by controllers
using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

public abstract class ApiBase : ControllerBase
{
    protected readonly AppDbContext Db;
    protected ApiBase(AppDbContext db) => Db = db;

    protected void SetETag(string tag) => Response.Headers.ETag = tag;

    // Normalizes an If-Match / If-None-Match header value for comparison.
    protected static string? NormalizeTag(string? raw)
    {
        if (string.IsNullOrWhiteSpace(raw)) return null;
        var v = raw.Trim();
        if (v == "*") return "*";
        if (v.StartsWith("W/", StringComparison.Ordinal)) v = v.Substring(2).Trim();
        return v;
    }

    protected bool IfNoneMatchMatches(string current)
        => NormalizeTag(Request.Headers.IfNoneMatch.ToString()) is string t
           && (t == "*" || t == current);

    protected IActionResult Prob(int status, string title)
        => Problem(title: title, statusCode: status);
}
