// WarehousesController.cs
using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/warehouses")]
[Produces("application/json")]
public class WarehousesController : ApiBase
{
    public WarehousesController(AppDbContext db) : base(db) { }

    [HttpPost]
    [Consumes("application/json")]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] WarehouseRequest? body, CancellationToken ct)
    {
        if (body is null || body.Id is null || body.Id == Guid.Empty || body.Code is null)
            return Prob(400, "Invalid body.");

        var id = body.Id.Value;
        var canonical = CanonicalJson.Warehouse(id, body.Code, body.CapacityCubicMeters);
        var tag = CanonicalJson.ETagOf(canonical);
        var entity = new Depot
        {
            PublicId = id,
            Code = body.Code,
            CapacityCubicMeters = body.CapacityCubicMeters,
            ETag = tag,
            CreateHash = tag
        };
        Db.Depots.Add(entity);
        try
        {
            await Db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (IsUniqueViolation(ex))
        {
            Db.Entry(entity).State = EntityState.Detached;
            var existing = await Db.Depots.IgnoreQueryFilters()
                .FirstOrDefaultAsync(d => d.PublicId == id, ct);
            if (existing is null) throw;
            if (existing.DeletedAt is not null)
                return Prob(410, "A warehouse with this id was deleted.");
            if (existing.CreateHash != tag)
                return Prob(409, "A warehouse with this id already exists with different content.");
            SetETag(existing.ETag);
            return Ok(Map(existing));
        }

        SetETag(tag);
        var resp = Map(entity);
        return CreatedAtAction(nameof(Get), new { id }, resp);
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var d = await Db.Depots.IgnoreQueryFilters()
            .FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (d is null) return Prob(404, "Warehouse not found.");
        if (d.DeletedAt is not null) return Prob(410, "Warehouse deleted.");

        SetETag(d.ETag);
        if (IfNoneMatchMatches(d.ETag)) return StatusCode(304);
        return Ok(Map(d));
    }

    [HttpPut("{id:guid}")]
    [Consumes("application/json")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id,
        [FromBody] WarehouseRequest? body,
        [FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken ct)
    {
        // Body validation first — 400 wins over 428.
        if (body is null || body.Id is null || body.Code is null)
            return Prob(400, "Invalid body.");
        if (body.Id.Value != id)
            return Prob(400, "Body id does not match route id.");

        var match = NormalizeTag(ifMatch);
        if (match is null)
            return Prob(428, "If-Match header is required.");

        var d = await Db.Depots.IgnoreQueryFilters()
            .FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (d is null) return Prob(404, "Warehouse not found.");
        if (d.DeletedAt is not null) return Prob(410, "Warehouse deleted.");

        var newTag = CanonicalJson.ETagOf(
            CanonicalJson.Warehouse(id, body.Code, body.CapacityCubicMeters));

        if (d.ETag == newTag) return NoContent(); // change already applied

        if (match != "*" && match != d.ETag)
        {
            SetETag(d.ETag);
            return Prob(412, "ETag does not match current state.");
        }

        d.Code = body.Code;
        d.CapacityCubicMeters = body.CapacityCubicMeters;
        d.ETag = newTag;
        d.LastAuditAt = DateTime.UtcNow;
        try
        {
            await Db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            Db.Entry(d).State = EntityState.Detached;
            var current = await Db.Depots.IgnoreQueryFilters()
                .FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (current is not null) SetETag(current.ETag);
            return Prob(412, "Warehouse was modified concurrently.");
        }

        SetETag(newTag);
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken ct)
    {
        var match = NormalizeTag(ifMatch);
        if (match is null)
            return Prob(428, "If-Match header is required.");

        var d = await Db.Depots.IgnoreQueryFilters()
            .Include(x => x.Consignments)
            .FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (d is null || d.DeletedAt is not null) return NoContent();

        if (match != "*" && match != d.ETag)
        {
            SetETag(d.ETag);
            return Prob(412, "ETag does not match current state.");
        }

        var now = DateTime.UtcNow;
        d.DeletedAt = now;
        d.LastAuditAt = now;
        foreach (var c in d.Consignments)
            c.DeletedAt = now;
        try
        {
            await Db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return NoContent(); // raced with another delete or update
        }
        return NoContent();
    }

    internal static WarehouseResponse Map(Depot d) => new()
    {
        Id = d.PublicId,
        Code = d.Code,
        CapacityCubicMeters = d.CapacityCubicMeters
    };

    internal static bool IsUniqueViolation(DbUpdateException ex)
        => ex.InnerException is Microsoft.Data.Sqlite.SqliteException { SqliteErrorCode: 19 };
}
