            .FirstOrDefaultAsync(d => d.PublicId == warehouseId, ct);
        if (depot is null) return Prob(404, "Warehouse not found.");
        if (depot.DeletedAt is not null) return Prob(410, "Warehouse deleted.");

        var id = body.Id.Value;
        var canonical = CanonicalJson.Shipment(id, warehouseId, body.Reference, body.WeightKg, body.Fragile);
        var tag = CanonicalJson.ETagOf(canonical);
        var entity = new Consignment
        {
            PublicId = id,
            DepotKey = depot.Key,
            WarehouseId = warehouseId,
            Reference = body.Reference,
            WeightKg = body.WeightKg,
            Fragile = body.Fragile,
            ETag = tag,
            CreateHash = tag
        };
        Db.Consignments.Add(entity);
        try
        {
            await Db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (WarehousesController.IsUniqueViolation(ex))
        {
            Db.Entry(entity).State = EntityState.Detached;
            var existing = await Db.Consignments.IgnoreQueryFilters()
                .FirstOrDefaultAsync(c => c.PublicId == id, ct);
            if (existing is null) throw;
            if (existing.DeletedAt is not null)
                return Prob(410, "A shipment with this id was deleted.");
            if (existing.WarehouseId != warehouseId || existing.CreateHash != tag)
                return Prob(409, "A shipment with this id already exists with different content.");
            SetETag(existing.ETag);
            return Ok(Map(existing));
        }

        SetETag(tag);
        return CreatedAtAction(nameof(Get), new { id }, Map(entity));
    }

    [HttpGet("api/shipments/{id:guid}")]
    [ProducesResponseType(typeof(ShipmentResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var c = await Db.Consignments.IgnoreQueryFilters()
            .FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (c is null) return Prob(404, "Shipment not found.");
        if (c.DeletedAt is not null) return Prob(410, "Shipment deleted.");

        // Server-owned counter; never part of the ETag or representation.
        c.DownloadCount++;
        try { await Db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { Db.Entry(c).State = EntityState.Detached; }

        SetETag(c.ETag);
        if (IfNoneMatchMatches(c.ETag)) return StatusCode(304);
        return Ok(Map(c));
    }

    [HttpPut("api/shipments/{id:guid}")]
    [Consumes("application/json")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id,
        [FromBody] ShipmentRequest? body,
        [FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken ct)
    {
        if (body is null || body.Id is null || body.WarehouseId is null || body.Reference is null)
            return Prob(400, "Invalid body.");
        if (body.Id.Value != id)
            return Prob(400, "Body id does not match route id.");

        var match = NormalizeTag(ifMatch);
        if (match is null)
            return Prob(428, "If-Match header is required.");

        var c = await Db.Consignments.IgnoreQueryFilters()
            .FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (c is null) return Prob(404, "Shipment not found.");
        if (c.DeletedAt is not null) return Prob(410, "Shipment deleted.");

        if (body.WarehouseId.Value != c.WarehouseId)
            return Prob(409, "A shipment cannot be moved to another warehouse.");

        var newTag = CanonicalJson.ETagOf(
            CanonicalJson.Shipment(id, c.WarehouseId, body.Reference, body.WeightKg, body.Fragile));

        if (c.ETag == newTag) return NoContent();

        if (match != "*" && match != c.ETag)
        {
            SetETag(c.ETag);
            return Prob(412, "ETag does not match current state.");
        }

        c.Reference = body.Reference;
        c.WeightKg = body.WeightKg;
        c.Fragile = body.Fragile;
        c.ETag = newTag;
        try
        {
            await Db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            Db.Entry(c).State = EntityState.Detached;
            var current = await Db.Consignments.IgnoreQueryFilters()
                .FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (current is not null) SetETag(current.ETag);
            return Prob(412, "Shipment was modified concurrently.");
        }

        SetETag(newTag);
        return NoContent();
    }

    [HttpDelete("api/shipments/{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken ct)
    {
        var match = NormalizeTag(ifMatch);
        if (match is null)
            return Prob(428, "If-Match header is required.");

        var c = await Db.Consignments.IgnoreQueryFilters()
            .FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (c is null || c.DeletedAt is not null) return NoContent();

        if (match != "*" && match != c.ETag)
        {
            SetETag(c.ETag);
            return Prob(412, "ETag does not match current state.");
        }

        c.DeletedAt = DateTime.UtcNow;
        try
        {
            await Db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return NoContent();
        }
        return NoContent();
    }

    internal static ShipmentResponse Map(Consignment c) => new()
    {
        Id = c.PublicId,
        WarehouseId = c.WarehouseId,
        Reference = c.Reference,
        WeightKg = c.WeightKg,
        Fragile = c.Fragile
    };
}
