public static class Canonical
{
    public static string Warehouse(Guid id, string code, int capacityCubicMeters) =>
        ETagOf("{\"id\":\"" + id.ToString("D") + "\",\"code\":\"" + Esc(code) +
               "\",\"capacityCubicMeters\":" + capacityCubicMeters.ToString(CultureInfo.InvariantCulture) + "}");

    public static string Shipment(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile) =>
        ETagOf("{\"id\":\"" + id.ToString("D") + "\",\"warehouseId\":\"" + warehouseId.ToString("D") +
               "\",\"reference\":\"" + Esc(reference) + "\",\"weightKg\":" + Dec(weightKg) +
               ",\"fragile\":" + (fragile ? "true" : "false") + "}");

    static string ETagOf(string canonical)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return "\"" + Convert.ToBase64String(hash).Replace('+', '-').Replace('/', '_').TrimEnd('=') + "\"";
    }

    static string Dec(decimal d)
    {
        var s = d.ToString("0.############################", CultureInfo.InvariantCulture);
        return s.EndsWith(".") ? s.TrimEnd('.') : s;
    }

    static string Esc(string s)
    {
        var n = s.Normalize(NormalizationForm.FormC);
        var sb = new StringBuilder(n.Length);
        foreach (var c in n)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.ToString();
    }
}

public static class HttpHelpers
{
    public static bool ETagMatches(string? header, string etag)
    {
        if (string.IsNullOrEmpty(header)) return false;
        foreach (var raw in header.Split(','))
        {
            var v = raw.Trim();
            if (v == "*") return true;
            if (v.StartsWith("W/", StringComparison.Ordinal)) v = v.Substring(2);
            if (v == etag) return true;
        }
        return false;
    }

    public static string TombstoneTag() => "\"" + Guid.NewGuid().ToString("N") + "\"";
}

