using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
public class WarehousesController : ControllerBase
{
    private readonly AppDb _db;
    public WarehousesController(AppDb db) => _db = db;

    static WarehouseResponse ToResponse(Depot d) => new()
    {
        Id = d.PublicId, Code = d.Code, CapacityCubicMeters = d.CapacityCubicMeters
    };

    ObjectResult Err(int status) =>
        Problem(statusCode: status, title: status switch
        {
            400 => "Bad Request", 404 => "Not Found", 409 => "Conflict",
            410 => "Gone", 412 => "Precondition Failed", 428 => "Precondition Required",
            _ => "Error"
        });

    [HttpPost("api/warehouses")]
    [Consumes("application/json")]
    [Produces("application/json")]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody][Required] WarehouseBody? body, CancellationToken ct)
    {
        if (body?.Id is null || body.Id == Guid.Empty || body.Code is null || body.CapacityCubicMeters is null)
            return Err(400);
        var etag = Canonical.Warehouse(body.Id.Value, body.Code, body.CapacityCubicMeters.Value);
        var entity = new Depot
        {
            PublicId = body.Id.Value, Code = body.Code,
            CapacityCubicMeters = body.CapacityCubicMeters.Value,
            ETag = etag, CreateHash = etag, LastAuditAt = DateTime.UtcNow
        };
        _db.Depots.Add(entity);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.Entry(entity).State = EntityState.Detached;
            var ex = await _db.Depots.IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(d => d.PublicId == body.Id.Value, ct);
            if (ex is null) throw;
            if (ex.DeletedAt is not null) return Err(410);
            Response.Headers.ETag = ex.ETag;
            return ex.CreateHash == etag ? Ok(ToResponse(ex)) : Err(409);
        }
        Response.Headers.ETag = etag;
        return Created($"/api/warehouses/{entity.PublicId}", ToResponse(entity));
    }

    [HttpGet("api/warehouses/{id:guid}")]
    [Produces("application/json")]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var e = await _db.Depots.IgnoreQueryFilters().AsNoTracking()
            .FirstOrDefaultAsync(d => d.PublicId == id, ct);
        if (e is null) return Err(404);
        if (e.DeletedAt is not null) return Err(410);
        Response.Headers.ETag = e.ETag;
        if (HttpHelpers.ETagMatches(Request.Headers.IfNoneMatch, e.ETag)) return StatusCode(304);
        return Ok(ToResponse(e));
    }

    [HttpPut("api/warehouses/{id:guid}")]
    [Consumes("application/json")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody][Required] WarehouseBody? body,
        [FromHeader(Name = "If-Match")][Required] string? ifMatch, CancellationToken ct)
    {
        if (body?.Id is null || body.Id != id || body.Code is null || body.CapacityCubicMeters is null)
            return Err(400);
        var e = await _db.Depots.IgnoreQueryFilters().FirstOrDefaultAsync(d => d.PublicId == id, ct);
        if (e is null) return Err(404);
        if (e.DeletedAt is not null) return Err(410);
        var newEtag = Canonical.Warehouse(id, body.Code, body.CapacityCubicMeters.Value);
        if (newEtag == e.ETag)
        {
            Response.Headers.ETag = e.ETag;
            return NoContent();
        }
        var im = ifMatch ?? Request.Headers["If-Match"].ToString();
        if (string.IsNullOrEmpty(im)) return Err(428);
        if (!HttpHelpers.ETagMatches(im, e.ETag))
        {
            Response.Headers.ETag = e.ETag;
            return Err(412);
        }
        var orig = e.ETag;
        e.Code = body.Code;
        e.CapacityCubicMeters = body.CapacityCubicMeters.Value;
        e.LastAuditAt = DateTime.UtcNow;
        e.ETag = newEtag;
        _db.Entry(e).Property(x => x.ETag).OriginalValue = orig;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await _db.Depots.IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(d => d.PublicId == id, ct);
            if (cur is null) return Err(404);
            Response.Headers.ETag = cur.ETag;
            return Err(412);
        }
        Response.Headers.ETag = newEtag;
        return NoContent();
    }

    [HttpDelete("api/warehouses/{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")][Required] string? ifMatch, CancellationToken ct)
    {
        var im = ifMatch ?? Request.Headers["If-Match"].ToString();
        if (string.IsNullOrEmpty(im)) return Err(428);
        var e = await _db.Depots.IgnoreQueryFilters().FirstOrDefaultAsync(d => d.PublicId == id, ct);
        if (e is null || e.DeletedAt is not null) return NoContent();
        if (!HttpHelpers.ETagMatches(im, e.ETag))
        {
            Response.Headers.ETag = e.ETag;
            return Err(412);
        }
        var children = await _db.Consignments.IgnoreQueryFilters()
            .Where(c => c.DepotId == e.Id && c.DeletedAt == null).ToListAsync(ct);
        var now = DateTime.UtcNow;
        var orig = e.ETag;
        e.DeletedAt = now;
        e.ETag = HttpHelpers.TombstoneTag();
        _db.Entry(e).Property(x => x.ETag).OriginalValue = orig;
        foreach (var c in children)
        {
            var co = c.ETag;
            c.DeletedAt = now;
            c.ETag = HttpHelpers.TombstoneTag();
            _db.Entry(c).Property(x => x.ETag).OriginalValue = co;
        }
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await _db.Depots.IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(d => d.PublicId == id, ct);
            if (cur is null || cur.DeletedAt is not null) return NoContent();
            Response.Headers.ETag = cur.ETag;
            return Err(412);
        }
        return NoContent();
    }
}

