// Canonical.cs — canonical JSON + ETag hashing
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

namespace WarehouseApi;

public static class Canonical
{
    public static string ETagOf(string canonicalJson)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson));
        return "\"" + Convert.ToBase64String(hash)
            .Replace('+', '-').Replace('/', '_').TrimEnd('=') + "\"";
    }

    public static void WriteString(StringBuilder sb, string value)
    {
        var s = value.Normalize(NormalizationForm.FormC);
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < ' ') sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }

    public static string Num(decimal d)
    {
        var s = d.ToString(CultureInfo.InvariantCulture); // decimal never uses exponents
        if (s.Contains('.')) s = s.TrimEnd('0').TrimEnd('.');
        return s is "" or "-0" ? "0" : s;
    }

    public static string DepotJson(Guid id, string code, int capacity)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString()).Append("\",\"code\":");
        WriteString(sb, code);
        sb.Append(",\"capacityCubicMeters\":").Append(capacity.ToString(CultureInfo.InvariantCulture)).Append('}');
        return sb.ToString();
    }

    public static string ConsignmentJson(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString())
          .Append("\",\"warehouseId\":\"").Append(warehouseId.ToString()).Append("\",\"reference\":");
        WriteString(sb, reference);
        sb.Append(",\"weightKg\":").Append(Num(weightKg))
          .Append(",\"fragile\":").Append(fragile ? "true" : "false").Append('}');
        return sb.ToString();
    }

    /// <summary>True if an If-Match/If-None-Match value satisfies the stored ETag.</summary>
    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        var h = header.Trim();
        if (h == "*") return true;
        if (h.StartsWith("W/")) h = h.Substring(2);
        return h == etag;
    }
}
