// WarehousesController.cs
using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace WarehouseApi;

[ApiController]
[Route("api/warehouses")]
public class WarehousesController : ControllerBase
{
    private readonly WarehouseDbContext _db;
    public WarehousesController(WarehouseDbContext db) => _db = db;

    static ObjectResult Problem(int status, string title) =>
        new(new ProblemDetails { Status = status, Title = title })
        {
            StatusCode = status,
            ContentTypes = { "application/problem+json" }
        };

    static WarehouseResponse Rep(Depot d) => new(d.Id, d.Code, d.CapacityCubicMeters);
    static ShipmentResponse Rep(Consignment c) =>
        new(c.Id, c.Depot.Id, c.Reference, c.WeightKg, c.Fragile);

    [HttpPost]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create(
        [Required][FromBody] WarehouseInput body, CancellationToken ct)
    {
        if (body.Id is null or { } && body.Id == Guid.Empty || body.Id is null || body.Code is null || body.CapacityCubicMeters is null)
            return Problem(400, "Invalid warehouse body.");
        var id = body.Id!.Value;
        var canonical = Canonical.DepotJson(id, body.Code!, body.CapacityCubicMeters!.Value);
        var hash = Canonical.ETagOf(canonical);

        var depot = new Depot
        {
            Id = id,
            Code = body.Code!,
            CapacityCubicMeters = body.CapacityCubicMeters!.Value,
            ETag = hash,
            CreateHash = hash,
            LastAuditAt = DateTime.UtcNow
        };
        _db.Depots.Add(depot);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.Entry(depot).State = EntityState.Detached;
            var existing = await _db.Depots.IgnoreQueryFilters()
                .FirstOrDefaultAsync(d => d.Id == id, ct);
            if (existing is null) throw;
            if (existing.DeletedAt is not null)
                return Problem(410, "Warehouse is deleted.");
            if (existing.CreateHash == hash)
            {
                Response.Headers.ETag = existing.ETag;
                return Ok(Rep(existing));
            }
            return Problem(409, "A different warehouse already uses this id.");
        }

        Response.Headers.ETag = depot.ETag;
        return Created($"/api/warehouses/{depot.Id}", Rep(depot));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id,
        [FromHeader(Name = "If-None-Match")] string? ifNoneMatch, CancellationToken ct)
    {
        var depot = await _db.Depots.FirstOrDefaultAsync(d => d.Id == id, ct);
        if (depot is null)
        {
            var dead = await _db.Depots.IgnoreQueryFilters()
                .AnyAsync(d => d.Id == id && d.DeletedAt != null, ct);
            return Problem(dead ? 410 : 404, dead ? "Warehouse is deleted." : "Warehouse not found.");
        }
        Response.Headers.ETag = depot.ETag;
        if (Canonical.Matches(ifNoneMatch, depot.ETag)) return StatusCode(304);
        return Ok(Rep(depot));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id,
        [Required][FromBody] WarehouseInput body,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken ct)
    {
        // validation first: 400 beats 428
        if (body.Id is null || body.Code is null || body.CapacityCubicMeters is null)
            return Problem(400, "Invalid warehouse body.");
        if (body.Id.Value != id)
            return Problem(400, "Body id does not match the route id.");
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(428, "If-Match header is required.");

        var depot = await _db.Depots.FirstOrDefaultAsync(d => d.Id == id, ct);
        if (depot is null)
        {
            var dead = await _db.Depots.IgnoreQueryFilters()
                .AnyAsync(d => d.Id == id && d.DeletedAt != null, ct);
            return Problem(dead ? 410 : 404, dead ? "Warehouse is deleted." : "Warehouse not found.");
        }

        var newHash = Canonical.ETagOf(Canonical.DepotJson(id, body.Code!, body.CapacityCubicMeters!.Value));
        if (depot.ETag == newHash)
        {
            Response.Headers.ETag = depot.ETag;
            return NoContent(); // already applied
        }
        if (!Canonical.Matches(ifMatch, depot.ETag))
        {
            Response.Headers.ETag = depot.ETag;
            return Problem(412, "ETag does not match the current representation.");
        }

        depot.Code = body.Code!;
        depot.CapacityCubicMeters = body.CapacityCubicMeters!.Value;
        depot.ETag = newHash;
        depot.LastAuditAt = DateTime.UtcNow;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await _db.Depots.IgnoreQueryFilters()
                .FirstOrDefaultAsync(d => d.Id == id, ct);
            if (cur is not null) Response.Headers.ETag = cur.ETag;
            return Problem(412, "ETag does not match the current representation.");
        }
        Response.Headers.ETag = depot.ETag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(428, "If-Match header is required.");

        var depot = await _db.Depots.FirstOrDefaultAsync(d => d.Id == id, ct);
        if (depot is null) return NoContent(); // unknown or already deleted

        if (!Canonical.Matches(ifMatch, depot.ETag))
        {
            Response.Headers.ETag = depot.ETag;
            return Problem(412, "ETag does not match the current representation.");
        }

        var now = DateTime.UtcNow;
        await using var tx = await _db.Database.BeginTransactionAsync(ct);
        // soft-delete the shipments in the same transaction
        await _db.Consignments.IgnoreQueryFilters()
            .Where(c => c.DepotPk == depot.Pk && c.DeletedAt == null)
            .ExecuteUpdateAsync(s => s.SetProperty(c => c.DeletedAt, now), ct);
        depot.DeletedAt = now;
        depot.LastAuditAt = now;
        try
        {
            await _db.SaveChangesAsync(ct);
            await tx.CommitAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            await tx.RollbackAsync(ct);
            var cur = await _db.Depots.IgnoreQueryFilters()
                .FirstOrDefaultAsync(d => d.Id == id, ct);
            if (cur is null || cur.DeletedAt is not null) return NoContent();
            Response.Headers.ETag = cur.ETag;
            return Problem(412, "ETag does not match the current representation.");
        }
        return NoContent();
    }

    // ---- shipments created under a warehouse ----

    [HttpPost("{warehouseId:guid}/shipments")]
    [ProducesResponseType(typeof(ShipmentResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(ShipmentResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> CreateShipment(Guid warehouseId,
        [Required][FromBody] ShipmentInput body, CancellationToken ct)
    {
        if (body.Id is null || body.WarehouseId is null || body.Reference is null
            || body.WeightKg is null || body.Fragile is null)
            return Problem(400, "Invalid shipment body.");
        if (body.WarehouseId.Value != warehouseId)
            return Problem(400, "Body warehouseId does not match the route.");

        var depot = await _db.Depots.FirstOrDefaultAsync(d => d.Id == warehouseId, ct);
        if (depot is null)
        {
            var dead = await _db.Depots.IgnoreQueryFilters()
                .AnyAsync(d => d.Id == warehouseId && d.DeletedAt != null, ct);
            return Problem(dead ? 410 : 404, dead ? "Warehouse is deleted." : "Warehouse not found.");
        }

        var id = body.Id!.Value;
        var canonical = Canonical.ConsignmentJson(id, warehouseId,
            body.Reference!, body.WeightKg!.Value, body.Fragile!.Value);
        var hash = Canonical.ETagOf(canonical);

        var c = new Consignment
        {
            Id = id,
            DepotPk = depot.Pk,
            Depot = depot,
            Reference = body.Reference!,
            WeightKg = body.WeightKg!.Value,
            Fragile = body.Fragile!.Value,
            ETag = hash,
            CreateHash = hash
        };
        _db.Consignments.Add(c);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.Entry(c).State = EntityState.Detached;
            var existing = await _db.Consignments.IgnoreQueryFilters()
                .Include(x => x.Depot)
                .FirstOrDefaultAsync(x => x.Id == id, ct);
            if (existing is null) throw;
            if (existing.DeletedAt is not null)
                return Problem(410, "Shipment is deleted.");
            if (existing.CreateHash == hash)
            {
                Response.Headers.ETag = existing.ETag;
                return Ok(Rep(existing));
            }
            return Problem(409, "A different shipment already uses this id.");
        }

        c.Depot = depot;
        Response.Headers.ETag = c.ETag;
        return Created($"/api/shipments/{c.Id}", Rep(c));
    }
}
