            .FirstOrDefaultAsync(x => x.Id == id, ct);
        if (c is null)
        {
            var dead = await _db.Consignments.IgnoreQueryFilters()
                .AnyAsync(x => x.Id == id && x.DeletedAt != null, ct);
            return Problem(dead ? 410 : 404, dead ? "Shipment is deleted." : "Shipment not found.");
        }

        // bump the read counter; it is never part of the ETag or concurrency
        await _db.Consignments.Where(x => x.Pk == c.Pk)
            .ExecuteUpdateAsync(s => s.SetProperty(x => x.DownloadCount, x => x.DownloadCount + 1), ct);

        Response.Headers.ETag = c.ETag;
        if (Canonical.Matches(ifNoneMatch, c.ETag)) return StatusCode(304);
        return Ok(new ShipmentResponse(c.Id, c.Depot.Id, c.Reference, c.WeightKg, c.Fragile));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id,
        [Required][FromBody] ShipmentInput body,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken ct)
    {
        if (body.Id is null || body.WarehouseId is null || body.Reference is null
            || body.WeightKg is null || body.Fragile is null)
            return Problem(400, "Invalid shipment body.");
        if (body.Id.Value != id)
            return Problem(400, "Body id does not match the route id.");
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(428, "If-Match header is required.");

        var c = await _db.Consignments.Include(x => x.Depot)
            .FirstOrDefaultAsync(x => x.Id == id, ct);
        if (c is null)
        {
            var dead = await _db.Consignments.IgnoreQueryFilters()
                .AnyAsync(x => x.Id == id && x.DeletedAt != null, ct);
            return Problem(dead ? 410 : 404, dead ? "Shipment is deleted." : "Shipment not found.");
        }

        if (body.WarehouseId.Value != c.Depot.Id)
            return Problem(409, "Shipments cannot be moved to another warehouse.");

        var newHash = Canonical.ETagOf(Canonical.ConsignmentJson(id, c.Depot.Id,
            body.Reference!, body.WeightKg!.Value, body.Fragile!.Value));
        if (c.ETag == newHash)
        {
            Response.Headers.ETag = c.ETag;
            return NoContent();
        }
        if (!Canonical.Matches(ifMatch, c.ETag))
        {
            Response.Headers.ETag = c.ETag;
            return Problem(412, "ETag does not match the current representation.");
        }

        c.Reference = body.Reference!;
        c.WeightKg = body.WeightKg!.Value;
        c.Fragile = body.Fragile!.Value;
        c.ETag = newHash;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await _db.Consignments.IgnoreQueryFilters()
                .FirstOrDefaultAsync(x => x.Id == id, ct);
            if (cur is not null) Response.Headers.ETag = cur.ETag;
            return Problem(412, "ETag does not match the current representation.");
        }
        Response.Headers.ETag = c.ETag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(428, "If-Match header is required.");

        var c = await _db.Consignments.FirstOrDefaultAsync(x => x.Id == id, ct);
        if (c is null) return NoContent();

        if (!Canonical.Matches(ifMatch, c.ETag))
        {
            Response.Headers.ETag = c.ETag;
            return Problem(412, "ETag does not match the current representation.");
        }

        c.DeletedAt = DateTime.UtcNow;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await _db.Consignments.IgnoreQueryFilters()
                .FirstOrDefaultAsync(x => x.Id == id, ct);
            if (cur is null || cur.DeletedAt is not null) return NoContent();
            Response.Headers.ETag = cur.ETag;
            return Problem(412, "ETag does not match the current representation.");
        }
        return NoContent();
    }
