// ---------------- Canonical JSON + ETag ----------------

internal static class ETagging
{
    public static string DepotEtag(Guid id, string code, int capacity) =>
        Hash(Build(b =>
        {
            b.Append("{\"id\":"); Guid(b, id);
            b.Append(",\"code\":"); Str(b, code);
            b.Append(",\"capacityCubicMeters\":").Append(capacity.ToString(CultureInfo.InvariantCulture));
            b.Append('}');
        }));

    public static string ConsignmentEtag(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile) =>
        Hash(Build(b =>
        {
            b.Append("{\"id\":"); Guid(b, id);
            b.Append(",\"warehouseId\":"); Guid(b, warehouseId);
            b.Append(",\"reference\":"); Str(b, reference);
            b.Append(",\"weightKg\":").Append(Num(weightKg));
            b.Append(",\"fragile\":").Append(fragile ? "true" : "false");
            b.Append('}');
        }));

    private static string Build(Action<StringBuilder> f) { var b = new StringBuilder(); f(b); return b.ToString(); }

    private static void Guid(StringBuilder b, Guid g) { b.Append('"').Append(g.ToString()).Append('"'); } // ToString is lowercase "d"

    private static string Num(decimal d)
    {
        var s = d.ToString(CultureInfo.InvariantCulture); // never scientific
        var dot = s.IndexOf('.');
        if (dot >= 0)
        {
            s = s.TrimEnd('0');
            if (s.EndsWith('.')) s = s[..^1];
        }
        return s;
    }

    private static void Str(StringBuilder sb, string value)
    {
        var s = value.Normalize(NormalizationForm.FormC);
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }

    private static string Hash(string canonical)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return Convert.ToBase64String(bytes).Replace('+', '-').Replace('/', '_').TrimEnd('=');
    }

    /// <summary>Matches an If-Match / If-None-Match header value against an unquoted ETag.</summary>
    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var raw in header.Split(','))
        {
            var t = raw.Trim();
            if (t == "*") return true;
            if (t.StartsWith("W/", StringComparison.Ordinal)) t = t[2..].TrimStart();
            if (t.Length >= 2 && t[0] == '"' && t[^1] == '"') t = t[1..^1];
            if (t == etag) return true;
        }
        return false;
    }

    public static bool IsUniqueViolation(DbUpdateException ex) =>
        ex.GetBaseException() is SqliteException { SqliteErrorCode: 19 };
}

