            return Http.Problem(400, "Invalid request body.");

        var hash = ETagging.DepotEtag(id, body.Code, cap);
        var entity = new Depot
        {
            PublicId = id,
            Code = body.Code,
            CapacityCubicMeters = cap,
            ETag = hash,
            CreateHash = hash,
            LastAuditAt = DateTime.UtcNow
        };
        _db.Depots.Add(entity);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (ETagging.IsUniqueViolation(ex))
        {
            _db.Entry(entity).State = EntityState.Detached;
            var cur = await _db.Depots.IgnoreQueryFilters()
                .FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (cur is null) throw;
            if (cur.DeletedAt is not null) return Gone();
            if (cur.CreateHash == hash)
            {
                SetETag(cur.ETag);
                return Ok(ToResponse(cur));
            }
            return Conflict();
