            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.Entry(e).State = EntityState.Detached;
            var cur = await _db.Depots.IgnoreQueryFilters()
                .FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (cur is not null) SetETag(cur.ETag);
            return Http.Problem(412, "Precondition Failed");
