            .FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (e is null || e.DeletedAt is not null) return NoContent();
        if (!ETagging.Matches(ifMatch, e.ETag))
        {
            SetETag(e.ETag);
            return Http.Problem(412, "Precondition Failed");
        }

        var shipments = await _db.Consignments.IgnoreQueryFilters()
            .Where(c => c.DepotKey == e.Key && c.DeletedAt == null)
            .ToListAsync(ct);

        await using var tx = await _db.Database.BeginTransactionAsync(ct);
        var now = DateTime.UtcNow;
