    [ProducesResponseType(typeof(ShipmentResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var e = await _db.Consignments.IgnoreQueryFilters()
            .FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (e is null) return Http.Problem(404, "Not Found");
        if (e.DeletedAt is not null) return Gone();

        var response = ToResponse(e);
        var etag = e.ETag;

        // server-owned read counter; never part of the representation or the token
        e.DownloadCount++;
        try { await _db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { _db.Entry(e).State = EntityState.Detached; }

        SetETag(etag);
        if (ETagging.Matches(IfNoneMatch, etag)) return StatusCode(304);
        return Ok(response);
    }

    [HttpPut("/api/shipments/{id:guid}")]
    [Consumes("application/json")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody] ShipmentRequest? body,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken ct)
    {
        if (body?.Id is not { } bid || body.WarehouseId is not { } bwid ||
            body.Reference is null || body.WeightKg is not { } w || body.Fragile is not { } f)
            return Http.Problem(400, "Invalid request body.");
        if (bid != id)
            return Http.Problem(400, "Body id does not match route id.");
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Http.Problem(428, "If-Match header is required.");

        var e = await _db.Consignments.IgnoreQueryFilters()
            .FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (e is null) return Http.Problem(404, "Not Found");
        if (e.DeletedAt is not null) return Gone();
        if (bwid != e.WarehouseGuid)
            return Conflict(); // moving a shipment to another warehouse is not allowed

        var newHash = ETagging.ConsignmentEtag(id, e.WarehouseGuid, body.Reference, w, f);
        if (newHash == e.ETag)
        {
            SetETag(e.ETag);
            return NoContent();
        }
        if (!ETagging.Matches(ifMatch, e.ETag))
        {
            SetETag(e.ETag);
            return Http.Problem(412, "Precondition Failed");
        }

        e.Reference = body.Reference;
        e.WeightKg = w;
        e.Fragile = f;
        e.ETag = newHash;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.Entry(e).State = EntityState.Detached;
            var cur = await _db.Consignments.IgnoreQueryFilters()
                .FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (cur is not null) SetETag(cur.ETag);
            return Http.Problem(412, "Precondition Failed");
        }

        SetETag(e.ETag);
        return NoContent();
    }

    [HttpDelete("/api/shipments/{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")] string ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Http.Problem(428, "If-Match header is required.");

        var e = await _db.Consignments.IgnoreQueryFilters()
            .FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (e is null || e.DeletedAt is not null) return NoContent();
        if (!ETagging.Matches(ifMatch, e.ETag))
        {
            SetETag(e.ETag);
            return Http.Problem(412, "Precondition Failed");
        }

        e.DeletedAt = DateTime.UtcNow;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.Entry(e).State = EntityState.Detached;
            var cur = await _db.Consignments.IgnoreQueryFilters()
                .FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (cur is not null && cur.DeletedAt is null)
            {
                SetETag(cur.ETag);
                return Http.Problem(412, "Precondition Failed");
            }
        }
        return NoContent();
    }
}
```

Key design points:

- **Entities**: `Depot` and `Consignment` have an internal `int Key`, a unique `PublicId`, a required `ETag` concurrency token, an immutable `CreateHash` (`AfterSaveBehavior.Throw`), a `DeletedAt` tombstone with a global query filter, plus server-owned `LastAuditAt` / `DownloadCount`.
- **ETag**: quoted unpadded base64url SHA-256 over canonical JSON built exactly per spec — lowercase GUIDs, NFC strings, minimal escaping, numbers without trailing zeros; server-owned fields excluded.
- **Create**: insert-then-classify on the SQLite unique violation (`SqliteErrorCode 19`); replay → 200, different content → 409, tombstoned id → 410.
- **Concurrency**: `ETag` is the EF concurrency token, so two writers from the same ETag produce one winner and one `DbUpdateConcurrencyException` → 412, never a 5xx.
- **Validation order on PUT**: body validity and body/route id match → 400 before the If-Match 428 check; "already applied" (same hash) short-circuits to 204; deletes cascade warehouse → shipments in one transaction.
- **Contract**: every action has `[ProducesResponseType]` for all statuses it returns, `If-Match` is a non-nullable `[FromHeader]` parameter (required in OpenAPI), bodies are non-nullable `[FromBody]` (required), and `CancellationToken` flows to every EF call.

