// File: Canonical.cs

using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public static class Canonical
{
    public static string Hash(string canonical)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        var b64 = Convert.ToBase64String(bytes).Replace('+', '-').Replace('/', '_').TrimEnd('=');
        return "\"" + b64 + "\"";
    }

    public static string Warehouse(Guid id, string code, int capacity)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("D"));
        sb.Append("\",\"code\":\"").Append(Escape(code));
        sb.Append("\",\"capacityCubicMeters\":").Append(capacity.ToString(CultureInfo.InvariantCulture));
        sb.Append('}');
        return sb.ToString();
    }

    public static string Shipment(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("D"));
        sb.Append("\",\"warehouseId\":\"").Append(warehouseId.ToString("D"));
        sb.Append("\",\"reference\":\"").Append(Escape(reference));
        sb.Append("\",\"weightKg\":").Append(weightKg.ToString("0.#############################", CultureInfo.InvariantCulture));
        sb.Append(",\"fragile\":").Append(fragile ? "true" : "false");
        sb.Append('}');
        return sb.ToString();
    }

    private static string Escape(string s)
    {
        s = s.Normalize(NormalizationForm.FormC);
        var sb = new StringBuilder(s.Length);
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.ToString();
    }
}
