// File: Controllers.cs

using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

public abstract class ApiBase : ControllerBase
{
    protected static bool IsUniqueViolation(DbUpdateException ex)
        => ex.InnerException is SqliteException s && s.SqliteErrorCode == 19;

    protected static bool ETagMatches(string? header, string etag)
    {
        if (header == null) return false;
        header = header.Trim();
        if (header == "*") return true;
        foreach (var part in header.Split(','))
        {
            var t = part.Trim();
            if (t.StartsWith("W/", StringComparison.Ordinal)) t = t.Substring(2).Trim();
            if (string.Equals(t, etag, StringComparison.Ordinal)) return true;
        }
        return false;
    }

    protected ObjectResult Problem(int status, string title)
    {
        var pd = new ProblemDetails { Status = status, Title = title };
        return new ObjectResult(pd) { StatusCode = status, ContentTypes = { "application/problem+json" } };
    }

    protected IActionResult NotModifiedOrOk(string etag, object body)
    {
        Response.Headers.ETag = etag;
        var inm = Request.Headers.IfNoneMatch.ToString();
        if (ETagMatches(inm.Length == 0 ? null : inm, etag))
            return StatusCode(304);
        return Ok(body);
    }
}

[ApiController]
[Route("api/warehouses")]
public sealed class WarehousesController : ApiBase
{
    private readonly AppDbContext _db;
    public WarehousesController(AppDbContext db) => _db = db;

    private static WarehouseResponse ToResponse(Depot d)
        => new() { Id = d.PublicId, Code = d.Code, CapacityCubicMeters = d.CapacityCubicMeters };

    private static string ETagOf(WarehouseInput i)
        => Canonical.Hash(Canonical.Warehouse(i.Id, i.Code!, i.CapacityCubicMeters));

    private static string ETagOf(Depot d)
        => Canonical.Hash(Canonical.Warehouse(d.PublicId, d.Code, d.CapacityCubicMeters));

    [HttpPost]
    [ProducesResponseType(typeof(WarehouseResponse), 201)]
    [ProducesResponseType(typeof(WarehouseResponse), 200)]
    [ProducesResponseType(typeof(ProblemDetails), 400)]
    [ProducesResponseType(typeof(ProblemDetails), 409)]
    [ProducesResponseType(typeof(ProblemDetails), 410)]
    public async Task<IActionResult> Create([FromBody] WarehouseInput body, CancellationToken ct)
    {
        if (body == null || body.Id == Guid.Empty || body.Code == null)
            return Problem(400, "Bad Request");

        var etag = ETagOf(body);
        var depot = new Depot { PublicId = body.Id, Code = body.Code, CapacityCubicMeters = body.CapacityCubicMeters, ETag = etag, CreateHash = etag };
        _db.Depots.Add(depot);
        try
        {
            await _db.SaveChangesAsync(ct);
            Response.Headers.ETag = etag;
            return Created($"/api/warehouses/{body.Id}", ToResponse(depot));
        }
        catch (DbUpdateException ex) when (IsUniqueViolation(ex))
        {
            _db.Entry(depot).State = EntityState.Detached;
            var existing = await _db.Depots.IgnoreQueryFilters()
                .SingleAsync(d => d.PublicId == body.Id, ct);
            if (existing.DeletedAt != null)
                return Problem(410, "Gone");
            Response.Headers.ETag = existing.ETag;
            if (existing.CreateHash == etag)
                return Ok(ToResponse(existing));
            return Problem(409, "Conflict");
        }
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(WarehouseResponse), 200)]
    [ProducesResponseType(304)]
    [ProducesResponseType(typeof(ProblemDetails), 404)]
    [ProducesResponseType(typeof(ProblemDetails), 410)]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var d = await _db.Depots.IgnoreQueryFilters().SingleOrDefaultAsync(x => x.PublicId == id, ct);
        if (d == null) return Problem(404, "Not Found");
        if (d.DeletedAt != null) return Problem(410, "Gone");
        return NotModifiedOrOk(d.ETag, ToResponse(d));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 400)]
    [ProducesResponseType(typeof(ProblemDetails), 404)]
    [ProducesResponseType(typeof(ProblemDetails), 409)]
    [ProducesResponseType(typeof(ProblemDetails), 410)]
    [ProducesResponseType(typeof(ProblemDetails), 412)]
    [ProducesResponseType(typeof(ProblemDetails), 428)]
    public async Task<IActionResult> Put(Guid id, [FromBody] WarehouseInput body,
        [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken ct)
    {
        if (body == null || body.Id != id || body.Code == null)
            return Problem(400, "Bad Request");

        var d = await _db.Depots.IgnoreQueryFilters().SingleOrDefaultAsync(x => x.PublicId == id, ct);
        if (d == null) return Problem(404, "Not Found");
        if (d.DeletedAt != null) return Problem(410, "Gone");
        if (ifMatch == null) return Problem(428, "Precondition Required");

        var newEtag = ETagOf(body);
        if (d.ETag == newEtag) { Response.Headers.ETag = d.ETag; return NoContent(); }
        if (!ETagMatches(ifMatch, d.ETag))
        {
            Response.Headers.ETag = d.ETag;
            return Problem(412, "Precondition Failed");
        }

        d.Code = body.Code!;
        d.CapacityCubicMeters = body.CapacityCubicMeters;
        d.ETag = newEtag;
        d.LastAuditAt = DateTime.UtcNow;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await _db.Depots.AsNoTracking().SingleAsync(x => x.PublicId == id, ct);
            Response.Headers.ETag = cur.ETag;
            return Problem(412, "Precondition Failed");
        }
        Response.Headers.ETag = newEtag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(204)]
    [ProducesResponseType(typeof(ProblemDetails), 412)]
    [ProducesResponseType(typeof(ProblemDetails), 428)]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken ct)
    {
        if (ifMatch == null) return Problem(428, "Precondition Required");

        var d = await _db.Depots.IgnoreQueryFilters()
            .Include(x => x.Consignments)
            .SingleOrDefaultAsync(x => x.PublicId == id, ct);
        if (d == null || d.DeletedAt != null) return NoContent();
        if (!ETagMatches(ifMatch, d.ETag))
        {
            Response.Headers.ETag = d.ETag;
            return Problem(412, "Precondition Failed");
        }

        var now = DateTime.UtcNow;
        d.DeletedAt = now;
        d.ETag = Canonical.Hash(d.ETag + now.Ticks.ToString());
        var shipments = await _db.Consignments.IgnoreQueryFilters()
            .Where(c => c.DepotKey == d.Key && c.DeletedAt == null).ToListAsync(ct);
        foreach (var c in shipments)
        {
            c.DeletedAt = now;
            c.ETag = Canonical.Hash(c.ETag + now.Ticks.ToString());
        }
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return NoContent();
        }
        return NoContent();
    }
}

