public sealed class Depot
{
    public int Key { get; set; }                 // internal PK, never exposed
    public Guid PublicId { get; set; }
    public string Code { get; set; } = "";
    public int CapacityCubicMeters { get; set; }
    public string ETag { get; set; } = "";       // concurrency token
    public string CreateHash { get; set; } = ""; // immutable hash of the create request
    public DateTime? DeletedAt { get; set; }     // tombstone
    public DateTime? LastAuditAt { get; set; }   // server-owned
    public List<Consignment> Consignments { get; set; } = new();
}

public sealed class Consignment
{
    public int Key { get; set; }
    public Guid PublicId { get; set; }
    public int DepotKey { get; set; }
    public Depot Depot { get; set; } = null!;
    public string Reference { get; set; } = "";
    public decimal WeightKg { get; set; }
    public bool Fragile { get; set; }
    public string ETag { get; set; } = "";
    public string CreateHash { get; set; } = "";
    public DateTime? DeletedAt { get; set; }
    public int DownloadCount { get; set; }       // server-owned counter
}

public sealed class AppDb : DbContext
{
    public AppDb(DbContextOptions<AppDb> options) : base(options) { }

    public DbSet<Depot> Depots => Set<Depot>();
    public DbSet<Consignment> Consignments => Set<Consignment>();

    protected override void OnModelCreating(ModelBuilder mb)
    {
        mb.Entity<Depot>(b =>
        {
            b.HasKey(x => x.Key);
            b.HasIndex(x => x.PublicId).IsUnique();
            b.Property(x => x.Code).IsRequired();
            b.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
            b.Property(x => x.CreateHash).IsRequired()
                .Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            b.HasQueryFilter(x => x.DeletedAt == null);
        });
        mb.Entity<Consignment>(b =>
        {
            b.HasKey(x => x.Key);
            b.HasIndex(x => x.PublicId).IsUnique();
            b.Property(x => x.Reference).IsRequired();
            b.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
            b.Property(x => x.CreateHash).IsRequired()
                .Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            b.HasOne(x => x.Depot).WithMany(d => d.Consignments)
                .HasForeignKey(x => x.DepotKey);
            b.HasQueryFilter(x => x.DeletedAt == null);
        });
    }
}
