// File: ETags.cs
using System;
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public static class ETags
{
    private static string JStr(string s)
    {
        s = s.Normalize(NormalizationForm.FormC);
        var sb = new StringBuilder(s.Length + 2).Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }

    private static string Num(decimal d)
    {
        var s = d.ToString("0.#############################", CultureInfo.InvariantCulture);
        return s;
    }

    public static string Canonical(Guid id, string code, int capacityCubicMeters)
        => "{\"id\":" + JStr(id.ToString("D").ToLowerInvariant())
         + ",\"code\":" + JStr(code)
         + ",\"capacityCubicMeters\":" + capacityCubicMeters.ToString(CultureInfo.InvariantCulture) + "}";

    public static string Canonical(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile)
        => "{\"id\":" + JStr(id.ToString("D").ToLowerInvariant())
         + ",\"warehouseId\":" + JStr(warehouseId.ToString("D").ToLowerInvariant())
         + ",\"reference\":" + JStr(reference)
         + ",\"weightKg\":" + Num(weightKg)
         + ",\"fragile\":" + (fragile ? "true" : "false") + "}";

    // Quoted unpadded base64url SHA-256
    public static string Hash(string canonical)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        var b64 = Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + b64 + "\"";
    }

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var t in header.Split(','))
        {
            var v = t.Trim();
            if (v == "*") return true;
            if (v.StartsWith("W/", StringComparison.Ordinal)) v = v[2..];
            if (string.Equals(v, etag, StringComparison.Ordinal)) return true;
        }
        return false;
    }
}
