// File: WarehousesController.cs
using System;
using System.ComponentModel.DataAnnotations;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/warehouses")]
public class WarehousesController : ControllerBase
{
    private readonly AppDb _db;
    public WarehousesController(AppDb db) => _db = db;

    private static bool UniqueViolation(DbUpdateException ex)
        => ex.InnerException is SqliteException { SqliteErrorCode: 19 };

    private async Task<Depot?> FindRaw(Guid id, CancellationToken ct)
        => await _db.Depots.IgnoreQueryFilters().SingleOrDefaultAsync(d => d.PublicId == id, ct);

    private static WarehouseOut ToOut(Depot d) => new()
    {
        Id = d.PublicId,
        Code = d.Code,
        CapacityCubicMeters = d.CapacityCubicMeters
    };

    [HttpPost]
    [ProducesResponseType(typeof(WarehouseOut), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(WarehouseOut), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody][Required] WarehouseIn? body, CancellationToken ct)
    {
        if (body is null || body.Id is null || body.Id == Guid.Empty
            || body.Code is null || body.CapacityCubicMeters is null)
            return Problem(statusCode: 400, detail: "Invalid body.");

        var canon = ETags.Canonical(body.Id.Value, body.Code, body.CapacityCubicMeters.Value);
        var etag = ETags.Hash(canon);
        var depot = new Depot
        {
            PublicId = body.Id.Value,
            Code = body.Code,
            CapacityCubicMeters = body.CapacityCubicMeters.Value,
            ETag = etag,
            CreateHash = etag,
            LastAuditAt = DateTime.UtcNow
        };
        _db.Depots.Add(depot);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (UniqueViolation(ex))
        {
            _db.Entry(depot).State = EntityState.Detached;
            var existing = await FindRaw(body.Id.Value, ct);
            if (existing is null) return Problem(statusCode: 500);
            if (existing.DeletedAt is not null)
                return Problem(statusCode: 410, detail: "Warehouse was deleted.");
            Response.Headers.ETag = existing.ETag;
            if (existing.CreateHash == etag)
                return Ok(ToOut(existing));
            return Problem(statusCode: 409, detail: "Id already exists with different content.");
        }

        Response.Headers.ETag = etag;
        return CreatedAtAction(nameof(Get), new { id = depot.PublicId }, ToOut(depot));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(WarehouseOut), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, [FromHeader(Name = "If-None-Match")] string? ifNoneMatch, CancellationToken ct)
    {
        var d = await FindRaw(id, ct);
        if (d is null) return Problem(statusCode: 404, detail: "Warehouse not found.");
        if (d.DeletedAt is not null) return Problem(statusCode: 410, detail: "Warehouse was deleted.");
        Response.Headers.ETag = d.ETag;
        if (ETags.Matches(ifNoneMatch, d.ETag)) return StatusCode(304);
        return Ok(ToOut(d));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody][Required] WarehouseIn? body,
        [FromHeader(Name = "If-Match")][Required] string? ifMatch, CancellationToken ct)
    {
        if (body is null || body.Id is null || body.Code is null || body.CapacityCubicMeters is null)
            return Problem(statusCode: 400, detail: "Invalid body.");
        if (body.Id.Value != id)
            return Problem(statusCode: 400, detail: "Body id does not match route id.");
        if (ifMatch is null)
            return Problem(statusCode: 428, detail: "If-Match header is required.");

        var d = await FindRaw(id, ct);
        if (d is null) return Problem(statusCode: 404, detail: "Warehouse not found.");
        if (d.DeletedAt is not null) return Problem(statusCode: 410, detail: "Warehouse was deleted.");

        var newEtag = ETags.Hash(ETags.Canonical(id, body.Code, body.CapacityCubicMeters.Value));
        if (d.ETag == newEtag) { Response.Headers.ETag = d.ETag; return NoContent(); }
        if (!ETags.Matches(ifMatch, d.ETag))
        {
            Response.Headers.ETag = d.ETag;
            return Problem(statusCode: 412, detail: "ETag does not match.");
        }

        var old = d.ETag;
        d.Code = body.Code;
        d.CapacityCubicMeters = body.CapacityCubicMeters.Value;
        d.ETag = newEtag;
        d.LastAuditAt = DateTime.UtcNow;
        _db.Entry(d).Property(x => x.ETag).OriginalValue = old;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await FindRaw(id, ct);
            if (cur is { DeletedAt: null }) Response.Headers.ETag = cur.ETag;
            if (cur is { DeletedAt: not null })
                return Problem(statusCode: 410, detail: "Warehouse was deleted.");
            return Problem(statusCode: 412, detail: "ETag does not match.");
        }
        Response.Headers.ETag = newEtag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")][Required] string? ifMatch, CancellationToken ct)
    {
        if (ifMatch is null)
            return Problem(statusCode: 428, detail: "If-Match header is required.");

        var d = await FindRaw(id, ct);
        if (d is null || d.DeletedAt is not null) return NoContent();
        if (!ETags.Matches(ifMatch, d.ETag))
        {
            Response.Headers.ETag = d.ETag;
            return Problem(statusCode: 412, detail: "ETag does not match.");
        }

        var now = DateTime.UtcNow;
        var old = d.ETag;
        d.DeletedAt = now;
        d.LastAuditAt = now;
        d.ETag = ETags.Hash(ETags.Canonical(d.PublicId, d.Code, d.CapacityCubicMeters));
        _db.Entry(d).Property(x => x.ETag).OriginalValue = old;

        var children = await _db.Consignments.IgnoreQueryFilters()
            .Where(c => c.DepotKey == d.Key && c.DeletedAt == null).ToListAsync(ct);
        foreach (var c in children)
        {
            var cOld = c.ETag;
            c.DeletedAt = now;
            c.ETag = ETags.Hash(ETags.Canonical(c.PublicId, d.PublicId, c.Reference, c.WeightKg, c.Fragile));
            _db.Entry(c).Property(x => x.ETag).OriginalValue = cOld;
        }
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Problem(statusCode: 412, detail: "ETag does not match.");
        }
        return NoContent();
    }
}
