{
    private readonly AppDb _db;
    public ShipmentsController(AppDb db) => _db = db;

    private static bool UniqueViolation(DbUpdateException ex)
        => ex.InnerException is SqliteException { SqliteErrorCode: 19 };

    private async Task<Consignment?> FindRaw(Guid id, CancellationToken ct)
        => await _db.Consignments.IgnoreQueryFilters().Include(c => c.Depot)
            .SingleOrDefaultAsync(c => c.PublicId == id, ct);

    private static ShipmentOut ToOut(Consignment c) => new()
    {
        Id = c.PublicId,
        WarehouseId = c.Depot.PublicId,
        Reference = c.Reference,
        WeightKg = c.WeightKg,
        Fragile = c.Fragile
    };

    [HttpPost("warehouses/{warehouseId:guid}/shipments")]
    [ProducesResponseType(typeof(ShipmentOut), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(ShipmentOut), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create(Guid warehouseId, [FromBody][Required] ShipmentIn? body, CancellationToken ct)
    {
        if (body is null || body.Id is null || body.Id == Guid.Empty || body.WarehouseId is null
            || body.Reference is null || body.WeightKg is null || body.Fragile is null)
            return Problem(statusCode: 400, detail: "Invalid body.");
        if (body.WarehouseId.Value != warehouseId)
            return Problem(statusCode: 400, detail: "warehouseId does not match route.");

        var depot = await _db.Depots.IgnoreQueryFilters()
            .SingleOrDefaultAsync(d => d.PublicId == warehouseId, ct);
        if (depot is null) return Problem(statusCode: 404, detail: "Warehouse not found.");
        if (depot.DeletedAt is not null) return Problem(statusCode: 410, detail: "Warehouse was deleted.");

        var canon = ETags.Canonical(body.Id.Value, warehouseId, body.Reference,
            body.WeightKg.Value, body.Fragile.Value);
        var etag = ETags.Hash(canon);
        var c = new Consignment
        {
            PublicId = body.Id.Value,
            DepotKey = depot.Key,
            Reference = body.Reference,
            WeightKg = body.WeightKg.Value,
            Fragile = body.Fragile.Value,
            ETag = etag,
            CreateHash = etag
        };
        _db.Consignments.Add(c);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (UniqueViolation(ex))
        {
            _db.Entry(c).State = EntityState.Detached;
            var existing = await FindRaw(body.Id.Value, ct);
            if (existing is null) return Problem(statusCode: 500);
            if (existing.DeletedAt is not null)
                return Problem(statusCode: 410, detail: "Shipment was deleted.");
            Response.Headers.ETag = existing.ETag;
            if (existing.CreateHash == etag)
                return Ok(ToOut(existing));
            return Problem(statusCode: 409, detail: "Id already exists with different content.");
        }

        Response.Headers.ETag = etag;
        return CreatedAtAction(nameof(Get), new { id = c.PublicId }, ToOut(c));
    }

    [HttpGet("shipments/{id:guid}")]
    [ProducesResponseType(typeof(ShipmentOut), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, [FromHeader(Name = "If-None-Match")] string? ifNoneMatch, CancellationToken ct)
    {
        var c = await FindRaw(id, ct);
        if (c is null) return Problem(statusCode: 404, detail: "Shipment not found.");
        if (c.DeletedAt is not null) return Problem(statusCode: 410, detail: "Shipment was deleted.");

        c.DownloadCount++;
        await _db.SaveChangesAsync(ct); // server-owned counter, not part of ETag

        Response.Headers.ETag = c.ETag;
        if (ETags.Matches(ifNoneMatch, c.ETag)) return StatusCode(304);
        return Ok(ToOut(c));
    }

    [HttpPut("shipments/{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody][Required] ShipmentIn? body,
        [FromHeader(Name = "If-Match")][Required] string? ifMatch, CancellationToken ct)
    {
        if (body is null || body.Id is null || body.WarehouseId is null || body.Reference is null
            || body.WeightKg is null || body.Fragile is null)
            return Problem(statusCode: 400, detail: "Invalid body.");
        if (body.Id.Value != id)
            return Problem(statusCode: 400, detail: "Body id does not match route id.");
        if (ifMatch is null)
            return Problem(statusCode: 428, detail: "If-Match header is required.");

        var c = await FindRaw(id, ct);
        if (c is null) return Problem(statusCode: 404, detail: "Shipment not found.");
        if (c.DeletedAt is not null) return Problem(statusCode: 410, detail: "Shipment was deleted.");
        if (body.WarehouseId.Value != c.Depot.PublicId)
            return Problem(statusCode: 409, detail: "Cannot move a shipment to another warehouse.");

        var newEtag = ETags.Hash(ETags.Canonical(id, body.WarehouseId.Value, body.Reference,
            body.WeightKg.Value, body.Fragile.Value));
        if (c.ETag == newEtag) { Response.Headers.ETag = c.ETag; return NoContent(); }
        if (!ETags.Matches(ifMatch, c.ETag))
        {
            Response.Headers.ETag = c.ETag;
            return Problem(statusCode: 412, detail: "ETag does not match.");
        }

        var old = c.ETag;
        c.Reference = body.Reference;
        c.WeightKg = body.WeightKg.Value;
        c.Fragile = body.Fragile.Value;
        c.ETag = newEtag;
        _db.Entry(c).Property(x => x.ETag).OriginalValue = old;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var cur = await FindRaw(id, ct);
            if (cur is { DeletedAt: null }) Response.Headers.ETag = cur.ETag;
            if (cur is { DeletedAt: not null })
                return Problem(statusCode: 410, detail: "Shipment was deleted.");
            return Problem(statusCode: 412, detail: "ETag does not match.");
        }
        Response.Headers.ETag = newEtag;
        return NoContent();
    }

