        if (!ETags.Matches(ifMatch, c.ETag))
        {
            Response.Headers.ETag = c.ETag;
            return Problem(statusCode: 412, detail: "ETag does not match.");
        }

        var old = c.ETag;
        c.DeletedAt = DateTime.UtcNow;
        c.ETag = ETags.Hash(ETags.Canonical(c.PublicId, c.Depot.PublicId, c.Reference, c.WeightKg, c.Fragile));
        _db.Entry(c).Property(x => x.ETag).OriginalValue = old;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Problem(statusCode: 412, detail: "ETag does not match.");
        }
        return NoContent();
    }
