    }

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] Blog blog)
    {
        if (blog.Id == Guid.Empty)
            blog.Id = Guid.NewGuid();
        if (string.IsNullOrWhiteSpace(blog.Name))
            return BadRequest(new { error = "Name is required." });

        var existing = await _context.Blogs.FindAsync(blog.Id);
        if (existing is not null)
        {
            return existing.Name == blog.Name
                ? Ok(existing)
                : Conflict(new { error = "A blog with this id already exists." });
        }

        _context.Blogs.Add(blog);
        await _context.SaveChangesAsync();
        return CreatedAtAction(nameof(Get), new { id = blog.Id }, blog);
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id)
    {
        var blog = await _context.Blogs.FindAsync(id);
        return blog is null ? NotFound() : Ok(blog);
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] Blog blog)
    {
        if (string.IsNullOrWhiteSpace(blog.Name))
            return BadRequest(new { error = "Name is required." });

        var existing = await _context.Blogs.FindAsync(id);
        if (existing is null)
            return NotFound();

        existing.Name = blog.Name;
        await _context.SaveChangesAsync();
        return Ok(existing);
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var blog = await _context.Blogs.FindAsync(id);
        if (blog is null)
            return NotFound();

        _context.Blogs.Remove(blog);
        await _context.SaveChangesAsync();
        return NoContent();
    }

    [HttpPost("{blogId:guid}/posts")]
    public async Task<IActionResult> CreatePost(Guid blogId, [FromBody] Post post)
    {
        var blog = await _context.Blogs.FindAsync(blogId);
        if (blog is null)
            return NotFound(new { error = "Blog not found." });

        if (post.Id == Guid.Empty)
            post.Id = Guid.NewGuid();
        if (string.IsNullOrWhiteSpace(post.Title))
            return BadRequest(new { error = "Title is required." });

        post.BlogId = blogId;
        post.Views = 0;

        var existing = await _context.Posts.FindAsync(post.Id);
        if (existing is not null)
        {
            var same = existing.BlogId == blogId && existing.Title == post.Title;
            return same
                ? Ok(existing)
                : Conflict(new { error = "A post with this id already exists." });
        }

        _context.Posts.Add(post);
        await _context.SaveChangesAsync();
        return CreatedAtAction("GetPost", "Posts", new { id = post.Id }, post);
    }
}
