[ApiController]
[Route("api/posts")]
public class PostsController : ControllerBase
{
    private readonly AppDbContext _context;

    public PostsController(AppDbContext context)
    {
        _context = context;
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id)
    {
        var post = await _context.Posts.FindAsync(id);
        if (post is null)
            return NotFound();

        await _context.Posts
            .Where(p => p.Id == id)
            .ExecuteUpdateAsync(s => s.SetProperty(p => p.Views, p => p.Views + 1));

        post.Views += 1;
        return Ok(post);
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] Post post)
    {
        if (string.IsNullOrWhiteSpace(post.Title))
            return BadRequest(new { error = "Title is required." });

        var existing = await _context.Posts.FindAsync(id);
        if (existing is null)
            return NotFound();

        if (!await _context.Blogs.AnyAsync(b => b.Id == post.BlogId))
            return BadRequest(new { error = "Blog not found." });

        existing.BlogId = post.BlogId;
        existing.Title = post.Title;
        await _context.SaveChangesAsync();
        return Ok(existing);
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var post = await _context.Posts.FindAsync(id);
        if (post is null)
            return NotFound();

        _context.Posts.Remove(post);
        await _context.SaveChangesAsync();
        return NoContent();
    }
}
