// Controllers.cs
using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/blogs")]
public class BlogsController : ControllerBase
{
    private readonly AppDbContext _db;

    public BlogsController(AppDbContext db) => _db = db;

    [HttpPost]
    public async Task<ActionResult<BlogDto>> Create(BlogDto dto, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(dto.Name))
            return BadRequest("Name is required.");

        var id = dto.Id == Guid.Empty ? Guid.NewGuid() : dto.Id;

        // Idempotent create for retried requests.
        var existing = await _db.Blogs.FindAsync(new object[] { id }, ct);
        if (existing is not null)
            return Ok(ToDto(existing));

        var blog = new Blog { Id = id, Name = dto.Name };
        _db.Blogs.Add(blog);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            // Lost a race with a concurrent insert; return the existing row.
            _db.Entry(blog).State = EntityState.Detached;
            var winner = await _db.Blogs.AsNoTracking().FirstOrDefaultAsync(b => b.Id == id, ct);
            if (winner is not null)
                return Ok(ToDto(winner));
            throw;
        }
        return CreatedAtAction(nameof(Get), new { id }, ToDto(blog));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<BlogDto>> Get(Guid id, CancellationToken ct)
    {
        var blog = await _db.Blogs.AsNoTracking().FirstOrDefaultAsync(b => b.Id == id, ct);
        return blog is null ? NotFound() : Ok(ToDto(blog));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<BlogDto>> Update(Guid id, BlogDto dto, CancellationToken ct)
    {
        var blog = await _db.Blogs.FindAsync(new object[] { id }, ct);
        if (blog is null)
            return NotFound();

        blog.Name = dto.Name ?? blog.Name;
        await _db.SaveChangesAsync(ct);
        return Ok(ToDto(blog));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var blog = await _db.Blogs.FindAsync(new object[] { id }, ct);
        if (blog is null)
            return NotFound();

        _db.Blogs.Remove(blog);
        await _db.SaveChangesAsync(ct);
        return NoContent();
    }

    private static BlogDto ToDto(Blog b) => new() { Id = b.Id, Name = b.Name };
}

