    {
        var post = await _db.Posts.FirstOrDefaultAsync(p => p.Id == id, ct);
        if (post is null)
            return NotFound();

        // Server-maintained view counter; never client-set.
        post.Views++;
        await _db.SaveChangesAsync(ct);
        return Ok(ToDto(post));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<PostDto>> Update(Guid id, PostDto dto, CancellationToken ct)
    {
        var post = await _db.Posts.FindAsync(new object[] { id }, ct);
        if (post is null)
            return NotFound();

        // Views is server-maintained and ignored from the client.
        post.Title = dto.Title ?? post.Title;
        await _db.SaveChangesAsync(ct);
        return Ok(ToDto(post));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var post = await _db.Posts.FindAsync(new object[] { id }, ct);
        if (post is null)
            return NotFound();

        _db.Posts.Remove(post);
        await _db.SaveChangesAsync(ct);
        return NoContent();
    }

    private static PostDto ToDto(Post p) =>
        new() { Id = p.Id, BlogId = p.BlogId, Title = p.Title, Views = p.Views };
