            return BadRequest(new { error = "title is required" });

        var blogExists = await _db.Blogs.AnyAsync(b => b.Id == blogId);
        if (!blogExists)
            return NotFound(new { error = "blog not found" });

        if (post.Id == Guid.Empty)
            post.Id = Guid.NewGuid();

        var existing = await _db.Posts.FindAsync(post.Id);
        if (existing is not null)
            return Ok(existing);

        var entity = new Post
        {
            Id = post.Id,
            BlogId = blogId,
            Title = post.Title,
            Views = 0,
            Version = 0
        };

        _db.Posts.Add(entity);
        await _db.SaveChangesAsync();

        return Created($"/api/posts/{entity.Id}", entity);
    }

    [HttpGet("/api/posts/{id:guid}")]
    public async Task<IActionResult> Get(Guid id)
    {
        await _db.Posts
            .Where(p => p.Id == id)
            .ExecuteUpdateAsync(s => s.SetProperty(p => p.Views, p => p.Views + 1));

        var post = await _db.Posts.AsNoTracking().FirstOrDefaultAsync(p => p.Id == id);
        return post is null ? NotFound() : Ok(post);
    }

    [HttpPut("/api/posts/{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] Post post)
    {
        if (string.IsNullOrWhiteSpace(post.Title))
            return BadRequest(new { error = "title is required" });

        var existing = await _db.Posts.FindAsync(id);
        if (existing is null)
            return NotFound();

        var blogId = post.BlogId == Guid.Empty ? existing.BlogId : post.BlogId;
        var blogExists = await _db.Blogs.AnyAsync(b => b.Id == blogId);
        if (!blogExists)
            return NotFound(new { error = "blog not found" });

        // Update only client-owned fields atomically; Views is preserved and
        // Version is bumped as a concurrency token.
        var updated = await _db.Posts
            .Where(p => p.Id == id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(p => p.Title, post.Title)
                .SetProperty(p => p.BlogId, blogId)
                .SetProperty(p => p.Version, p => p.Version + 1));

        if (updated == 0)
            return NotFound();

        var result = await _db.Posts.AsNoTracking().FirstAsync(p => p.Id == id);
        return Ok(result);
    }

    [HttpDelete("/api/posts/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
