using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace BlogApi;

[ApiController]
[Route("api")]
public class PostsController : ControllerBase
{
    private readonly BlogContext _db;

    public PostsController(BlogContext db)
    {
        _db = db;
    }

    [HttpPost("blogs/{blogId:guid}/posts")]
    public async Task<IActionResult> Create(Guid blogId, [FromBody] PostDto dto, CancellationToken ct)
    {
        if (string.IsNullOrEmpty(dto.Title))
            return BadRequest(new { error = "title is required" });

        if (!await _db.Blogs.AnyAsync(b => b.Id == blogId, ct))
            return NotFound(new { error = "blog not found" });

        if (dto.Id != Guid.Empty)
        {
            var existing = await _db.Posts.AsNoTracking().FirstOrDefaultAsync(p => p.Id == dto.Id, ct);
            if (existing != null)
                return Ok(existing);
        }

        var post = new Post
        {
            Id = dto.Id == Guid.Empty ? Guid.NewGuid() : dto.Id,
            BlogId = blogId,
            Title = dto.Title,
            Views = 0
        };
        _db.Posts.Add(post);
        await _db.SaveChangesAsync(ct);
        return CreatedAtAction(nameof(Get), new { id = post.Id }, post);
    }

    [HttpGet("blogs/{blogId:guid}/posts")]
    public async Task<IActionResult> ListByBlog(Guid blogId, CancellationToken ct)
    {
        var posts = await _db.Posts.AsNoTracking()
            .Where(p => p.BlogId == blogId)
            .OrderBy(p => p.Id)
            .ToListAsync(ct);
        return Ok(posts);
    }

    [HttpGet("posts/{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var post = await _db.Posts.AsNoTracking().FirstOrDefaultAsync(p => p.Id == id, ct);
        if (post == null) return NotFound();

        await _db.Posts.Where(p => p.Id == id)
            .ExecuteUpdateAsync(s => s.SetProperty(p => p.Views, p => p.Views + 1), ct);
        post.Views++;

        return Ok(post);
    }

    [HttpPut("posts/{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] PostDto dto, CancellationToken ct)
    {
        if (string.IsNullOrEmpty(dto.Title))
            return BadRequest(new { error = "title is required" });

        var post = await _db.Posts.FirstOrDefaultAsync(p => p.Id == id, ct);
        if (post == null) return NotFound();

        if (dto.BlogId != Guid.Empty && dto.BlogId != post.BlogId)
        {
            if (!await _db.Blogs.AnyAsync(b => b.Id == dto.BlogId, ct))
                return NotFound(new { error = "blog not found" });
            post.BlogId = dto.BlogId;
        }

        post.Title = dto.Title;
        await _db.SaveChangesAsync(ct);
        return Ok(post);
    }

    [HttpDelete("posts/{id:guid}")]
