using Microsoft.EntityFrameworkCore;

namespace BlogApi;

public class AppDbContext : DbContext
{
    public AppDbContext(DbContextOptions<AppDbContext> options)
        : base(options)
    {
    }

    public DbSet<Blog> Blogs => Set<Blog>();
    public DbSet<Post> Posts => Set<Post>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            entity.HasKey(e => e.Id);
            entity.Property(e => e.Name).IsRequired();
            entity.Property<int>("Version").IsConcurrencyToken().ValueGeneratedNever();
        });

        modelBuilder.Entity<Post>(entity =>
        {
            entity.HasKey(e => e.Id);
            entity.Property(e => e.Title).IsRequired();
            entity.Property<int>("Version").IsConcurrencyToken().ValueGeneratedNever();
            entity.HasOne<Blog>()
                  .WithMany()
                  .HasForeignKey(e => e.BlogId)
                  .OnDelete(DeleteBehavior.Cascade);
        });
    }

    public override int SaveChanges(bool acceptAllChangesOnSuccess)
    {
        UpdateVersionProperties();
        return base.SaveChanges(acceptAllChangesOnSuccess);
    }

    public override Task<int> SaveChangesAsync(bool acceptAllChangesOnSuccess, CancellationToken cancellationToken = default)
    {
        UpdateVersionProperties();
        return base.SaveChangesAsync(acceptAllChangesOnSuccess, cancellationToken);
    }

    private void UpdateVersionProperties()
    {
        foreach (var entry in ChangeTracker.Entries())
        {
            if (entry.Entity is not (Blog or Post))
            {
                continue;
            }

            if (entry.State == EntityState.Added)
            {
                entry.Property("Version").CurrentValue = 0;
            }
            else if (entry.State == EntityState.Modified)
            {
                var property = entry.Property("Version");
                var current = property.CurrentValue is int value ? value : 0;
                property.CurrentValue = current + 1;
            }
        }
    }
}
