using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace BlogApi;

[ApiController]
[Route("api/blogs")]
public sealed class BlogsController : ControllerBase
{
    private readonly AppDbContext _db;

    public BlogsController(AppDbContext db)
    {
        _db = db;
    }

    [HttpPost]
    public async Task<IActionResult> Create(BlogWriteRequest request, CancellationToken cancellationToken)
    {
        if (request.Name is null)
        {
            return BadRequest(new { message = "Name is required." });
        }

        var id = request.Id ?? Guid.NewGuid();
        var existing = await _db.Blogs.AsNoTracking().FirstOrDefaultAsync(b => b.Id == id, cancellationToken);
        if (existing is not null)
        {
            return existing.Name == request.Name
                ? Ok(existing)
                : Conflict(new { message = "A blog with this id already exists." });
        }

        var blog = new Blog { Id = id, Name = request.Name };
        _db.Blogs.Add(blog);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            var raced = await _db.Blogs.AsNoTracking().FirstOrDefaultAsync(b => b.Id == id, cancellationToken);
            if (raced is null)
            {
                throw;
            }

            return raced.Name == request.Name
                ? Ok(raced)
                : Conflict(new { message = "A blog with this id already exists." });
        }

        return Created($"/api/blogs/{blog.Id}", blog);
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken cancellationToken)
    {
        var blog = await _db.Blogs.AsNoTracking().FirstOrDefaultAsync(b => b.Id == id, cancellationToken);
        return blog is null ? NotFound() : Ok(blog);
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, BlogWriteRequest request, CancellationToken cancellationToken)
    {
        if (request.Name is null)
        {
            return BadRequest(new { message = "Name is required." });
        }

        if (request.Id.HasValue && request.Id.Value != id)
        {
            return BadRequest(new { message = "Id in the body does not match the route." });
        }

        var blog = await _db.Blogs.FirstOrDefaultAsync(b => b.Id == id, cancellationToken);
        if (blog is null)
        {
            return NotFound();
        }

        blog.Name = request.Name;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await ConcurrencyConflictAsync(id, cancellationToken);
        }

        return Ok(blog);
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken cancellationToken)
    {
        var blog = await _db.Blogs.FirstOrDefaultAsync(b => b.Id == id, cancellationToken);
        if (blog is null)
        {
            return NotFound();
        }

        var posts = await _db.Posts.Where(p => p.BlogId == id).ToListAsync(cancellationToken);
        _db.Posts.RemoveRange(posts);
        _db.Blogs.Remove(blog);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await ConcurrencyConflictAsync(id, cancellationToken);
        }

        return NoContent();
    }

    private async Task<IActionResult> ConcurrencyConflictAsync(Guid id, CancellationToken cancellationToken)
    {
        var exists = await _db.Blogs.AsNoTracking().AnyAsync(b => b.Id == id, cancellationToken);
        if (!exists)
        {
            return NotFound();
        }

        return Conflict(new { message = "The blog was modified by another request." });
    }
}
