        var id = request.Id ?? Guid.NewGuid();
        var existing = await _db.Posts.AsNoTracking().FirstOrDefaultAsync(p => p.Id == id, cancellationToken);
        if (existing is not null)
        {
            return existing.BlogId == blogId && existing.Title == request.Title
                ? Ok(existing)
                : Conflict(new { message = "A post with this id already exists." });
        }

        var post = new Post
        {
