            Views = 0
        };
        _db.Posts.Add(post);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            var raced = await _db.Posts.AsNoTracking().FirstOrDefaultAsync(p => p.Id == id, cancellationToken);
            if (raced is not null)
            {
                return raced.BlogId == blogId && raced.Title == request.Title
                    ? Ok(raced)
                    : Conflict(new { message = "A post with this id already exists." });
            }

            var blogStillExists = await _db.Blogs.AsNoTracking().AnyAsync(b => b.Id == blogId, cancellationToken);
            if (!blogStillExists)
