        var post = await _db.Posts.AsNoTracking().FirstOrDefaultAsync(p => p.Id == id, cancellationToken);
        return post is null ? NotFound() : Ok(post);
    }

    [HttpPut("posts/{id:guid}")]
    public async Task<IActionResult> Update(Guid id, PostWriteRequest request, CancellationToken cancellationToken)
    {
        if (request.Title is null)
        {
            return BadRequest(new { message = "Title is required." });
        }

        if (request.Id.HasValue && request.Id.Value != id)
        {
            return BadRequest(new { message = "Id in the body does not match the route." });
        }

        var post = await _db.Posts.FirstOrDefaultAsync(p => p.Id == id, cancellationToken);
        if (post is null)
        {
            return NotFound();
        }

        if (request.BlogId.HasValue && request.BlogId.Value != post.BlogId)
        {
            var targetBlogExists = await _db.Blogs.AsNoTracking().AnyAsync(b => b.Id == request.BlogId.Value, cancellationToken);
            if (!targetBlogExists)
            {
                return BadRequest(new { message = "blogId does not reference an existing blog." });
            }

            post.BlogId = request.BlogId.Value;
        }

        post.Title = request.Title;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
            await _db.Entry(post).ReloadAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await ConcurrencyConflictAsync(id, cancellationToken);
        }

        return Ok(post);
    }

    [HttpDelete("posts/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken cancellationToken)
    {
        var post = await _db.Posts.FirstOrDefaultAsync(p => p.Id == id, cancellationToken);
        if (post is null)
        {
            return NotFound();
        }

        _db.Posts.Remove(post);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await ConcurrencyConflictAsync(id, cancellationToken);
        }

        return NoContent();
    }

    private async Task<IActionResult> ConcurrencyConflictAsync(Guid id, CancellationToken cancellationToken)
    {
        var exists = await _db.Posts.AsNoTracking().AnyAsync(p => p.Id == id, cancellationToken);
        if (!exists)
        {
            return NotFound();
        }

        return Conflict(new { message = "The post was modified by another request." });
    }
