// CanonicalJson.cs
using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

internal static class CanonicalJson
{
    public static string Blog(Guid id, string name) =>
        "{\"id\":\"" + Id(id) + "\",\"name\":" + Str(name) + "}";

    public static string Post(Guid id, Guid blogId, string title) =>
        "{\"id\":\"" + Id(id) + "\",\"blogId\":\"" + Id(blogId) + "\",\"title\":" + Str(title) + "}";

    public static string ETag(string canonical) => "\"" + Hash(canonical) + "\"";

    public static string Hash(string canonical)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
    }

    private static string Id(Guid id) => id.ToString("d");

    private static string Str(string value)
    {
        var s = value.Normalize(NormalizationForm.FormC);
        var sb = new StringBuilder(s.Length + 2);
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < ' ')
                        sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else
                        sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
        return sb.ToString();
    }
}

internal static class Api
{
    public static ObjectResult Problem(int statusCode, string title, string? detail = null)
    {
        var problem = new ProblemDetails
        {
            Type = "https://httpstatuses.com/" + statusCode,
            Title = title,
            Status = statusCode,
            Detail = detail
        };
        return new ObjectResult(problem)
        {
            StatusCode = statusCode,
            ContentTypes = { "application/problem+json" }
        };
    }

    public static bool ETagMatches(string? headerValue, string currentETag)
    {
        if (string.IsNullOrWhiteSpace(headerValue)) return false;
        var unquoted = currentETag.Trim('"');
        foreach (var part in headerValue.Split(','))
        {
            var v = part.Trim();
            if (v.StartsWith("W/", StringComparison.Ordinal)) v = v[2..];
            if (v == "*" ||
                string.Equals(v, currentETag, StringComparison.Ordinal) ||
                string.Equals(v, unquoted, StringComparison.Ordinal))
                return true;
        }
        return false;
    }

    public static bool IsUniqueViolation(DbUpdateException ex) =>
        ex.InnerException is SqliteException sqlite &&
        (sqlite.SqliteErrorCode == 19 ||
         sqlite.SqliteExtendedErrorCode is 1555 or 2067 or 787);
}
