[ApiController]
[Route("api/blogs")]
public class BlogsController : ControllerBase
{
    private readonly AppDbContext _db;

    public BlogsController(AppDbContext db) => _db = db;

    [HttpPost]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<ActionResult<BlogResponse>> Create(
        [FromBody] BlogRequest request, CancellationToken cancellationToken)
    {
        if (request is null || request.Id == Guid.Empty || request.Name is null)
            return Api.Problem(StatusCodes.Status400BadRequest, "Bad Request",
                "A blog id and name are required.");

        var canonical = CanonicalJson.Blog(request.Id, request.Name);
        var etag = CanonicalJson.ETag(canonical);
        var entity = new Blog
        {
            PublicId = request.Id,
            Name = request.Name,
            ETag = etag,
            CreateHash = CanonicalJson.Hash(canonical)
        };
        _db.Blogs.Add(entity);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException ex) when (Api.IsUniqueViolation(ex))
        {
            var existing = await _db.Blogs.IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(b => b.PublicId == request.Id, cancellationToken);
            if (existing is null) throw;
            if (existing.DeletedAtUtc is not null)
                return Api.Problem(StatusCodes.Status410Gone, "Gone", "The blog has been deleted.");
            if (!string.Equals(existing.CreateHash, entity.CreateHash, StringComparison.Ordinal))
                return Api.Problem(StatusCodes.Status409Conflict, "Conflict",
                    "A blog with this id already exists.");
            Response.Headers.ETag = existing.ETag;
            return Ok(new BlogResponse(existing.PublicId, existing.Name));
        }

        Response.Headers.ETag = etag;
        return Created($"/api/blogs/{request.Id:d}", new BlogResponse(request.Id, request.Name));
    }

    [HttpGet("{id}")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<ActionResult<BlogResponse>> Get(
        Guid id,
        [FromHeader(Name = "If-None-Match")] string? ifNoneMatch,
        CancellationToken cancellationToken)
    {
        var blog = await _db.Blogs.IgnoreQueryFilters().AsNoTracking()
            .FirstOrDefaultAsync(b => b.PublicId == id, cancellationToken);
        if (blog is null)
            return Api.Problem(StatusCodes.Status404NotFound, "Not Found", "The blog was not found.");
        if (blog.DeletedAtUtc is not null)
            return Api.Problem(StatusCodes.Status410Gone, "Gone", "The blog has been deleted.");

        Response.Headers.ETag = blog.ETag;
        if (Api.ETagMatches(ifNoneMatch, blog.ETag))
            return StatusCode(StatusCodes.Status304NotModified);
        return Ok(new BlogResponse(blog.PublicId, blog.Name));
    }

    [HttpPut("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(
        Guid id,
        [FromBody] BlogRequest request,
        [FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken cancellationToken)
    {
        if (request is null || request.Id == Guid.Empty || request.Name is null)
            return Api.Problem(StatusCodes.Status400BadRequest, "Bad Request",
                "A blog id and name are required.");
        if (request.Id != id)
            return Api.Problem(StatusCodes.Status400BadRequest, "Bad Request",
                "The body id must match the route id.");
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Api.Problem(StatusCodes.Status428PreconditionRequired, "Precondition Required",
                "An If-Match header is required.");

        var blog = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.PublicId == id, cancellationToken);
        if (blog is null)
            return Api.Problem(StatusCodes.Status404NotFound, "Not Found", "The blog was not found.");
        if (blog.DeletedAtUtc is not null)
            return Api.Problem(StatusCodes.Status410Gone, "Gone", "The blog has been deleted.");

        var etag = CanonicalJson.ETag(CanonicalJson.Blog(id, request.Name));
        if (blog.ETag == etag)
        {
            Response.Headers.ETag = blog.ETag;
            return NoContent();
        }
        if (!Api.ETagMatches(ifMatch, blog.ETag))
        {
            Response.Headers.ETag = blog.ETag;
            return Api.Problem(StatusCodes.Status412PreconditionFailed, "Precondition Failed",
                "The blog was modified by another request.");
        }

        blog.Name = request.Name;
        blog.ETag = etag;
        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await ConcurrencyConflict(id, cancellationToken);
        }

        Response.Headers.ETag = etag;
        return NoContent();
    }

    [HttpDelete("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Api.Problem(StatusCodes.Status428PreconditionRequired, "Precondition Required",
                "An If-Match header is required.");

        var blog = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.PublicId == id, cancellationToken);
        if (blog is null || blog.DeletedAtUtc is not null)
            return NoContent();
        if (!Api.ETagMatches(ifMatch, blog.ETag))
        {
            Response.Headers.ETag = blog.ETag;
            return Api.Problem(StatusCodes.Status412PreconditionFailed, "Precondition Failed",
                "The blog was modified by another request.");
        }

        var now = DateTimeOffset.UtcNow;
        blog.DeletedAtUtc = now;
        var posts = await _db.Posts.Where(p => p.BlogId == blog.Id).ToListAsync(cancellationToken);
        foreach (var post in posts)
            post.DeletedAtUtc = now;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await ConcurrencyConflict(id, cancellationToken);
        }
        return NoContent();
    }

    private async Task<IActionResult> ConcurrencyConflict(Guid publicId, CancellationToken cancellationToken)
    {
        var current = await _db.Blogs.IgnoreQueryFilters().AsNoTracking()
            .FirstOrDefaultAsync(b => b.PublicId == publicId, cancellationToken);
        if (current is null)
            return Api.Problem(StatusCodes.Status404NotFound, "Not Found", "The blog was not found.");
        if (current.DeletedAtUtc is not null)
            return Api.Problem(StatusCodes.Status410Gone, "Gone", "The blog has been deleted.");
        Response.Headers.ETag = current.ETag;
        return Api.Problem(StatusCodes.Status412PreconditionFailed, "Precondition Failed",
            "The blog was modified by another request.");
    }
