        post.DeletedAtUtc = DateTimeOffset.UtcNow;
        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            return await ConcurrencyConflict(id, cancellationToken);
        }
        return NoContent();
    }

    private async Task<IActionResult> ConcurrencyConflict(Guid publicId, CancellationToken cancellationToken)
    {
        var current = await _db.Posts.IgnoreQueryFilters().AsNoTracking()
            .FirstOrDefaultAsync(p => p.PublicId == publicId, cancellationToken);
        if (current is null)
            return Api.Problem(StatusCodes.Status404NotFound, "Not Found", "The post was not found.");
        if (current.DeletedAtUtc is not null)
