// Canonical.cs
using System.Security.Cryptography;
using System.Text;

public static class Canonical
{
    private static string Q(Guid g) => "\"" + g.ToString("D") + "\"";

    public static string Blog(Guid id, string name) =>
        "{\"id\":" + Q(id) + ",\"name\":" + Quote(name) + "}";

    public static string Post(Guid id, Guid blogId, string title) =>
        "{\"id\":" + Q(id) + ",\"blogId\":" + Q(blogId) + ",\"title\":" + Quote(title) + "}";

    private static string Quote(string value)
    {
        var s = value.Normalize(NormalizationForm.FormC);
        var sb = new StringBuilder(s.Length + 2);
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else
                        sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }

    public static string Hash(string canonical)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return Convert.ToBase64String(bytes).Replace('+', '-').Replace('/', '_').TrimEnd('=');
    }

    public static string ETag(string canonical) => "\"" + Hash(canonical) + "\"";
}
