// Api.cs
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

internal static class Api
{
    private static bool MatchesOne(string h, string etag)
    {
        h = h.Trim();
        if (h.StartsWith("W/", StringComparison.OrdinalIgnoreCase))
            h = h[2..].Trim();
        return h == etag || (h.Length > 0 && h[0] != '"' && "\"" + h + "\"" == etag);
    }

    public static bool ETagMatches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        var h = header.Trim();
        return h == "*" || MatchesOne(h, etag);
    }

    public static bool NoneMatch(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var part in header.Split(','))
        {
            var h = part.Trim();
            if (h == "*" || MatchesOne(h, etag)) return true;
        }
        return false;
    }
}

internal static class Storage
{
    public static bool IsUniqueViolation(DbUpdateException ex)
    {
        for (var inner = ex.InnerException; inner is not null; inner = inner.InnerException)
            if (inner is SqliteException sqlite && sqlite.SqliteErrorCode == 19)
                return true;
        return false;
    }
}
