            return Problem(statusCode: StatusCodes.Status412PreconditionFailed, title: "Precondition Failed",
                detail: "The If-Match precondition did not match the current representation.");

        post.DeletedAt = DateTimeOffset.UtcNow;
        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.ChangeTracker.Clear();
            var current = await _db.Posts.IgnoreQueryFilters()
                .FirstOrDefaultAsync(p => p.PublicId == id, cancellationToken);
            if (current is not null) Response.Headers.ETag = current.ETag;
            return Problem(statusCode: StatusCodes.Status412PreconditionFailed, title: "Precondition Failed",
                detail: "The resource was modified by another request.");
        }

        return NoContent();
    }
}
