// CanonicalJson.cs
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public static class CanonicalJson
{
    public static string Blog(Guid id, string name) =>
        "{\"id\":" + GuidJson(id) + ",\"name\":" + StringJson(name) + "}";

    public static string Post(Guid id, Guid blogId, string title) =>
        "{\"id\":" + GuidJson(id) + ",\"blogId\":" + GuidJson(blogId) + ",\"title\":" + StringJson(title) + "}";

    public static string ETag(string canonicalJson)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson));
        var base64Url = Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + base64Url + "\"";
    }

    private static string GuidJson(Guid value) => "\"" + value.ToString("D") + "\"";

    private static string StringJson(string value)
    {
        var normalized = value.Normalize(NormalizationForm.FormC);
        var sb = new StringBuilder(normalized.Length + 2);
        sb.Append('"');
        foreach (var c in normalized)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else
                        sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
        return sb.ToString();
    }
}
