// ApiControllerBase.cs
using Microsoft.AspNetCore.Mvc;

public abstract class ApiControllerBase : ControllerBase
{
    protected ObjectResult ProblemResult(int statusCode, string title, string? detail = null, string? etag = null)
    {
        if (etag is not null)
            Response.Headers.ETag = etag;
        return new ObjectResult(new ProblemDetails { Status = statusCode, Title = title, Detail = detail })
        {
            StatusCode = statusCode,
            ContentTypes = { "application/problem+json" }
        };
    }

    protected static bool ETagMatches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header))
            return false;
        foreach (var part in header.Split(','))
        {
            var candidate = part.Trim();
            if (candidate.StartsWith("W/", StringComparison.OrdinalIgnoreCase))
                candidate = candidate[2..];
            if (candidate == "*" || string.Equals(candidate, etag, StringComparison.Ordinal))
                return true;
        }
        return false;
    }
}
