// BlogsController.cs
using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/blogs")]
public class BlogsController : ApiControllerBase
{
    private readonly AppDbContext _db;

    public BlogsController(AppDbContext db) => _db = db;

    [HttpPost]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] BlogRequest request, CancellationToken ct)
    {
        if (request.Id == Guid.Empty || request.Name is null)
            return ProblemResult(StatusCodes.Status400BadRequest, "Invalid request",
                "id and name are required");

        var etag = CanonicalJson.ETag(CanonicalJson.Blog(request.Id, request.Name));
        var blog = new Blog
        {
            PublicId = request.Id,
            Name = request.Name,
            ETag = etag,
            CreateHash = etag
        };
        _db.Blogs.Add(blog);

        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.Entry(blog).State = EntityState.Detached;
            var existing = await _db.Blogs.IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(b => b.PublicId == request.Id, ct);
            if (existing is null)
                throw;
            if (existing.DeletedAt is not null)
                return ProblemResult(StatusCodes.Status410Gone, "Gone", "The blog has been deleted");
            if (existing.CreateHash == etag)
            {
                Response.Headers.ETag = existing.ETag;
                return Ok(new BlogResponse { Id = existing.PublicId, Name = existing.Name });
            }
            return ProblemResult(StatusCodes.Status409Conflict, "Conflict",
                "A blog with this id already exists");
        }

        Response.Headers.ETag = etag;
        return Created($"/api/blogs/{request.Id}",
            new BlogResponse { Id = blog.PublicId, Name = blog.Name });
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var blog = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null)
            return ProblemResult(StatusCodes.Status404NotFound, "Not found");
        if (blog.DeletedAt is not null)
            return ProblemResult(StatusCodes.Status410Gone, "Gone", "The blog has been deleted");
        if (ETagMatches(Request.Headers.IfNoneMatch.ToString(), blog.ETag))
            return new StatusCodeResult(StatusCodes.Status304NotModified);
        Response.Headers.ETag = blog.ETag;
        return Ok(new BlogResponse { Id = blog.PublicId, Name = blog.Name });
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromBody] BlogRequest request,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (request.Id == Guid.Empty || request.Id != id || request.Name is null)
            return ProblemResult(StatusCodes.Status400BadRequest, "Invalid request",
                "id must match the route and name is required");
        if (string.IsNullOrWhiteSpace(ifMatch))
            return ProblemResult(StatusCodes.Status428PreconditionRequired,
                "If-Match header is required");

        var blog = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null)
            return ProblemResult(StatusCodes.Status404NotFound, "Not found");
        if (blog.DeletedAt is not null)
            return ProblemResult(StatusCodes.Status410Gone, "Gone", "The blog has been deleted");

        var newEtag = CanonicalJson.ETag(CanonicalJson.Blog(id, request.Name));
        if (blog.ETag == newEtag)
            return NoContent();
        if (!ETagMatches(ifMatch, blog.ETag))
            return ProblemResult(StatusCodes.Status412PreconditionFailed,
                "Precondition failed", etag: blog.ETag);

        blog.Name = request.Name;
        blog.ETag = newEtag;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await _db.Blogs.IgnoreQueryFilters().AsNoTracking()
                .Where(b => b.PublicId == id).Select(b => b.ETag)
                .FirstOrDefaultAsync(ct);
            return ProblemResult(StatusCodes.Status412PreconditionFailed,
                "Precondition failed", etag: current ?? blog.ETag);
        }

        Response.Headers.ETag = newEtag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return ProblemResult(StatusCodes.Status428PreconditionRequired,
                "If-Match header is required");

        var blog = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null || blog.DeletedAt is not null)
            return NoContent();
        if (!ETagMatches(ifMatch, blog.ETag))
            return ProblemResult(StatusCodes.Status412PreconditionFailed,
                "Precondition failed", etag: blog.ETag);

        var now = DateTimeOffset.UtcNow;
        blog.DeletedAt = now;
        var posts = await _db.Posts.IgnoreQueryFilters()
            .Where(p => p.BlogId == id && p.DeletedAt == null)
            .ToListAsync(ct);
        foreach (var post in posts)
            post.DeletedAt = now;
        await _db.SaveChangesAsync(ct);
        return NoContent();
    }
}
