```csharp
using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace SupportTickets
{
    [ApiController]
    [Route("api/support-tickets")]
    public class SupportTicketsController : ControllerBase
    {
        private readonly TicketDbContext _db;

        public SupportTicketsController(TicketDbContext db)
        {
            _db = db;
        }

        // POST /api/support-tickets
        // Idempotent with respect to retries: if a ticket with the supplied id
        // already exists, the existing ticket is returned instead of creating a
        // duplicate or failing.
        [HttpPost]
        public async Task<IActionResult> Create([FromBody] Ticket request)
        {
            if (request == null)
            {
                return BadRequest();
            }

            var id = request.Id == Guid.Empty ? Guid.NewGuid() : request.Id;

            var existing = await _db.Tickets.FindAsync(id);
            if (existing != null)
            {
                return Ok(existing);
            }

            var ticket = new Ticket
            {
                Id = id,
                Subject = request.Subject ?? string.Empty,
                Priority = request.Priority,
                Escalated = request.Escalated,
                Category = request.Category ?? string.Empty,
                ViewCount = 0,
                LastViewedAt = null,
                Version = 0
            };

            _db.Tickets.Add(ticket);
            try
            {
                await _db.SaveChangesAsync();
            }
            catch (DbUpdateException)
            {
                // A concurrent request created the same id first (retry race).
                _db.Entry(ticket).State = EntityState.Detached;
                var raced = await _db.Tickets.FindAsync(id);
                if (raced != null)
                {
                    return Ok(raced);
                }
                throw;
            }

            return CreatedAtAction(nameof(GetById), new { id = ticket.Id }, ticket);
        }

        // GET /api/support-tickets/{id}
        // Records a view: increments ViewCount and updates LastViewedAt.
        [HttpGet("{id:guid}")]
        public async Task<IActionResult> GetById(Guid id)
        {
            var ticket = await _db.Tickets.FindAsync(id);
            if (ticket == null)
            {
                return NotFound();
            }

            ticket.ViewCount++;
            ticket.LastViewedAt = DateTime.UtcNow;

            try
            {
                await _db.SaveChangesAsync();
            }
            catch (DbUpdateException)
            {
                // Lost a concurrent write; reload and return the latest state.
                _db.Entry(ticket).State = EntityState.Detached;
                ticket = await _db.Tickets.FindAsync(id);
                if (ticket == null)
                {
                    return NotFound();
                }
            }

            return Ok(ticket);
        }

        // PUT /api/support-tickets/{id}
        // Full replacement of client-editable fields. ViewCount, LastViewedAt
        // and Version are server-maintained and are never taken from the body.
        [HttpPut("{id:guid}")]
        public async Task<IActionResult> Update(Guid id, [FromBody] Ticket request)
        {
            if (request == null)
            {
                return BadRequest();
            }

            var ticket = await _db.Tickets.FindAsync(id);
            if (ticket == null)
            {
                return NotFound();
            }

            ticket.Subject = request.Subject ?? string.Empty;
            ticket.Priority = request.Priority;
            ticket.Escalated = request.Escalated;
            ticket.Category = request.Category ?? string.Empty;
            // ViewCount and LastViewedAt intentionally preserved.
            ticket.Version++;

            try
            {
                await _db.SaveChangesAsync();
            }
            catch (DbUpdateConcurrencyException)
            {
                return Conflict();
            }
            catch (DbUpdateException)
            {
                return StatusCode(500);
            }

            return Ok(ticket);
        }

        // DELETE /api/support-tickets/{id}
        [HttpDelete("{id:guid}")]
        public async Task<IActionResult> Delete(Guid id)
        {
            var ticket = await _db.Tickets.FindAsync(id);
            if (ticket == null)
            {
                return NotFound();
            }

            _db.Tickets.Remove(ticket);
            await _db.SaveChangesAsync();

            return NoContent();
        }
    }
}
