**SupportTicketsController.cs**:

```csharp
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace SupportTickets;

[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly TicketDbContext _db;

    public SupportTicketsController(TicketDbContext db)
    {
        _db = db;
    }

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] CreateTicketRequest request)
    {
        var id = request.Id == Guid.Empty ? Guid.NewGuid() : request.Id;

        if (request.Id != Guid.Empty)
        {
            var existing = await FindExistingAsync(id);
            if (existing is not null)
                return ReplayOrConflict(existing, request);
        }

        var ticket = new Ticket
        {
            Id = id,
            Subject = request.Subject ?? string.Empty,
            Priority = request.Priority,
            Escalated = request.Escalated,
            Category = request.Category ?? string.Empty,
        };

        _db.Tickets.Add(ticket);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            // Concurrent insert with the same id (e.g. retried POST): treat as replay.
            _db.Entry(ticket).State = EntityState.Detached;
            var raced = await FindExistingAsync(id);
            if (raced is not null)
                return ReplayOrConflict(raced, request);
            throw;
        }

        return CreatedAtAction(nameof(GetById), new { id = ticket.Id }, ToResponse(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> GetById(Guid id)
    {
        var exists = await _db.Tickets.AnyAsync(t => t.Id == id);
        if (!exists)
            return NotFound();

        // Atomic increment so concurrent GETs never lose a view.
        var now = DateTime.UtcNow;
        await _db.Database.ExecuteSqlRawAsync(
            "UPDATE Tickets SET ViewCount = ViewCount + 1, LastViewedAt = {0} WHERE Id = {1}",
            now, id);

        var ticket = await _db.Tickets.AsNoTracking().FirstAsync(t => t.Id == id);
        return Ok(ToResponse(ticket));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] UpdateTicketRequest request)
    {
        var rows = await _db.Tickets
            .Where(t => t.Id == id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.Subject, request.Subject ?? string.Empty)
                .SetProperty(t => t.Priority, request.Priority)
                .SetProperty(t => t.Escalated, request.Escalated)
                .SetProperty(t => t.Category, request.Category ?? string.Empty));

        if (rows == 0)
            return NotFound();

        var ticket = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id);
        if (ticket is null)
            return NotFound();

        return Ok(ToResponse(ticket));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var rows = await _db.Tickets.Where(t => t.Id == id).ExecuteDeleteAsync();
        return rows == 0 ? NotFound() : NoContent();
    }

    private async Task<Ticket?> FindExistingAsync(Guid id) =>
        await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id);

    private IActionResult ReplayOrConflict(Ticket existing, CreateTicketRequest request)
    {
        var same = existing.Subject == (request.Subject ?? string.Empty)
            && existing.Priority == request.Priority
            && existing.Escalated == request.Escalated
            && existing.Category == (request.Category ?? string.Empty);

        return same
            ? Ok(ToResponse(existing))
            : Conflict(ToResponse(existing));
    }

    private static TicketResponse ToResponse(Ticket t) => new()
    {
        Id = t.Id,
        Subject = t.Subject,
        Priority = t.Priority,
        Escalated = t.Escalated,
        Category = t.Category,
        ViewCount = t.ViewCount,
        LastViewedAt = t.LastViewedAt,
    };
}
