        {
            _db = db;
        }

        [HttpPost]
        public async Task<IActionResult> Create([FromBody] Ticket ticket)
        {
            if (ticket == null || ticket.Id == Guid.Empty)
            {
                return BadRequest();
            }

            var existing = await _db.Tickets.FindAsync(ticket.Id);
            if (existing != null)
            {
                return Ok(existing);
            }

            ticket.ViewCount = 0;
            ticket.LastViewedAt = null;
            _db.Tickets.Add(ticket);
            try
            {
                await _db.SaveChangesAsync();
            }
            catch (DbUpdateException)
            {
                var raced = await _db.Tickets.FindAsync(ticket.Id);
                if (raced != null)
                {
                    return Ok(raced);
                }
                throw;
            }

            return CreatedAtAction(nameof(GetById), new { id = ticket.Id }, ticket);
        }

        [HttpGet("{id:guid}")]
        public async Task<IActionResult> GetById(Guid id)
        {
            var ticket = await _db.Tickets.FindAsync(id);
            if (ticket == null)
            {
                return NotFound();
            }

            ticket.ViewCount++;
            ticket.LastViewedAt = DateTime.UtcNow;
            await _db.SaveChangesAsync();

            return Ok(ticket);
        }

        [HttpPut("{id:guid}")]
        public async Task<IActionResult> Update(Guid id, [FromBody] Ticket ticket)
        {
            if (ticket == null || ticket.Id != id)
            {
                return BadRequest();
            }

            var existing = await _db.Tickets.FindAsync(id);
            if (existing == null)
            {
                return NotFound();
            }

            existing.Subject = ticket.Subject;
            existing.Priority = ticket.Priority;
            existing.Escalated = ticket.Escalated;
            existing.Category = ticket.Category;

            await _db.SaveChangesAsync();
            return Ok(existing);
        }

        [HttpDelete("{id:guid}")]
        public async Task<IActionResult> Delete(Guid id)
        {
            var existing = await _db.Tickets.FindAsync(id);
            if (existing == null)
            {
                return NotFound();
            }

            _db.Tickets.Remove(existing);
            await _db.SaveChangesAsync();
            return NoContent();
        }
    }
}
