using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace SupportTickets;

[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly TicketDbContext _db;

    public SupportTicketsController(TicketDbContext db)
    {
        _db = db;
    }

    [HttpPost]
    public async Task<ActionResult<Ticket>> Create(
        [FromBody] TicketRequest request,
        CancellationToken cancellationToken)
    {
        var subject = request.Subject;
        var category = request.Category;
        if (subject is null || category is null)
        {
            return BadRequest(new { message = "Subject and category are required." });
        }

        var id = request.Id == Guid.Empty ? Guid.NewGuid() : request.Id;

        var existing = await _db.Tickets
            .AsNoTracking()
            .FirstOrDefaultAsync(t => t.Id == id, cancellationToken);

        if (existing is not null)
        {
            return SameTicket(existing, request)
                ? CreatedAtAction(nameof(Get), new { id }, existing)
                : Conflict(new { message = "A ticket with this id already exists." });
        }

        var ticket = new Ticket
        {
            Id = id,
            Subject = subject,
            Priority = request.Priority,
            Escalated = request.Escalated,
            Category = category
        };

        _db.Tickets.Add(ticket);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();

            var raced = await _db.Tickets
                .AsNoTracking()
                .FirstOrDefaultAsync(t => t.Id == id, cancellationToken);

            if (raced is null)
            {
                throw;
            }

            return SameTicket(raced, request)
                ? CreatedAtAction(nameof(Get), new { id }, raced)
                : Conflict(new { message = "A ticket with this id already exists." });
        }

        return CreatedAtAction(nameof(Get), new { id }, ticket);
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<Ticket>> Get(Guid id, CancellationToken cancellationToken)
    {
        var viewedAt = DateTime.UtcNow;

        var updated = await _db.Tickets
            .Where(t => t.Id == id)
            .ExecuteUpdateAsync(
                setters => setters
                    .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                    .SetProperty(t => t.LastViewedAt, (DateTime?)viewedAt),
                cancellationToken);

        if (updated == 0)
        {
            return NotFound();
        }

        var ticket = await _db.Tickets
            .AsNoTracking()
            .FirstOrDefaultAsync(t => t.Id == id, cancellationToken);

        return ticket is null ? NotFound() : Ok(ticket);
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<Ticket>> Update(
        Guid id,
        [FromBody] TicketRequest request,
        CancellationToken cancellationToken)
    {
        var subject = request.Subject;
        var category = request.Category;
        if (subject is null || category is null)
        {
            return BadRequest(new { message = "Subject and category are required." });
        }

        var updated = await _db.Tickets
            .Where(t => t.Id == id)
            .ExecuteUpdateAsync(
                setters => setters
                    .SetProperty(t => t.Subject, subject)
                    .SetProperty(t => t.Priority, request.Priority)
                    .SetProperty(t => t.Escalated, request.Escalated)
                    .SetProperty(t => t.Category, category),
                cancellationToken);

        if (updated == 0)
        {
            return NotFound();
        }

        var ticket = await _db.Tickets
            .AsNoTracking()
            .FirstOrDefaultAsync(t => t.Id == id, cancellationToken);

        return ticket is null ? NotFound() : Ok(ticket);
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken cancellationToken)
    {
        var deleted = await _db.Tickets
            .Where(t => t.Id == id)
            .ExecuteDeleteAsync(cancellationToken);

        return deleted == 0 ? NotFound() : NoContent();
    }

    private static bool SameTicket(Ticket ticket, TicketRequest request)
    {
        return ticket.Subject == request.Subject
            && ticket.Priority == request.Priority
            && ticket.Escalated == request.Escalated
            && ticket.Category == request.Category;
    }
}
