using Microsoft.EntityFrameworkCore;

namespace SupportTickets;

public class TicketDbContext : DbContext
{
    public TicketDbContext(DbContextOptions<TicketDbContext> options) : base(options)
    {
    }

    public DbSet<Ticket> Tickets => Set<Ticket>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Ticket>(entity =>
        {
            entity.ToTable("Tickets");
            entity.HasKey(t => t.Id);
            entity.Property(t => t.Subject).IsRequired();
            entity.Property(t => t.Category).IsRequired();
            // Shadow concurrency token: not part of the entity, so it never
            // appears in JSON, but lets EF detect concurrent modifications.
            entity.Property<int>("RowVersion").IsConcurrencyToken();
        });
    }

    public static void IncrementVersion(DbContext db, Ticket ticket)
    {
        var entry = db.Entry(ticket);
        var prop = entry.Property("RowVersion");
        prop.CurrentValue = (int)(prop.OriginalValue ?? 0) + 1;
    }
}
