using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace SupportTickets;

public class TicketRequest
{
    public Guid? Id { get; set; }
    public string? Subject { get; set; }
    public int Priority { get; set; }
    public bool Escalated { get; set; }
    public string? Category { get; set; }
}

[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly TicketDbContext _db;
    private readonly IServiceProvider _services;

    public SupportTicketsController(TicketDbContext db, IServiceProvider services)
    {
        _db = db;
        _services = services;
    }

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] TicketRequest request)
    {
        if (request.Id is Guid id && id != Guid.Empty)
        {
            var existing = await _db.Tickets.FindAsync(id);
            if (existing is not null)
            {
                return CreatedAtAction(nameof(GetById), new { id }, existing);
            }
        }

        var ticket = new Ticket
        {
            Id = request.Id is Guid rid && rid != Guid.Empty ? rid : Guid.NewGuid(),
            Subject = request.Subject ?? string.Empty,
            Priority = request.Priority,
            Escalated = request.Escalated,
            Category = request.Category ?? string.Empty
        };

        _db.Tickets.Add(ticket);
        try
        {
            TicketDbContext.IncrementVersion(_db, ticket);
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            // Concurrent insert of the same id (e.g. a retried POST).
            _db.Entry(ticket).State = EntityState.Detached;
            var existing = await _db.Tickets.FindAsync(ticket.Id);
            if (existing is not null)
            {
                return CreatedAtAction(nameof(GetById), new { id = existing.Id }, existing);
            }
            throw;
        }

        return CreatedAtAction(nameof(GetById), new { id = ticket.Id }, ticket);
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> GetById(Guid id)
    {
        var updated = await _db.Tickets
            .Where(t => t.Id == id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, DateTime.UtcNow));

        if (updated == 0)
        {
            return NotFound();
        }

        var ticket = await _db.Tickets.FindAsync(id);
        return ticket is null ? NotFound() : Ok(ticket);
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] TicketRequest request)
    {
        var ticket = await _db.Tickets.FindAsync(id);
        if (ticket is null)
        {
            return NotFound();
        }

        Apply(ticket, request);
        TicketDbContext.IncrementVersion(_db, ticket);

        try
        {
            await _db.SaveChangesAsync();
            return Ok(ticket);
        }
        catch (DbUpdateConcurrencyException)
        {
            // Another writer modified the row between our read and write.
            // Reload fresh state in a new scope and reapply once.
            using var scope = _services.CreateAsyncScope();
            var db = scope.ServiceProvider.GetRequiredService<TicketDbContext>();
            var fresh = await db.Tickets.FindAsync(id);
            if (fresh is null)
            {
                return NotFound();
            }
            Apply(fresh, request);
            TicketDbContext.IncrementVersion(db, fresh);
            try
            {
                await db.SaveChangesAsync();
                return Ok(fresh);
            }
            catch (DbUpdateConcurrencyException)
            {
                return Conflict();
            }
        }
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var ticket = await _db.Tickets.FindAsync(id);
        if (ticket is null)
        {
            return NotFound();
        }

        _db.Tickets.Remove(ticket);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }
        return NoContent();
    }

    private static void Apply(Ticket ticket, TicketRequest request)
    {
        ticket.Subject = request.Subject ?? string.Empty;
        ticket.Priority = request.Priority;
        ticket.Escalated = request.Escalated;
        ticket.Category = request.Category ?? string.Empty;
    }
}
