using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly SupportTicketDbContext _db;

    public SupportTicketsController(SupportTicketDbContext db)
    {
        _db = db;
    }

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] TicketRequest request)
    {
        if (request.Subject is null || request.Category is null)
        {
            return BadRequest(new { error = "subject and category are required" });
        }

        var subject = request.Subject;
        var category = request.Category;
        var priority = request.Priority ?? 0;
        var escalated = request.Escalated ?? false;

        var suppliedId = request.Id;
        if (suppliedId == Guid.Empty)
        {
            suppliedId = null;
        }

        if (suppliedId is null)
        {
            var created = new Ticket
            {
                Id = Guid.NewGuid(),
                Subject = subject,
                Priority = priority,
                Escalated = escalated,
                Category = category
            };

            _db.Tickets.Add(created);
            await _db.SaveChangesAsync();

            return CreatedAtAction(nameof(GetById), new { id = created.Id }, ToResponse(created));
        }

        var ticketId = suppliedId.Value;
        var existing = await _db.Tickets.FindAsync(ticketId);
        if (existing is not null)
        {
            return SameClientFields(existing, subject, priority, escalated, category)
                ? Ok(ToResponse(existing))
                : Conflict(new { error = "A ticket with this id already exists" });
        }

        var ticket = new Ticket
        {
            Id = ticketId,
            Subject = subject,
            Priority = priority,
            Escalated = escalated,
            Category = category
        };

        _db.Tickets.Add(ticket);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();
            var raced = await _db.Tickets.FindAsync(ticketId);
            if (raced is not null)
            {
                return SameClientFields(raced, subject, priority, escalated, category)
                    ? Ok(ToResponse(raced))
                    : Conflict(new { error = "A ticket with this id already exists" });
            }

            throw;
        }

        return CreatedAtAction(nameof(GetById), new { id = ticket.Id }, ToResponse(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> GetById(Guid id)
    {
        var now = DateTime.UtcNow;
        var affected = await _db.Database.ExecuteSqlInterpolatedAsync($"""
            UPDATE "Tickets"
            SET "ViewCount" = "ViewCount" + 1,
                "LastViewedAt" = {now}
            WHERE "Id" = {id}
            """);

        if (affected == 0)
        {
            return NotFound();
        }

        var ticket = await _db.Tickets.FindAsync(id);
        return ticket is null ? NotFound() : Ok(ToResponse(ticket));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] TicketRequest request)
    {
        if (request.Subject is null || request.Category is null)
        {
            return BadRequest(new { error = "subject and category are required" });
        }

        if (request.Id.HasValue &&
            request.Id.Value != Guid.Empty &&
            request.Id.Value != id)
        {
            return BadRequest(new { error = "id in the body does not match the route id" });
        }

        var ticket = await _db.Tickets.FindAsync(id);
        if (ticket is null)
        {
            return NotFound();
        }

        ticket.Subject = request.Subject;
        ticket.Priority = request.Priority ?? 0;
        ticket.Escalated = request.Escalated ?? false;
        ticket.Category = request.Category;

        await _db.SaveChangesAsync();
        return Ok(ToResponse(ticket));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var ticket = await _db.Tickets.FindAsync(id);
        if (ticket is null)
        {
            return NotFound();
        }

        _db.Tickets.Remove(ticket);
        await _db.SaveChangesAsync();
        return NoContent();
    }

    private static bool SameClientFields(
        Ticket ticket,
        string subject,
        int priority,
        bool escalated,
        string category)
    {
        return ticket.Subject == subject
            && ticket.Priority == priority
            && ticket.Escalated == escalated
            && ticket.Category == category;
    }

    private static TicketResponse ToResponse(Ticket ticket)
    {
        return new TicketResponse
        {
            Id = ticket.Id,
            Subject = ticket.Subject,
            Priority = ticket.Priority,
            Escalated = ticket.Escalated,
            Category = ticket.Category,
            ViewCount = ticket.ViewCount,
            LastViewedAt = ticket.LastViewedAt
        };
