using System.ComponentModel.DataAnnotations;
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

namespace SupportTickets;

public sealed class TicketRequest
{
    public Guid Id { get; set; }

    [Required]
    public string? Subject { get; set; }

    public int Priority { get; set; }

    public bool Escalated { get; set; }

    [Required]
    public string? Category { get; set; }
}

public sealed class TicketResponse
{
    public Guid Id { get; set; }
    public string Subject { get; set; } = string.Empty;
    public int Priority { get; set; }
    public bool Escalated { get; set; }
    public string Category { get; set; } = string.Empty;
}

public sealed class Ticket
{
    public int Id { get; set; }
    public Guid PublicId { get; set; }
    public string Subject { get; set; } = string.Empty;
    public int Priority { get; set; }
    public bool Escalated { get; set; }
    public string Category { get; set; } = string.Empty;
    public string ETag { get; set; } = string.Empty;
    public string CreateRequestHash { get; set; } = string.Empty;
    public int ViewCount { get; set; }
    public DateTime? LastViewedAt { get; set; }
    public DateTime? DeletedAt { get; set; }
}

public static class Canonicalizer
{
    public static string ComputeHash(Guid id, string subject, int priority, bool escalated, string category)
    {
        var canonical = BuildCanonicalJson(id, subject, priority, escalated, category);
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return Base64UrlEncode(bytes);
    }

    public static string QuoteEtag(string hash) => "\"" + hash + "\"";

    private static string BuildCanonicalJson(Guid id, string subject, int priority, bool escalated, string category)
    {
        var sb = new StringBuilder(160);
        sb.Append("{\"id\":\"").Append(id.ToString("D").ToLowerInvariant()).Append("\",\"subject\":\"");
        AppendJsonString(sb, subject);
        sb.Append("\",\"priority\":").Append(priority.ToString(CultureInfo.InvariantCulture));
        sb.Append(",\"escalated\":").Append(escalated ? "true" : "false");
        sb.Append(",\"category\":\"");
        AppendJsonString(sb, category);
        sb.Append("\"}");
        return sb.ToString();
    }

    private static void AppendJsonString(StringBuilder sb, string value)
    {
        var normalized = value.Normalize(NormalizationForm.FormC);
        foreach (var c in normalized)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        sb.Append("\\u").Append(((int)c).ToString("x2", CultureInfo.InvariantCulture));
                    else
                        sb.Append(c);
                    break;
            }
        }
    }

    private static string Base64UrlEncode(byte[] bytes) =>
        Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
}
