using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ModelBinding;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

namespace SupportTickets;

[ApiController]
[Route("api/support-tickets")]
[Produces("application/json")]
public sealed class SupportTicketsController : ControllerBase
{
    private readonly AppDbContext _db;

    public SupportTicketsController(AppDbContext db) => _db = db;

    [HttpPost]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create(
        [FromBody(EmptyBodyBehavior = EmptyBodyBehavior.Disallow)] TicketRequest request,
        CancellationToken cancellationToken)
    {
        if (request is null || request.Id == Guid.Empty || request.Subject is null || request.Category is null)
            return Problem(statusCode: StatusCodes.Status400BadRequest, title: "Bad Request",
                           detail: "A valid id, subject and category are required.");

        var subject = request.Subject;
        var category = request.Category;
        var hash = Canonicalizer.ComputeHash(request.Id, subject, request.Priority, request.Escalated, category);
        var etag = Canonicalizer.QuoteEtag(hash);

        for (var attempt = 0; attempt < 2; attempt++)
        {
            var ticket = new Ticket
            {
                PublicId = request.Id,
                Subject = subject,
                Priority = request.Priority,
                Escalated = request.Escalated,
                Category = category,
                ETag = etag,
                CreateRequestHash = hash,
                ViewCount = 0,
                LastViewedAt = null,
                DeletedAt = null
            };

            _db.Tickets.Add(ticket);
            try
            {
                await _db.SaveChangesAsync(cancellationToken);
                Response.Headers.ETag = etag;
                return Created($"/api/support-tickets/{request.Id}", ToResponse(ticket));
            }
            catch (DbUpdateException ex) when (IsUniqueViolation(ex))
            {
                _db.ChangeTracker.Clear();
                var existing = await _db.Tickets
                    .IgnoreQueryFilters()
                    .FirstOrDefaultAsync(t => t.PublicId == request.Id, cancellationToken);

                if (existing is null)
                    continue;

                if (existing.DeletedAt is not null)
                    return Problem(statusCode: StatusCodes.Status410Gone, title: "Gone",
                                   detail: "The ticket has been deleted.");

                if (existing.CreateRequestHash == hash)
                {
                    Response.Headers.ETag = existing.ETag;
                    return Ok(ToResponse(existing));
                }

                return Problem(statusCode: StatusCodes.Status409Conflict, title: "Conflict",
                               detail: "A ticket with this id already exists with different content.");
            }
        }

        throw new InvalidOperationException("Unable to create ticket.");
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(
        Guid id,
        [FromHeader(Name = "If-None-Match")] string? ifNoneMatch,
        CancellationToken cancellationToken)
    {
        var ticket = await _db.Tickets
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);

        if (ticket is null)
            return Problem(statusCode: StatusCodes.Status404NotFound, title: "Not Found",
                           detail: "The ticket was not found.");

        if (ticket.DeletedAt is not null)
            return Problem(statusCode: StatusCodes.Status410Gone, title: "Gone",
                           detail: "The ticket has been deleted.");

        Response.Headers.ETag = ticket.ETag;
        await IncrementViewCountAsync(id, cancellationToken);

        if (MatchesETag(ifNoneMatch, ticket.ETag))
            return StatusCode(StatusCodes.Status304NotModified);

        return Ok(ToResponse(ticket));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(
        Guid id,
        [FromBody(EmptyBodyBehavior = EmptyBodyBehavior.Disallow)] TicketRequest request,
        [FromHeader(Name = "If-Match")] [Required] string ifMatch,
        CancellationToken cancellationToken)
    {
        if (request is null || request.Subject is null || request.Category is null || request.Id != id)
            return Problem(statusCode: StatusCodes.Status400BadRequest, title: "Bad Request",
                           detail: "The body must contain a valid ticket whose id matches the route id.");

        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(statusCode: StatusCodes.Status428PreconditionRequired, title: "Precondition Required",
                           detail: "The If-Match header is required.");

        var subject = request.Subject;
        var category = request.Category;
        var hash = Canonicalizer.ComputeHash(request.Id, subject, request.Priority, request.Escalated, category);
        var newEtag = Canonicalizer.QuoteEtag(hash);

        var ticket = await _db.Tickets
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);

        if (ticket is null)
            return Problem(statusCode: StatusCodes.Status404NotFound, title: "Not Found",
                           detail: "The ticket was not found.");

        if (ticket.DeletedAt is not null)
            return Problem(statusCode: StatusCodes.Status410Gone, title: "Gone",
                           detail: "The ticket has been deleted.");

        if (ticket.ETag == newEtag)
        {
            Response.Headers.ETag = ticket.ETag;
            return NoContent();
        }

        if (!MatchesETag(ifMatch, ticket.ETag))
        {
            Response.Headers.ETag = ticket.ETag;
            return Problem(statusCode: StatusCodes.Status412PreconditionFailed, title: "Precondition Failed",
                           detail: "The If-Match header does not match the current ticket.");
        }

        ticket.Subject = subject;
        ticket.Priority = request.Priority;
        ticket.Escalated = request.Escalated;
        ticket.Category = category;
        ticket.ETag = newEtag;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
            Response.Headers.ETag = newEtag;
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.ChangeTracker.Clear();
            var current = await _db.Tickets
                .IgnoreQueryFilters()
                .Where(t => t.PublicId == id)
                .Select(t => new { t.ETag, t.DeletedAt })
                .FirstOrDefaultAsync(cancellationToken);

            if (current is null)
                return Problem(statusCode: StatusCodes.Status404NotFound, title: "Not Found",
                               detail: "The ticket was not found.");

            if (current.DeletedAt is not null)
                return Problem(statusCode: StatusCodes.Status410Gone, title: "Gone",
                               detail: "The ticket has been deleted.");

            Response.Headers.ETag = current.ETag;
            return Problem(statusCode: StatusCodes.Status412PreconditionFailed, title: "Precondition Failed",
                           detail: "The If-Match header does not match the current ticket.");
        }
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [FromHeader(Name = "If-Match")] [Required] string ifMatch,
        CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(statusCode: StatusCodes.Status428PreconditionRequired, title: "Precondition Required",
                           detail: "The If-Match header is required.");

        for (var attempt = 0; attempt < 5; attempt++)
        {
            _db.ChangeTracker.Clear();
            var ticket = await _db.Tickets
                .IgnoreQueryFilters()
                .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);

            if (ticket is null || ticket.DeletedAt is not null)
                return NoContent();

            if (!MatchesETag(ifMatch, ticket.ETag))
            {
                Response.Headers.ETag = ticket.ETag;
                return Problem(statusCode: StatusCodes.Status412PreconditionFailed, title: "Precondition Failed",
                               detail: "The If-Match header does not match the current ticket.");
            }

            ticket.DeletedAt = DateTime.UtcNow;
            try
            {
                await _db.SaveChangesAsync(cancellationToken);
                return NoContent();
            }
            catch (DbUpdateConcurrencyException)
            {
                continue;
            }
        }

        _db.ChangeTracker.Clear();
        var current = await _db.Tickets
            .IgnoreQueryFilters()
            .Where(t => t.PublicId == id)
            .Select(t => new { t.ETag, t.DeletedAt })
            .FirstOrDefaultAsync(cancellationToken);

        if (current is null || current.DeletedAt is not null)
            return NoContent();

        Response.Headers.ETag = current.ETag;
        return Problem(statusCode: StatusCodes.Status412PreconditionFailed, title: "Precondition Failed",
                       detail: "The If-Match header does not match the current ticket.");
    }

    private async Task IncrementViewCountAsync(Guid publicId, CancellationToken cancellationToken)
    {
        DateTime? now = DateTime.UtcNow;
        await _db.Tickets
            .Where(t => t.PublicId == publicId && t.DeletedAt == null)
            .ExecuteUpdateAsync(
                s => s.SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                      .SetProperty(t => t.LastViewedAt, now),
                cancellationToken);
    }

    private static TicketResponse ToResponse(Ticket ticket) => new()
    {
        Id = ticket.PublicId,
        Subject = ticket.Subject,
        Priority = ticket.Priority,
        Escalated = ticket.Escalated,
        Category = ticket.Category
    };

    private static bool MatchesETag(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header))
            return false;

        foreach (var part in header.Split(','))
        {
            var value = part.Trim();
            if (value == "*" || value == etag)
                return true;
        }

        return false;
    }

    private static bool IsUniqueViolation(DbUpdateException ex)
    {
        for (Exception? e = ex; e is not null; e = e.InnerException)
        {
            if (e is SqliteException sqlite &&
                (sqlite.SqliteErrorCode == 19 || sqlite.SqliteErrorCode == 1555 || sqlite.SqliteErrorCode == 2067))
                return true;

            if (e.Message.Contains("UNIQUE constraint failed", StringComparison.OrdinalIgnoreCase))
                return true;
        }

        return false;
    }
}
