// TicketCanonical.cs
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public static class TicketCanonical
{
    public static string Build(Guid id, string subject, int priority, bool escalated, string category)
    {
        var sb = new StringBuilder(256);
        sb.Append("{\"id\":\"").Append(id.ToString("D")).Append("\",");
        sb.Append("\"subject\":").Append(JsonString(subject)).Append(',');
        sb.Append("\"priority\":").Append(priority.ToString(CultureInfo.InvariantCulture)).Append(',');
        sb.Append("\"escalated\":").Append(escalated ? "true" : "false").Append(',');
        sb.Append("\"category\":").Append(JsonString(category)).Append('}');
        return sb.ToString();
    }

    public static string ComputeEtag(string canonical)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_');
    }

    public static string EtagOf(Guid id, string subject, int priority, bool escalated, string category)
        => ComputeEtag(Build(id, subject, priority, escalated, category));

    public static string QuoteEtag(string etag) => "\"" + etag + "\"";

    private static string JsonString(string value)
    {
        var sb = new StringBuilder(value.Length + 2);
        sb.Append('"');
        foreach (var c in value.Normalize())
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else
                        sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
        return sb.ToString();
    }

    public static string NormalizeTag(string? value)
    {
        if (string.IsNullOrWhiteSpace(value)) return "";
        var v = value.Trim();
        if (v.StartsWith("W/", StringComparison.OrdinalIgnoreCase)) v = v[2..].Trim();
        if (v.Length >= 2 && v[0] == '"' && v[^1] == '"') v = v[1..^1];
        return v;
    }

    public static bool TagMatches(string? headerValue, string etag)
        => headerValue != null && NormalizeTag(headerValue) == etag;

    public static bool IfNoneMatchMatches(string? header, string etag)
    {
        if (string.IsNullOrEmpty(header)) return false;
        foreach (var part in header.Split(','))
        {
            var p = part.Trim();
            if (p == "*" || NormalizeTag(p) == etag) return true;
        }
        return false;
    }
}
