        if (ticket.DeletedAt != null)
            return Problem(StatusCodes.Status410Gone, "Gone", "The ticket has been deleted.");

        var newEtag = TicketCanonical.EtagOf(id, body.Subject, body.Priority, body.Escalated, body.Category);

        if (newEtag == ticket.ETag)
        {
            Response.Headers.ETag = TicketCanonical.QuoteEtag(newEtag);
            return NoContent();
        }

        var matcher = ifMatch.Trim();
        if (matcher != "*" && !TicketCanonical.TagMatches(ifMatch, ticket.ETag))
        {
            Response.Headers.ETag = TicketCanonical.QuoteEtag(ticket.ETag);
            return Problem(StatusCodes.Status412PreconditionFailed, "Precondition Failed", "The If-Match precondition failed.");
        }

        ticket.Subject = body.Subject;
        ticket.Priority = body.Priority;
        ticket.Escalated = body.Escalated;
        ticket.Category = body.Category;
        ticket.ETag = newEtag;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.Entry(ticket).State = EntityState.Detached;
            var current = await _db.Tickets
                .IgnoreQueryFilters()
                .AsNoTracking()
                .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);
            if (current?.DeletedAt != null)
                return Problem(StatusCodes.Status410Gone, "Gone", "The ticket has been deleted.");
            if (current != null)
                Response.Headers.ETag = TicketCanonical.QuoteEtag(current.ETag);
            return Problem(StatusCodes.Status412PreconditionFailed, "Precondition Failed", "The If-Match precondition failed.");
        }

        Response.Headers.ETag = TicketCanonical.QuoteEtag(newEtag);
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(StatusCodes.Status428PreconditionRequired, "Precondition Required", "If-Match header is required.");

        var ticket = await _db.Tickets
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);

        if (ticket == null || ticket.DeletedAt != null)
            return NoContent();

        var matcher = ifMatch.Trim();
        if (matcher != "*" && !TicketCanonical.TagMatches(ifMatch, ticket.ETag))
        {
            Response.Headers.ETag = TicketCanonical.QuoteEtag(ticket.ETag);
            return Problem(StatusCodes.Status412PreconditionFailed, "Precondition Failed", "The If-Match precondition failed.");
        }

        ticket.DeletedAt = DateTime.UtcNow;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.Entry(ticket).State = EntityState.Detached;
            var current = await _db.Tickets
                .IgnoreQueryFilters()
                .AsNoTracking()
                .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);
            if (current == null || current.DeletedAt != null)
                return NoContent();
            Response.Headers.ETag = TicketCanonical.QuoteEtag(current.ETag);
            return Problem(StatusCodes.Status412PreconditionFailed, "Precondition Failed", "The If-Match precondition failed.");
        }

        return NoContent();
    }

    private static bool IsUniqueViolation(DbUpdateException ex)
        => ex.InnerException is SqliteException sqlite
            && (sqlite.SqliteExtendedErrorCode == 1555 || sqlite.SqliteExtendedErrorCode == 2067);

    private static TicketResponse ToResponse(Ticket t)
        => new(t.PublicId, t.Subject, t.Priority, t.Escalated, t.Category);
