// CanonicalJson.cs
using System.Security.Cryptography;
using System.Text;

internal static class CanonicalJson
{
    public static string Blog(Guid id, string? name)
    {
        var sb = new StringBuilder(64);
        sb.Append("{\"id\":");
        AppendGuid(sb, id);
        sb.Append(",\"name\":");
        AppendString(sb, name);
        sb.Append('}');
        return sb.ToString();
    }

    public static string Post(Guid id, Guid blogId, string? title)
    {
        var sb = new StringBuilder(96);
        sb.Append("{\"id\":");
        AppendGuid(sb, id);
        sb.Append(",\"blogId\":");
        AppendGuid(sb, blogId);
        sb.Append(",\"title\":");
        AppendString(sb, title);
        sb.Append('}');
        return sb.ToString();
    }

    private static void AppendGuid(StringBuilder sb, Guid value)
    {
        sb.Append('"').Append(value.ToString("D")).Append('"');
    }

    private static void AppendString(StringBuilder sb, string? value)
    {
        sb.Append('"');
        foreach (var c in (value ?? string.Empty).Normalize(NormalizationForm.FormC))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        sb.Append("\\u").Append(((int)c).ToString("x4", System.Globalization.CultureInfo.InvariantCulture));
                    else
                        sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }
}

internal static class Tags
{
    public static string Blog(Guid id, string? name) => Hash(CanonicalJson.Blog(id, name));
    public static string Post(Guid id, Guid blogId, string? title) => Hash(CanonicalJson.Post(id, blogId, title));

    public static string Quote(string etag) => $"\"{etag}\"";

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var part in header.Split(','))
        {
            var v = part.Trim();
            if (v == "*") return true;
            if (v.StartsWith("W/", StringComparison.Ordinal)) v = v[2..].TrimStart();
            if (v.Length >= 2 && v[0] == '"' && v[^1] == '"') v = v[1..^1];
            if (string.Equals(v, etag, StringComparison.Ordinal)) return true;
        }
        return false;
    }

    private static string Hash(string canonical)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
    }
}
