// BlogsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/blogs")]
public class BlogsController : ControllerBase
{
    private readonly AppDbContext _db;

    public BlogsController(AppDbContext db) => _db = db;

    [HttpPost]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] BlogRequest request, CancellationToken ct)
    {
        if (request.Id is not { } id || id == Guid.Empty)
            return Problem("A valid 'id' is required in the request body.", statusCode: StatusCodes.Status400BadRequest);

        var name = request.Name ?? string.Empty;
        var etag = Tags.Blog(id, name);

        for (var attempt = 1; ; attempt++)
        {
            _db.Blogs.Add(new Blog { PublicId = id, Name = name, ETag = etag, CreateHash = etag });
            try
            {
                await _db.SaveChangesAsync(ct);
                break;
            }
            catch (DbUpdateException)
            {
                _db.ChangeTracker.Clear();
                var existing = await _db.Blogs.IgnoreQueryFilters()
                    .FirstOrDefaultAsync(b => b.PublicId == id, ct);
                if (existing is not null)
                    return ClassifyConflict(existing, etag);
                if (attempt == 2) throw;
            }
        }

        Response.Headers.Location = $"/api/blogs/{id}";
        Response.Headers.ETag = Tags.Quote(etag);
        return Created($"/api/blogs/{id}", new BlogResponse(id, name));
    }

    private IActionResult ClassifyConflict(Blog existing, string requestEtag)
    {
        if (existing.DeletedAt is not null)
            return Problem("The resource has been deleted.", statusCode: StatusCodes.Status410Gone);
        if (existing.CreateHash == requestEtag)
        {
            Response.Headers.Location = $"/api/blogs/{existing.PublicId}";
            Response.Headers.ETag = Tags.Quote(existing.ETag);
            return Ok(new BlogResponse(existing.PublicId, existing.Name));
        }
        return Problem("A resource with this id already exists.", statusCode: StatusCodes.Status409Conflict);
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, [FromHeader(Name = "If-None-Match")] string? ifNoneMatch, CancellationToken ct)
    {
        var blog = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null)
            return Problem("The resource was not found.", statusCode: StatusCodes.Status404NotFound);
        if (blog.DeletedAt is not null)
            return Problem("The resource has been deleted.", statusCode: StatusCodes.Status410Gone);

        Response.Headers.ETag = Tags.Quote(blog.ETag);
        if (Tags.Matches(ifNoneMatch, blog.ETag))
            return StatusCode(StatusCodes.Status304NotModified);
        return Ok(new BlogResponse(blog.PublicId, blog.Name));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromBody] BlogRequest request,
        [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken ct)
    {
        if (request.Id != id)
            return Problem("The body 'id' must equal the route id.", statusCode: StatusCodes.Status400BadRequest);
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem("The If-Match header is required.", statusCode: StatusCodes.Status428PreconditionRequired);

        var blog = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null)
            return Problem("The resource was not found.", statusCode: StatusCodes.Status404NotFound);
        if (blog.DeletedAt is not null)
            return Problem("The resource has been deleted.", statusCode: StatusCodes.Status410Gone);

        var name = request.Name ?? string.Empty;
        var etag = Tags.Blog(id, name);
        if (blog.ETag == etag)
        {
            Response.Headers.ETag = Tags.Quote(etag);
            return NoContent();
        }
        if (!Tags.Matches(ifMatch, blog.ETag))
            return PreconditionFailed(blog.ETag);

        blog.Name = name;
        blog.ETag = etag;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();
            var current = await CurrentEtag(id, ct);
            return PreconditionFailed(current);
        }

        Response.Headers.ETag = Tags.Quote(etag);
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem("The If-Match header is required.", statusCode: StatusCodes.Status428PreconditionRequired);

        var blog = await _db.Blogs.IgnoreQueryFilters()
            .FirstOrDefaultAsync(b => b.PublicId == id, ct);
        if (blog is null || blog.DeletedAt is not null)
            return NoContent();
        if (!Tags.Matches(ifMatch, blog.ETag))
            return PreconditionFailed(blog.ETag);

        var now = DateTime.UtcNow;
        blog.DeletedAt = now;
        var posts = await _db.Posts.IgnoreQueryFilters()
            .Where(p => p.BlogPublicId == id && p.DeletedAt == null)
            .ToListAsync(ct);
        foreach (var post in posts)
            post.DeletedAt = now;

        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();
            return PreconditionFailed(await CurrentEtag(id, ct));
        }
        return NoContent();
    }

    private async Task<string> CurrentEtag(Guid id, CancellationToken ct)
    {
        var etag = await _db.Blogs.IgnoreQueryFilters()
            .Where(b => b.PublicId == id)
            .Select(b => b.ETag)
            .FirstOrDefaultAsync(ct);
        return etag ?? string.Empty;
    }

    private ObjectResult PreconditionFailed(string currentEtag)
    {
        Response.Headers.ETag = Tags.Quote(currentEtag);
        return Problem("The resource was modified.", statusCode: StatusCodes.Status412PreconditionFailed);
    }
}
