    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromBody] PostRequest request,
        [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken ct)
    {
        if (request.Id != id || request.BlogId is null)
            return Problem("The body 'id' must equal the route id and 'blogId' is required.", statusCode: StatusCodes.Status400BadRequest);
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem("The If-Match header is required.", statusCode: StatusCodes.Status428PreconditionRequired);

        var post = await _db.Posts.IgnoreQueryFilters()
            .FirstOrDefaultAsync(p => p.PublicId == id, ct);
        if (post is null)
            return Problem("The resource was not found.", statusCode: StatusCodes.Status404NotFound);
        if (post.DeletedAt is not null)
            return Problem("The resource has been deleted.", statusCode: StatusCodes.Status410Gone);
        if (request.BlogId != post.BlogPublicId)
            return Problem("A post cannot be moved to another blog.", statusCode: StatusCodes.Status409Conflict);

        var title = request.Title ?? string.Empty;
        var etag = Tags.Post(id, post.BlogPublicId, title);
        if (post.ETag == etag)
        {
            Response.Headers.ETag = Tags.Quote(etag);
            return NoContent();
        }
        if (!Tags.Matches(ifMatch, post.ETag))
            return PreconditionFailed(post.ETag);

        post.Title = title;
        post.ETag = etag;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();
            return PreconditionFailed(await CurrentEtag(id, ct));
        }

        Response.Headers.ETag = Tags.Quote(etag);
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem("The If-Match header is required.", statusCode: StatusCodes.Status428PreconditionRequired);

        var post = await _db.Posts.IgnoreQueryFilters()
            .FirstOrDefaultAsync(p => p.PublicId == id, ct);
        if (post is null || post.DeletedAt is not null)
            return NoContent();
        if (!Tags.Matches(ifMatch, post.ETag))
            return PreconditionFailed(post.ETag);

        post.DeletedAt = DateTime.UtcNow;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();
            return PreconditionFailed(await CurrentEtag(id, ct));
        }
        return NoContent();
    }

    private async Task<string> CurrentEtag(Guid id, CancellationToken ct)
    {
        var etag = await _db.Posts.IgnoreQueryFilters()
            .Where(p => p.PublicId == id)
            .Select(p => p.ETag)
            .FirstOrDefaultAsync(ct);
        return etag ?? string.Empty;
    }

    private ObjectResult PreconditionFailed(string currentEtag)
    {
        Response.Headers.ETag = Tags.Quote(currentEtag);
        return Problem("The resource was modified.", statusCode: StatusCodes.Status412PreconditionFailed);
    }
