// SupportTicketCanonical.cs
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public static class SupportTicketCanonical
{
    public static string Build(Guid id, string? subject, int priority, bool escalated, string? category)
    {
        var sb = new StringBuilder(160);
        sb.Append("{\"id\":");
        AppendJsonString(sb, id.ToString("D"));
        sb.Append(",\"subject\":");
        AppendJsonString(sb, subject);
        sb.Append(",\"priority\":").Append(priority.ToString(CultureInfo.InvariantCulture));
        sb.Append(",\"escalated\":").Append(escalated ? "true" : "false");
        sb.Append(",\"category\":");
        AppendJsonString(sb, category);
        sb.Append('}');
        return sb.ToString();
    }

    public static string Hash(string canonical)
    {
        var bytes = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        return Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
    }

    public static string Quote(string raw) => "\"" + raw + "\"";

    public static bool Matches(string? header, string rawEtag)
    {
        if (string.IsNullOrWhiteSpace(header))
        {
            return false;
        }

        foreach (var part in header.Split(','))
        {
            var token = part.Trim();
            if (token.StartsWith("W/", StringComparison.OrdinalIgnoreCase))
            {
                token = token[2..].Trim();
            }
            if (token == "*")
            {
                return true;
            }
            if (token.Length >= 2 && token[0] == '"' && token[^1] == '"')
            {
                token = token[1..^1];
            }
            if (string.Equals(token, rawEtag, StringComparison.Ordinal))
            {
                return true;
            }
        }
        return false;
    }

    private static void AppendJsonString(StringBuilder sb, string? value)
    {
        sb.Append('"');
        if (value is not null)
        {
            var normalized = value.Normalize(NormalizationForm.FormC);
            foreach (var c in normalized)
            {
                switch (c)
                {
                    case '"': sb.Append("\\\""); break;
                    case '\\': sb.Append("\\\\"); break;
                    case '\b': sb.Append("\\b"); break;
                    case '\f': sb.Append("\\f"); break;
                    case '\n': sb.Append("\\n"); break;
                    case '\r': sb.Append("\\r"); break;
                    case '\t': sb.Append("\\t"); break;
                    default:
                        if (c < ' ')
                        {
                            sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                        }
                        else
                        {
                            sb.Append(c);
                        }
                        break;
                }
            }
        }
        sb.Append('"');
    }
}
