using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/support-tickets")]
public sealed class SupportTicketsController : ControllerBase
{
    private readonly TicketDbContext _db;

    public SupportTicketsController(TicketDbContext db)
    {
        _db = db;
    }

    [HttpPost]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] TicketRequest request, CancellationToken cancellationToken)
    {
        if (request is null || request.Id == Guid.Empty)
        {
            return Problem(StatusCodes.Status400BadRequest, "Invalid request body.");
        }

        var subject = request.Subject ?? string.Empty;
        var category = request.Category ?? string.Empty;
        var canonical = SupportTicketCanonical.Build(request.Id, subject, request.Priority, request.Escalated, category);
        var etag = SupportTicketCanonical.Hash(canonical);

        var ticket = new Ticket
        {
            PublicId = request.Id,
            Subject = subject,
            Priority = request.Priority,
            Escalated = request.Escalated,
            Category = category,
            ETag = etag,
            CreateHash = etag
        };

        _db.Tickets.Add(ticket);
        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            _db.Entry(ticket).State = EntityState.Detached;
            var existing = await _db.Tickets
                .IgnoreQueryFilters()
                .FirstOrDefaultAsync(t => t.PublicId == request.Id, cancellationToken);

            if (existing is null)
            {
                throw;
            }
            if (existing.DeletedAt is not null)
            {
                return Problem(StatusCodes.Status410Gone, "The ticket has been deleted.");
            }
            if (!string.Equals(existing.CreateHash, etag, StringComparison.Ordinal))
            {
                return Problem(StatusCodes.Status409Conflict, "A ticket with this id already exists.");
            }

            Response.Headers.ETag = SupportTicketCanonical.Quote(existing.ETag);
            return Ok(ToResponse(existing));
        }

        Response.Headers.ETag = SupportTicketCanonical.Quote(etag);
        return CreatedAtAction(nameof(Get), new { id = ticket.PublicId }, ToResponse(ticket));
    }

    [HttpGet("{id}")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(
        Guid id,
        [FromHeader(Name = "If-None-Match")] string? ifNoneMatch,
        CancellationToken cancellationToken)
    {
        var ticket = await _db.Tickets
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);

        if (ticket is null)
        {
            return Problem(StatusCodes.Status404NotFound, "Ticket not found.");
        }
        if (ticket.DeletedAt is not null)
        {
            return Problem(StatusCodes.Status410Gone, "The ticket has been deleted.");
        }

        await _db.Tickets
            .Where(t => t.PublicId == id)
            .ExecuteUpdateAsync(
                s => s.SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                      .SetProperty(t => t.LastViewedAt, (DateTime?)DateTime.UtcNow),
                cancellationToken);

        Response.Headers.ETag = SupportTicketCanonical.Quote(ticket.ETag);
        if (SupportTicketCanonical.Matches(ifNoneMatch, ticket.ETag))
        {
            return StatusCode(StatusCodes.Status304NotModified);
        }

        return Ok(ToResponse(ticket));
    }

    [HttpPut("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(
        Guid id,
        [FromBody] TicketRequest request,
        [FromHeader(Name = "If-Match")] string ifMatch,
        CancellationToken cancellationToken)
    {
        if (request is null || request.Id == Guid.Empty || request.Id != id)
        {
            return Problem(StatusCodes.Status400BadRequest, "Invalid request body.");
        }
        if (string.IsNullOrWhiteSpace(ifMatch))
        {
            return Problem(StatusCodes.Status428PreconditionRequired, "The If-Match header is required.");
        }

        var ticket = await _db.Tickets
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);

        if (ticket is null)
        {
            return Problem(StatusCodes.Status404NotFound, "Ticket not found.");
        }
        if (ticket.DeletedAt is not null)
        {
            return Problem(StatusCodes.Status410Gone, "The ticket has been deleted.");
        }

        var subject = request.Subject ?? string.Empty;
        var category = request.Category ?? string.Empty;
        var canonical = SupportTicketCanonical.Build(id, subject, request.Priority, request.Escalated, category);
        var newEtag = SupportTicketCanonical.Hash(canonical);

        if (string.Equals(newEtag, ticket.ETag, StringComparison.Ordinal))
        {
            Response.Headers.ETag = SupportTicketCanonical.Quote(ticket.ETag);
            return NoContent();
        }

        if (!SupportTicketCanonical.Matches(ifMatch, ticket.ETag))
        {
            Response.Headers.ETag = SupportTicketCanonical.Quote(ticket.ETag);
            return Problem(StatusCodes.Status412PreconditionFailed, "The If-Match precondition failed.");
        }

        ticket.Subject = subject;
        ticket.Priority = request.Priority;
        ticket.Escalated = request.Escalated;
        ticket.Category = category;
        ticket.ETag = newEtag;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.Entry(ticket).State = EntityState.Detached;
            var current = await _db.Tickets
                .IgnoreQueryFilters()
                .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);

            if (current is null)
            {
                return Problem(StatusCodes.Status404NotFound, "Ticket not found.");
            }
            if (current.DeletedAt is not null)
            {
                return Problem(StatusCodes.Status410Gone, "The ticket has been deleted.");
            }

            Response.Headers.ETag = SupportTicketCanonical.Quote(current.ETag);
            return Problem(StatusCodes.Status412PreconditionFailed, "The If-Match precondition failed.");
        }

        Response.Headers.ETag = SupportTicketCanonical.Quote(newEtag);
        return NoContent();
    }

    [HttpDelete("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [FromHeader(Name = "If-Match")] string ifMatch,
        CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
        {
            return Problem(StatusCodes.Status428PreconditionRequired, "The If-Match header is required.");
        }

        var ticket = await _db.Tickets
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);

        if (ticket is null || ticket.DeletedAt is not null)
        {
            return NoContent();
        }

        if (!SupportTicketCanonical.Matches(ifMatch, ticket.ETag))
        {
            Response.Headers.ETag = SupportTicketCanonical.Quote(ticket.ETag);
            return Problem(StatusCodes.Status412PreconditionFailed, "The If-Match precondition failed.");
        }

        ticket.DeletedAt = DateTime.UtcNow;
        ticket.ETag = SupportTicketCanonical.Hash("tombstone:" + ticket.ETag);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.Entry(ticket).State = EntityState.Detached;
            var current = await _db.Tickets
                .IgnoreQueryFilters()
                .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);

            if (current is null || current.DeletedAt is not null)
            {
                return NoContent();
            }

            Response.Headers.ETag = SupportTicketCanonical.Quote(current.ETag);
            return Problem(StatusCodes.Status412PreconditionFailed, "The If-Match precondition failed.");
        }

        return NoContent();
    }

    private static TicketResponse ToResponse(Ticket ticket) => new()
    {
        Id = ticket.PublicId,
        Subject = ticket.Subject,
        Priority = ticket.Priority,
        Escalated = ticket.Escalated,
        Category = ticket.Category
    };
}
