                throw;

            if (existing.TombstonedAt is not null)
                return Problem(statusCode: StatusCodes.Status410Gone, detail: "The ticket has been deleted.");

            if (existing.CreateHash == createHash)
            {
                Response.Headers.ETag = existing.ETag;
                return Ok(ToResponse(existing));
            }

            return Problem(statusCode: StatusCodes.Status409Conflict, detail: "A ticket with this id already exists.");
        }

        Response.Headers.ETag = etag;
        return Created($"/api/support-tickets/{request.Id}", ToResponse(ticket));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(
        Guid id,
        [FromHeader(Name = "If-None-Match")] string? ifNoneMatch,
        CancellationToken cancellationToken)
    {
        var ticket = await _db.Tickets
            .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);

        if (ticket is null)
        {
            var tombstoned = await _db.Tickets
                .IgnoreQueryFilters()
                .AnyAsync(t => t.PublicId == id && t.TombstonedAt != null, cancellationToken);
            return tombstoned
                ? Problem(statusCode: StatusCodes.Status410Gone, detail: "The ticket has been deleted.")
                : Problem(statusCode: StatusCodes.Status404NotFound, detail: "The ticket was not found.");
        }

        await _db.Tickets
            .IgnoreQueryFilters()
            .Where(t => t.Id == ticket.Id && t.TombstonedAt == null)
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, _ => (DateTime?)DateTime.UtcNow), cancellationToken);

        Response.Headers.ETag = ticket.ETag;
        if (ETagMatches(ifNoneMatch, ticket.ETag))
            return StatusCode(StatusCodes.Status304NotModified);

        return Ok(ToResponse(ticket));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(
        Guid id,
        [FromBody] TicketRequest request,
        [FromHeader(Name = "If-Match")] string ifMatch,
        CancellationToken cancellationToken)
    {
        if (request is null || request.Id == Guid.Empty || request.Id != id ||
            request.Subject is null || request.Category is null)
            return Problem(statusCode: StatusCodes.Status400BadRequest, detail: "Invalid ticket.");

        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(statusCode: StatusCodes.Status428PreconditionRequired, detail: "If-Match header is required.");

        var ticket = await _db.Tickets
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);

        if (ticket is null)
            return Problem(statusCode: StatusCodes.Status404NotFound, detail: "The ticket was not found.");

        if (ticket.TombstonedAt is not null)
            return Problem(statusCode: StatusCodes.Status410Gone, detail: "The ticket has been deleted.");

        var subject = request.Subject.Normalize(NormalizationForm.FormC);
        var category = request.Category.Normalize(NormalizationForm.FormC);
        var newEtag = TicketCanonicalJson.ETagFor(
            TicketCanonicalJson.Build(id, subject, request.Priority, request.Escalated, category));

        if (newEtag == ticket.ETag)
        {
            Response.Headers.ETag = newEtag;
            return NoContent();
        }

        if (!ETagMatches(ifMatch, ticket.ETag))
            return PreconditionFailed(ticket.ETag);

        ticket.Subject = subject;
        ticket.Priority = request.Priority;
        ticket.Escalated = request.Escalated;
        ticket.Category = category;
        ticket.ETag = newEtag;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.Entry(ticket).State = EntityState.Detached;
            var current = await _db.Tickets
                .IgnoreQueryFilters()
                .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);
            if (current is null)
                return Problem(statusCode: StatusCodes.Status404NotFound, detail: "The ticket was not found.");
            if (current.TombstonedAt is not null)
                return Problem(statusCode: StatusCodes.Status410Gone, detail: "The ticket has been deleted.");
            return PreconditionFailed(current.ETag);
        }

        Response.Headers.ETag = newEtag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [FromHeader(Name = "If-Match")] string ifMatch,
        CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(statusCode: StatusCodes.Status428PreconditionRequired, detail: "If-Match header is required.");

        var ticket = await _db.Tickets
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);

        if (ticket is null || ticket.TombstonedAt is not null)
            return NoContent();

        if (!ETagMatches(ifMatch, ticket.ETag))
            return PreconditionFailed(ticket.ETag);

        ticket.TombstonedAt = DateTime.UtcNow;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.Entry(ticket).State = EntityState.Detached;
            var current = await _db.Tickets
                .IgnoreQueryFilters()
                .FirstOrDefaultAsync(t => t.PublicId == id, cancellationToken);
            if (current is null || current.TombstonedAt is not null)
                return NoContent();
            return PreconditionFailed(current.ETag);
        }

        return NoContent();
    }

    private ObjectResult PreconditionFailed(string etag)
    {
        Response.Headers.ETag = etag;
        return Problem(statusCode: StatusCodes.Status412PreconditionFailed,
            detail: "The resource has been modified.");
    }

    private static bool ETagMatches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header))
            return false;

        var expected = etag.Trim('"');
        foreach (var part in header.Split(','))
        {
            var value = part.Trim();
            if (value == "*")
                return true;
            if (value.Length >= 2 && value[0] == '"' && value[^1] == '"')
                value = value[1..^1];
            if (string.Equals(value, expected, StringComparison.Ordinal))
                return true;
        }
        return false;
    }

    private static TicketResponse ToResponse(Ticket t) => new()
    {
        Id = t.PublicId,
        Subject = t.Subject,
        Priority = t.Priority,
        Escalated = t.Escalated,
        Category = t.Category
    };
}
