```csharp
// Canonical.cs
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

namespace SupportTickets;

public static class Canonical
{
    public static string Etag(Guid id, string subject, int priority, bool escalated, string category)
    {
        var json = CanonicalJson(id, subject, priority, escalated, category);
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(json));
        var base64url = Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + base64url + "\"";
    }

    private static string CanonicalJson(Guid id, string subject, int priority, bool escalated, string category)
    {
        var sb = new StringBuilder(160);
        sb.Append("{\"id\":\"").Append(id.ToString("D")).Append("\",\"subject\":");
        AppendString(sb, subject);
        sb.Append(",\"priority\":").Append(priority.ToString(CultureInfo.InvariantCulture));
        sb.Append(",\"escalated\":").Append(escalated ? "true" : "false");
        sb.Append(",\"category\":");
        AppendString(sb, category);
        sb.Append('}');
        return sb.ToString();
    }

    private static void AppendString(StringBuilder sb, string value)
    {
        sb.Append('"');
        var s = value.Normalize(NormalizationForm.FormC);
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else
                        sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }
}
