```csharp
// SupportTicketsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

namespace SupportTickets;

[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly AppDbContext _db;

    public SupportTicketsController(AppDbContext db) => _db = db;

    private TicketResponse ToResponse(Ticket t) => new()
    {
        Id = t.PublicId,
        Subject = t.Subject,
        Priority = t.Priority,
        Escalated = t.Escalated,
        Category = t.Category,
    };

    private Task<Ticket?> FindAnyAsync(Guid id, CancellationToken ct)
        => _db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(t => t.PublicId == id, ct);

    private void SetETag(string etag) => Response.Headers.ETag = etag;

    private static string Unquote(string s) =>
        s.Length >= 2 && s[0] == '"' && s[^1] == '"' ? s[1..^1] : s;

    private static bool ETagMatches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        var h = header.Trim();
        if (h == "*") return true;
        if (h.StartsWith("W/", StringComparison.Ordinal)) h = h[2..].Trim();
        return Unquote(h) == Unquote(etag);
    }

    private static bool IsUniqueViolation(DbUpdateException ex)
        => ex.InnerException is SqliteException sqlite
           && sqlite.SqliteErrorCode == 19
           && sqlite.Message.Contains("UNIQUE", StringComparison.OrdinalIgnoreCase);

    [HttpPost]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] TicketRequest request, CancellationToken cancellationToken)
    {
        if (request.Id is not { } publicId)
            return Problem(statusCode: StatusCodes.Status400BadRequest, title: "Bad Request",
                detail: "The id field is required.");
        if (request.Subject is null || request.Category is null)
            return Problem(statusCode: StatusCodes.Status400BadRequest, title: "Bad Request",
                detail: "The subject and category fields are required.");

        var etag = Canonical.Etag(publicId, request.Subject, request.Priority,
            request.Escalated, request.Category);
        var ticket = new Ticket
        {
            PublicId = publicId,
            Subject = request.Subject,
            Priority = request.Priority,
            Escalated = request.Escalated,
            Category = request.Category,
            ETag = etag,
            CreateRequestHash = etag,
        };
        _db.Tickets.Add(ticket);
        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException ex) when (IsUniqueViolation(ex))
        {
            _db.ChangeTracker.Clear();
            var existing = await FindAnyAsync(publicId, cancellationToken);
            if (existing is null)
                return Problem(statusCode: StatusCodes.Status409Conflict, title: "Conflict",
                    detail: "A ticket with this id already exists.");
            if (existing.TombstoneAt is not null)
                return Problem(statusCode: StatusCodes.Status410Gone, title: "Gone",
                    detail: "The ticket has been deleted.");
            if (existing.CreateRequestHash == etag)
            {
                SetETag(existing.ETag);
                return Ok(ToResponse(existing));
            }
            return Problem(statusCode: StatusCodes.Status409Conflict, title: "Conflict",
                detail: "A ticket with this id already exists with different content.");
        }

        SetETag(etag);
        return Created($"/api/support-tickets/{publicId}", ToResponse(ticket));
    }

    [HttpGet("{id}")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken cancellationToken)
    {
        var ticket = await FindAnyAsync(id, cancellationToken);
        if (ticket is null)
            return Problem(statusCode: StatusCodes.Status404NotFound, title: "Not Found",
                detail: "The ticket was not found.");
        if (ticket.TombstoneAt is not null)
            return Problem(statusCode: StatusCodes.Status410Gone, title: "Gone",
                detail: "The ticket has been deleted.");

        var saved = false;
        for (var attempt = 0; attempt < 3 && !saved; attempt++)
        {
            ticket.ViewCount++;
            ticket.LastViewedAt = DateTime.UtcNow;
            try
            {
                await _db.SaveChangesAsync(cancellationToken);
                saved = true;
            }
            catch (DbUpdateConcurrencyException)
            {
                _db.ChangeTracker.Clear();
                ticket = await FindAnyAsync(id, cancellationToken);
                if (ticket is null)
                    return Problem(statusCode: StatusCodes.Status404NotFound, title: "Not Found",
                        detail: "The ticket was not found.");
                if (ticket.TombstoneAt is not null)
                    return Problem(statusCode: StatusCodes.Status410Gone, title: "Gone",
                        detail: "The ticket has been deleted.");
            }
        }

        SetETag(ticket.ETag);
        if (ETagMatches(Request.Headers.IfNoneMatch.ToString(), ticket.ETag))
            return StatusCode(StatusCodes.Status304NotModified);
        return Ok(ToResponse(ticket));
    }

    [HttpPut("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(Guid id, [FromBody] TicketRequest request,
        [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken cancellationToken)
    {
        if (request.Id != id || request.Subject is null || request.Category is null)
            return Problem(statusCode: StatusCodes.Status400BadRequest, title: "Bad Request",
                detail: "The body id must match the route id and subject and category are required.");
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(statusCode: StatusCodes.Status428PreconditionRequired, title: "Precondition Required",
                detail: "The If-Match header is required.");

        var ticket = await FindAnyAsync(id, cancellationToken);
        if (ticket is null)
            return Problem(statusCode: StatusCodes.Status404NotFound, title: "Not Found",
                detail: "The ticket was not found.");
        if (ticket.TombstoneAt is not null)
            return Problem(statusCode: StatusCodes.Status410Gone, title: "Gone",
                detail: "The ticket has been deleted.");

        var newEtag = Canonical.Etag(id, request.Subject, request.Priority,
            request.Escalated, request.Category);
        if (newEtag == ticket.ETag)
        {
            SetETag(ticket.ETag);
            return NoContent();
        }
        if (!ETagMatches(ifMatch, ticket.ETag))
        {
            SetETag(ticket.ETag);
            return Problem(statusCode: StatusCodes.Status412PreconditionFailed, title: "Precondition Failed",
                detail: "The If-Match header does not match the current ETag.");
        }

        ticket.Subject = request.Subject;
        ticket.Priority = request.Priority;
        ticket.Escalated = request.Escalated;
        ticket.Category = request.Category;
        ticket.ETag = newEtag;
        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.ChangeTracker.Clear();
            var current = await FindAnyAsync(id, cancellationToken);
            if (current is null)
                return Problem(statusCode: StatusCodes.Status404NotFound, title: "Not Found",
                    detail: "The ticket was not found.");
            if (current.TombstoneAt is not null)
                return Problem(statusCode: StatusCodes.Status410Gone, title: "Gone",
                    detail: "The ticket has been deleted.");
            if (current.ETag == newEtag)
            {
                SetETag(newEtag);
                return NoContent();
            }
            SetETag(current.ETag);
            return Problem(statusCode: StatusCodes.Status412PreconditionFailed, title: "Precondition Failed",
                detail: "The If-Match header does not match the current ETag.");
        }

        SetETag(newEtag);
        return NoContent();
    }

    [HttpDelete("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id,
        [FromHeader(Name = "If-Match")] string? ifMatch, CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
            return Problem(statusCode: StatusCodes.Status428PreconditionRequired, title: "Precondition Required",
                detail: "The If-Match header is required.");

        var ticket = await FindAnyAsync(id, cancellationToken);
        if (ticket is null || ticket.TombstoneAt is not null)
            return NoContent();
        if (!ETagMatches(ifMatch, ticket.ETag))
        {
            SetETag(ticket.ETag);
            return Problem(statusCode: StatusCodes.Status412PreconditionFailed, title: "Precondition Failed",
                detail: "The If-Match header does not match the current ETag.");
        }

        ticket.TombstoneAt = DateTime.UtcNow;
        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.ChangeTracker.Clear();
            var current = await FindAnyAsync(id, cancellationToken);
            if (current is null || current.TombstoneAt is not null)
                return NoContent();
            SetETag(current.ETag);
            return Problem(statusCode: StatusCodes.Status412PreconditionFailed, title: "Precondition Failed",
                detail: "The If-Match header does not match the current ETag.");
        }
        return NoContent();
    }
}
