using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace WarehouseApi;

[ApiController]
[Route("api")]
public class ShipmentsController : ControllerBase
{
    private readonly AppDbContext _db;

    public ShipmentsController(AppDbContext db)
    {
        _db = db;
    }

    [HttpGet("shipments/{id:guid}")]
    public async Task<ActionResult<Consignment>> Get(Guid id)
    {
        var shipment = await _db.Consignments
            .AsNoTracking()
            .Include(c => c.Warehouse)
            .FirstOrDefaultAsync(c => c.Id == id);

        if (shipment is null)
            return NotFound();

        shipment.DownloadCount++;
        await _db.Consignments.Where(c => c.Id == id)
            .ExecuteUpdateAsync(s => s.SetProperty(c => c.DownloadCount, c => c.DownloadCount + 1));

        return shipment;
    }

    [HttpPost("warehouses/{warehouseId:guid}/shipments")]
    public async Task<ActionResult<Consignment>> Create(Guid warehouseId, Consignment shipment)
    {
        if (!await _db.Depots.AnyAsync(d => d.Id == warehouseId))
            return NotFound();

        if (shipment.Id == Guid.Empty)
            shipment.Id = Guid.NewGuid();

        shipment.WarehouseId = warehouseId;
        shipment.DownloadCount = 0;
        shipment.Warehouse = null;
        _db.Consignments.Add(shipment);
        await _db.SaveChangesAsync();

        return CreatedAtAction(nameof(Get), new { id = shipment.Id }, shipment);
    }

    [HttpPut("shipments/{id:guid}")]
    public async Task<ActionResult<Consignment>> Update(Guid id, Consignment shipment)
    {
        var existing = await _db.Consignments.FindAsync(id);
        if (existing is null)
            return NotFound();

        if (!await _db.Depots.AnyAsync(d => d.Id == shipment.WarehouseId))
            return BadRequest();

        existing.WarehouseId = shipment.WarehouseId;
        existing.Reference = shipment.Reference;
        existing.WeightKg = shipment.WeightKg;
        existing.Fragile = shipment.Fragile;
        await _db.SaveChangesAsync();

        return existing;
    }

    [HttpDelete("shipments/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var shipment = await _db.Consignments.FindAsync(id);
        if (shipment is null)
            return NotFound();

        _db.Consignments.Remove(shipment);
        await _db.SaveChangesAsync();
        return NoContent();
    }
}
