using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/warehouses")]
public class WarehousesController : ControllerBase
{
    private readonly AppDbContext _db;

    public WarehousesController(AppDbContext db) => _db = db;

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] Depot depot)
    {
        if (string.IsNullOrWhiteSpace(depot.Code))
            return BadRequest("code is required");

        depot.Id = depot.Id == Guid.Empty ? Guid.NewGuid() : depot.Id;

        var existing = await _db.Depots.FindAsync(depot.Id);
        if (existing != null)
            return Ok(existing); // idempotent retry

        depot.CapacityCubicMeters = depot.CapacityCubicMeters;
        depot.LastAuditAt = null;
        depot.ConcurrencyStamp = Guid.NewGuid();
        _db.Depots.Add(depot);

        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            return Conflict("warehouse already exists");
        }

        return CreatedAtAction(nameof(Get), new { id = depot.Id }, depot);
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id)
    {
        var depot = await _db.Depots.FindAsync(id);
        if (depot == null) return NotFound();

        depot.LastAuditAt = DateTime.UtcNow;
        try { await _db.SaveChangesAsync(); }
        catch (DbUpdateConcurrencyException) { /* audit timestamp is best-effort */ }

        return Ok(depot);
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] Depot depot)
    {
        if (string.IsNullOrWhiteSpace(depot.Code))
            return BadRequest("code is required");

        var existing = await _db.Depots.FindAsync(id);
        if (existing == null) return NotFound();

        existing.Code = depot.Code;
        existing.CapacityCubicMeters = depot.CapacityCubicMeters;
        existing.ConcurrencyStamp = Guid.NewGuid();

        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict("warehouse was modified concurrently");
        }

        return Ok(existing);
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var depot = await _db.Depots.FindAsync(id);
        if (depot == null) return NotFound();

        _db.Depots.Remove(depot);

        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict("warehouse was modified concurrently");
        }

        return NoContent();
    }
}
