// ShipmentsController.cs
using System;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
public class ShipmentsController : ControllerBase
{
    private readonly AppDbContext _db;

    public ShipmentsController(AppDbContext db) => _db = db;

    [HttpPost("api/warehouses/{warehouseId:guid}/shipments")]
    public async Task<IActionResult> Create(Guid warehouseId, [FromBody] Consignment consignment)
    {
        if (string.IsNullOrWhiteSpace(consignment.Reference))
            return BadRequest("reference is required");

        var warehouseExists = await _db.Depots.AnyAsync(d => d.Id == warehouseId);
        if (!warehouseExists) return NotFound("warehouse not found");

        consignment.Id = consignment.Id == Guid.Empty ? Guid.NewGuid() : consignment.Id;
        consignment.WarehouseId = warehouseId;

        var existing = await _db.Consignments.FindAsync(consignment.Id);
        if (existing != null)
            return Ok(existing); // idempotent retry

        consignment.DownloadCount = 0;
        consignment.ConcurrencyStamp = Guid.NewGuid();
        _db.Consignments.Add(consignment);

        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            return Conflict("shipment already exists");
        }

        return CreatedAtAction(nameof(Get), new { id = consignment.Id }, consignment);
    }

    [HttpGet("api/warehouses/{warehouseId:guid}/shipments")]
    public async Task<IActionResult> ListByWarehouse(Guid warehouseId)
    {
        var warehouseExists = await _db.Depots.AnyAsync(d => d.Id == warehouseId);
        if (!warehouseExists) return NotFound("warehouse not found");

        var shipments = await _db.Consignments
            .Where(c => c.WarehouseId == warehouseId)
            .ToListAsync();

        return Ok(shipments);
    }

    [HttpGet("api/shipments/{id:guid}")]
    public async Task<IActionResult> Get(Guid id)
    {
        for (var attempt = 0; attempt < 3; attempt++)
        {
            var consignment = await _db.Consignments.FindAsync(id);
            if (consignment == null) return NotFound();

            consignment.DownloadCount++;
            try
            {
                await _db.SaveChangesAsync();
                return Ok(consignment);
            }
            catch (DbUpdateConcurrencyException)
            {
                _db.Entry(consignment).State = EntityState.Detached;
            }
        }

        return Conflict("shipment was modified concurrently");
    }

    [HttpPut("api/shipments/{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] Consignment consignment)
    {
        if (string.IsNullOrWhiteSpace(consignment.Reference))
            return BadRequest("reference is required");

        var existing = await _db.Consignments.FindAsync(id);
        if (existing == null) return NotFound();

        var warehouseExists = await _db.Depots.AnyAsync(d => d.Id == consignment.WarehouseId);
        if (!warehouseExists) return NotFound("warehouse not found");

        existing.WarehouseId = consignment.WarehouseId;
        existing.Reference = consignment.Reference;
        existing.WeightKg = consignment.WeightKg;
        existing.Fragile = consignment.Fragile;
        existing.ConcurrencyStamp = Guid.NewGuid();

        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict("shipment was modified concurrently");
        }

        return Ok(existing);
    }

    [HttpDelete("api/shipments/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var consignment = await _db.Consignments.FindAsync(id);
        if (consignment == null) return NotFound();

        _db.Consignments.Remove(consignment);

        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict("shipment was modified concurrently");
        }

        return NoContent();
    }
}
