// WarehousesController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace Logistics;

[ApiController]
[Route("api/warehouses")]
public class WarehousesController : ControllerBase
{
    private readonly AppDbContext _db;

    public WarehousesController(AppDbContext db)
    {
        _db = db;
    }

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] WarehouseRequest request)
    {
        var id = request.Id == Guid.Empty ? Guid.NewGuid() : request.Id;
        var code = request.Code ?? string.Empty;

        var existing = await _db.Depots
            .AsNoTracking()
            .FirstOrDefaultAsync(d => d.Id == id);

        if (existing is not null)
        {
            return Matches(existing, code, request.CapacityCubicMeters)
                ? Ok(ToDto(existing))
                : Conflict(new { error = "A warehouse with this id already exists." });
        }

        var depot = new Depot
        {
            Id = id,
            Code = code,
            CapacityCubicMeters = request.CapacityCubicMeters
        };
        _db.Depots.Add(depot);

        try
        {
            await DbRetry.RunAsync(() => _db.SaveChangesAsync());
        }
        catch (DbUpdateException)
        {
            var winner = await _db.Depots
                .AsNoTracking()
                .FirstOrDefaultAsync(d => d.Id == id);

            return winner is not null && Matches(winner, code, request.CapacityCubicMeters)
                ? Ok(ToDto(winner))
                : Conflict(new { error = "A warehouse with this id already exists." });
        }

        return CreatedAtAction(nameof(GetById), new { id }, ToDto(depot));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> GetById(Guid id)
    {
        var updated = await DbRetry.RunAsync(() => _db.Depots
            .Where(d => d.Id == id)
            .ExecuteUpdateAsync(s => s.SetProperty(d => d.LastAuditAt, DateTime.UtcNow)));

        if (updated == 0)
        {
            return NotFound();
        }

        var depot = await _db.Depots.AsNoTracking().FirstAsync(d => d.Id == id);
        return Ok(ToDto(depot));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] WarehouseRequest request)
    {
        if (request.Id != Guid.Empty && request.Id != id)
        {
            return BadRequest(new { error = "The id in the route does not match the id in the body." });
        }

        var code = request.Code ?? string.Empty;
        var updated = await DbRetry.RunAsync(() => _db.Depots
            .Where(d => d.Id == id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(d => d.Code, code)
                .SetProperty(d => d.CapacityCubicMeters, request.CapacityCubicMeters)));

        if (updated == 0)
        {
            return NotFound();
        }

        var depot = await _db.Depots.AsNoTracking().FirstAsync(d => d.Id == id);
        return Ok(ToDto(depot));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var deleted = await DbRetry.RunAsync(async () =>
        {
            await using var transaction = await _db.Database.BeginTransactionAsync();
            await _db.Consignments.Where(c => c.DepotId == id).ExecuteDeleteAsync();
            var rows = await _db.Depots.Where(d => d.Id == id).ExecuteDeleteAsync();

            if (rows == 0)
            {
                await transaction.RollbackAsync();
            }
            else
            {
                await transaction.CommitAsync();
            }

            return rows;
        });

        return deleted == 0 ? NotFound() : NoContent();
    }

    private static bool Matches(Depot depot, string code, int capacity) =>
        depot.Code == code && depot.CapacityCubicMeters == capacity;

    private static WarehouseDto ToDto(Depot depot) => new()
    {
        Id = depot.Id,
        Code = depot.Code,
        CapacityCubicMeters = depot.CapacityCubicMeters,
        LastAuditAt = depot.LastAuditAt
    };
}
