// ShipmentsController.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace Logistics;

[ApiController]
public class ShipmentsController : ControllerBase
{
    private readonly AppDbContext _db;

    public ShipmentsController(AppDbContext db)
    {
        _db = db;
    }

    [HttpPost("~/api/warehouses/{warehouseId:guid}/shipments")]
    public async Task<IActionResult> Create(Guid warehouseId, [FromBody] ShipmentRequest request)
    {
        if (request.WarehouseId != Guid.Empty && request.WarehouseId != warehouseId)
        {
            return BadRequest(new { error = "The warehouseId in the route does not match the body." });
        }

        if (!await _db.Depots.AnyAsync(d => d.Id == warehouseId))
        {
            return NotFound(new { error = "Warehouse not found." });
        }

        var id = request.Id == Guid.Empty ? Guid.NewGuid() : request.Id;
        var reference = request.Reference ?? string.Empty;

        var existing = await _db.Consignments
            .AsNoTracking()
            .FirstOrDefaultAsync(c => c.Id == id);

        if (existing is not null)
        {
            return Matches(existing, warehouseId, reference, request.WeightKg, request.Fragile)
                ? Ok(ToDto(existing))
                : Conflict(new { error = "A shipment with this id already exists." });
        }

        var consignment = new Consignment
        {
            Id = id,
            DepotId = warehouseId,
            Reference = reference,
            WeightKg = request.WeightKg,
            Fragile = request.Fragile,
            DownloadCount = 0
        };
        _db.Consignments.Add(consignment);

        try
        {
            await DbRetry.RunAsync(() => _db.SaveChangesAsync());
        }
        catch (DbUpdateException)
        {
            var winner = await _db.Consignments
                .AsNoTracking()
                .FirstOrDefaultAsync(c => c.Id == id);

            return winner is not null && Matches(winner, warehouseId, reference, request.WeightKg, request.Fragile)
                ? Ok(ToDto(winner))
                : Conflict(new { error = "A shipment with this id already exists." });
        }

        return CreatedAtAction(nameof(GetById), new { id }, ToDto(consignment));
    }

    [HttpGet("api/shipments/{id:guid}")]
    public async Task<IActionResult> GetById(Guid id)
    {
        var updated = await DbRetry.RunAsync(() => _db.Consignments
            .Where(c => c.Id == id)
            .ExecuteUpdateAsync(s => s.SetProperty(
                c => c.DownloadCount,
                c => c.DownloadCount + 1)));

        if (updated == 0)
        {
            return NotFound();
        }

        var consignment = await _db.Consignments.AsNoTracking().FirstAsync(c => c.Id == id);
        return Ok(ToDto(consignment));
    }

    [HttpPut("api/shipments/{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] ShipmentRequest request)
    {
        if (request.Id != Guid.Empty && request.Id != id)
        {
            return BadRequest(new { error = "The id in the route does not match the id in the body." });
        }

        var reference = request.Reference ?? string.Empty;
        Guid? newDepotId = null;

        if (request.WarehouseId != Guid.Empty)
        {
            if (!await _db.Depots.AnyAsync(d => d.Id == request.WarehouseId))
            {
                return BadRequest(new { error = "Warehouse not found." });
            }

            newDepotId = request.WarehouseId;
        }

        var updated = await DbRetry.RunAsync(() => _db.Consignments
            .Where(c => c.Id == id)
            .ExecuteUpdateAsync(s =>
            {
                var calls = s.SetProperty(c => c.Reference, reference)
                             .SetProperty(c => c.WeightKg, request.WeightKg)
                             .SetProperty(c => c.Fragile, request.Fragile);

                if (newDepotId.HasValue)
                {
                    calls = calls.SetProperty(c => c.DepotId, newDepotId.Value);
                }

                return calls;
            }));

        if (updated == 0)
        {
            return NotFound();
        }

        var consignment = await _db.Consignments.AsNoTracking().FirstAsync(c => c.Id == id);
        return Ok(ToDto(consignment));
    }

    [HttpDelete("api/shipments/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        var deleted = await DbRetry.RunAsync(() => _db.Consignments
            .Where(c => c.Id == id)
            .ExecuteDeleteAsync());

        return deleted == 0 ? NotFound() : NoContent();
    }

    private static bool Matches(
        Consignment consignment,
        Guid warehouseId,
        string reference,
        decimal weightKg,
        bool fragile) =>
        consignment.DepotId == warehouseId &&
        consignment.Reference == reference &&
        consignment.WeightKg == weightKg &&
        consignment.Fragile == fragile;

    private static ShipmentDto ToDto(Consignment consignment) => new()
    {
        Id = consignment.Id,
        WarehouseId = consignment.DepotId,
        Reference = consignment.Reference,
        WeightKg = consignment.WeightKg,
        Fragile = consignment.Fragile,
        DownloadCount = consignment.DownloadCount
    };
}
