```csharp
using Api.Data;
using Api.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace Api.Controllers;

[ApiController]
[Route("api/warehouses")]
public class WarehousesController : ControllerBase
{
    private readonly AppDbContext _db;

    public WarehousesController(AppDbContext db) => _db = db;

    [HttpPost]
    public async Task<ActionResult<Depot>> Create([FromBody] CreateDepotRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Code))
            return BadRequest("code is required");

        var id = request.Id ?? Guid.NewGuid();

        // Idempotent retry: if a client supplied an id that already exists, return it.
        var existing = await _db.Depots.FindAsync(id);
        if (existing is not null)
        {
            if (existing.Code != request.Code || existing.CapacityCubicMeters != request.CapacityCubicMeters)
                return Conflict(existing);
            return CreatedAtAction(nameof(Get), new { id = existing.Id }, existing);
        }

        var depot = new Depot
        {
            Id = id,
            Code = request.Code,
            CapacityCubicMeters = request.CapacityCubicMeters
        };

        _db.Depots.Add(depot);
        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateException)
        {
            _db.Entry(depot).State = EntityState.Detached;
            var raced = await _db.Depots.FindAsync(id);
            if (raced is not null) return CreatedAtAction(nameof(Get), new { id = raced.Id }, raced);
            throw;
        }

        return CreatedAtAction(nameof(Get), new { id = depot.Id }, depot);
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<Depot>> Get(Guid id)
    {
        var depot = await _db.Depots.FindAsync(id);
        return depot is null ? NotFound() : Ok(depot);
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<Depot>> Update(Guid id, [FromBody] UpdateDepotRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Code))
            return BadRequest("code is required");

        var depot = await _db.Depots.FindAsync(id);
        if (depot is null) return NotFound();

        depot.Code = request.Code;
        depot.CapacityCubicMeters = request.CapacityCubicMeters;
        depot.LastAuditAt = DateTime.UtcNow;

        try
        {
            await _db.SaveChangesAsync();
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }

        return Ok(depot);
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
