            return BadRequest(new { error = "code is required" });
        if (input.CapacityCubicMeters < 0)
            return BadRequest(new { error = "capacityCubicMeters must be non-negative" });

        var id = input.Id == Guid.Empty ? Guid.NewGuid() : input.Id;

        // Idempotent create: a retried POST with the same id returns the existing row.
        var existing = await _db.Depots.AsNoTracking().FirstOrDefaultAsync(d => d.Id == id, ct);
        if (existing is not null)
        {
            if (existing.Code == input.Code.Trim() && existing.CapacityCubicMeters == input.CapacityCubicMeters)
                return Ok(existing);
            return Conflict(new { error = "A warehouse with this id already exists." });
        }

        var depot = new Depot
        {
            Id = id,
            Code = input.Code.Trim(),
            CapacityCubicMeters = input.CapacityCubicMeters
        };
        _db.Depots.Add(depot);
        await _db.SaveChangesAsync(ct);

        return CreatedAtAction(nameof(Get), new { id = depot.Id }, depot);
