    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var exists = await _db.Depots.AnyAsync(d => d.Id == id, ct);
        if (!exists) return NotFound();

        // Server-maintained audit timestamp, updated atomically on every read.
        await _db.Depots.Where(d => d.Id == id)
            .ExecuteUpdateAsync(s => s.SetProperty(d => d.LastAuditAt, DateTime.UtcNow), ct);

        var depot = await _db.Depots.AsNoTracking().FirstAsync(d => d.Id == id, ct);
        return Ok(depot);
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] WarehouseUpdate input, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(input.Code))
            return BadRequest(new { error = "code is required" });
        if (input.CapacityCubicMeters < 0)
            return BadRequest(new { error = "capacityCubicMeters must be non-negative" });

        for (var attempt = 0; attempt < 3; attempt++)
        {
            var depot = await _db.Depots.FirstOrDefaultAsync(d => d.Id == id, ct);
            if (depot is null) return NotFound();

            depot.Code = input.Code.Trim();
            depot.CapacityCubicMeters = input.CapacityCubicMeters;
            depot.Version++;

            try
