            return BadRequest(new { error = "code and capacityCubicMeters are required" });

        for (var attempt = 0; attempt < MaxAttempts; attempt++)
        {
            var depot = await _db.Depots.FindAsync(id);
            if (depot is null)
                return NotFound();

            depot.Code = request.Code;
            depot.CapacityCubicMeters = request.CapacityCubicMeters.Value;
            depot.Version++;

