using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;

public static class AppSetup
{
    public static void ConfigureServices(IServiceCollection services, string sqliteConnectionString)
    {
        services.AddDbContext<AppDbContext>(options => options.UseSqlite(sqliteConnectionString));
        services.AddControllers();
    }
}

internal static class DbContextRetryExtensions
{
    public static async Task<int> SaveChangesWithRetryAsync(this DbContext db, int maxAttempts = 5)
    {
        for (var attempt = 0; ; attempt++)
        {
            try
            {
                return await db.SaveChangesAsync();
            }
            catch (DbUpdateException ex) when (IsBusy(ex) && attempt < maxAttempts - 1)
            {
                await Task.Delay(50 * (attempt + 1));
            }
        }

        static bool IsBusy(DbUpdateException ex)
            => ex.InnerException is SqliteException { SqliteErrorCode: 5 or 6 };
    }
}
```

Notes on design choices:

- **Idempotent creates**: if the client supplies an `id` and retries after a timeout, `POST` returns the already-created resource instead of duplicating or failing on the PK.
- **Concurrency**: `Version` is an EF concurrency token on both entities; concurrent `PUT`s that race produce `409 Conflict` rather than silent lost updates. SQLite `BUSY`/`LOCKED` errors are retried with backoff.
- **`DownloadCount`**: incremented atomically via `ExecuteUpdateAsync` on `GET /api/shipments/{id}`.
- **`LastAuditAt`**: set server-side on warehouse create/update; clients cannot set it since requests bind to DTOs, not the entities.
- Deleting a warehouse cascades to its shipments via the configured FK.

