using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public static class Canonical
{
    public static string Warehouse(Guid id, string code, int capacityCubicMeters)
    {
        var builder = new StringBuilder();
        builder.Append("{\"id\":");
        AppendString(builder, id.ToString("D"));
        builder.Append(",\"code\":");
        AppendString(builder, code);
        builder.Append(",\"capacityCubicMeters\":");
        builder.Append(capacityCubicMeters.ToString(CultureInfo.InvariantCulture));
        builder.Append('}');
        return builder.ToString();
    }

    public static string Shipment(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile)
    {
        var builder = new StringBuilder();
        builder.Append("{\"id\":");
        AppendString(builder, id.ToString("D"));
        builder.Append(",\"warehouseId\":");
        AppendString(builder, warehouseId.ToString("D"));
        builder.Append(",\"reference\":");
        AppendString(builder, reference);
        builder.Append(",\"weightKg\":");
        builder.Append(FormatDecimal(weightKg));
        builder.Append(",\"fragile\":");
        builder.Append(fragile ? "true" : "false");
        builder.Append('}');
        return builder.ToString();
    }

    public static string ComputeETag(string canonicalJson)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson));
        var encoded = Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + encoded + "\"";
    }

    private static string FormatDecimal(decimal value)
    {
        if (value == 0m)
        {
            return "0";
        }

        var text = value.ToString("F28", CultureInfo.InvariantCulture).TrimEnd('0');
        return text.EndsWith('.') ? text[..^1] : text;
    }

    private static void AppendString(StringBuilder builder, string value)
    {
        builder.Append('"');
        foreach (var ch in value.Normalize())
        {
            switch (ch)
            {
                case '"':
                    builder.Append("\\\"");
                    break;
                case '\\':
                    builder.Append("\\\\");
                    break;
                case '\b':
                    builder.Append("\\b");
                    break;
                case '\f':
                    builder.Append("\\f");
                    break;
                case '\n':
                    builder.Append("\\n");
                    break;
                case '\r':
                    builder.Append("\\r");
                    break;
                case '\t':
                    builder.Append("\\t");
                    break;
                default:
                    if (ch < 0x20)
                    {
                        builder.Append("\\u");
                        builder.Append(((int)ch).ToString("x4", CultureInfo.InvariantCulture));
                    }
                    else
                    {
                        builder.Append(ch);
                    }
                    break;
            }
        }
        builder.Append('"');
    }
}
