using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

public abstract class ApiControllerBase : ControllerBase
{
    protected ObjectResult ProblemResult(int statusCode, string title, string? detail = null)
    {
        var problem = new ProblemDetails
        {
            Status = statusCode,
            Title = title,
            Detail = detail
        };
        var result = new ObjectResult(problem) { StatusCode = statusCode };
        result.ContentTypes.Add("application/problem+json");
        return result;
    }

    protected void SetETag(string etag)
    {
        Response.Headers.ETag = etag;
    }

    protected static bool ETagMatches(string? headerValue, string etag)
    {
        var value = headerValue?.Trim();
        return value == "*" || string.Equals(value, etag, StringComparison.Ordinal);
    }

    protected static bool IsUniqueViolation(DbUpdateException exception)
    {
        for (Exception? current = exception; current != null; current = current.InnerException)
        {
            if (current is SqliteException sqlite)
            {
                return sqlite.SqliteErrorCode == 19 &&
                       sqlite.Message.Contains("UNIQUE", StringComparison.OrdinalIgnoreCase);
            }
        }

        return exception.Message.Contains("UNIQUE", StringComparison.OrdinalIgnoreCase);
    }
}
