                .HasPrincipalKey(depot => depot.PublicId);
        });

        modelBuilder.Entity<Consignment>(entity =>
        {
            entity.HasKey(consignment => consignment.Id);
            entity.HasIndex(consignment => consignment.PublicId).IsUnique();
            entity.Property(consignment => consignment.Reference).IsRequired();
            entity.Property(consignment => consignment.ETag).IsRequired().IsConcurrencyToken();
            entity.Property(consignment => consignment.CreateHash).IsRequired()
                .Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            entity.HasQueryFilter(consignment => consignment.DeletedAt == null);
        });
    }
