using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public static class CanonicalJson
{
    public static string WarehouseEtag(Guid id, string code, int capacityCubicMeters) =>
        ETag(Warehouse(id, code, capacityCubicMeters));

    public static string ShipmentEtag(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile) =>
        ETag(Shipment(id, warehouseId, reference, weightKg, fragile));

    public static string ETag(string canonicalJson)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson));
        var value = Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + value + "\"";
    }

    private static string Warehouse(Guid id, string code, int capacityCubicMeters)
    {
        var builder = new StringBuilder();
        builder.Append("{\"id\":");
        WriteGuid(builder, id);
        builder.Append(",\"code\":");
        WriteString(builder, code);
        builder.Append(",\"capacityCubicMeters\":");
        WriteInt32(builder, capacityCubicMeters);
        builder.Append('}');
        return builder.ToString();
    }

    private static string Shipment(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile)
    {
        var builder = new StringBuilder();
        builder.Append("{\"id\":");
        WriteGuid(builder, id);
        builder.Append(",\"warehouseId\":");
        WriteGuid(builder, warehouseId);
        builder.Append(",\"reference\":");
        WriteString(builder, reference);
        builder.Append(",\"weightKg\":");
        WriteDecimal(builder, weightKg);
        builder.Append(",\"fragile\":");
        builder.Append(fragile ? "true" : "false");
        builder.Append('}');
        return builder.ToString();
    }

    private static void WriteGuid(StringBuilder builder, Guid value)
    {
        builder.Append('"');
        builder.Append(value.ToString("D", CultureInfo.InvariantCulture).ToLowerInvariant());
        builder.Append('"');
    }

    private static void WriteInt32(StringBuilder builder, int value) =>
        builder.Append(value.ToString(CultureInfo.InvariantCulture));

    private static void WriteDecimal(StringBuilder builder, decimal value)
    {
        if (value == 0m)
        {
            builder.Append('0');
            return;
        }

        var text = value.ToString(CultureInfo.InvariantCulture);
        if (text.Contains('.'))
        {
            text = text.TrimEnd('0').TrimEnd('.');
        }

        if (text == "-0")
        {
            text = "0";
        }

        builder.Append(text);
    }

    private static void WriteString(StringBuilder builder, string value)
    {
        builder.Append('"');
        var normalized = value.Normalize(NormalizationForm.FormC);
        foreach (var character in normalized)
        {
            switch (character)
            {
                case '"':
                    builder.Append("\\\"");
                    break;
                case '\\':
                    builder.Append("\\\\");
                    break;
                case '\b':
                    builder.Append("\\b");
                    break;
                case '\f':
                    builder.Append("\\f");
                    break;
                case '\n':
                    builder.Append("\\n");
                    break;
                case '\r':
                    builder.Append("\\r");
                    break;
                case '\t':
                    builder.Append("\\t");
                    break;
                default:
                    if (character < ' ')
                    {
                        builder.Append("\\u");
                        builder.Append(((int)character).ToString("x4", CultureInfo.InvariantCulture));
                    }
                    else
                    {
                        builder.Append(character);
                    }

                    break;
            }
        }

        builder.Append('"');
    }
}
