public sealed class WarehouseController : ControllerBase
{
    private readonly AppDbContext _db;

    public WarehouseController(AppDbContext db) => _db = db;

    [HttpPost]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] [Required] WarehouseRequest request, CancellationToken cancellationToken)
    {
        if (!TryValidateCreate(request, out var invalid))
        {
            return invalid!;
        }

        request.Code = request.Code!.Normalize(NormalizationForm.FormC);
        var id = request.Id!.Value;
        var etag = CanonicalJson.WarehouseEtag(id, request.Code, request.CapacityCubicMeters!.Value);

        var depot = new Depot
        {
            PublicId = id,
            Code = request.Code,
            CapacityCubicMeters = request.CapacityCubicMeters.Value,
            ETag = etag,
            CreateHash = etag
        };

        _db.Depots.Add(depot);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();
            var existing = await _db.Depots
                .IgnoreQueryFilters()
                .AsNoTracking()
                .FirstOrDefaultAsync(depot => depot.PublicId == id, cancellationToken);

            if (existing is null)
            {
                throw;
            }

            if (existing.DeletedAt is not null)
            {
                return ApiSupport.Error(StatusCodes.Status410Gone, "Gone", "The warehouse has been deleted.");
            }

            if (existing.CreateHash == etag)
            {
                Response.Headers.ETag = existing.ETag;
                return Ok(WarehouseResponse.From(existing));
            }

            return ApiSupport.Error(StatusCodes.Status409Conflict, "Conflict", "The warehouse id is already in use.");
        }

        Response.Headers.ETag = etag;
        Response.Headers.Location = $"/api/warehouses/{id}";
        return StatusCode(StatusCodes.Status201Created, WarehouseResponse.From(depot));
    }

    [HttpGet("{id}")]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken cancellationToken)
    {
        var depot = await _db.Depots
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(depot => depot.PublicId == id, cancellationToken);

        if (depot is null)
        {
            return ApiSupport.Error(StatusCodes.Status404NotFound, "Not Found", "The warehouse was not found.");
        }

        if (depot.DeletedAt is not null)
        {
            return ApiSupport.Error(StatusCodes.Status410Gone, "Gone", "The warehouse has been deleted.");
        }

        Response.Headers.ETag = depot.ETag;
        if (ApiSupport.ETagMatches(Request.Headers["If-None-Match"].ToString(), depot.ETag))
        {
            return StatusCode(StatusCodes.Status304NotModified);
        }

        DateTime? auditedAt = DateTime.UtcNow;
        await _db.Depots
            .Where(depot => depot.PublicId == id)
            .ExecuteUpdateAsync(setters => setters.SetProperty(depot => depot.LastAuditAt, auditedAt), cancellationToken);

        return Ok(WarehouseResponse.From(depot));
    }

    [HttpPut("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Update(
        Guid id,
        [FromBody] [Required] WarehouseRequest request,
        [FromHeader(Name = "If-Match")] [Required] string? ifMatch,
        CancellationToken cancellationToken)
    {
        if (!TryValidateUpdate(request, id, out var invalid))
        {
            return invalid!;
        }

        if (string.IsNullOrWhiteSpace(ifMatch))
        {
            return ApiSupport.Error(StatusCodes.Status428PreconditionRequired, "Precondition Required", "The If-Match header is required.");
        }

        request.Code = request.Code!.Normalize(NormalizationForm.FormC);
        var depot = await _db.Depots
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(depot => depot.PublicId == id, cancellationToken);

        if (depot is null)
        {
            return ApiSupport.Error(StatusCodes.Status404NotFound, "Not Found", "The warehouse was not found.");
        }

        if (depot.DeletedAt is not null)
        {
            return ApiSupport.Error(StatusCodes.Status410Gone, "Gone", "The warehouse has been deleted.");
        }

        var etag = CanonicalJson.WarehouseEtag(id, request.Code, request.CapacityCubicMeters!.Value);
        if (depot.ETag == etag)
        {
            return NoContent();
        }

        if (!ApiSupport.ETagMatches(ifMatch, depot.ETag))
        {
            Response.Headers.ETag = depot.ETag;
            return ApiSupport.Error(StatusCodes.Status412PreconditionFailed, "Precondition Failed", "The If-Match precondition failed.");
        }

        depot.Code = request.Code;
        depot.CapacityCubicMeters = request.CapacityCubicMeters.Value;
        depot.ETag = etag;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await CurrentWarehouseEtagAsync(id, cancellationToken);
            if (current is null || current.DeletedAt is not null)
            {
                return ApiSupport.Error(StatusCodes.Status410Gone, "Gone", "The warehouse has been deleted.");
            }

            if (current.ETag == etag)
            {
                return NoContent();
            }

            Response.Headers.ETag = current.ETag;
            return ApiSupport.Error(StatusCodes.Status412PreconditionFailed, "Precondition Failed", "The If-Match precondition failed.");
        }
    }

    [HttpDelete("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [FromHeader(Name = "If-Match")] [Required] string? ifMatch,
        CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(ifMatch))
        {
            return ApiSupport.Error(StatusCodes.Status428PreconditionRequired, "Precondition Required", "The If-Match header is required.");
        }

        var depot = await _db.Depots
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(depot => depot.PublicId == id, cancellationToken);

        if (depot is null || depot.DeletedAt is not null)
        {
            return NoContent();
        }

        if (!ApiSupport.ETagMatches(ifMatch, depot.ETag))
        {
            Response.Headers.ETag = depot.ETag;
            return ApiSupport.Error(StatusCodes.Status412PreconditionFailed, "Precondition Failed", "The If-Match precondition failed.");
        }

        await using var transaction = await _db.Database.BeginTransactionAsync(cancellationToken);
        DateTime? deletedAt = DateTime.UtcNow;
        depot.DeletedAt = deletedAt;

        await _db.Consignments
            .Where(consignment => consignment.WarehouseId == id && consignment.DeletedAt == null)
            .ExecuteUpdateAsync(setters => setters.SetProperty(consignment => consignment.DeletedAt, deletedAt), cancellationToken);

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
            await transaction.CommitAsync(cancellationToken);
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            var current = await CurrentWarehouseEtagAsync(id, cancellationToken);
            if (current is null || current.DeletedAt is not null)
            {
                return NoContent();
            }

            Response.Headers.ETag = current.ETag;
            return ApiSupport.Error(StatusCodes.Status412PreconditionFailed, "Precondition Failed", "The If-Match precondition failed.");
        }
    }

    private async Task<Depot?> CurrentWarehouseEtagAsync(Guid id, CancellationToken cancellationToken)
    {
        _db.ChangeTracker.Clear();
        return await _db.Depots
            .IgnoreQueryFilters()
            .AsNoTracking()
            .FirstOrDefaultAsync(depot => depot.PublicId == id, cancellationToken);
    }

    private static bool TryValidateCreate(WarehouseRequest? request, out IActionResult? invalid)
    {
        invalid = null;
        if (request is null || !request.Id.HasValue || request.Id.Value == Guid.Empty ||
            request.Code is null || !request.CapacityCubicMeters.HasValue)
        {
            invalid = ApiSupport.Error(StatusCodes.Status400BadRequest, "Bad Request", "The request body is invalid.");
            return false;
        }

        return true;
    }

    private static bool TryValidateUpdate(WarehouseRequest? request, Guid routeId, out IActionResult? invalid)
    {
        invalid = null;
        if (request is null || !request.Id.HasValue || request.Id.Value == Guid.Empty || request.Id.Value != routeId ||
            request.Code is null || !request.CapacityCubicMeters.HasValue)
        {
            invalid = ApiSupport.Error(StatusCodes.Status400BadRequest, "Bad Request", "The request body is invalid.");
            return false;
        }

        return true;
    }
}
