// Canonical.cs
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

namespace Api;

public static class Canonical
{
    public static string Normalize(string value) => value.Normalize(NormalizationForm.FormC);

    public static string Warehouse(Guid id, string code, int capacityCubicMeters)
    {
        var sb = new StringBuilder(160);
        sb.Append("{\"id\":");
        AppendGuid(sb, id);
        sb.Append(",\"code\":");
        AppendString(sb, code);
        sb.Append(",\"capacityCubicMeters\":");
        sb.Append(capacityCubicMeters.ToString(CultureInfo.InvariantCulture));
        sb.Append('}');
        return sb.ToString();
    }

    public static string Consignment(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile)
    {
        var sb = new StringBuilder(220);
        sb.Append("{\"id\":");
        AppendGuid(sb, id);
        sb.Append(",\"warehouseId\":");
        AppendGuid(sb, warehouseId);
        sb.Append(",\"reference\":");
        AppendString(sb, reference);
        sb.Append(",\"weightKg\":");
        AppendDecimal(sb, weightKg);
        sb.Append(",\"fragile\":");
        sb.Append(fragile ? "true" : "false");
        sb.Append('}');
        return sb.ToString();
    }

    public static string ETagFor(string canonical)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonical));
        var encoded = Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + encoded + "\"";
    }

    private static void AppendGuid(StringBuilder sb, Guid id) =>
        sb.Append('"').Append(id.ToString("D")).Append('"');

    private static void AppendString(StringBuilder sb, string value)
    {
        sb.Append('"');
        foreach (var c in value.Normalize(NormalizationForm.FormC))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20)
                        sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else
                        sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }

    private static void AppendDecimal(StringBuilder sb, decimal value)
    {
        if (value == 0m)
        {
            sb.Append('0');
            return;
        }
        var s = value.ToString(CultureInfo.InvariantCulture);
        if (s.IndexOf('.') >= 0)
            s = s.TrimEnd('0').TrimEnd('.');
        sb.Append(s);
    }
}
