using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Microsoft.Net.Http.Headers;

namespace Api;

public abstract class ApiControllerBase : ControllerBase
{
    protected void SetETag(string etag) => Response.Headers[HeaderNames.ETag] = etag;

    protected IActionResult BadRequestProblem(string detail) =>
        Problem(detail: detail, statusCode: StatusCodes.Status400BadRequest);

    protected IActionResult NotFoundProblem(string detail) =>
        Problem(detail: detail, statusCode: StatusCodes.Status404NotFound);

    protected IActionResult ConflictProblem(string detail) =>
        Problem(detail: detail, statusCode: StatusCodes.Status409Conflict);

    protected IActionResult GoneProblem(string detail) =>
        Problem(detail: detail, statusCode: StatusCodes.Status410Gone);

    protected IActionResult PreconditionFailedProblem(string detail, string currentETag)
    {
        SetETag(currentETag);
        return Problem(detail: detail, statusCode: StatusCodes.Status412PreconditionFailed);
    }

    protected IActionResult PreconditionRequiredProblem() =>
        Problem(detail: "The If-Match header is required.",
            statusCode: StatusCodes.Status428PreconditionRequired);

    protected static WarehouseResponse ToResponse(Depot depot) => new()
    {
        Id = depot.PublicId,
        Code = depot.Code,
        CapacityCubicMeters = depot.CapacityCubicMeters
    };

    protected static ShipmentResponse ToResponse(Consignment consignment) => new()
    {
        Id = consignment.PublicId,
        WarehouseId = consignment.WarehouseId,
        Reference = consignment.Reference,
        WeightKg = consignment.WeightKg,
        Fragile = consignment.Fragile
    };

    protected static bool ConditionMatches(string? headerValue, string etag)
    {
        if (string.IsNullOrWhiteSpace(headerValue))
            return false;
        foreach (var part in headerValue.Split(','))
        {
            var token = part.Trim();
            if (token.StartsWith("W/", StringComparison.Ordinal))
                token = token[2..];
            if (token == "*" || string.Equals(token, etag, StringComparison.Ordinal))
                return true;
        }
        return false;
    }

    protected static bool IsUniqueViolation(DbUpdateException exception)
    {
        for (var inner = exception.InnerException; inner is not null; inner = inner.InnerException)
            if (inner is SqliteException sqlite && sqlite.SqliteErrorCode == 19)
                return true;
        return false;
    }
}
