        catch (DbUpdateException ex) when (IsUniqueViolation(ex))
        {
            _db.ChangeTracker.Clear();
            var existing = await _db.Depots.IgnoreQueryFilters()
                .FirstOrDefaultAsync(d => d.PublicId == body.Id, cancellationToken);
            if (existing is null)
                return ConflictProblem("A warehouse with this id already exists.");
            if (existing.TombstoneAt is not null)
                return GoneProblem("The warehouse has been deleted.");
            SetETag(existing.ETag);
            if (existing.CreateHash == etag)
                return Ok(ToResponse(existing));
            return ConflictProblem("A warehouse with this id already exists with different content.");
