            return PreconditionFailedProblem("The If-Match header does not match the current ETag.", depot.ETag);

        var now = DateTime.UtcNow;
        depot.TombstoneAt = now;
        var shipments = await _db.Consignments
            .Where(c => c.WarehouseId == depot.PublicId)
            .ToListAsync(cancellationToken);
        foreach (var shipment in shipments)
            shipment.TombstoneAt = now;

