        [FromHeader(Name = "If-Match")] string ifMatch,
        CancellationToken cancellationToken)
    {
        if (body is null || body.Id != id || body.Reference is null)
            return BadRequestProblem("The request body is invalid.");
        if (string.IsNullOrWhiteSpace(ifMatch))
            return PreconditionRequiredProblem();

        var consignment = await _db.Consignments.IgnoreQueryFilters()
            .FirstOrDefaultAsync(c => c.PublicId == id, cancellationToken);
        if (consignment is null)
            return NotFoundProblem("Shipment not found.");
        if (consignment.TombstoneAt is not null)
            return GoneProblem("The shipment has been deleted.");

        var reference = Canonical.Normalize(body.Reference);
        var etag = Canonical.ETagFor(
            Canonical.Consignment(id, body.WarehouseId, reference, body.WeightKg, body.Fragile));

        if (etag == consignment.ETag)
        {
            SetETag(consignment.ETag);
            return NoContent();
        }
        if (body.WarehouseId != consignment.WarehouseId)
            return ConflictProblem("A shipment cannot be moved to another warehouse.");
        if (!ConditionMatches(ifMatch, consignment.ETag))
            return PreconditionFailedProblem("The If-Match header does not match the current ETag.", consignment.ETag);

        consignment.Reference = reference;
        consignment.WeightKg = body.WeightKg;
        consignment.Fragile = body.Fragile;
        consignment.ETag = etag;

        try
        {
            await _db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.ChangeTracker.Clear();
            var current = await _db.Consignments.IgnoreQueryFilters()
                .FirstOrDefaultAsync(c => c.PublicId == id, cancellationToken);
            if (current is null)
                return NotFoundProblem("Shipment not found.");
            if (current.TombstoneAt is not null)
                return GoneProblem("The shipment has been deleted.");
            return PreconditionFailedProblem("The If-Match header does not match the current ETag.", current.ETag);
        }

        SetETag(etag);
        return NoContent();
    }

